using System;
using System.Buffers;
using System.Buffers.Binary;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Text;
using System.Threading;
using org.unirail.collections;

namespace org.unirail;

///<summary>
///Runtime base class shared by all generated AdHoc protocol code (C# port).
///<para>
///AdHoc is a <b>streaming</b> binary protocol: a pack is never materialized as one contiguous byte
///array. Instead, bytes flow through a single small, reusable <see cref="buffer"/> while a state machine
///(the <see cref="Connection.Receiver"/> on the read side, the <see cref="Connection.Transmitter"/> on the
///write side) is driven field by field. When the buffer drains mid-field, the machine parks — recording
///<i>what</i> it was assembling in <see cref="mode"/> and <i>where</i> to resume in the active slot's state —
///and continues on the next buffer fill. Memory use is therefore constant in the buffer size, independent of
///pack size.
///</para>
///<para>
///This class holds the state shared by both directions: the working <see cref="buffer"/> and its
///<see cref="byte_"/>/<see cref="byte_max"/> cursor, the bit-accumulation scratch
///(<see cref="bit"/>/<see cref="bits"/>), the scalar staging registers (<see cref="u4"/>/<see cref="u8"/>/<see cref="u8_"/>),
///the <see cref="mode"/> sentinel, and the CRC-16 helpers used by the optional framing layers.
///</para>
///</summary>
public class AdHoc
{
    ///<summary>
    ///A pull source of protocol bytes — the outbound side of a channel. A transport calls <see cref="Read"/>
    ///to drain serialized bytes from it into a socket buffer. The <see cref="Connection.Transmitter"/> is the
    ///canonical implementation.
    ///</summary>
    public interface BytesSrc
    {
        ///<summary>
        ///Reads a sequence of bytes from the current source and advances the position within the source by the number of bytes read.
        ///</summary>
        ///<param name="dst">The byte array to which data is read.</param>
        ///<param name="dst_byte">The zero-based byte offset in <paramref name="dst"/> at which to begin storing the data read from the current source.</param>
        ///<param name="dst_bytes">The maximum number of bytes to be read from the current source.</param>
        ///<returns>
        ///A positive integer indicating the total number of bytes read into the buffer <paramref name="dst"/>.
        ///Returns 0 if <paramref name="dst_bytes"/> is 0, or if there is currently no data available but the source is still open and might provide data later (e.g., not enough space in <paramref name="dst"/> to fit a minimal unit of data).
        ///Returns -1 if no more data is available from the source (end of stream).
        ///</returns>
        int Read(byte[] dst, int dst_byte, int dst_bytes);

        ///<summary>
        ///Gets a value indicating whether the byte source is currently open and available for reading.
        ///</summary>
        ///<returns>True if the source is open; otherwise, false.</returns>
        bool isOpen();

        ///<summary>
        ///Closes the byte source and releases any associated resources.
        ///</summary>
        void Close();
    }

    ///<summary>
    ///A push sink of protocol bytes — the inbound side of a channel. A transport calls <see cref="Write"/>
    ///to hand it bytes arriving off the wire. The <see cref="Connection.Receiver"/> is the canonical implementation.
    ///<para>
    ///ATTENTION! The buffer passed to <see cref="Write"/> is borrowed: it may be reused and overwritten as soon
    ///as the call returns, so an implementation must consume (or copy out) everything it needs before returning.
    ///</para>
    ///</summary>
    public interface BytesDst
    {
        ///<summary>
        ///Writes a sequence of bytes to the current destination and advances the current position within this destination by the number of bytes written.
        ///ATTENTION! The data in the provided buffer <paramref name="src"/> may be modified after this call due to buffer reuse by the caller.
        ///</summary>
        ///<param name="src">The byte array containing the data to write. </param>
        ///<param name="src_byte">The zero-based byte offset in <paramref name="src"/> from which to begin copying bytes to the current destination.</param>
        ///<param name="src_bytes">The number of bytes to write to the current destination.</param>
        ///<returns>The total number of bytes successfully written to the destination. This can be less than <paramref name="src_bytes"/> if the destination cannot accept all bytes (e.g., buffer full).</returns>
        int Write(byte[] src, int src_byte, int src_bytes);

        ///<summary>
        ///Checks if the byte destination is open.
        ///</summary>
        ///<returns>True if open, false otherwise.</returns>
        bool isOpen();

        ///<summary>
        ///Closes the byte destination.
        ///</summary>
        void Close();

        ///<summary>
        ///The socket under a session that outlives it is gone: the session parks and waits for its peer. A destination
        ///that keeps a stream across sockets lets go only of what was the socket's; any other is closed, as at any end.
        ///</summary>
        void Suspend() => Close();
    }

    ///<summary>
    ///Namespace for the two halves of a live channel and the contract that wires them together:
    ///<see cref="External"/> (the transport-facing adapter — socket, serial port, tunnel endpoint) and
    ///<see cref="Internal"/> (the application-facing supplier of the <see cref="BytesSrc"/>/<see cref="BytesDst"/>
    ///and the lifecycle-event callback). The transport drives <see cref="External"/>; the generated/application
    ///code implements <see cref="Internal"/>. The receive/transmit state machines (<see cref="Receiver"/>,
    ///<see cref="Transmitter"/>) and the <see cref="Tunnel"/> relay also live here.
    ///</summary>
    public interface Connection
    {
        ///<summary>
        ///The keys a session encrypts its packs with: the field <c>keys</c> of its <see cref="Transmitter"/> and its
        ///<see cref="Receiver"/>, where the ChaCha20 stage of a pack chain takes them - the stage itself holds no key. One key
        ///per connection the session has had, each from that connection's handshake (<see cref="NoiseNK"/>) and named by an
        ///id both sides derive from it. A pack names the key it was encrypted with, so a pack replayed from the journal after
        ///a reconnect is decrypted with the key of the connection it was made on; new packs take the newest key. The transport
        ///adds the key of every connection to the session it carries - after a reclaim, to the session moved onto the
        ///connection - and clears the rings when the session ends; no key is dropped before that, or a pack replayed with it
        ///would be lost. Written by the transport, read by the pack stages on other threads: an array replaced whole.
        ///</summary>
        public sealed class Keyring
        {
            public sealed class Key
            {
                public readonly uint id;
                public readonly byte[] key, iv;

                public Key(uint id, byte[] key, byte[] iv)
                {
                    this.id = id;
                    this.key = key;
                    this.iv = iv;
                }
            }

            volatile Key[] keys = Array.Empty<Key>();

            ///<summary>The newest key: new packs are encrypted with it. null - the session has none.</summary>
            public Key? Current
            {
                get {
                    var k = keys;
                    return k.Length == 0 ? null : k[k.Length - 1];
                }
            }

            ///<summary>How many keys the session has: one per connection it has had.</summary>
            public int Count => keys.Length;

            public Key? Find(uint id)
            {
                var k = keys;
                for (var i = k.Length - 1; 0 <= i; i--)
                    if (k[i].id == id)
                        return k[i];
                return null;
            }

            public void Add(Key key)
            {
                lock (this)
                {
                    var old = keys;
                    if (0 < old.Length && old[old.Length - 1].id == key.id)
                        return;
                    var list = new System.Collections.Generic.List<Key>(old.Length + 1);
                    foreach (var k in old)
                        if (k.id != key.id)
                            list.Add(k);
                    list.Add(key);
                    keys = list.ToArray();
                }
            }

            ///<summary>Adds <paramref name="key"/> to the rings of the Transmitter and the Receiver of <paramref name="session"/>.</summary>
            public static void Seat(Internal? session, Key? key)
            {
                if (session == null || key == null)
                    return;
                (session.BytesDst as Receiver)?.keys.Add(key);
                transmitter(session)?.keys.Add(key);
            }

            ///<summary><paramref name="session"/> is over: the keys of its Transmitter and its Receiver go.</summary>
            public static void Clear(Internal? session)
            {
                if (session == null)
                    return;
                (session.BytesDst as Receiver)?.keys.Clear();
                transmitter(session)?.keys.Clear();
            }

            static Transmitter? transmitter(Internal session) => session.BytesSrc switch {
                Transmitter t => t,
                Transmitter.Resumable r => r.transmitter,
                _ => null
            };

            ///<summary>The session is over: its keys go. Only let go, not wiped: one key sits in the rings of every session
            ///its connection carried - after a reclaim, in the session moved onto it and in the one it had before.</summary>
            public void Clear()
            {
                lock (this)
                    keys = Array.Empty<Key>();
            }
        }

        ///<summary>
        ///Defines a contract for an external communication connection (e.g., a network socket, serial port)
        ///that acts as an adapter between the external I/O and the internal byte stream handling system.
        ///</summary>
        public interface External
        {
            ///<summary>The identity the session was given — see <see cref="reclaim"/>; 0 while it is not set.</summary>
            int id => 0;

            ///<summary>The session id of this connection — the value <see cref="identify"/>/<see cref="reclaim"/> return; -1 while there is none.</summary>
            long session() => -1;

            ///<summary>
            ///This side made the connection: on a new socket it names itself first ( its login ), and names its position in the
            ///peer's journal only once the peer has named its own ( <see cref="Connection.Control"/> ).
            ///</summary>
            bool dialing => false;

            ///<summary>A failure of what this connection carries - a guaranteed pack dropped half-way among them - to the failure handler of its host. Default: nothing.</summary>
            void failure(Exception e) {}

            ///<summary>
            ///Sets the identity of this connection to <paramref name="id"/> and tells the <see cref="Internal"/> to
            ///<see cref="Internal.resume"/>. Nothing else: no parked session is claimed. Returns an opaque <b>session
            ///id</b> — the one value the peer persists and later hands to <see cref="reclaim"/> to continue this session
            ///over a new socket. It encodes the slot and the identity; the application never takes it apart.
            ///</summary>
            ///<returns>The session id to remember for a later <see cref="reclaim"/>.</returns>
            long identify(int id)
            {
                Internal.resume(this);
                return ((long)-1 << 32) | (uint)id; //no registry slot: only a reclaimable transport packs a real one
            }

            ///<summary>
            ///Continues a session that was parked on <b>another</b> connection of this host. <paramref name="session_id"/>
            ///is not this connection's own <see cref="session"/>: it is the token the peer was given by that earlier
            ///connection — the <see cref="identify"/>/<see cref="reclaim"/> return, or its <see cref="session"/> — kept
            ///across the socket loss and now sent back over this new socket. The token names the slot the parked session
            ///waits on and proves the identity that owns it; the application never takes it apart.
            ///<para>
            ///When that slot still holds the parked session under that identity, the session moves onto this connection
            ///and the old slot is freed. Otherwise — the slot was reaped, never parked, or is this very connection — only
            ///the identity is left in the token and this is exactly <see cref="identify"/> of it. Either way the
            ///connection is identified from here on.
            ///</para>
            ///The default has no slots to look up: it is <see cref="identify"/> of the token's identity.
            ///</summary>
            ///<param name="session_id">The token the peer persisted from its previous connection to this host.</param>
            ///<returns>This connection's <see cref="session"/> — the fresh token the peer keeps for its next <see cref="reclaim"/>.</returns>
            long reclaim(long session_id) { return identify((int)session_id); }

            ///<summary>
            ///<see cref="reclaim(long)"/> of a token that came from the peer. A token is no secret: it holds the slot and the identity, and
            ///either can be guessed. So <paramref name="id"/> is the identity the login of this connection has proved - by a key, a UUID,
            ///whatever the application trusts - and the session moves only when it is the identity the token names. Any other token leaves
            ///this connection with its own session, <see cref="identify">identified</see> as <paramref name="id"/>.
            ///</summary>
            ///<param name="session_id">The token the peer sent.</param>
            ///<param name="id">The identity this connection has proved.</param>
            ///<returns>This connection's <see cref="session"/>, for the peer's next login.</returns>
            long reclaim(long session_id, int id) => (int)session_id == id ? reclaim(session_id) : identify(id);

            ///<summary>
            ///Gets or sets the reception timeout in milliseconds.
            ///A negative value in the getter indicates that a graceful close is in progress.
            ///Setting a negative value initiates a graceful close and sets the timeout to its absolute value.
            ///</summary>
            int ReceiveTimeout { get; set; }

            ///<summary>
            ///Gets or sets the send timeout in milliseconds.
            ///A negative value in the getter indicates that a graceful close is in progress.
            ///Setting a negative value initiates a graceful close and sets the timeout to its absolute value.
            ///</summary>
            int TransmitTimeout { get; set; }

            ///<summary>
            ///A deadline of one of the actor instances of this connection ( <c>[Deadline]</c>, <c>[Idle]</c> ): <paramref name="ms"/> from now.
            ///The connection keeps only the nearest of its instances' deadlines - no timer object - and when it comes asks
            ///<see cref="Internal.OnDeadline"/> with the connection's I/O paused, so the instances fire with nothing of theirs in flight.
            ///A deadline pushed later - every pack of an <c>[Idle]</c> instance - is an addition and a comparison. Any thread.
            ///</summary>
            ///<returns>when it runs out, in milliseconds since the epoch - the value the instance keeps and <see cref="Internal.OnDeadline"/>
            ///compares with; 0 - this transport keeps no deadlines, none will come.</returns>
            long Deadline(long ms) => 0;

            ///<summary>
            ///How long this side may say nothing: a third of the <c>[ReceiveTimeout]</c> of the connection - the silence of the
            ///link the peer waits out -, in milliseconds; 0 - this side has nothing to say it with. The generated code sets it with
            ///<see cref="ReceiveTimeout"/>. A line silent for so long carries <c>Pulse_</c> ( <see cref="Internal.Pulse"/> ): the side
            ///that accepted the connection says it by itself, the side that dialed answers it ( <see cref="HeardPulse"/> ) - or says
            ///it by itself, when it receives nothing -, so the receive timeout of a side runs out only when its peer is gone.
            ///Default: nothing - the transport keeps no time.
            ///</summary>
            void Pulse(long ms) {}

            ///<summary>
            ///The peer said <c>Pulse_</c>. The side that dialed answers it, unless it said something in the last half of
            ///<see cref="Pulse"/>: the peer heard that. Default: nothing.
            ///</summary>
            void HeardPulse() {}

            ///<summary>
            ///The wait of the stage ran out - the <c>[ReceiveTimeout]</c> of the state: no pack of the peer came in it - and
            ///<see cref="Internal.OnReceiveTimeout"/> answered 0. Closes the connection as its receive timeout does: a loss, an
            ///identified session is parked. Default: <see cref="lost"/>.
            ///</summary>
            void ReceiveTimedOut() => lost();

            ///<summary>
            ///Gets a value indicating whether the communication connection is currently open and active.
            ///</summary>
            bool IsOpen { get; }

            ///<summary>
            ///Gracefully closes the communication connection.
            ///This may involve flushing send buffers and completing pending operations.
            ///Whether it also releases the underlying resources or leaves the connection reusable is up to the
            ///implementation (a pooled transport connection drains and returns itself to its pool).
            ///</summary>
            void Close();

            ///<summary>
            ///Immediately terminates the connection, cancelling any pending I/O — a hard stop that does not
            ///guarantee buffered data is sent. Use for force-closing on an unrecoverable error. Contrast with
            ///the graceful <see cref="Close"/>.
            ///</summary>
            void Abort();

            ///<summary>
            ///Ends the connection as a LOSS: what the peer sends can no longer be parsed, so the channel goes the way a broken
            ///link does — an identified session is parked for <see cref="Internal.resumable_seconds"/> and its journal survives.
            ///A transport that never parks just <see cref="Abort"/>s.
            ///</summary>
            void lost() => Abort();

            ///<summary>The application-facing <see cref="Internal"/> half this transport is bound to.</summary>
            Internal Internal { get; set; }

            ///<summary>
            ///Kicks the receive loop. Called when a downstream-aware nested <see cref="BytesDst"/>
            ///has just become ready to accept bytes again, so the pending tail (stashed by
            ///<c>Network.cs</c> after a short <see cref="BytesDst.Write"/>) can be flushed and
            ///<c>ReceiveAsync</c> re-armed. Default no-op for transports that don't pause receive.
            ///</summary>
            void WakeReceive() {}

            ///<summary>
            ///Kicks the transmit loop. Called when new bytes are enqueued on the transmitter,
            ///or when a backpressure-aware nested <see cref="BytesSrc"/> has just deposited
            ///bytes into an armed slot. Default no-op for transports that drive their own
            ///transmit loop.
            ///</summary>
            void WakeTransmit() {}

            ///<summary>
            ///The session goes on on this connection: the peer is asked to continue its stream from the position of this side's
            ///receiver. Called by the generated <c>resume(connection)</c>. A datagram transport sends the request in the header of
            ///a datagram; default no-op.
            ///</summary>
            void Continue() {}

            ///<summary>
            ///the seconds a parked session still waits for its peer to return, 0 once its deadline has passed but it has
            ///not been reaped yet, or -1 when this connection holds no parked session. A parked connection still accepts
            ///packs onto the queue; they go out once the peer reconnects.
            ///</summary>
            int parked => -1;

            ///<summary>
            ///Zero-copy receive handoff. Hands the transport's CURRENT receive buffer to a
            ///schema-blind consumer (a tunnel <see cref="Tunnel.Relay"/>) and installs
            ///<paramref name="buffer"/> as the fresh receive buffer in its place. <paramref name="swapTo"/>
            ///becomes the top-level inbound <see cref="BytesDst"/> that subsequent buffers are delivered to
            ///(its <c>Write</c> drives the relay); passing <c>null</c> restores normal id-dispatched receiving
            ///(end-of-stream). Default: not supported (only zero-copy-capable transports implement it).
            ///</summary>
            void swapReceive(BytesDst? swapTo, byte[] buffer) => throw new NotSupportedException();

            ///<summary>
            ///Whether <see cref="swapReceive"/> is supported: a consumer may take the current receive buffer whole,
            ///because the bytes it is offered run to the end of that buffer. A transport that decodes frames inside
            ///its buffer (a WebSocket) cannot allow that, and a relay then copies what it takes.
            ///</summary>
            bool canSwapReceive => false;

            //There is deliberately NO transmit-side counterpart. One was tried and removed: it handed the same
//region to two sockets' async I/O at once, and the resulting corruption is why the tunnel Relay copies
            //the body into the outbound transmitter's own buffer instead (see its __get_bytes). Any future
            //zero-copy outbound source must first answer who owns the region while the send is in flight.
        }

        public interface Internal
        {
            ///<summary>
            ///Gets or sets the internal destination for data received from the external source.
            ///This property must be set before communication begins.
            ///</summary>
            BytesDst? BytesDst { get; }

            ///<summary>
            ///Gets or sets the internal source of data to be transmitted to the external destination.
            ///Setting this property is the final step in configuration and triggers the connection to become active.
            ///</summary>
            ///<remarks>
            ///The <see cref="External"/> implementation pulls data from this source via <see cref="BytesSrc.Read"/>.
            ///When the source has new bytes ready, the owning <see cref="Transmitter"/> reaches its hosting
            ///<see cref="External"/> via its <c>ext_connection</c> property and calls
            ///<see cref="External.WakeTransmit"/> to kick the transmit loop.
            ///</remarks>
            BytesSrc? BytesSrc { get; }

            ///<summary>
            ///Gets or sets a callback action to be invoked when significant connection events occur,
            ///such as connection, disconnection, or errors.
            ///</summary>
            ///<param name="connection">The connection instance raising the event.</param>
            ///<param name="Event">An event code identifying the type of event. Implementations
            ///should provide a public set of constants for these codes.</param>
            void OnExternalEvent(External connection, Network.TCP.ExternalConnection.Event Event);

            ///<summary>
            ///The session is open. <see cref="OnExternalEvent"/> is the detail - every socket, every cause, who did it;
            ///this and <see cref="OnClose"/> are the opposite: no detail, and exactly once each per session. Hook into
            ///whichever the job needs.
            ///<para>Called when the session can be used: with the socket for raw TCP, with the completed upgrade for a
            ///WebSocket - so a peer that never became one opens nothing and closes nothing. A parked session whose peer
            ///came back is not opened again: it hears <see cref="resume"/>.</para>
            ///</summary>
            void OnOpen() {}

            ///<summary>
            ///The session is over - once, for every session that heard <see cref="OnOpen"/>, whatever ended it: a close,
            ///a loss, a timeout answered with 0. Called after the closing event. While a lost session is parked
            ///(<see cref="resumable_seconds"/>) it is not over, and this comes when the wait runs out.
            ///</summary>
            void OnClose() {}

            ///<summary>
            ///Nothing came from the peer for <see cref="External.ReceiveTimeout"/> milliseconds - the link -, or no pack of it in the
            ///wait of the stage ( the <c>[ReceiveTimeout]</c> of the state ). A timeout is a question
            ///before it is a verdict: this is called while the connection is still whole, so the application can do
            ///something about the silence - send a heartbeat, ask again - and say how long it waits for the answer. It
            ///may as well <see cref="External.Close"/> or <see cref="External.Abort"/> the connection here itself; what
            ///it returns is then ignored.
            ///<para>Not called while a graceful close waits for the peer's FIN: that was never a timeout event.</para>
            ///</summary>
            ///<returns>the new wait in milliseconds. It holds for this one wait - the next runs on
            ///<see cref="External.ReceiveTimeout"/> again, which the handler is free to change. 0 (this default): the
            ///transport closes the connection as a loss - an identified session may be parked. int.MaxValue: no
            ///deadline at all.</returns>
            int OnReceiveTimeout() => 0;

            ///<summary>
            ///The line has been silent ( <see cref="External.Pulse"/> ): the transmitter says the service pack <c>Pulse_</c> once its
            ///queue is empty. On the connection's maintenance pass or I/O thread; the transport wakes the transmitter.
            ///</summary>
            ///<returns><c>false</c> - this side has no <c>Pulse_</c> to say: the protocol has none, or this side transmits nothing
            ///( this default ).</returns>
            bool Pulse() => false;

            ///<summary>
            ///The nearest deadline of this connection's actor instances ( <see cref="External.Deadline"/> ) has come. Called with the
            ///connection's I/O paused. Every instance whose deadline is not later than <paramref name="now"/> gets its <c>OnDeadline</c>;
            ///what is returned is the nearest of the others' - or 0, none. <paramref name="now"/> of <see cref="long.MinValue"/> fires
            ///nothing: only the nearest is asked for.
            ///</summary>
            long OnDeadline(long now) => 0;

            ///<summary>
            ///The process ends, and this session, parked, goes on in the next one ( <c>Network.TCP.snapshot</c> ): writes what it
            ///is - its journal, the position of its receiver, the states of its actors, what the application keeps of it. The
            ///generated code writes what the protocol holds and gives the application its region.
            ///</summary>
            ///<returns><c>false</c> - nothing to go on with: the session ends with the process.</returns>
            bool save(BinaryWriter to) => false;

            ///<summary>
            ///The session <see cref="save"/> wrote in the process before goes on in this one ( <c>Network.TCP.restore</c> ):
            ///parked, it waits for its peer as after a loss. Reads what <see cref="save"/> wrote, in the same order.
            ///</summary>
            void load(BinaryReader from) {}

            ///<summary>
            ///The peer has not taken what was written to it for <see cref="External.TransmitTimeout"/> milliseconds.
            ///The same question as <see cref="OnReceiveTimeout"/>, for the transmit side, with the same answers.
            ///</summary>
            int OnTransmitTimeout() => 0;

            ///<summary>
            ///The peer proved who it is and this session is the one it continues: <paramref name="connection"/> is the
            ///transport the session lives on from now on. A journalling side accepts its guaranteed packs from here on, a
            ///receiving side names its position to the peer. Called with <paramref name="connection"/> == null to signal the
            ///opposite on a receiving side: the peer could not continue - its journal is gone (it crashed and came back
            ///fresh) - so nothing will be replayed and the receiver must discard any saved state and start from a clean slate.
            ///<para>Where this and <see cref="resumable_seconds"/> sit in a session's life:</para>
            ///<code>
            ///live link
            ///   │  loss ────────────────► resumable_seconds(conn, event) → wait how long? (0 = do not park)
            ///   │                                   │
            ///   │                         session PARKED for N seconds
            ///   │                                   │
            ///   │  peer returns, identity proven ─► identify()/reclaim() calls resume():
            ///   │        resume(conn) → CONTINUES: sender may send its guaranteed packs; receiver names its position, restores FSM
            ///   │        resume(null) → sender's journal is gone (crash): nothing to replay; receiver discards saved state, starts CLEAN
            ///   ▼
            ///live link again
            ///</code>
            ///</summary>
            ///<returns>true when the position was sent.</returns>
            bool resume(External connection) => false;

            ///<summary>
            ///How long, in SECONDS, the session on <paramref name="connection"/> should outlive a lost or broken connection.
            ///The transport asks the moment the connection is lost, passing the same <c>(connection, event)</c> it passes to
            ///<see cref="OnExternalEvent"/> — so the application may vary the wait by cause (a network error versus a peer
            ///FIN), or refuse it after its own logout. 0 (this default) ends the session with the connection. The generated
            ///code overrides it from the <c>[Resumable(seconds)]</c> of the current state and of the Connection, the larger
            ///of the two, ignoring the arguments.
            ///</summary>
            int resumable_seconds(External connection, Network.TCP.ExternalConnection.Event Event) => 0;

            ///<summary>
            ///The <c>uid</c> of the host on the far side of this connection from the host a multiplexer shares: the byte a
            ///caller opens a multiplexed port with, and the key the listening side picks this connection by. The same number
            ///on both sides of the connection. <c>-1</c>: not multiplexed.
            ///</summary>
            int id => -1;

            ///<summary>
            ///Seats this Internal on <paramref name="ext"/> and returns the External it sat on before. <c>null</c> unseats it
            ///and returns it to its pool: the transport hands back an Internal it no longer needs this way.
            ///</summary>
            External? External(External? ext) => null;

            class Impl : Internal
            {
                public Impl(Action<External, Network.TCP.ExternalConnection.Event> onEvent, BytesDst? bytesDst, BytesSrc? bytesSrc)
                {
                    OnEvent = onEvent;
                    BytesDst = bytesDst;
                    BytesSrc = bytesSrc;
                }

                public BytesDst? BytesDst { get; set; }
                public BytesSrc? BytesSrc { get; set; }
                public void OnExternalEvent(External connection, Network.TCP.ExternalConnection.Event Event) => OnEvent?.Invoke(connection, Event);
                public Action<External, Network.TCP.ExternalConnection.Event> OnEvent;
            }
        }

        ///<summary>
        ///The base of a <c>[Grouped]</c> actor: its link and its group. <c>G</c> - its group class, the generated <c>Actor.Group</c> or one
        ///extending it. The generated actor adds its <c>connection</c> and <c>Join( connection, group )</c>.
        ///</summary>
        public abstract class GroupMember<A, G>
            where A : GroupMember<A, G>
            where G : Group<A, G>
        {
            ///<summary>The members around it in its group: read them under the group's lock.</summary>
            public A? prev, next;

            ///<summary>The group it is a member of; null - none. A group takes it from null only ( compare-and-set, under that
            ///group's lock ), so it is in one list at most, whoever joins it where.</summary>
            public G? group;

            ///<summary>Joins <paramref name="g"/>, and leaves the group it was in: one group at a time. false - it is in <paramref name="g"/> already.</summary>
            protected bool Enter(G g)
            {
                var was = group; //one read: another thread may move it meanwhile
                if (ReferenceEquals(was, g))
                    return false;
                was?.Remove((A)this);
                return g.Add((A)this);
            }

            ///<summary>Leaves its group, if it is in one. Its Release calls it: an instance that is gone is in no group.</summary>
            public void Leave() => group?.Remove((A)this);
        }

        ///<summary>
        ///Actor instances of any connections of the host, together - every subscriber of a feed, every watcher of a list - of an
        ///actor declared <c>[Grouped]</c>: the generated actor extends <see cref="GroupMember{A, G}"/>, and has its own group class,
        ///<c>Actor.Group</c>, extending this one - the place for what all the members of a group share, and the class to extend for a
        ///group of one's own. An instance joins with its
        ///<c>Join( connection, group )</c> and leaves with its <c>Leave()</c>; its <c>Release</c> leaves by itself.
        ///<para>The members are a list linked through the instances (<see cref="GroupMember{A, G}.prev"/>, <see cref="GroupMember{A, G}.next"/>):
        ///joining puts the instance at the head, leaving takes it out where it is - both O(1), no walk, no object made, so moving to
        ///another group is two such steps. A walk reads the fields,
        ///under the group's lock (<see cref="Lock"/>, a <see cref="FastReentrantSpinLock"/>) as joining and leaving are:
        ///<c>group.Lock.Acquire(); try { for( var w = group.head; w != null; w = w.next ) ... } finally { group.Lock.Release(); }</c></para>
        ///</summary>
        public class Group<A, G>
            where A : GroupMember<A, G>
            where G : Group<A, G>
        {
            ///<summary>The first member: a walk starts here, under the group's lock. Read it, do not write it.</summary>
            public A? head;

            ///<summary>How many members now. Read it, do not write it.</summary>
            public int size;

            ///<summary>The lock of the group: joining, leaving and a walk are under it.</summary>
            public FastReentrantSpinLock Lock = new();

            ///<summary>The groups around this one in its <see cref="Groups{A, G}"/>: read them under that list's lock.</summary>
            public G? prev, next;

            ///<summary>The list of groups it is in; null - none. Taken from null only, as a member's group is: one list at a time.</summary>
            public Groups<A, G>? list;

            ///<summary>Joins the list of groups <paramref name="l"/>, and leaves the one it was in. false - it is in <paramref name="l"/> already, or another join took it meanwhile.</summary>
            public bool Join(Groups<A, G> l)
            {
                var was = list;
                if (ReferenceEquals(was, l))
                    return false;
                was?.Remove((G)this);
                return l.Add((G)this);
            }

            ///<summary>Leaves its list of groups, if it is in one.</summary>
            public void Leave() => list?.Remove((G)this);

            internal bool Add(A a)
            {
                Lock.Acquire();
                var took = Interlocked.CompareExchange(ref a.group, (G)this, null) == null; //false: in a group - this one, or another that a join took it to meanwhile
                if (took)
                {
                    a.prev = null;
                    a.next = head;
                    if (head != null)
                        head.prev = a;
                    head = a;
                    size++;
                }

                Lock.Release();
                return took;
            }

            internal void Remove(A a)
            {
                Lock.Acquire();
                if (ReferenceEquals(a.group, this))
                {
                    if (a.prev == null)
                        head = a.next;
                    else
                        a.prev.next = a.next;
                    if (a.next != null)
                        a.next.prev = a.prev;
                    a.prev = a.next = null;
                    a.group = null;
                    size--;
                }

                Lock.Release();
            }
        }

        ///<summary>
        ///A list of groups - the feeds of a telemetry, the rooms of a chat: linked through the groups (<see cref="Group{A, G}.prev"/>,
        ///<see cref="Group{A, G}.next"/>), joining and leaving O(1), a group in one list at a time. A walk under its <see cref="Lock"/>:
        ///<c>groups.Lock.Acquire(); try { for( var g = groups.head; g != null; g = g.next ) ... } finally { groups.Lock.Release(); }</c>
        ///Extend it with what the groups listed share.
        ///</summary>
        public class Groups<A, G>
            where A : GroupMember<A, G>
            where G : Group<A, G>
        {
            ///<summary>The first group: a walk starts here, under the list's lock. Read it, do not write it.</summary>
            public G? head;

            ///<summary>How many groups now. Read it, do not write it.</summary>
            public int size;

            ///<summary>The lock of the list: joining, leaving and a walk are under it.</summary>
            public FastReentrantSpinLock Lock = new();

            internal bool Add(G g)
            {
                Lock.Acquire();
                var took = Interlocked.CompareExchange(ref g.list, this, null) == null;
                if (took)
                {
                    g.prev = null;
                    g.next = head;
                    if (head != null)
                        head.prev = g;
                    head = g;
                    size++;
                }

                Lock.Release();
                return took;
            }

            internal void Remove(G g)
            {
                Lock.Acquire();
                if (ReferenceEquals(g.list, this))
                {
                    if (g.prev == null)
                        head = g.next;
                    else
                        g.prev.next = g.next;
                    if (g.next != null)
                        g.next.prev = g.prev;
                    g.prev = g.next = null;
                    g.list = null;
                    size--;
                }

                Lock.Release();
            }
        }

        ///<summary>
        ///What a connection that guarantees packs says over a stream - TCP, a WebSocket, a tunnel - besides its packs. It is said
        ///with packs the generator makes itself for a project that guarantees packs, with ids above the ids of the packs of the
        ///description; the generated code serializes, parses and dispatches them as it does any pack, and calls here:
        ///<code>
        ///Confirm_   the decoder of its sender has taken one more step of the journal of the peer
        ///Fresh_     the decoder has no position: the session is new on its side, the stream is to go on from what the journal holds
        ///Continue_  the stream is to go on from the position it carries
        ///Ok_        the journal holds the position asked for: the bytes behind this pack go on from it
        ///Lost_      the journal does not hold the position asked for: the stream goes on from the position it carries
        ///</code>
        ///A position travels modulo 2 to the power of 8 times position_bytes: the position meant is the one nearer than half of
        ///that to the position of the side that reads it - a journal is smaller than that. A journal that has not answered in its
        ///session yet answers any position with Lost_: the position of a session this side has lost is not of this journal,
        ///however close it looks.
        ///<para>A stream loses nothing while its connection lives, so nothing is said twice and nothing is asked for: the decoder
        ///confirms on its own, once a receive call, with a Confirm_ for every border of a step its position crossed. Both sides
        ///count the borders from the position they agreed on. The position counts the bytes of the guaranteed pack in progress
        ///too: a pack the loss of a connection cut goes on from the byte it was cut at.</para>
        ///<para>A new socket of a session: until the two sides agree nothing goes out but these packs. The side that made the
        ///connection names itself first - its login. The side that took it names its position once the login identified the
        ///session ( <see cref="greet"/> ), and says nothing more. The side that made the connection names its own position then
        ///and answers right behind it - Ok_ or Lost_ -, and its journal goes on behind the answer; the other side answers it the
        ///same way. A decoder holding a guaranteed pack in progress reads these packs with a receiver of their own
        ///( <see cref="Receiver.greeter"/> ) until the answer to its position: Ok_ - the pack goes on, Lost_ - it is dropped.
        ///A datagram transport has no use for them: the header of a datagram carries all of it. Why nothing else goes out in
        ///between: the order in the description of <see cref="Transmitter.Resumable"/>.</para>
        ///<para>One object a connection. The only word read per pack is <see cref="Transmitter.to_say"/>.</para>
        ///</summary>
        public sealed class Control
        {
            public const int CONFIRM = 0, FRESH = 1, CONTINUE = 2, OK = 3, LOST = 4;

            long from, lost, ok;       //the position each kind of pack carries, written by whoever has it to say: Volatile.Read/Write only
            int confirms;              //the Confirm_ packs to say: Interlocked only
            volatile bool asked;       //this side has named its position on this socket
            volatile bool asking;      //and the peer has not answered it yet: what is received meanwhile is not confirmed
            volatile bool heard_;      //the peer has named its position on this socket
            long asked_at;             //the position named: Volatile.Read/Write only
            long agreed = AGREED_NONE; //the position of this side's decoder the two agreed on, on this socket: Volatile.Read/Write only
            const long AGREED_NONE = long.MinValue;
            bool answered;  //the journal of this side has answered in this session
            long confirmed; //the border of a step the peer confirmed last, in the journal of this side
            int saying;     //the kind of the pack being said

            ///<summary>The position the pack being said carries, as it travels: read by the generated serializer.</summary>
            public ulong value;

            internal readonly int shift; //a step is 1 << shift bytes

            ///<summary>
            ///The peer confirms what it received once per this many bytes ( <c>Confirm_</c> ): a journal holds up to a step it has
            ///sent and the peer has received, but not confirmed yet.
            ///</summary>
            public long step => 1L << shift;
            internal readonly long mask;   //what of a position travels
            internal readonly int id_mask; //what of the id bytes is the id of a pack: the rest is the address of an actor

            readonly Internal inner;
            readonly Transmitter transmitter;
            readonly Receiver receiver;
            readonly Transmitter.Resumable? journal; //null: this side guarantees nothing of what it sends
            readonly Transmitter.BytesSrc confirm, fresh, continue_, ok_, lost_;

            ///<param name="position_bytes">how many bytes of a position travel</param>
            ///<param name="step">a Confirm_ for every so many bytes received: a power of two</param>
            ///<param name="id_mask">the bits of the id bytes that are the id of a pack</param>
            ///<param name="confirm">the generated packs, in the order of the kinds</param>
            public Control(Internal inner, Transmitter transmitter, Receiver receiver, Transmitter.Resumable? journal, int position_bytes, int step, int id_mask,
                           Transmitter.BytesSrc confirm, Transmitter.BytesSrc fresh, Transmitter.BytesSrc continue_, Transmitter.BytesSrc ok, Transmitter.BytesSrc lost)
            {
                this.inner = inner;
                this.transmitter = transmitter;
                this.receiver = receiver;
                this.journal = journal;
                mask = position_bytes < 8 ? (1L << (position_bytes << 3)) - 1 : -1L;
                shift = BitOperations.TrailingZeroCount(step);
                this.id_mask = id_mask;
                this.confirm = confirm;
                this.fresh = fresh;
                this.continue_ = continue_;
                ok_ = ok;
                lost_ = lost;
                receiver.control = this;
            }

            void say(int kind)
            {
                if (kind == CONFIRM && transmitter.agreeing)
                { //the answer to the peer's position is to be right before the bytes of the journal: a confirmation waits for them
                    transmitter.confirm_deferred = true;
                    if (transmitter.agreeing)
                        return;
                    transmitter.confirm_deferred = false; //agreed meanwhile: said now
                }

                Interlocked.Or(ref transmitter.to_say, 1 << kind);
                transmitter.ext_connection?.WakeTransmit();
            }

            ///<summary>The decoder crossed <paramref name="borders"/> borders of a step since it confirmed last. On the thread that receives.</summary>
            internal void confirm_(int borders)
            {
                if (asking)
                    return; //the answer to the position named sets the count anew
                Interlocked.Add(ref confirms, borders);
                say(CONFIRM);
            }

            ///<summary>
            ///The session goes on on this connection: the peer is asked to continue its stream from the position of the decoder of
            ///this side. Called by the generated <c>resume(connection)</c>. The side that made the connection names its position
            ///once the peer has named its own: until then it says nothing here. Once the two agreed on the socket, the position is
            ///named anew when it is not the one agreed on - the application moved it ( a role taken over, say ).
            ///</summary>
            public void Continue()
            {
                if (!dialing)
                    greet();
                else if (heard_)
                {
                    var at = receiver.received;
                    if (at != Volatile.Read(ref agreed))
                        ask(at);
                }
            }

            ///<summary>
            ///This side names its position in the peer's journal on this socket, once: Fresh_ - none. Until the position the peer
            ///names is answered, the journal of this side sends nothing but what is said here. The side that took the connection:
            ///when the login identified the session ( <c>identify</c>, <c>reclaim</c> ). The side that made it: when the peer's
            ///position is heard.
            ///</summary>
            public void greet()
            {
                if (asked)
                    return;
                asked = true;
                if (journal != null)
                    transmitter.agreeing = true;
                ask(receiver.received);
            }

            void ask(long at)
            {
                Volatile.Write(ref asked_at, at);
                asking = true;
                if (at < 0)
                    say(FRESH);
                else
                {
                    Volatile.Write(ref from, at);
                    say(CONTINUE);
                }
            }

            bool dialing => transmitter.ext_connection?.dialing == true;

            ///<summary>The two sides agreed: the bytes of the journal go on behind the answer. A confirmation said meanwhile goes now.</summary>
            internal static void settled(Transmitter t)
            {
                t.agreeing = false;
                if (!t.confirm_deferred)
                    return;
                t.confirm_deferred = false;
                Interlocked.Or(ref t.to_say, 1 << CONFIRM);
            }

            ///<summary>The connection is gone: what was to be said on it is not said on the next one, and the next one is agreed on anew.</summary>
            internal void silent()
            {
                transmitter.confirm_deferred = false;
                Volatile.Write(ref transmitter.to_say, 0);
                transmitter.agreeing = false;
                Volatile.Write(ref confirms, 0);
                asked = asking = heard_ = false;
                Volatile.Write(ref agreed, AGREED_NONE);
            }

            ///<summary>The session is over: a journal of the next one has not answered yet.</summary>
            internal void ended() => answered = false;

            ///<summary>
            ///Writes what the next process needs of this side's word in the session ( <see cref="load"/> ): whether the journal of
            ///this side has answered in it - a position the peer names on the next socket is then one of this journal.
            ///</summary>
            public void save(BinaryWriter to) => to.Write(answered);

            ///<summary>Takes up what <see cref="save"/> wrote in the process before.</summary>
            public void load(BinaryReader from) => answered = from.ReadBoolean();

            ///<summary>
            ///The peer goes on from <paramref name="low"/>, a position as it travels, -1 - from none: the journal continues there -
            ///the peer is told Ok_ -, or the peer is told where it does - Lost_. Nothing goes out between the answer and the bytes of
            ///the journal behind it.
            ///</summary>
            void answer(long low)
            {
                transmitter.agreeing = true;
                var position = low < 0 || !answered ? -1 : journal!.resolve(low, mask);
                answered = true;
                if (0 <= position && journal!.holds(position))
                {
                    Volatile.Write(ref ok, position);
                    confirmed = position;
                    say(OK);
                    return;
                }

                var at = journal!.resume(position);
                if (at == -1)
                    return;
                Volatile.Write(ref lost, at);
                confirmed = at;
                say(LOST);
            }

            ///<summary>
            ///What the generated <c>_OnSerializing</c> sends next: called while <see cref="Transmitter.to_say"/> is not 0. The
            ///position of this side first: the answer is right before the journal.
            ///</summary>
            public Transmitter.BytesSrc next()
            {
                var s = Volatile.Read(ref transmitter.to_say);
                var kind = (s & 1 << CONTINUE) != 0 ? CONTINUE
                           : (s & 1 << FRESH) != 0  ? FRESH
                           : (s & 1 << LOST) != 0   ? LOST
                           : (s & 1 << OK) != 0     ? OK
                                                    : CONFIRM;
                saying = kind;
                Interlocked.And(ref transmitter.to_say, ~(1 << kind)); //taken first, read second: a position written after this is said again
                switch (kind)
                {
                    case CONFIRM:
                        if (0 < Interlocked.Decrement(ref confirms))
                            Interlocked.Or(ref transmitter.to_say, 1 << CONFIRM); //more to confirm
                        return confirm;
                    case FRESH:
                        return fresh;
                    case CONTINUE:
                        value = (ulong)(Volatile.Read(ref from) & mask);
                        return continue_;
                    case LOST:
                        value = (ulong)(Volatile.Read(ref lost) & mask);
                        return lost_;
                    default:
                        return ok_;
                }
            }

            ///<summary>The pack <see cref="next"/> gave is out: called by its generated serializer.</summary>
            public void said()
            {
                if (saying == LOST)
                    journal!.resume(Volatile.Read(ref lost)); //the peer is told: the stream goes on from there
                else if (saying == OK)
                    journal!.resume(Volatile.Read(ref ok)); //the bytes of the journal follow the answer
            }

            ///<summary>Confirm_ of the peer: on the thread that receives.</summary>
            public void heard_confirm()
            {
                if (journal == null)
                    return;
                confirmed = (confirmed >> shift) + 1 << shift;
                journal.ack(confirmed);
            }

            ///<summary>
            ///Fresh_ or Continue_ of the peer: <paramref name="low"/> - the position as it travels, -1 - none. On the thread that
            ///receives. Fresh_ in a session this journal has answered in already: the peer is a new run that took the session by
            ///its account - the run that had it is gone, and with it everything of the session on that side; the application
            ///hears it as <see cref="Internal.resume"/> with null, as when the peer's journal is gone.
            ///</summary>
            public void heard_continue(long low)
            {
                heard_ = true;
                if (dialing)
                    greet(); //the peer is identified and named its position: this one names its own first
                if (journal != null)
                {
                    var anew = low < 0 && answered;
                    answer(low);
                    if (anew)
                        inner.resume(null);
                }
            }

            ///<summary>Ok_ of the peer: the stream goes on from the position this side named. On the thread that receives.</summary>
            public void heard_ok()
            {
                asking = false;
                var at = Volatile.Read(ref asked_at);
                Volatile.Write(ref agreed, at);
                receiver.goes_on(at);
            }

            ///<summary>Lost_ of the peer: the packs between are lost, the stream goes on from <paramref name="low"/>. On the thread that receives.</summary>
            public void heard_lost(long low)
            {
                asking = false;
                var position = receiver.resolve(low, mask);
                Volatile.Write(ref agreed, position);
                if (receiver.greeting)
                    receiver.Lost(position); //the guaranteed pack in progress is dropped
                else
                    receiver.position(position);
                inner.resume(null); //told when the position is the new one already
            }
        }

        ///<summary>
        ///The inbound state machine: a <see cref="BytesDst"/> that consumes bytes off the wire and drives the
        ///generated per-pack deserializers field by field. Each <c>Write</c> call feeds it whatever the transport
        ///just read; when a value spans buffer fills it parks (see <see cref="mode"/>) and resumes on the next
        ///call. It reads a packet ID first, dispatches to the matching <see cref="BytesDst"/> packet handler, and
        ///notifies its handler at the start and end of each pack.
        ///<para>
        ///Generated protocol code subclasses this with the concrete <see cref="id"/> dispatch and pack handlers;
        ///an optional <see cref="Framing"/> layer can sit in front of it to add 0xFF framing and CRC checking.
        ///</para>
        ///</summary>
        public abstract class Receiver : Base_.Receiver, BytesDst
        {
            ///<summary>The keys the ChaCha20 stages of this session's pack chains decrypt with: see <see cref="Connection.Keyring"/>.</summary>
            public readonly Keyring keys = new();

            ///<summary>The pack being received is not to be dispatched when it ends: outdated (a replay of what arrived), or
            ///not to be decrypted (its key is not of this session). Cleared as each pack starts.</summary>
            public bool drop_received;

            public abstract int id { get; }

            ///<summary>
            ///The owning external connection, or <c>null</c> for free-standing / test receivers
            ///(e.g. <see cref="Virtual"/>). Backpressure-aware nested <see cref="BytesDst"/>
            ///implementations read this property to reach <see cref="Connection.External.WakeReceive"/>
            ///on the hosting transport.
            ///</summary>
            public abstract External? ext_connection { get; }

            ///<summary>Under a <see cref="Framing"/>: a pack that cannot be parsed is dropped and the next 0xFF starts the next one -
            ///its CRC was not checked yet, the bytes may be distorted; the connection is not torn down for it.</summary>
            internal bool framed;

            ///<summary>
            ///Bytes consumed by the top-level <see cref="Write"/> calls. During such a call it is offset by the
            ///buffer's starting index, so that <see cref="consumed"/> is the stream position directly.
            ///</summary>
            private long _consumed;

            ///<summary>
            ///The number of bytes this receiver has consumed from its input. Inside a callback of a top-level pack it
            ///is the stream position of the byte about to be parsed; in <c>_OnReceived</c> it is the position just past
            ///the pack. The bytes a nested chain decodes and feeds back through <see cref="Write"/> are not counted.
            ///</summary>
            public long consumed => buffer == null ? _consumed : _consumed + byte_;
#region guaranteed packs
            //The journal of the peer is a buffer of bytes: the bytes of its guaranteed packs, one after another. What this
            //side tells the peer is how many of them arrived - the transport carries the number and does not count: which
            //bytes are a guaranteed pack's is known here and nowhere else. Over datagrams the count goes on inside a pack: a
            //guaranteed pack cut by a lost datagram is not dropped, the peer sends on from the byte it was cut at.

            private long guarded_;             //the position in the peer's journal behind the last guaranteed pack received whole
            private long guarded_from = -1;    //consumed at the first byte of the guaranteed pack in progress; -1: none, or the pack in progress is not guaranteed
            private bool positioned;           //the position is known: the peer named where its journal goes on from
            private long told = long.MaxValue; //a stream: the position the steps are counted from; above every position while there is nothing to confirm to

            ///<summary>A stream: what this side says besides its packs - the confirmations of this decoder among it. null: a datagram transport, or nothing is guaranteed.</summary>
            public Control? control;

            ///<summary>The generated <c>_OnReceiving</c>: the pack that starts is a guaranteed one. Its bytes count from its id on.</summary>
            protected void guarded()
            {
                guarded_from = consumed - id_bytes;
                guarded_id = control == null ? (int)u4 : (int)u4 & control.id_mask; //what the id bytes carry besides the id ( the address of an actor ) is not the pack's
            }

            private int guarded_id; //the id of the guaranteed pack in progress: told when it is dropped half-way

            ///<summary>
            ///A guaranteed pack is half received: its sender keeps sending it, so silence of the link means the link carries
            ///nothing ( <see cref="Network.TCP.Redial.Stalled"/> ). From any thread, as a hint.
            ///</summary>
            public bool guarding => 0 <= Volatile.Read(ref guarded_from);

            ///<summary>
            ///A new socket of the session, and a guaranteed pack in progress: the packs the two sides agree by come first
            ///( <see cref="Control"/> ), read by <see cref="greeter_"/> until the answer to the position this side named.
            ///</summary>
            internal bool greeting;

            ///<summary>
            ///Reads the packs of the agreement on a new socket while a guaranteed pack in progress waits here: a receiver of their
            ///own, made by the generated code ( <see cref="greeter"/> ) the first time a socket is lost in the middle of a pack.
            ///</summary>
            private Receiver? greeter_;

            ///<summary>A receiver of the generated code that dispatches the packs of the agreement only. null: a pack in progress is dropped with the socket that cut it.</summary>
            protected virtual Receiver? greeter() => null;

            ///<summary>
            ///The packs of the agreement on a new socket, ahead of the guaranteed pack in progress. Their bytes are not the pack's:
            ///they are not counted, <see cref="received"/> stays. The answer to the position this side named ends what the greeter
            ///reads: what is behind it is the pack's.
            ///</summary>
            ///<returns>false - not a pack of the agreement: the stream is not the one agreed on, the connection is dropped as a broken one.</returns>
            private bool greet()
            {
                var at = byte_;
                var src = buffer!;
                _consumed += at; //what the greeter reads is not counted: received stays while it reads
                buffer = null;
                var r = greeter_!.Write(src, at, byte_max - at);
                buffer = src;
                byte_ = r < 0 ? byte_max : at + r;
                _consumed -= byte_;
                if (r < 0 && greeting)
                {
                    Lost(guarded_);
                    return false;
                }

                return true;
            }

            ///<summary>The answer to the position this side named is heard: the greeter reads no further, what is behind the answer is the pack's.</summary>
            private void greeted()
            {
                if (!greeting)
                    return;
                greeting = false;
                var g = greeter_!;
                if (g.buffer != null)
                    g.byte_max = g.byte_;
            }

            ///<summary>
            ///The peer's journal goes on from <paramref name="position"/>, the one this side named ( Ok_ ): the guaranteed pack in
            ///progress goes on with the bytes behind the answer. The steps are counted from the position.
            ///</summary>
            internal void goes_on(long position)
            {
                told = position;
                if (!greeting)
                    return;
                greeted();
                if (position != received)
                    Lost(position);
            }

            ///<summary>
            ///The position <paramref name="low"/>, as it travels ( <paramref name="mask"/> ), means: the nearest one to the position of
            ///this receiver, as it is when no position is known yet.
            ///</summary>
            internal long resolve(long low, long mask)
            {
                if (!positioned || mask == -1L)
                    return low;
                var at = guarded_;
                var d = (low - at) & mask;
                if ((long)((ulong)mask >> 1) < d)
                    d -= mask + 1;
                return at + d;
            }

            ///<summary>
            ///The position in the peer's journal this receiver has got to - the bytes of the guaranteed pack in progress count
            ///too; <c>-1</c> while no position is known.
            ///</summary>
            public long received => !positioned        ? -1
                                    : guarded_from < 0 ? guarded_
                                                       : guarded_ + consumed - guarded_from;

            ///<summary>
            ///The bytes that follow do not continue what was received before them: they come from the peer's journal, from the
            ///position <see cref="received"/> named, or start with a fresh pack. A guaranteed pack in progress is kept - its bytes
            ///go on. An unguaranteed one will never be completed, and a pack id read in part tells nothing of its pack: both are
            ///dropped, and a pack id is waited for.
            ///</summary>
            public void Continue()
            {
                if (guarded_from < 0 || slot?.dst == null)
                    Abandon();
            }

            ///<summary>
            ///The journal of the peer does not hold the position asked for: its stream goes on from <paramref name="position"/>,
            ///a pack starts there. What this receiver holds of a pack in progress is dropped.
            ///</summary>
            public void Lost(long position)
            {
                greeted();
                if (0 <= guarded_from && slot?.dst != null)
                    ext_connection?.failure(new InvalidOperationException($"The guaranteed pack {guarded_id} was cut by the loss of a connection and is dropped: the journal of the peer does not hold its bytes, its stream goes on from {position}"));
                Abandon();
                this.position(position);
            }

            ///<summary>The stream of the peer goes on from <paramref name="position"/> of its journal, with a pack that starts there. The steps are counted from the position.</summary>
            internal void position(long position)
            {
                guarded_from = -1;
                guarded_ = position;
                told = control == null ? long.MaxValue : position;
                positioned = true;
            }

            ///<summary>
            ///Writes the position of this receiver for the process that takes the session up after this one ( <see cref="load"/> ):
            ///behind the last guaranteed pack received whole. A pack in progress is not taken along - its bytes went to an object of
            ///this process; the peer's journal holds it from its start, and sends it again.
            ///</summary>
            public void save(BinaryWriter to)
            {
                to.Write(positioned);
                to.Write(guarded_);
            }

            ///<summary>
            ///Takes up the position <see cref="save"/> wrote in the process before: the stream of the peer goes on behind the last
            ///guaranteed pack received whole, the peer is asked for it on the next socket.
            ///</summary>
            public void load(BinaryReader from)
            {
                var known = from.ReadBoolean();
                var at = from.ReadInt64();
                if (known)
                    position(at);
                else
                    unpositioned();
            }

            ///<summary>The session is over: the position is of no journal any more.</summary>
            protected internal void unpositioned()
            {
                guarded_from = -1;
                guarded_ = 0;
                told = long.MaxValue;
                positioned = false;
                control?.ended();
            }
#endregion

            ///<summary>
            ///The speed this receiver takes bytes at, bytes a second: the bytes the transport handed over since the last measure,
            ///over the time since then - measured once 10 ms at least went by, a pause longer than a second is not counted. Not
            ///averaged: the speed now. Any transport: the bytes are those it hands over. 0 - none measured yet. From any thread.
            ///</summary>
            public long speed => Volatile.Read(ref speed_);

            long speed_, speed_mark, speed_at; //the speed; consumed and the clock ( Stopwatch ) when it was measured last

            private int exit(bool top, int ret)
            {
                if (top)
                {
                    _consumed += byte_;
                    var now = System.Diagnostics.Stopwatch.GetTimestamp();
                    var t = now - speed_at;
                    if (System.Diagnostics.Stopwatch.Frequency / 100 <= t)
                    { //what came since the last measure, over the time it took - not a pause
                        if (t < System.Diagnostics.Stopwatch.Frequency)
                            Volatile.Write(ref speed_, (long)((_consumed - speed_mark) * (double)System.Diagnostics.Stopwatch.Frequency / t));
                        speed_at = now;
                        speed_mark = _consumed;
                    }
                    if (control != null)
                    { //a stream: what was handed over is parsed - the borders of a step it crossed are told to the peer. The bytes of
                      //a guaranteed pack in progress count: a pack larger than the journal of the peer goes on while it is received
                        var at = guarded_from < 0 ? guarded_ : guarded_ + _consumed - guarded_from;
                        var borders = (at >> control.shift) - (told >> control.shift);
                        if (0 < borders)
                        {
                            told = at;
                            control.confirm_((int)borders);
                        }
                    }
                }

                return ret;
            }

            ///<summary>
            ///Arms the per-stream completion hook — the resource-policy channel for streamed byte fields. The
            ///implementor of <c>__bytes(scope)</c> — the only party that knows how the stream it returns must be
            ///treated — calls this on the scope right before returning; the generated override plants the hook
            ///DIRECTLY into the chain about to be armed (<c>chain().onStreamComplete = …</c> — <c>chain()</c> is
            ///idempotent until the arming, so the imminent <c>stream(…)</c> picks the very same chain; an inner
            ///stream's arming can therefore never clobber an outer stream's hook). The generated <c>Chain</c>
            ///invokes the hook INSTEAD of the default when the stream ends, consuming it.
            ///<para>Second argument: <c>true</c> — the stream completed cleanly (the <c>0x0000</c> terminator);
            ///<c>false</c> — it was torn down (abort/reset) — e.g. delete a partially received file.</para>
            ///<para>When no hook is armed, the stream-end default runs — a
            ///<see cref="FileStream"/> sink is closed, anything else only unreferenced. To suppress even that (e.g.
            ///keep a caller-owned <see cref="FileStream"/> open), call the parameterless <see cref="OnStreamComplete()"/>.</para>
            ///<para>Overridden by the generated Receiver (only it knows its <c>Chain</c> machinery); the base has
            ///no chain to plant into.</para>
            ///</summary>
            public virtual void OnStreamComplete(Action<Receiver, bool>? onStreamComplete) => throw new NotSupportedException("This Receiver has no stream-chain machinery to plant the hook into.");

            ///<summary>Convenience overload — arms <see cref="OnStreamComplete_None"/>: "do nothing at the stream end",
            ///suppressing the stream-end default for the imminent stream.</summary>
            public void OnStreamComplete() => OnStreamComplete(OnStreamComplete_None);

            ///<summary>No-op hook: arms "do nothing at the stream end", suppressing the stream-end default.</summary>
            private static readonly Action<Receiver, bool> OnStreamComplete_None = (_, _) =>
            {};

            ///<summary>
            ///A simplified, 'one-shot' receiver designed to parse a single, specific packet type from a byte stream
            ///passed via the Write method.
            ///<para>
            ///It acts as a temporary, virtual connection for a single deserialization task, similar to `JSON.parse`. This is highly useful for
            ///scenarios like reading a known object from a file, deserializing from a byte array, or in unit tests,
            ///where the full overhead of a persistent communication connection is unnecessary.
            ///</para>
            ///</summary>
            public class Virtual : Receiver
            {
                public override int id => 0;
                public override External? ext_connection => null;
                BytesDst? dst;

                public Virtual(int id_bytes) : base(null!, id_bytes) {}

                ///<summary>
                ///Configures the receiver to populate a specific packet object from the byte stream.
                ///This method must be called before passing any data to the Write() method.
                ///</summary>
                ///<param name="dst">The concrete packet object that will be populated from the bytes.</param>
                public void SetBytesDst(BytesDst dst) => this.dst = dst;

                protected override BytesDst _OnReceiving(int id)
                {
                    if (dst == null)
                        throw new InvalidOperationException("No BytesDst is armed: SetBytesDst() must be called before Write(); id from bytes stream is " + id + ".");

                    return dst.__id != id ? throw new ArgumentException("Provided BytesDst `id` and `id` from bytes stream do not match.") : dst;
                }

                protected override void _OnReceived(BytesDst received) => dst = null;

                public override void Close()
                {
                    dst = null;
                    base.Close(); //base.Close() calls the non-virtual Reset()
                }
            }

            ///<summary>
            ///The per-pack deserializer contract: one implementation per message type, driven by the
            ///<see cref="Receiver"/> once it has dispatched on the packet ID. Generated code implements it to
            ///pull each field from the receiver's staging registers and buffer.
            ///</summary>
            public interface BytesDst
            {
                ///<summary>
                ///Consume bytes for this pack from the receiver, advancing its state. Returns when the buffer is
                ///exhausted or the pack is complete; a partial value parks and resumes on the next call.
                ///</summary>
                ///<param name="src">The <see cref="Receiver"/> providing the byte stream and deserialization context.</param>
                ///<returns>True if this pack/part is complete; false if more bytes are needed (parked).</returns>
                bool __put_bytes(Receiver src);

                ///<summary>
                ///Gets the unique identifier for this message type or data structure.
                ///</summary>
                int __id { get; }

                ///<summary>
                ///Terminal (leaf) consumer — the END of a receive stream chain and the receive-side dual of
                ///<see cref="Transmitter.BytesSrc.Adapter"/>. An <see cref="Adapter"/> bridges the pure-byte
                ///<see cref="BytesDst"/> contract into a real .NET <see cref="System.IO.Stream"/> (any kind: file,
                ///memory, network…), so it can sit at the bottom of a composed chain. As the chain leaf it has no
                ///inner stage to forward to.
                ///<para>Because completion is decided by the surrounding framer — there is no intrinsic EOF on the
                ///receive side — the sink is <b>not</b> auto-closed by this class' own state machine: at the stream
                ///boundary (the <c>0x0000</c> terminator) and on teardown (<c>Chain.Release</c>) the generated
                ///<c>Chain</c> runs the captured <see cref="Receiver.OnStreamComplete"/> hook, or — when none was
                ///armed — the default: a <see cref="FileStream"/> sink is closed, anything
                ///else only unreferenced.</para>
                ///</summary>
                public class Adapter : BytesDst
                {
                    //PUBLIC on purpose: codegen re-arms a statically wired endpoint by DIRECT field access (the inline
                    //equivalent of Init minus the maxStreamBytes line) so a cap set once survives per-stream re-arms.
                    public Stream? dst;                         //underlying byte sink (any System.IO.Stream, incl. FileStream); null while armed as a re-entrant receiver sink
                    public long maxStreamBytes = long.MaxValue; //cap on TOTAL bytes written to dst (the IDL [S(N)] limit); set by EVERY Init (unlimited when the overload takes no cap)

                    ///<summary>A stream past its <c>[S(N)]</c> cap: told as what it is - OVERFLOW - then thrown, and the receiver
                    ///tears the stream down.</summary>
                    internal static InvalidOperationException overflow(Receiver src, string why)
                    {
                        var e = new InvalidOperationException(why);
                        Receiver.error_handler.error(src, null, Receiver.OnError.OVERFLOW, e);
                        return e;
                    }
                    public long _total; //bytes written to dst so far — reset by Init / codegen re-arm

                    public int __id => id;

                    public int id = int.MinValue; //endpoint id; reset to the int.MinValue sentinel by every id-less Init, stamped by every id-taking Init

                    //A STRUCTURED streamed datatype feeds its decoded bytes back into the Receiver itself rather than out
                    //to a byte sink. Since dst is a System.IO.Stream — which a Receiver cannot also be — that arming needs
                    //its own field and its own Init(Receiver) overload.
                    Receiver? _rx; //re-entrant structured-datatype sink; null ⇒ plain byte sink

                    //PUBLIC for the same reason as dst: codegen re-arms a statically wired endpoint by DIRECT field access.
                    //An application-level sink that is neither a System.IO.Stream nor a Receiver — e.g. a virtual
                    //connection's Internal.BytesDst. Unlike Stream.Write (all-or-throw), AdHoc.BytesDst.Write returns how
                    //many bytes it ACCEPTED and may take fewer than offered, so the drain loop advances by that count and
                    //parks on 0 (backpressure) instead of assuming the whole window landed.
                    public AdHoc.BytesDst? dst_; //application-level byte sink; null ⇒ not armed as one

                    internal bool failed; //dst_ threw during this stream: the rest of the stream is consumed unseen (cleared by every arming)

                    ///<summary>
                    ///The stream this Adapter feeds ended as void — <see cref="Transmitter.Chunked.ABORT"/>, or its carrier
                    ///was lost mid-way. A sink that parses packs (a virtual connection's receiver) drops the pack in progress
                    ///and waits for a pack id again: the next stream it is fed starts on a pack boundary.
                    ///</summary>
                    public void abandon()
                    {
                        failed = false;
                        (dst_ as Receiver)?.Abandon();
                    }
//region Init — path family (self-opened file sink; always owned/closed by this Adapter)

                    ///<summary>PRIMARY (re)configuration with an explicit endpoint <paramref name="id"/>. Opens the sink file
                    ///(created/truncated for writing).
                    ///<paramref name="maxStreamBytes"/> is the IDL <c>[S(N)]</c> cap on TOTAL bytes written; exceeding it makes
                    ///<see cref="__put_bytes"/> throw. Applies to THIS arming only. Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(string dst, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.dst = new FileStream(dst, FileMode.Create, FileAccess.Write, FileShare.None);
                        _rx = null;
                        dst_ = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        failed = false;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(dst, long.MaxValue, id)</c> (no size cap).</summary>
                    public Adapter Init(string dst, int id) => Init(dst, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration WITHOUT an id — stamps the <see cref="int.MinValue"/> sentinel, then
                    ///delegates to the id-taking primary.</summary>
                    public Adapter Init(string dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(dst, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(string dst) => Init(dst, long.MaxValue);
//endregion
//region Init — stream family (caller-supplied sink; stream-end policy = the OnStreamComplete hook, else the stream-end default)

                    ///<summary>PRIMARY (re)configuration with a caller-supplied <see cref="System.IO.Stream"/> sink and an explicit
                    ///endpoint <paramref name="id"/>. Adopts <paramref name="dst"/>. What happens to it at the stream end is decided
                    ///by the <see cref="Receiver.OnStreamComplete"/> hook the supplier may arm, else by the <see cref="onComplete"/>
                    ///default. Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(Stream dst, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.dst = dst;
                        _rx = null;
                        dst_ = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        failed = false;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(dst, long.MaxValue, id)</c> (no size cap).</summary>
                    public Adapter Init(Stream dst, int id) => Init(dst, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration with a caller-supplied sink WITHOUT an id — stamps the
                    ///<see cref="int.MinValue"/> sentinel, then delegates to the id-taking primary.</summary>
                    public Adapter Init(Stream dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(dst, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(Stream dst) => Init(dst, long.MaxValue);
//endregion
//region Init — re-entrant receiver sink (see _rx)

                    ///<summary>Arm as a re-entrant sink for a STRUCTURED streamed datatype: decoded plaintext is fed back into
                    ///<paramref name="rx"/> instead of out to a byte sink. Clears <see cref="dst"/> and the size cap, and stamps
                    ///the <see cref="int.MinValue"/> id sentinel — such a stream is an embedded field, never dispatched by id.</summary>
                    public Adapter Init(Receiver rx)
                    {
                        id = int.MinValue;
                        _total = 0;
                        dst = null;
                        dst_ = null;
                        _rx = rx;
                        maxStreamBytes = long.MaxValue;
                        redirect = null;
                        failed = false;
                        return this;
                    }
//endregion
//region Init — application-sink family (caller-supplied AdHoc.BytesDst; never touched by the stream-end default)

                    ///<summary>PRIMARY (re)configuration with a caller-supplied <see cref="AdHoc.BytesDst"/> sink — an application-level
                    ///byte consumer that is neither a <see cref="System.IO.Stream"/> nor a <see cref="Receiver"/> (e.g. a virtual
                    ///connection's <c>Internal.BytesDst</c>) — and an explicit endpoint <paramref name="id"/>. Adopts
                    ///<paramref name="dst"/>. The stream-end default never closes such a sink (it only drops the
                    ///reference); closing belongs to the supplier — via an <see cref="Receiver.OnStreamComplete"/> hook if wanted.
                    ///<para>Such a sink may accept FEWER bytes than offered; <see cref="__put_bytes"/> then parks and is re-driven, and the
                    ///<c>[S(N)]</c> <paramref name="maxStreamBytes"/> cap is charged per ACCEPTED byte, never per offered byte.</para>
                    ///Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(AdHoc.BytesDst dst, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.dst = null;
                        dst_ = dst;
                        _rx = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        failed = false;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(dst, long.MaxValue, id)</c>: uncapped. This is what a
                    ///generated tunnel endpoint arms its receive Adapter with: <c>_Adapter.Init(Internal.BytesDst, id)</c>.
                    ///<para>NOTE the second argument is an <c>int</c> id here, but a <c>long</c> selects the cap overload below — the same
                    ///id/cap split the stream family already has.</para></summary>
                    public Adapter Init(AdHoc.BytesDst dst, int id) => Init(dst, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration with a caller-supplied sink WITHOUT an id — stamps the
                    ///<see cref="int.MinValue"/> sentinel, then delegates to the id-taking primary.</summary>
                    public Adapter Init(AdHoc.BytesDst dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(dst, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(AdHoc.BytesDst dst) => Init(dst, long.MaxValue);
//endregion

                    public BytesDst? redirect;

                    ///<summary>
                    ///Writes the bytes currently available in <c>src.buffer</c> straight to <see cref="dst"/>, then returns
                    ///<c>false</c> to park — the framework's slot.dst dispatch re-drives this instance on the next fill, and the
                    ///surrounding framer decides the stream boundary. When driven as the inner <c>dst</c> of a framer (e.g.
                    ///<see cref="Chunked"/>), the buffer has already been clamped to the current chunk, so only those bytes are written.
                    ///</summary>
                    public virtual bool __put_bytes(Receiver src)
                    {
                        var buf = src.buffer;
                        //Every sink but dst_ drains the whole offered window, so the offer is a safe proxy for consumption and
                        //the cap can be charged (and tripped) up front. dst_ may accept only part of it, so its branch charges
                        //the cap per ACCEPTED chunk instead — otherwise backpressure near the [S(N)] limit would throw spuriously.
                        if (dst_ == null && maxStreamBytes < (_total += src.byte_max - src.byte_))
                            throw overflow(src, "Stream would exceed max size of " + maxStreamBytes + " bytes.");

                        for (;;)
                        {
                            if (redirect != null)
                                if (!redirect.__put_bytes(src))
                                    return false;
                                else
                                    for (redirect = null; src.slot!.dst != null && src.slot.dst.__put_bytes(src); src.slot = src.slot.prev)
                                        if (src.slot == src.streaming_slot)
                                            return true;
                                        else if (src.slot.prev == null)
                                            break;

                            if (src.byte_ >= src.byte_max)
                                break;
                            var position = src.byte_;
                            int n;
                            if (_rx != null) //structured datatype: re-enter the receiver
                            {
                                if (src.mode == STREAM_PACK)
                                    src.mode = src.streaming_mode;
                                n = _rx.write(src.buffer!);
                                src.buffer = buf; //write() nulls buffer at exit; restore for the framer
                            }
                            else if (dst_ != null) //application-level sink: it may accept only PART of the offer
                            {
                                if (failed) //the sink failed earlier in this stream: the rest of it is void, consume it unseen
                                {
                                    n = src.byte_max - src.byte_;
                                    src.byte_ = src.byte_max;
                                }
                                else if ((n = dst_.Write(src.buffer!, src.byte_, src.byte_max - src.byte_)) < 0)
                                {
                                    //The sink threw and reset itself — a Receiver's Write reports that as -1, having consumed
                                    //nothing it would admit to. Its pack in progress is gone, and every byte after it in this
                                    //stream belongs to that pack or to packs behind it: offered again, they would be parsed from
                                    //the middle of a pack (and adding -1 to the cursor would walk it backwards). Consume the rest
                                    //of the stream unseen instead; the next stream starts on a pack boundary.
                                    failed = true;
                                    n = src.byte_max - src.byte_;
                                    src.byte_ = src.byte_max;
                                }
                                else
                                {
                                    src.byte_ += n; //advance by what was ACCEPTED — n == 0 is backpressure, caught as "no progress" below
                                    if (maxStreamBytes < (_total += n))
                                        throw overflow(src, "Stream would exceed max size of " + maxStreamBytes + " bytes.");
                                }
                            }
                            else //plain byte sink
                            {
                                n = src.byte_max - src.byte_;
                                dst!.Write(src.buffer!, src.byte_, n);
                                src.byte_ += n;
                            }

                            if (n == int.MinValue)
                                return true; //wrapped datatype fully decoded
                            if (src.byte_ == position && redirect == null)
                                break; //no progress → yield
                        }

                        src.buffer = buf;
                        return false; //current fill drained — framework re-drives on next fill
                    }
                }
            }

            ///<summary>
            ///Defines an interface for handling events generated by a `Receiver`.
            ///</summary>
            public interface EventsHandler
            {
                ///<summary>
                ///Called when enough bytes have been received to identify the incoming packet type,
                ///but before the entire packet has been deserialized.
                ///</summary>
                ///<param name="src">The `Receiver` instance that identified the packet.</param>
                ///<param name="dst">The `BytesDst` instance corresponding to the identified packet type.</param>
                void OnReceiving(Receiver src, BytesDst dst) {}

                ///<summary>
                ///Called when a complete packet has been successfully received and deserialized.
                ///The packet is now ready for application-level processing.
                ///</summary>
                ///<param name="src">The `Receiver` instance that received the packet.</param>
                ///<param name="dst">The `BytesDst` instance representing the fully deserialized packet.</param>
                void OnReceived(Receiver src, BytesDst dst) {}
            }

            ///<summary>
            ///The current event handler for this receiver.
            ///</summary>
            public EventsHandler handler;

            ///<summary>
            ///Atomically exchanges the current event handler with a new one.
            ///</summary>
            ///<param name="handler">The new event handler to set.</param>
            ///<returns>The event handler that was previously set.</returns>
            public EventsHandler exchange(EventsHandler handler) => Interlocked.Exchange(ref this.handler, handler);

            ///<summary>
            ///Width in bytes of the leading packet-ID field every pack starts with — fixed for a given protocol
            ///(e.g. 1 byte for up to 256 pack types, 2 bytes for more).
            ///</summary>
            public readonly byte id_bytes;

            ///<summary>
            ///Initializes a new instance of the <see cref="Receiver"/> class.
            ///</summary>
            ///<param name="handler">The event handler for receiver events.</param>
            ///<param name="id_bytes">The number of bytes used at the beginning of a packet to identify its type (packet ID).</param>
            public Receiver(EventsHandler handler, int id_bytes)
            {
                this.handler = handler;
                bytes_left = bytes_max = this.id_bytes = (byte)id_bytes;
                root = new Slot(this, null);
            }

            ///<summary>
            ///Process-wide sink for receive-side errors (CRC mismatch, bad ID, overflow, …). Defaults to a
            ///handler that writes to the console; replace it to route errors elsewhere. Shared by all receivers,
            ///so assign once at startup.
            ///</summary>
            ///<summary>A pack or an actor against the roles: the failure handler has heard it, the connection is reset, the receive stops.</summary>
            public static readonly Exception DENIED = new UnauthorizedAccessException("against the roles");

            public static OnErrorHandler error_handler = OnErrorHandler.DEFAULT;

            ///<summary>
            ///Enumerates possible error types that can occur during reception.
            ///</summary>
            public enum OnError
            {
                ///<summary>
                ///Indicates a sequence of 0xFF 0xFF was detected, which is invalid outside of
                ///specific framing contexts or suggests a synchronization issue.
                ///</summary>
                FFFF_ERROR = 0,

                ///<summary>
                ///Indicates a CRC checksum mismatch, suggesting data corruption.
                ///</summary>
                CRC_ERROR = 1,

                ///<summary>
                ///Indicates that the received byte sequence does not conform to the expected
                ///framing or encoding rules, suggesting data corruption or desynchronization.
                ///</summary>
                BYTES_DISTORTION = 3,

                ///<summary>
                ///Indicates a buffer overflow, typically when a declared length exceeds
                ///buffer capacity or a predefined maximum.
                ///</summary>
                OVERFLOW = 4,

                ///<summary>
                ///Indicates that an invalid or unrecognized packet ID was received.
                ///</summary>
                INVALID_ID = 5,

                ///<summary>
                ///A receiving packet is rejected by dataflow or business logic rules.
                ///</summary>
                REJECTED = 6,

                ///<summary>
                ///Error code indicating a timeout during packet transmission or reception.
                ///</summary>
                TIMEOUT = 7,

                ///<summary>
                ///Generic error code for unspecified or unexpected errors during packet processing.
                ///</summary>
                ERROR = 8,

                ///<summary>
                ///Received packets were discarded because they did not satisfy the current
                ///state machine rules or protocol state expectations.
                ///</summary>
                DISCARDED_BYSTATE = 9,

                ///<summary>
                ///Attempted to deliver a received packet to an actor that does not support
                ///receiving messages (no receive behavior / handler defined).
                ///</summary>
                ACTOR_NOT_RECEIVABLE = 10
            }

            ///<summary>
            ///Defines an interface for handling errors that occur in a `Receiver`.
            ///</summary>
            public interface OnErrorHandler
            {
                ///<summary>
                ///A default `OnErrorHandler` implementation that logs errors to the console.
                ///</summary>
                static OnErrorHandler DEFAULT = new ToConsole();

                ///<summary>
                ///A concrete `OnErrorHandler` that writes error information to the console.
                ///</summary>
                class ToConsole : OnErrorHandler
                {
                    ///<summary>
                    ///Handles a `Receiver` error by printing details to the console.
                    ///</summary>
                    ///<param name="src">The `AdHoc.BytesDst` (often a `Receiver.Framing` or `Receiver` itself) where the error occurred.</param>
                    ///<param name="arg">Optional argument context (e.g., the packet being processed).</param>
                    ///<param name="error">The type of error.</param>
                    ///<param name="ex">An optional exception associated with the error.</param>
                    public void error(AdHoc.BytesDst src, object? arg, OnError error, Exception? ex = null)
                    {
                        string label;

                        //Handle all defined error codes
                        switch (error)
                        {
                            case OnError.FFFF_ERROR:
                                label = "FFFF_ERROR";
                                break;
                            case OnError.CRC_ERROR:
                                label = "CRC_ERROR";
                                break;
                            case OnError.BYTES_DISTORTION:
                                label = "BYTES_DISTORTION";
                                break;
                            case OnError.OVERFLOW:
                                label = "OVERFLOW";
                                break;
                            case OnError.INVALID_ID:
                                label = "INVALID_ID";
                                break;
                            case OnError.REJECTED:
                                label = "REJECTED";
                                break;
                            case OnError.TIMEOUT:
                                label = "TIMEOUT";
                                break;
                            case OnError.ERROR:
                                label = "GENERIC_ERROR";
                                break;
                            case OnError.DISCARDED_BYSTATE:
                                label = "DISCARDED_BYSTATE";
                                break;
                            case OnError.ACTOR_NOT_RECEIVABLE:
                                label = "ACTOR_NOT_RECEIVABLE";
                                break;
                            default:
                                label = $"UNKNOWN_ERROR ({error})";
                                break;
                        }

                        //Generate stack trace info: if exception is missing, print current stack trace
                        var traceInfo = ex == null ? Environment.StackTrace : ex.ToString();

                        //Include arg info if present
                        var argInfo = arg != null ? $"\nArg: {arg}" : "";

                        Console.WriteLine($"{label} at {src}{argInfo}\n{traceInfo}");
                    }
                }

                ///<summary>
                ///Handles a `Receiver` error.
                ///</summary>
                ///<param name="src">The `AdHoc.BytesDst` (often a `Receiver.Framing` or `Receiver` itself) where the error occurred.</param>
                ///<param name="arg">Optional context argument.</param>
                ///<param name="error">The type of error.</param>
                ///<param name="ex">An optional exception associated with the error.</param>
                void error(AdHoc.BytesDst src, object? arg, OnError error, Exception? ex = null);
            }

            ///<summary>
            ///The framing decoder of a byte stream: COBS ( Consistent Overhead Byte Stuffing ) with 0xFF as the delimiter.
            ///0xFF starts a pack and comes nowhere else: the bytes of the pack and its CRC-32C ( 4 bytes, the high one first )
            ///come as blocks, none of their bytes 0xFF: [c][c bytes], c 0..253, implies a 0xFF of the data after it, but for
            ///the last block of the pack; a long block [254][l0][l1][l0 + 255 * l1 bytes], l0 and l1 0..254, implies none.
            ///Every byte is looked at for 0xFF, whatever the blocks say: a distortion loses only the pack it hit, the next 0xFF
            ///starts the next one. The bytes go to the <c>upper_layer</c> where they lie, as they come; the pack goes to the
            ///application once its CRC matched.
            ///</summary>
            public class Framing : AdHoc.BytesDst, EventsHandler
            {
                public bool isOpen() => upper_layer.isOpen();

                ///<summary>
                ///The `Receiver` instance that will process the decoded frames from this framing layer.
                ///</summary>
                public Receiver upper_layer; //Provides external interface for decoded receiving data

                ///<summary>
                ///Handles events for decoded frames, typically forwarding them to the original handler of the `upper_layer` before it was hooked by this framing instance.
                ///</summary>
                public EventsHandler handler; //Handles decoded frame events for upper layer

                ///<summary>
                ///Atomically exchanges the current event handler with a new one.
                ///</summary>
                ///<param name="handler">The new event handler to set.</param>
                ///<returns>The event handler that was previously set.</returns>
                public EventsHandler exchange(EventsHandler handler) => Interlocked.Exchange(ref this.handler, handler);

                ///<summary>
                ///Initializes a new instance of the <see cref="Framing"/> class.
                ///</summary>
                ///<param name="upper_layer">The `Receiver` instance that will process the decoded frames.</param>
                public Framing(Receiver upper_layer) => switch_to(upper_layer);

                ///<summary>
                ///Switches the framing layer to operate on a new `upper_layer` receiver.
                ///This also resets the internal state of the framing decoder and hooks its event handling into the new `upper_layer`.
                ///</summary>
                ///<param name="upper_layer">The new `Receiver` instance to process decoded frames.</param>
                public void switch_to(Receiver upper_layer)
                {
                    Reset();
                    seek = true;

                    if (this.upper_layer != null)
                    {
                        this.upper_layer.reset();
                        this.upper_layer.exchange(handler); //off hook
                        this.upper_layer.framed = false;
                    }

                    handler = (this.upper_layer = upper_layer).exchange(this);
                    upper_layer.framed = true;
                }

                ///<summary>
                ///Reports an error and drops the pack in flight: in the `upper_layer` too - a pack id read in part as well -,
                ///or the next pack would go on with it.
                ///</summary>
                ///<param name="error">The type of error to report.</param>
                void error_reset(OnError error)
                {
                    error_handler.error(this, null, error);
                    upper_layer.Abandon();
                    Reset();
                }

                public void Close()
                {
                    Reset();
                    seek = true;
                    upper_layer.Close();
                }

                ///<summary>
                ///Forgets the pack in flight: its CRC, where its blocks are.
                ///</summary>
                void Reset()
                {
                    crc = 0;
                    crc_from = -1;
                    if (waiting_for_dispatching_pack != null)
                    {
                        //the pack waited for its CRC: dropped, so is the capture of its bytes
                        var copy = upper_layer.bytesCopy;
                        if (copy != null)
                        {
                            upper_layer.bytesCopy = null;
                            copy.fail(upper_layer);
                        }

                        waiting_for_dispatching_pack = null;
                    }

                    left = 0;
                    length = 0;
                    implied = false;
                }

                ///<summary>
                ///Decodes the framed bytes in <paramref name="src"/> where they lie - a code becomes the 0xFF of the data it
                ///implies, or is taken out between two runs - and hands the runs to the <c>upper_layer</c>.
                ///<para>ATTENTION! <paramref name="src"/> is borrowed and may be overwritten after this returns.</para>
                ///</summary>
                public int Write(byte[] src, int src_byte, int src_bytes)
                {
                    if (src_bytes < 1)
                        return 0;

                    int limit = src_byte + src_bytes, p = src_byte, from = p; //the wire bytes taken; where the run being taken starts
                    for (;;)
                    {
                        var ff = src.AsSpan(p, limit - p).IndexOf((byte)0xFF); //vectorized: where the bytes of this pack end in the window
                        ff = ff < 0 ? limit : p + ff;
                        if (seek)
                        {
                            if (after && p < ff) //bytes behind a pack, before the 0xFF of the next one: a 0xFF distorted, a pack lost
                            {
                                after = false;
                                error_handler.error(this, null, OnError.BYTES_DISTORTION);
                            }
                        }
                        else
                            while (p < ff)
                                if (0 < left) //the bytes of a block stay where they are
                                {
                                    var n = Math.Min(left, ff - p);
                                    p += n;
                                    left -= n;
                                }
                                else if (0 < length) //a byte of the length of a long block: taken out between two runs
                                {
                                    deliver(src, from, p);
                                    if (length == 2)
                                        low = src[p];
                                    else
                                        left = low + 255 * src[p];
                                    length--;
                                    from = ++p;
                                }
                                else //a code: the 0xFF the block before implies goes in its place, else it is taken out between two runs
                                {
                                    var c = src[p];
                                    if (implied)
                                        src[p] = 0xFF;
                                    else
                                    {
                                        deliver(src, from, p);
                                        from = p + 1;
                                    }

                                    p++;
                                    started = true;
                                    if (c < 254)
                                    {
                                        left = c;
                                        implied = true;
                                    }
                                    else
                                    {
                                        length = 2;
                                        implied = false;
                                    }
                                }

                        if (ff == limit)
                            break;
                        //0xFF: a pack starts
                        if (!seek)
                            deliver(src, from, ff); //a whole pack ends there: its CRC checked, the bytes skipped from then on
                        if (!seek)                  //the pack was not whole
                            if (started)
                                error_reset(OnError.BYTES_DISTORTION); //its id, body or CRC
                            else
                                error_handler.error(this, null, OnError.FFFF_ERROR); //no byte of it at all
                        else if (!upper_layer.idle())                                //bytes behind a pack - its CRC did not match, or the 0xFF of the next one was distorted - the receiver took for a pack
                        {
                            if (after)
                                error_handler.error(this, null, OnError.BYTES_DISTORTION);
                            upper_layer.Abandon();
                        }

                        Reset();
                        seek = false;
                        after = false;
                        started = false;
                        from = p = ff + 1;
                    }

                    if (!seek)
                        deliver(src, from, limit);
                    return src_bytes;
                }

                ///<summary>
                ///Hands the decoded bytes [<paramref name="from"/>, <paramref name="to"/>) of <paramref name="src"/> on: the CRC of
                ///a whole pack first, then the <c>upper_layer</c>; the bytes it takes go into the CRC.
                ///</summary>
                void deliver(byte[] src, int from, int to)
                {
                    while (from < to && waiting_for_dispatching_pack != null)
                        getting_crc(src[from++]);
                    if (to <= from || seek)
                        return;
                    crc_from = from;
                    var n = upper_layer.Write(src, from, to - from);
                    if (n < 0) //the receiver gave up on the pack ( an id it cannot dispatch ): the rest of it is of none
                    {
                        Reset();
                        seek = true;
                    }
                    else if (0 <= crc_from) //the pack goes on: its bytes so far ( none when it ended in OnReceived )
                        crc = crc32c(crc, src.AsSpan(crc_from, n));

                    crc_from = -1;
                }

                public void OnReceiving(Receiver src, BytesDst dst) => Volatile.Read(ref handler)?.OnReceiving(src, dst);

                public void OnReceived(Receiver src, BytesDst pack)
                {
                    if (0 <= crc_from) //the last bytes of the pack
                        crc = crc32c(crc, src.buffer.AsSpan(crc_from, src.byte_ - crc_from));
                    crc_from = -1;
                    pack_crc = 0;
                    pack_crc_byte = CRC_LEN_BYTES - 1;
                    waiting_for_dispatching_pack = pack;

                    while (0 < src.remaining && waiting_for_dispatching_pack != null)
                        getting_crc(src.get_byte());
                }

                BytesDst? waiting_for_dispatching_pack;

                ///<summary>The pack waiting for its CRC: it matched, to the application.</summary>
                void dispatch()
                {
                    var pack = waiting_for_dispatching_pack!;
                    upper_layer.checked_received(pack);
                    handler?.OnReceived(upper_layer, pack);
                    upper_layer.bytesCopy = null; //the pack is dispatched: its capture is the application's now
                }

                ///<summary>
                ///Takes the next byte of the CRC of the pack received, the high byte first; the last one checks it: the
                ///pack goes to the application or is dropped. The bytes up to the next pack are of none.
                ///</summary>
                ///<param name="crc_byte">The next byte of the CRC value being received from the stream.</param>
                void getting_crc(int crc_byte)
                {
                    pack_crc |= (uint)crc_byte << pack_crc_byte * 8;

                    pack_crc_byte--;
                    if (-1 < pack_crc_byte)
                        return; //need more

                    if (crc == pack_crc)
                        dispatch(); //dispatching
                    else
                        error_handler.error(this, null, OnError.CRC_ERROR); //bad CRC

                    Reset();
                    seek = true;
                    after = true;
                }

                int left;          //The bytes left in the block being received: 0 - the next byte is a code.
                int length;        //The bytes of the length of a long block left to come: 2, 1 or 0.
                int low;           //The low byte of the length of a long block.
                bool implied;      //The block before was a short one: a 0xFF of the data comes before the next block.
                bool started;      //A byte of the pack came after its 0xFF.
                bool seek = true;  //The bytes up to the next 0xFF are skipped: at the start, after a pack, after a distortion.
                bool after;        //A pack ended: a byte before the next 0xFF is told as a distortion.
                uint pack_crc;     //CRC value read from the incoming packet.
                uint crc;          //CRC-32C of the decoded bytes of the pack so far.
                int crc_from = -1; //Where the bytes of the pack start in the decoded bytes the `upper_layer` is writing: -1 - none.
                int pack_crc_byte; //Counter for bytes received for `pack_crc`.
            }
#region Slot
            ///<summary>
            ///One frame on the deserialization stack. Each nested pack/collection being read gets its own slot;
            ///the slots form a doubly-linked chain (<see cref="prev"/>/<see cref="next"/>) so the receiver can
            ///descend into a nested structure and pop back out without allocating per packet — slots are reused
            ///across packs. A slot carries the in-progress <see cref="dst"/> handler, the resume <c>state</c>, and
            ///the <see cref="fields_nulls"/> null-field bitmap for its level.
            ///</summary>
            internal class Slot : Base_.Receiver.Slot
            {
                ///<summary>
                ///The packet/field handler currently consuming bytes at this nesting level.
                ///</summary>
                public BytesDst dst;

                public BytesDst dst_(BytesDst dst)
                {
                    state = 0;
                    return this.dst = dst;
                }

                ///<summary>
                ///Bitmap of which optional fields at this level are present: one bit per nullable field, read up
                ///front so the deserializer can skip absent ones. See <see cref="get_fields_nulls"/>.
                ///</summary>
                public int fields_nulls;

                ///<summary>
                ///Gets the `BytesDst` instance from the `next` slot in the chain, cast to the specified type `DST`.
                ///</summary>
                ///<typeparam name="DST">The expected type of the `BytesDst` in the next slot.</typeparam>
                ///<returns>The `BytesDst` from the next slot, cast to `DST`.</returns>
                public DST get_bytes<DST>() => (DST)next.dst;

                internal Slot next;
                internal readonly Slot? prev;

                ///<summary>
                ///Initializes a new instance of the <see cref="Slot"/> class.
                ///</summary>
                ///<param name="dst">The `Receiver` associated with this slot chain.</param>
                ///<param name="prev">The previous slot in the chain, or null if this is the root slot.</param>
                public Slot(Receiver dst, Slot? prev) : base(dst)
                {
                    this.prev = prev;
                    if (prev != null)
                        prev.next = this;
                }
            }

            internal Slot? slot;

            ///<summary>
            ///Root of the slot chain: the slot every packet starts at, and the anchor of the nested slots grown
            ///from it. Held strongly — a chain level is a handful of ints plus <see cref="Slot.dst"/>, which the
            ///packet drops when it ends, so the WeakReference it replaced bought no memory back and cost a
            ///tracked deref on every packet.
            ///</summary>
            internal readonly Slot root;

            internal Slot? streaming_slot; //completion boundary for Write
            internal uint streaming_mode;  //the pre-park mode saved on entering STREAM_PACK

            ///<summary>
            ///Resumes the stream parked in STREAM_PACK mode and tells how it went. Negative: still parked, more bytes
            ///needed. 0: the stream ended and the pack around it goes on. Positive: the stream was the packet itself
            ///(its slot is the root), which is now complete - dispatch it. Only the generated chain knows which: the answer is
            ///the slot of the stream it drives, neither the current <c>slot</c> (where the pack inside the stream
            ///stopped) nor <c>streaming_slot</c> (the innermost of nested streams, while the outer one is what ends here).
            ///</summary>
            public virtual int unpark() => 1;
#endregion

            ///<summary>
            ///Reads a byte from the buffer and stores it as `fields_nulls` in the current slot.
            ///This byte is typically a bitmask indicating null fields for a message.
            ///</summary>
            ///<param name="this_case">The state to set for retry if not enough bytes are available.</param>
            ///<returns>True if the byte was read successfully; false if a retry is needed due to insufficient data.</returns>
            public bool get_fields_nulls(uint this_case)
            {
                if (byte_ < byte_max)
                {
                    slot!.fields_nulls = buffer![byte_++];
                    return true;
                }

                slot!.state = this_case;
                mode = RETRY;
                return false;
            }

            ///<summary>
            ///Checks if a specific field is marked as null based on the `fields_nulls` bitmask in the current slot.
            ///</summary>
            ///<param name="field">The bit representing the field to check (e.g., a power of 2).</param>
            ///<returns>True if the field's corresponding bit is NOT set in `fields_nulls` (meaning it is null, by convention where 0 means null); false otherwise.</returns>
            public bool is_null(int field) => (slot!.fields_nulls & field) == 0;

            ///<summary>
            ///Reads a byte. If the byte is 0 (null indicator), returns false.
            ///Otherwise, updates `u8_` by ORing the byte value shifted by `shift`, sets `u8` to this new `u8_` value, and returns true.
            ///</summary>
            ///<param name="shift">The number of bits to left-shift the byte value before ORing with `u8_`.</param>
            ///<returns>False if the read byte is 0; true otherwise.</returns>
            public bool byte_nulls(byte shift)
            {
                u4 = get_byte();
                if (u4 == 0)
                    return false;
                u8 = u8_ |= (ulong)u4 << shift;
                return true;
            }

            ///<summary>
            ///Reads a byte. If the byte is 0 (null indicator), returns false.
            ///Otherwise, `null_value` is ORed into `u8_`, `u8` is updated to this new `u8_` value, and the method returns true.
            ///This is used when a non-zero byte indicates presence, and `null_value` itself carries the presence flag for `u8_`.
            ///</summary>
            ///<param name="null_value">The value to OR into `u8_` if the read byte is not 0.</param>
            ///<returns>False if the read byte is 0; true otherwise.</returns>
            public bool byte_nulls(ulong null_value)
            {
                u4 = get_byte();
                if (u4 == 0)
                    return false;

                u8 = u8_ |= null_value;
                return true;
            }

            ///<summary>
            ///Reads a byte. If the byte is 0 (null indicator), returns false.
            ///Otherwise, if the byte is 0xFF, `null_value` is ORed into `u8_`.
            ///If the byte is neither 0 nor 0xFF, the byte value (shifted by `shift`) is ORed into `u8_`.
            ///In either non-zero case, `u8` is updated to the new `u8_` value, and the method returns true.
            ///</summary>
            ///<param name="shift">The number of bits to left-shift the byte value if it's not 0 or 0xFF.</param>
            ///<param name="null_value">The value to OR into `u8_` if the read byte is 0xFF.</param>
            ///<returns>False if the read byte is 0; true otherwise.</returns>
            public bool byte_nulls(byte shift, ulong null_value)
            {
                u4 = get_byte();
                if (u4 == 0)
                    return false;

                u8 = u8_ |= u4 == 0xFF ? null_value : (ulong)u4 << shift;
                return true;
            }

            ///<summary>
            ///Checks if the receiver is currently idle, meaning it's not in the middle of processing a packet.
            ///</summary>
            ///<returns>True between packs: no pack, nor a pack id, received in part; false otherwise.</returns>
            public bool idle() => slot?.dst == null && bytes_left == id_bytes; //between packets — the slot chain itself outlives the packet

            ///<summary>
            ///Attempts to read up to 4 bytes into `u4`. If fewer than `bytes_left` bytes are available,
            ///it reads what's available, updates `u4` partially, and decrements `bytes_left`.
            ///</summary>
            ///<returns>True if more bytes are still needed to complete the 4-byte read (i.e., `bytes_left` was not fully satisfied); false if 4 bytes (or the original `bytes_left` requirement) have been read into `u4`.</returns>
            bool not_get4()
            {
                if (remaining < bytes_left)
                {
                    var r = remaining;
                    u4 |= get4<uint>(r) << (bytes_max - bytes_left) * 8;
                    bytes_left -= r;
                    return true;
                }

                u4 |= get4<uint>(bytes_left) << (bytes_max - bytes_left) * 8;
                return false;
            }

            ///<summary>
            ///Abstract method to obtain a `BytesDst` handler suitable for deserializing a packet of the given `id`.
            ///This method is called after a packet ID has been read from the stream.
            ///</summary>
            ///<param name="id">The packet identifier.</param>
            ///<returns>A `BytesDst` instance capable of deserializing the identified packet type.</returns>
            ///<exception cref="Exception">Typically thrown if the `id` is unknown or invalid.</exception>
            protected abstract BytesDst _OnReceiving(int id); //throws Exception if wrong id

            protected abstract void _OnReceived(BytesDst received);

            ///<summary>A pack whose CRC matched: the <see cref="Framing"/> above dispatches it.</summary>
            internal void checked_received(BytesDst received) => _OnReceived(received);

            public bool isOpen() => slot?.dst != null; //a packet is being assembled right now

            ///<summary>
            ///Ends the session: leaves the receiver holding nothing from the connection that just died, and armed
            ///for a packet id — the state the next tenant of a pooled connection has to start from.
            ///<para>Runs unconditionally, unlike <see cref="reset"/>: the receiver is idle with <c>slot == null</c>
            ///while a packet id is split across two reads, and that half-assembled id sits in <c>u4</c> /
            ///<c>bytes_left</c>, where the next tenant's <c>not_get4</c> would OR its own id into it.</para>
            ///</summary>
            public virtual void Close()
            {
                reset();

                if (bytesCopy != null)
                {
                    bytesCopy.fail(this);
                    bytesCopy = null;
                }

                bytes_left = bytes_max = id_bytes; //Arm the packet id read
                u4 = 0;
                u8_ = 0;
                mode = OK;
                buffer = null;
                guarded_from = -1; //the session is over: a guaranteed pack in progress is not received, the position stays at its start
                greeting = false;
                control?.silent();
                str = null;

                if (chs != null)
                {
                    ArrayPool<char>.Shared.Return(chs);
                    chs = null;
                }

                streaming_slot = null; //The root slot is reused, so a value left by a torn-down chain would
                streaming_mode = OK;   //falsely match `slot == streaming_slot`

                clear(); //Generator-emitted registers
                for (var s = root; s != null; s = s.next)
                    s.clear();
            }

            ///<summary>
            ///The rest of the pack in progress will never arrive: the tunnel stream carrying it ended as void
            ///(<see cref="Transmitter.Chunked.ABORT"/>) or its carrier was lost. Drops that pack — including a pack id
            ///read only in part — and waits for a pack id again. The session itself is untouched: the next tunnel
            ///stream for this receiver starts on a pack boundary.
            ///</summary>
            ///<summary>
            ///The socket of a stream under the session is gone, and the session parks: as a datagram lost on UDP, the guaranteed
            ///pack in progress stays with the bytes of it received, counted in <see cref="received"/>. On the next socket the
            ///packs the two sides agree by come first ( <see cref="greeting"/> ): the pack goes on from the byte it was cut at, or
            ///is dropped when the peer's journal does not hold it any more. Anything else in progress will never be completed:
            ///dropped now. What was to be said on the socket goes with it. A session that does not go on is closed when its wait
            ///runs out ( <see cref="Close"/> ).
            ///</summary>
            public void Suspend()
            {
                buffer = null;
                if (control == null)
                {
                    Abandon();
                    return;
                }

                control.silent();
                if (positioned && 0 <= guarded_from && slot?.dst != null && (greeter_ ??= greeter()) != null)
                {
                    greeting = true;
                    greeter_.Abandon(); //what it read of the last socket is not of this one
                }
                else
                    Abandon();
            }

            public void Abandon()
            {
                reset();
                bytes_left = bytes_max = id_bytes; //reset() leaves a half-read pack id alone when no pack was dispatched yet
                u4 = 0;
                mode = OK;
                buffer = null;
                streaming_slot = null; //a streamed pack abandoned mid-body: as in Close, a value left by its torn-down chain
                streaming_mode = OK;   //would match the reused root slot and end the next pack at its first bytes
                guarded_from = -1;     //the bytes of a guaranteed pack dropped half-way are not received: the position stays at its start
                greeting = false;
            }

            ///<summary>
            ///Rewinds the packet in flight and releases the borrowed buffer. Error and session path.
            ///<para>Overridable: a generated streaming receiver overrides it to release its active chain first,
            ///then calls <c>base.reset()</c>.</para>
            ///</summary>
            protected virtual void reset()
            {
                if (slot == null)
                    return;
                if (bytesCopy != null)
                {
                    bytesCopy.fail(this);
                    bytesCopy = null;
                }

                for (var s = slot; s != null; s = s.next)
                {
                    //A tunnel packet abandoned mid-body. Its bytes went somewhere that keeps state across packets, and
                    //that state now sits in the middle of a pack that will never be completed:
                    if (s.dst is AdHoc.Connection.Tunnel.Relay relay) //a relay: its parse state and the outbound pack in flight
                        relay.InboundLost();
                    else if (s.dst is Chunked { isTunnel : true } tunnel) //a tunnel end: the virtual connection's receiver
                        tunnel.abandon();
                    s.dst = null;
                }

                slot = null;

                buffer = null;
                mode = OK;
                bytes_left = bytes_max = id_bytes; //Re-arm the packet id read: an error can land here mid-value
                u4 = 0;
                //dont set   u8 = 0; preserve probably a value pack data for framing layer.
                //dont set   str = null; preserve probably a value pack data for framing layer.
            }

            ///<summary>
            ///Defines an interface for intercepting raw bytes from the stream as they are processed by the <see cref="Receiver"/>.
            /// It is designed to solve a specific performance bottleneck: <b>"The Serialization Tax."</b> Usually, when a server receives a packet and needs to forward it to others, it has to:
            /// <para>
            ///  1. Receive Bytes --> 2. Deserialize to Object --> 3. Inspect/Save --> 4. Re-serialize Object --> 5. Send Bytes.
            /// </para>
            ///This code allows the system to do:
            /// <para>
            ///  1. Receive Bytes --> 2. <b>Capture Raw Bytes (simultaneously)</b> --> 3. Forward Raw Bytes (Skip step 2, 3 and 4).
            /// </para>
            ///<para>
            ///This is primarily used for "tapping" the byte stream for proxying, mirroring, or logging raw packet data without needing to re-serialize the object.
            ///</para>
            ///</summary>
            public interface BytesCopy : Transmitter.Broadcastable
            {
                ///<summary>
                ///Called when the <see cref="Receiver.Write"/> method is about to return, but the packet is not yet complete.
                ///This provides a chunk of raw bytes that have been consumed so far.
                ///</summary>
                ///<param name="r">The receiver instance providing the data.</param>
                ///<param name="offset">The offset in the receiver's current buffer where this chunk starts.</param>
                ///<param name="count">The number of bytes in this chunk.</param>
                void pass(Receiver r, int offset, int count);

                ///<summary>
                ///Called when the packet has been fully received and deserialized.
                ///This provides the final chunk of raw bytes for the packet.
                ///After this call, the <see cref="Receiver.bytesCopy"/> is automatically cleared (set to null).
                ///</summary>
                ///<param name="r">The receiver instance providing the data.</param>
                ///<param name="offset">The offset in the receiver's current buffer where this chunk starts.</param>
                ///<param name="count">The number of bytes in this chunk.</param>
                void last(Receiver r, int offset, int count);

                ///<summary>
                ///Called if the receiver is reset (due to error, timeout, or connection close) before the packet completes.
                ///Implementations should discard any partially captured data.
                ///After this call, the <see cref="Receiver.bytesCopy"/> is automatically cleared.
                ///</summary>
                ///<param name="r">The receiver instance.</param>
                void fail(Receiver r);

                ///<summary>
                ///A high-performance buffer manager that implements <see cref="BytesCopy"/> for capturing data
                ///and <see cref="Transmitter.BytesSrc"/> for replaying data.
                ///</summary>
                public class InMemory : BytesCopy
                {
                    ///<summary>
                    ///Internal buffer holding the reconstructed Packet ID followed by the Body.
                    ///Resizes dynamically as data is appended.
                    ///</summary>
                    protected byte[] bytes = new byte[128];

                    ///<summary>
                    ///The current number of valid bytes stored in <see cref="bytes"/>.
                    ///This acts as the write-head during capture and the end-of-stream marker during transmission.
                    ///</summary>
                    protected volatile int bytes_count;

                    //The internal counter.
                    protected int sending;

                    public int Acquire() => Interlocked.Increment(ref sending);

                    ///<summary>One atomic step for the references of all the subscribers of a broadcast.</summary>
                    public int Acquire(int n) => Interlocked.Add(ref sending, n);

                    public int State() => sending;

                    public int Release() => Release(1);

                    public int Release(int n)
                    {
                        int current;
                        while (n <= (current = Volatile.Read(ref sending)))
                            if (Interlocked.CompareExchange(ref sending, current - n, current) == current)
                            {
                                if (current == n)
                                    pool.Release(this);
                                return current - n;
                            }

                        return -1; //more than is held: nothing is changed
                    }

                    ///<summary>
                    ///Implementation of <see cref="Transmitter.BytesSrc"/>: Replays the captured raw bytes into a Transmitter.
                    ///This is called in separate thread repeatedly by the <see cref="Transmitter"/> until the entire buffer is sent.
                    ///</summary>
                    ///<param name="dst">The destination transmitter.</param>
                    ///<returns>True if the entire buffer has been consumed by this transmitter; otherwise, false.</returns>
                    public bool __get_bytes(Transmitter dst)
                    {
                        if (State() == 0)
                            throw new ObjectDisposedException("Reusing released InMemory object");
                        var __slot = dst.slot;
                        try
                        {
                            switch (__slot.state)
                            {
                                case 0:
                                    if (!dst.put_val((ulong)(__id & int.MaxValue), id_bytes, 1))
                                        return false;
                                    goto case 1;
                                case 1:

                                    //Calculate how many bytes we can copy in this specific chunk based on transmitter's available buffer space
                                    var len = Math.Min(bytes_count - (int)dst.stream_byte, dst.remaining);

                                    //Copy data from our internal storage to the network buffer
                                    copyBytes(bytes, (int)dst.stream_byte, dst.buffer!, dst.byte_, len);

                                    //Advance the transmitter's buffer pointer
                                    dst.byte_ += len;

                                    //Advance the per-transmitter seek pointer and check if transmission is complete
                                    if ((dst.stream_byte += (ulong)len) != (ulong)bytes_count)
                                    {
                                        __slot.state = 1;
                                        return false;
                                    }

                                    //Once this specific destination is finished, decrement reference count
                                    Release();

                                    return true;
                            }
                        }
                        catch (Exception e)
                        {
                            Release();
                            throw;
                        }

                        return true;
                    }

                    ///<summary>
                    ///Orchestrates the transfer of data from this source into a <see cref="Transmitter"/>'s buffer.
                    /// Can be overridden for specialized I/O (e.g., direct DMA or file-to-socket transfers).
                    ///</summary>
                    ///<param name="src">The internal byte array containing the payload.</param>
                    ///<param name="src_byte">The starting index (offset) within the source array.</param>
                    ///<param name="dst">The destination network buffer.</param>
                    ///<param name="dst_byte">The starting index within the destination buffer.</param>
                    ///<param name="bytes">The total number of bytes to copy in this operation.</param>
                    public virtual void copyBytes(byte[] src, int src_byte, byte[] dst, int dst_byte, int bytes) { Array.Copy(src, src_byte, dst, dst_byte, bytes); }

                    ///<summary>
                    ///Internal storage for the Packet ID.
                    ///</summary>
                    protected int id;

                    ///<summary>
                    ///Gets the Packet ID. The value is marked with a bitmask to distinguish <see cref="BytesCopy"/>
                    ///packets from standard serialized objects.
                    ///</summary>
                    public int __id => id;

                    ///<inheritdoc/>
                    public void pass(Receiver r, int offset, int len) => append(r.buffer!, offset, len);

                    ///<inheritdoc/>
                    public virtual void last(Receiver r, int offset, int len) => append(r.buffer!, offset, len);

                    ///<inheritdoc/>
                    public virtual void fail(Receiver r)
                    {
                        bytes_count = 0;
                        //Force release all references if the reception failed
                        while (0 < Release())
                            ;
                    }

                    ///<summary>
                    ///Appends data to the internal buffer, expanding it in powers of two if necessary.
                    ///</summary>
                    ///<param name="src">Source buffer from the Receiver.</param>
                    ///<param name="offset">Start index in source.</param>
                    ///<param name="len">Length of data to append.</param>
                    protected void append(byte[] src, int offset, int len)
                    {
                        if (len == 0)
                            return;

                        var required = bytes_count + len;

                        if (bytes.Length < required)
                            Array.Resize(ref bytes, Math.Max(required, bytes.Length * 2));

                        Array.Copy(src, offset, bytes, bytes_count, len);
                        bytes_count += len;
                    }

                    ///<summary>
                    ///Acquires a pooled instance and attaches it to the <see cref="Receiver"/> to begin interception.
                    ///</summary>
                    public static void Acquire(int id, Receiver dst) => Acquire(pool, id, dst);

                    ///<summary>
                    ///Acquires an instance from a specific pool and reconstructs the Packet ID header.
                    ///</summary>
                    ///<remarks>
                    ///Note: The Receiver has already read the ID by the time we attach. We must manually
                    ///write the ID back into the start of the buffer so the forwarded packet is complete.
                    ///</remarks>
                    public static void Acquire(Pool<InMemory> src, int id, Receiver dst)
                    {
                        var copy = src.Acquire();
                        //The reference of the capture: it keeps the object while the pack is received and broadcast,
                        //and Broadcaster.Broadcast( Receiver ) gives it back after the walk.
                        copy.Acquire();
                        //Apply bitmask (int.MinValue) to signify this packet is a raw byte copy.
                        copy.id = id | int.MinValue;
                        copy.id_bytes = dst.id_bytes;
                        copy.bytes_count = 0;
                        //Register copy as the interceptor for the receiver.
                        dst.bytesCopy = copy;
                    }

                    ///<summary>
                    ///Number of bytes used for the Packet ID header (e.g., 1, 2, 4).
                    ///</summary>
                    protected int id_bytes;

                    protected InMemory() {}

                    ///<summary>
                    ///Initializes the static object pool for <see cref="InMemory"/> instances.
                    ///</summary>
                    public static void InitPool(int power2poolSize) { pool = new Pool<InMemory>(power2poolSize, () => new InMemory()); }

                    protected static Pool<InMemory> pool;
                }
            }

            ///<summary>
            ///The active write hook. Set this property to capture raw bytes for the *current* packet being received.
            ///<para>
            ///<b>Lifecycle:</b><br/>
            ///1. Assign this field inside <see cref="EventsHandler.OnReceiving"/>.<br/>
            ///2. The hook receives data via <see cref="BytesCopy.pass"/> (partial) or <see cref="BytesCopy.last"/> (final).<br/>
            ///3. Upon <see cref="BytesCopy.last"/> or <see cref="BytesCopy.fail"/>, this field is automatically reset to <c>null</c>.
            ///</para>
            ///<para>
            ///<b>Important Note on Packet IDs:</b><br/>
            ///Since this hook is typically enabled in <c>OnReceiving</c>, the Packet ID bytes have <i>already</i> been consumed from the stream
            ///and will <b>not</b> be passed to the hook. To capture a full, replayable packet, you must manually write the
            ///Packet ID (available via the <c>dst.__id</c> or the <see cref="id_bytes"/> logic) to your output before capturing the body.
            ///</para>
            ///</summary>
            public BytesCopy? bytesCopy;

            ///<summary>
            ///Where the capture of the current pack starts in the buffer being written: after the pack id, unless the generated
            ///receiver defers it (-1) until the pack's transport headers are consumed and then points it at the body.
            ///</summary>
            public int bytesCopyOffset;

            ///<summary>
            ///Main inbound entry point: consume <paramref name="src_bytes"/> bytes from <paramref name="src"/>
            ///starting at <paramref name="src_byte"/>, advancing the deserialization state machine as far as they
            ///allow. Reads a packet ID when starting a fresh pack, dispatches to its handler, resumes any value
            ///parked by an earlier call (per <see cref="mode"/>), and fires the <c>OnReceiving</c>/<c>OnReceived</c>
            ///events as packs begin and complete. If the buffer is exhausted mid-value the machine simply parks;
            ///the next call picks up where it left off.
            ///<para>ATTENTION! <paramref name="src"/> is borrowed and may be overwritten after this returns.</para>
            ///</summary>
            ///<returns>The number of bytes consumed from <paramref name="src"/>.</returns>
            public int Write(byte[] src, int src_byte, int src_bytes)
            {
                var top = buffer == null; //a nested chain re-enters with its decoded bytes: not counted
                if (top)
                    _consumed -= src_byte;
                var entry = src_byte;
                if (greeting)
                {
                    buffer = src;
                    byte_max = (byte_ = src_byte) + src_bytes;
                    if (!greet())
                        return exit(top, -1);
                    src_bytes = byte_max - byte_;
                    src_byte = byte_;
                }

                if (0 <= bytesCopyOffset)
                    bytesCopyOffset = src_byte;
                for (buffer = src, byte_max = (byte_ = src_byte) + src_bytes; byte_ < byte_max;)
                {
                    try
                    {
                        if (slot?.dst == null)
                            try
                            {
                                if (not_get4())
                                    goto exit;                   //read id
                                bytesCopyOffset = byte_;         //the pack id is consumed: the capture starts here, unless _OnReceiving defers it
                                var dst = _OnReceiving((int)u4); //throws Exception if wrong id
                                slot = root;

                                slot.dst = dst;
                                slot.state = 0;
                                u8_ = 0; //Null-flags accumulator: byte_nulls / null_value OR into it
                                Volatile.Read(ref handler)?.OnReceiving(this, dst);
                                if (slot == null)
                                    return exit(top, -1); //receiving event handler has reset this
                            }
                            catch (Exception ex)
                            {
                                if (ex == DENIED)
                                {
                                    Abandon();
                                    buffer = null;
                                    return exit(top, -1);
                                }
                                //An id we cannot dispatch means the byte stream is desynchronized or hostile: every
                                //subsequent byte offset is untrustworthy, so there is nothing left to parse on this
                                //session. Record the event, tear the transport down, then drop our own state.
                                //report BEFORE reset() — after a reset `this` prints as "slot === undefined" (Java order)
                                error_handler.error(this, null, OnError.INVALID_ID, ex);
                                if (!framed)
                                    ext_connection?.lost(); //the channel is compromised: dropped like a broken link, the session may park
                                Abandon();                  //the pack id too: the next pack is read from its id ( framed, at the next 0xFF )
                                buffer = null;              //Release buffer reference: this return skips the common exit below
                                //Negative, like any other give-up: the rest of this input is not to be offered again. A caller
                                //that kept offering it would get one more INVALID_ID per garbage "id", and a tunnel end would
                                //feed the rest of a stream it can no longer parse into a receiver waiting for a pack id.
                                return exit(top, -1);
                            }
                        else //internal write
                            switch (mode)
                            {
                                case STREAM_PACK:
                                {
                                    mode = streaming_mode;
                                    var done = unpark();
                                    if (done < 0)
                                        goto exit;
                                    if (0 < done)
                                        goto dispatched;
                                    break;
                                }
                                case INT1:
                                    if (not_get4())
                                        goto exit;
                                    u8 = (ulong)(sbyte)u4;
                                    break;
                                case INT2:
                                    if (not_get4())
                                        goto exit;
                                    u8 = (ulong)(short)u4;
                                    break;
                                case INT4:
                                    if (not_get4())
                                        goto exit;
                                    u8 = (ulong)(int)u4;
                                    break;
                                case VAL4:
                                    if (not_get4())
                                        goto exit;
                                    break;
                                case VAL8:

                                    if (remaining < bytes_left)
                                    {
                                        var r = remaining;
                                        u8 |= get8<ulong>(r) << (bytes_max - bytes_left) * 8;
                                        bytes_left -= r;
                                        goto exit;
                                    }

                                    u8 |= get8<ulong>(bytes_left) << (bytes_max - bytes_left) * 8;
                                    break;
                                case VAL16:
                                    if (get16())
                                        break;
                                    goto exit;
                                case LEN0:
                                    if (not_get4())
                                        goto exit;
                                    slot.check_len0((int)u4);
                                    break;
                                case LEN1:
                                    if (not_get4())
                                        goto exit;
                                    slot.check_len1((int)u4);
                                    break;
                                case LEN2:
                                    if (not_get4())
                                        goto exit;
                                    slot.check_len2((int)u4);
                                    break;
                                case VARINT:
                                    if (varint())
                                        break;
                                    goto exit;

                                case STR:
                                    if (slot.state == (uint)bit)
                                        break;

                                    if (u8_ == ulong.MaxValue) //the length prefix is still unfinished
                                    {
                                        if (!varint())
                                            goto exit;
                                        if (check_length_and_getting_string())
                                            break;
                                        goto exit;
                                    }

                                    //getting_string resumes its own state: u4 characters in, wide, the split char in u8 / bytes_left.
                                    if (getting_string())
                                        break;
                                    goto exit;

                                case STR_RAW:
                                    //Chain-string leaf park (see StringStream) → SKIP, the leaf completes it.
                                    if (slot.state == (uint)bit)
                                        break;

                                    //No length prefix on this wire: the reader just drains the window, resuming its
                                    //own ASCII in bys or mid-char state from u8 / bytes_left. Completion comes from the
                                    //enclosing framer (Chunked's [0]-terminator branch), never from here.
                                    getting_str_raw();
                                    goto exit;

                                case STR_UTF8:
                                    //Chain-string leaf park (see UTFStream) → SKIP, the leaf completes it.
                                    if (slot.state == (uint)bit)
                                        break;

                                    //No length prefix on this wire: the decoder just drains the window, resuming its
                                    //own mid-sequence state from u8 / bytes_left. Completion comes from the enclosing
                                    //framer (Chunked's [0]-terminator branch), never from here.
                                    getting_string_utf();
                                    goto exit;
                            }

                        mode = OK;

                        for (;;)
                            if (slot.dst!.__put_bytes(this))
                            {
                                if (slot == null)
                                    return exit(top, -1); //what the pack said tore the connection down: this is reset ( a service pack's Control, resume( null ) )
                                if (slot == streaming_slot)
                                    return exit(top, int.MinValue); //streamed body complete
                                if (slot.prev == null)
                                    break;        //top-level packet complete → dispatch
                                slot = slot.prev; //pop one level
                            }
                            else
                                goto exit; //data over
                    }
                    catch (Exception ex) when (ex is not OutOfMemoryException)
                    {
                        if (ex == DENIED)
                        {
                            reset();
                            buffer = null;
                            return exit(top, -1);
                        }
                        //A pack body or a framer threw: every byte offset that follows is untrustworthy, the same
                        //verdict INVALID_ID gets above. Report, tear the transport down, drop our own state.
                        error_handler.error(this, slot?.dst, OnError.BYTES_DISTORTION, ex);
                        if (!framed)
                            ext_connection?.Abort(); //framed: the pack is dropped, the next 0xFF starts the next one
                        reset();
                        buffer = null; //Release buffer reference: this return skips the common exit below
                        return exit(top, -1);
                    }

                dispatched:
                    if (bytesCopy != null)
                        if (0 <= bytesCopyOffset)
                            bytesCopy.last(this, bytesCopyOffset, byte_ - bytesCopyOffset);
                        else
                            bytesCopy.fail(this); //the body never started

                    //A relayed tunnel region ends with no destination: the Relay clears slot.dst precisely because its
                    //bytes are not a packet received at this layer. Honour that here - handing the cleared destination
                    //on instead would make every generated _OnReceived carry a branch for a packet never received.
                    if (slot.dst != null)
                    {
                        if (0 <= guarded_from)
                        { //a guaranteed pack received whole: the position moves behind its last byte
                            guarded_ += consumed - guarded_from;
                            guarded_from = -1;
                        }

                        if (handler is Framing framing)
                        {
                            //The CRC that follows decides: the framing dispatches the pack once it matched, and clears
                            //bytesCopy then - the CRC may come with the next run of decoded bytes, after this returns.
                            bytesCopyOffset = -1; //the bytes up to the next pack id are not the pack's
                            framing.OnReceived(this, slot.dst);
                        }
                        else
                        {
                            _OnReceived(slot.dst);
                            handler?.OnReceived(this, slot.dst); //dispatching
                            bytesCopy = null;
                        }
                    }
                    else
                        bytesCopy = null;

                    u4 = 0;
                    bytes_left = bytes_max = id_bytes;
                    if (slot == null)
                        return exit(top, -1); //received event handler has reset this
                    slot.dst = null;          //preparing to read next packet data
                }

            exit:
                if (bytesCopy != null && 0 <= bytesCopyOffset)
                    bytesCopy.pass(this, bytesCopyOffset, byte_ - bytesCopyOffset);
                buffer = null;

                return exit(top, byte_ - entry);
            }

            ///<summary>Re-entrant entry (used by a streaming <see cref="BytesDst.Adapter"/>): drive Write over the current window; returns <see cref="int.MinValue"/> when the streamed body completes.</summary>
            public int write(byte[] buffer) => Write(buffer, byte_, byte_max - byte_);

            ///<summary>
            ///Gets the `BytesDst` instance for the current slot and invokes its `__put_bytes` method
            ///to continue deserialization of the current message.
            ///</summary>
            ///<typeparam name="DST">The expected type of the `BytesDst` handler.</typeparam>
            ///<param name="dst">The `BytesDst` instance, typically pre-allocated for the message type.</param>
            ///<returns>The `dst` instance after `__put_bytes` has been called.</returns>
            public DST get_bytes<DST>(DST dst)
                where DST : BytesDst
            {
                slot!.state = 0;
                dst.__put_bytes(this);
                return dst;
            }

            ///<summary>
            ///Deserializes a nested object from the byte stream, managing the deserialization stack.
            ///The method advances the slot stack and directly invokes the deserializer (`__put_bytes`)
            ///for the nested <paramref name="dst"/> object.
            ///</summary>
            ///<typeparam name="DST">The type of the nested object's deserializer.</typeparam>
            ///<param name="dst">The <see cref="BytesDst"/> instance (typically a Pack deserializer) that will consume the bytes.</param>
            ///<param name="retry_case">The state for the parent slot to transition to if deserialization is incomplete
            ///and requires more data from the underlying connection.</param>
            ///<returns>The provided <paramref name="dst"/> instance if the entire object was successfully deserialized.
            ///Returns <c>null</c> if more data is needed from the underlying connection (retry).</returns>
            public DST? try_get_bytes<DST>(DST dst, uint retry_case)
                where DST : class, BytesDst
            {
                var O = slot!; //Store current slot to manage the deserialization stack.
                //Advance to the next slot in the chain for the nested object.
                slot = O.next ?? (O.next = new Slot(this, O));

                slot.dst = dst;
                slot.state = 0;
                u8_ = 0;

                //Attempt to deserialize the object.
                if (dst.__put_bytes(this))
                { //If deserialization is complete, restore the parent slot and return the dst object.
                    slot = O;
                    return dst;
                }

                //If deserialization is not complete (more data needed), set the parent's state
                //for a retry and return null. The slot chain remains advanced.
                O.state = retry_case;
                return null;
            }

            ///<summary><c>int</c> overload of <see cref="try_get_bytes{DST}(DST,uint)"/> — the generated code passes an <c>int retry_case</c>.</summary>
            public DST? try_get_bytes<DST>(DST dst, int retry_case)
                where DST : class, BytesDst => try_get_bytes(dst, (uint) retry_case);

            ///<summary>
            ///<see cref="try_get_bytes{DST}(DST,uint)"/> whose nested slot starts at <paramref name="enter"/>: a pack that is the
            ///leaf of the chain on one of its collection fields reads the field from its own case.
            ///</summary>
            public DST? try_get_bytes<DST>(DST dst, int enter, int retry_case)
                where DST : class, BytesDst
            {
                var O = slot!;
                slot = O.next ?? (O.next = new Slot(this, O));

                slot.dst = dst;
                slot.state = (uint)enter;
                u8_ = 0;

                if (dst.__put_bytes(this))
