            ///Sets up a retry operation to read a specified number of bytes (up to 4) into `u4`.
            ///It reads any currently available bytes, stores them partially in `u4`,
            ///and sets the mode to `VAL4` and state to `get4_case` for continuation.
            ///</summary>
            ///<param name="bytes">The total number of bytes that need to be read (1 to 4).</param>
            ///<param name="get4_case">The state to resume at when more data is available.</param>
            ///<returns>Always false, indicating that a retry is required.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool retry_get4(int bytes, uint get4_case)
            {
                bytes_left = (bytes_max = bytes) - remaining;
                u4 = get4<uint>(remaining);
                slot!.state = get4_case;
                mode = VAL4;
                return false;
            }

            ///<summary>
            ///Gets the value currently stored in the `u4` buffer, reinterpreted as type `T`.
            ///This is an unsafe cast and assumes `T` is compatible with a 4-byte representation.
            ///</summary>
            ///<typeparam name="T">The type to reinterpret the `u4` buffer as.</typeparam>
            ///<returns>The value from `u4` cast to type `T`.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public T get4<T>() => Unsafe.As<uint, T>(ref u4);

            ///<summary>
            ///Reads a specified number of bytes (up to 4) from the buffer and returns them as type `T`.
            ///The bytes are combined into a `uint` respecting endianness, then reinterpreted as `T`.
            ///Advances the buffer position by `bytes`.
            ///</summary>
            ///<typeparam name="T">The target type (must be compatible with a 4-byte representation if `bytes` is large).</typeparam>
            ///<param name="bytes">The number of bytes to read (1 to 4).</param>
            ///<returns>The value of type `T` read from the buffer.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public T get4<T>(int bytes)
            {
                uint u4 = 0;
                byte_ += bytes;
                switch (bytes)
                {
                    case 4:
                        u4 = Endianness.OK.UInt32(buffer!, byte_ - 4);
                        break;
                    case 3:
                        u4 = Endianness.OK.UInt16(buffer!, byte_ - 3);
                        u4 |= (uint)buffer![byte_ - 1] << 16;
                        break;
                    case 2:
                        u4 = Endianness.OK.UInt16(buffer!, byte_ - 2);
                        break;
                    case 1:
                        u4 = buffer![byte_ - 1];
                        break;
                }

                return Unsafe.As<uint, T>(ref u4);
            }
#endregion
#region bits
            ///<summary>
            ///Initializes the state for bitwise reading operations. Resets `bits` accumulator and `bit` pointer.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void init_bits()
            {
                bits = 0;
                bit = 8;
            }

            ///<summary>
            ///Gets the value currently stored in `u4` (populated by `try_get_bits`), reinterpreted as type `T`.
            ///</summary>
            ///<typeparam name="T">The type to reinterpret `u4` as.</typeparam>
            ///<returns>The bits value from `u4` cast to type `T`.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public T get_bits<T>() => Unsafe.As<uint, T>(ref u4);

            ///<summary>
            ///Reads a specified number of bits from the buffer, potentially consuming one or more bytes.
            ///Bits are read from the internal `bits` accumulator; if more bits are needed, a byte is read from `buffer`.
            ///</summary>
            ///<typeparam name="T">The type to return the bits as (e.g., int, byte). The value is stored in the lower bits of `T`.</typeparam>
            ///<param name="len_bits">The number of bits to read (must be less than or equal to the bit-width of `T` and typically small, e.g., 1-8).</param>
            ///<returns>The bits read from the buffer, cast to type `T`.</returns>
            public T get_bits<T>(int len_bits)
            {
                uint ret;
                if (bit + len_bits < 9)
                {
                    ret = bits >> bit & 0xFFU >> 8 - len_bits;
                    bit += len_bits;
                }
                else
                {
                    ret = (bits >> bit | (bits = buffer![byte_++]) << 8 - bit) & 0xFFU >> 8 - len_bits;
                    bit = bit + len_bits - 8;
                }

                return Unsafe.As<uint, T>(ref ret);
            }

            ///<summary>
            ///Items of a bit array straight into its list: while the bit stream stands on a byte boundary, whole chunks -
            ///as many groups of 8 items (<c>bitsPerItem</c> bytes each) as one ulong takes - go from the buffer in one
            ///read and one or two word writes. The items before the next boundary and the tail go one by one, as before.
            ///</summary>
            ///<returns>The items received: a multiple of 8, and 0 when the stream is not on a byte boundary.</returns>
            public int get_bits<T>(org.unirail.collections.BitsList<T>.RW dst, int item, int items)
                where T : struct
            {
                if (bit != 8)
                    return 0;
                if (BitConverter.IsLittleEndian) //the list's words are LSB first: its bytes are the wire's - all whole groups in one copy
                {
                    int bl = dst.bitsPerItem, gl = Math.Min(items >> 3, (byte_max - byte_) / bl);
                    if (gl == 0)
                        return 0;
                    buffer.AsSpan(byte_, gl * bl).CopyTo(dst.BytesFor(item, gl << 3));
                    byte_ += gl * bl;
                    return gl << 3;
                }

                int b = dst.bitsPerItem, K = 8 / b, pos = byte_, got = 0;
                for (int g; 0 < (g = Math.Min(Math.Min(K, items - got >> 3), (byte_max - pos) / b)); got += g << 3, pos += g * b)
                    dst.Raw(item + got, g << 3, load(buffer!, pos, g * b));
                byte_ = pos;
                return got;
            }

            ///<summary><see cref="get_bits{T}(org.unirail.collections.BitsList{T}.RW, int, int)"/> of one-bit items: appended,
            ///every whole byte the buffer has at once - the list is filled in order, <paramref name="item"/> is its count.</summary>
            public int get_bits(org.unirail.collections.BitList.RW dst, int item, int items)
            {
                if (bit != 8)
                    return 0;
                var g = Math.Min(items >> 3, byte_max - byte_);
                if (g <= 0)
                    return 0;
                dst.AppendBytes(buffer.AsSpan(byte_, g));
                byte_ += g;
                return g << 3;
            }

            ///<summary>
            ///Nullable items straight into their list, whole groups of 8: a byte of their nulls (1 - null) and their values right
            ///after it, while the bit stream stands on a byte boundary and the buffer holds the longest group. The items before
            ///the next boundary, the tail and what the buffer cut go one by one, as before.
            ///</summary>
            ///<returns>The items received, a multiple of 8; 0 when the stream is not on a byte boundary or no group is sure to be there.</returns>
            public int get_nulls<T>(org.unirail.collections.NullablePrimitiveList<T>.RW dst, int item, int items)
                where T : struct => !BitConverter.IsLittleEndian || items<8 || bit != 8 ? 0 : dst.GroupsFrom(buffer!, ref byte_, byte_max, item, items>> 3) << 3;

            ///<summary>
            ///A chunk of a bit array an abstract pack takes item by item: while the bit stream stands on a byte boundary, up
            ///to <paramref name="items"/> items of <paramref name="bits_per_item"/> bits - as many as one ulong and the buffer
            ///hold, whole bytes - read into <see cref="AdHoc.u8"/> at once, item 0 in the lowest bits. The codec hands them on
            ///shifting it down.
            ///</summary>
            ///<returns>The items read, 0 when the stream is not on a byte boundary or no chunk is there.</returns>
            public int bits8(int items, int bits_per_item)
            {
                if (bit != 8)
                    return 0;
                var n = (int)Math.Min(Math.Min(items, 64 / bits_per_item), ((long)(byte_max - byte_) << 3) / bits_per_item); //a window past 256 MB: its bits do not fit an int
                n -= n % (8 >> System.Numerics.BitOperations.TrailingZeroCount(bits_per_item));                              //whole bytes
                if (n <= 0)
                    return 0;
                var bytes = n * bits_per_item >> 3;
                u8 = load(buffer!, byte_, bytes);
                byte_ += bytes;
                return n;
            }

            ///<summary>Whether the bit stream holds <paramref name="len_bits"/> more bits: the rest of the current byte and the buffer.</summary>
            public bool has_bits(int len_bits) => len_bits <= 8 - bit + ((long)(byte_max - byte_) << 3); //a window past 256 MB: its bits do not fit an int

            ///<summary>
            ///Attempts to read a specified number of bits from the buffer into `u4`.
            ///If not enough data (bytes) is available in the buffer to satisfy the bit read,
            ///sets up a retry at `this_case`.
            ///</summary>
            ///<param name="len_bits">The number of bits to read.</param>
            ///<param name="this_case">The state to retry at if reading fails due to insufficient underlying bytes.</param>
            ///<returns>True if the bits were read successfully into `u4`; false if a retry is needed.</returns>
            public bool try_get_bits(int len_bits, uint this_case)
            {
                if (bit + len_bits < 9)
                {
                    u4 = bits >> bit & 0xFFU >> 8 - len_bits;
                    bit += len_bits;
                }
                else if (byte_ < byte_max)
                {
                    u4 = (bits >> bit | (bits = buffer![byte_++]) << 8 - bit) & 0xFFU >> 8 - len_bits;
                    bit = bit + len_bits - 8;
                }
                else //not enough data
                {
                    retry_at(this_case);
                    return false;
                }

                return true;
            }
#endregion
#region varint
            ///<summary>
            ///Attempts to read `bytes_left` (assumed to be up to 8) from the buffer into `u8` for varint processing.
            ///If insufficient bytes, sets up a retry. This is a specialized version of `try_get8` for varint contexts.
            ///</summary>
            ///<param name="next_case">The state to retry at if reading fails.</param>
            ///<returns>True if bytes were read successfully; false if a retry is needed.</returns>
            public bool try_get8(uint next_case) => try_get8(bytes_left, next_case);

            ///<summary>
            ///Tries to read 1 bit for varint length information (0 for 1 byte, 1 for 2 bytes).
            ///Sets `bytes_left` and `bytes_max` according to this length.
            ///</summary>
            ///<param name="bits">Number of bits for length info (should be 1 for this method).</param>
            ///<param name="this_case">The state to retry at if reading bits fails.</param>
            ///<returns>True if length bit was read and `bytes_left` set; false if retry is needed.</returns>
            public bool try_get_varint_bits1(int bits, uint this_case)
            {
                if (!try_get_bits(bits, this_case))
                    return false;
                bytes_left = bytes_max = get_bits<int>() + 1;
                return true;
            }

            ///<summary>
            ///Tries to read a specified number of bits for varint length information.
            ///Sets `bytes_left` and `bytes_max` according to this length.
            ///</summary>
            ///<param name="bits">Number of bits for length info.</param>
            ///<param name="this_case">The state to retry at if reading bits fails.</param>
            ///<returns>True if length bits were read and `bytes_left` set; false if retry is needed.</returns>
            public bool try_get_varint_bits(int bits, uint this_case)
            {
                if (!try_get_bits(bits, this_case))
                    return false;
                bytes_left = bytes_max = get_bits<int>();
                return true;
            }

            ///<summary>
            ///Attempts to read a varint-encoded unsigned long from the buffer into `u8`.
            ///If not enough data, sets mode to `VARINT` and state to `next_case` for retry.
            ///</summary>
            ///<param name="next_case">The state to retry at if reading fails.</param>
            ///<returns>True if the varint was read successfully; false if a retry is needed.</returns>
            public bool try_get_varint(uint next_case)
            {
                u8 = 0;
                bytes_left = 0;

                if (varint())
                    return true;

                slot!.state = next_case;
                mode = VARINT;
                return false;
            }

            ///<summary>
            ///Reads a varint-encoded unsigned long from the `buffer` and accumulates it into `u8`.
            ///Updates `byte_` (buffer position) and `bytes_left` (varint shift accumulator).
            ///</summary>
            ///<returns>True if a complete varint value has been read; false if more bytes are needed from the buffer.</returns>
            internal bool varint()
            {
                //past 64 bits a malformed varint adds nothing: the shift of C# is taken mod 64, it would put its bits back low
                for (ulong b; byte_ < byte_max;)
                {
                    if ((b = buffer![byte_++]) < 0x80)
                    {
                        if (bytes_left < 64)
                            u8 |= b << bytes_left;
                        return true;
                    }

                    if (bytes_left < 64)
                    {
                        u8 |= (b & 0x7FUL) << bytes_left;
                        bytes_left += 7;
                    }
                }

                return false;
            }

            ///<summary>
            ///Decodes a ZigZag-encoded unsigned long back to a signed long.
            ///ZigZag encoding maps signed integers to unsigned integers so that numbers with a small absolute value
            ///(i.e., close to zero, positive or negative) have a small varint encoded value.
            ///</summary>
            ///<param name="src">The ZigZag-encoded unsigned long value.</param>
            ///<returns>The decoded signed long value.</returns>
            public static long zig_zag(ulong src) => -(long)(src & 1) ^ (long)(src >> 1);
#endregion
#region dims
            int[] dims = Array.Empty<int>(); //temporary buffer for the receiving string and more

            ///<summary>
            ///Initializes or resizes the internal `dims` array used for storing dimensions of multi-dimensional data.
            ///Also resets `u8` to 1 (often used as a running product of dimensions).
            ///</summary>
            ///<param name="size">The required size of the dimensions array.</param>
            public void init_dims(int size)
            {
                u8 = 1;
                if (size <= dims.Length)
                    return;
                ArrayPool<int>.Shared.Return(dims);
                dims = ArrayPool<int>.Shared.Rent(size);
            }

            ///<summary>
            ///Gets a dimension value from the internal `dims` array at the specified index.
            ///</summary>
            ///<param name="index">The index of the dimension to retrieve.</param>
            ///<returns>The dimension value stored at `dims[index]`.</returns>
            public int dim(int index) => dims[index];

            ///<summary>
            ///Reads a 4-byte integer from the buffer, validates it against `max`, stores it in `dims[index]`,
            ///and multiplies it into `u8` (which typically accumulates the total number of elements).
            ///Reports an overflow error if `dim > max`.
            ///</summary>
            ///<param name="max">The maximum allowed value for this dimension.</param>
            ///<param name="index">The index in the `dims` array where this dimension should be stored.</param>
            public void dim(int max, int index)
            {
                var dim = get4<int>();
                if (max < dim)
                { //the peer broke the protocol: told, then the connection is torn down - reading on would let it size the array
                    var e = new ArgumentOutOfRangeException("In dim(int max, int index){} max < dim : " + max + " < " + dim);
                    error_handler.error(this, null, OnError.OVERFLOW, e);
                    throw e;
                }

                u8 *= (ulong)dim;
                dims[index] = dim;
            }

            ///<summary>
            ///Reads a 4-byte integer from the buffer representing a length, and validates it against `max`.
            ///Over `max` the peer broke the protocol: the overflow is reported, then thrown - the connection is torn down.
            ///</summary>
            ///<param name="max">The maximum allowed value for this length.</param>
            ///<returns>The read length, within the `max` limit.</returns>
            public long length(long max)
            {
                var len = get4<int>();
                if (len <= max)
                    return len;

                //the peer broke the protocol: told, then the connection is torn down - the items behind would be read as the fields after
                var e = new ArgumentOutOfRangeException("In length(long max){} max < len : " + max + " < " + len);
                error_handler.error(this, null, OnError.OVERFLOW, e);
                throw e;
            }
#endregion
#region string
            //Stackless/Static exceptions to prevent CPU exhaustion DoS attacks on malformed input.
            private static readonly InvalidDataException MALFORMED_UTF8_ERR = new InvalidDataException("Malformed UTF-8 bytes detected.");
            private static readonly InvalidOperationException OVERFLOW_ERR = new InvalidOperationException("Declared string length exceeds maximum field accepts.");
            private static readonly InvalidDataException BROKEN_UNIT_ERR = new InvalidDataException("A UTF-16 unit of more than three varint bytes, or above U+FFFF: mended with U+FFFD.");

            ///<summary>The shift a varint UTF-16 unit gets to: three bytes at most, the last of them with 2 bits.</summary>
            internal const int UNIT_SHIFT_MAX = 14;

            ///<summary>The shift of a unit that went past three bytes: its bits are dropped, the byte that ends it makes U+FFFD.</summary>
            internal const int UNIT_BROKEN = 21;

            ///<summary>
            ///A unit of more than three bytes, or above U+FFFF: told to the error handler, mended as U+FFFD - the stream
            ///goes on, the count of the chars (the bytes that end one) as it was.
            ///</summary>
            [MethodImpl(MethodImplOptions.NoInlining)]
            char broken_unit()
            {
                error_handler.error(this, null, OnError.BYTES_DISTORTION, BROKEN_UNIT_ERR);
                return '�';
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public string? get_string()
            {
                var ret = str;
                str = null;
                return ret;
            }

            ///<summary>
            ///Finalizes a prefix-less string. The framer (e.g., Chunked's [0] branch) MUST call this
            ///instead of accessing `chs` directly, as pure ASCII strings are kept in the `bys` buffer.
            ///It also safely returns rented arrays to the ArrayPool.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public void complete_prefixless_string()
            {
                if (!wide)
                {
                    str = string.Create((int)u4, bys, static (dst, b) => Ascii.ToUtf16(b.AsSpan(0, dst.Length), dst, out _));
                }
                else
                {
                    str = new string(chs.AsSpan(0, (int)u4));
                    ArrayPool<char>.Shared.Return(chs!);
                    chs = null;
                }
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool try_get_string(uint max_chars, int get_string_case)
            {
                bit = ~get_string_case;

                //A short ASCII string whole in the window, its length in one byte or two: straight into the string, no state
                int p = byte_, n = byte_max - p;
                if (0 < n)
                {
                    ref var b = ref MemoryMarshal.GetArrayDataReference(buffer!);
                    uint len = Unsafe.Add(ref b, p);
                    var h = 1;
                    if (0x7F < len)
                        if (1 < n && Unsafe.Add(ref b, p + 1) < 0x80)
                        {
                            len = len & 0x7F | (uint)Unsafe.Add(ref b, p + 1) << 7;
                            h = 2;
                        }
                        else
                            len = uint.MaxValue;

                    if (len <= max_chars && len <= (uint)(n - h) && ascii(ref Unsafe.Add(ref b, p + h), (int)len))
                    {
                        str = len == 0 ? string.Empty : Encoding.Latin1.GetString(buffer!, p + h, (int)len);
                        byte_ = p + h + (int)len;
                        u8_ = u4 = len;
                        return true;
                    }
                }

                u4 = max_chars;
                u8_ = ulong.MaxValue;
                u8 = 0;
                bytes_left = 0;

                if (varint() && check_length_and_getting_string())
                    return true;

                slot!.state = (uint)get_string_case;
                mode = STR;
                return false;
            }

            ///<summary>
            ///Whether the <paramref name="n"/> bytes at <paramref name="s"/> are all ASCII. Below 16 bytes by two words that overlap -
            ///the vector search goes byte by byte there - from 16 on vectorized.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            static bool ascii(ref byte s, int n)
            {
                if (n < 4)
                    return n == 0 || ((s | Unsafe.Add(ref s, n >> 1) | Unsafe.Add(ref s, n - 1)) & 0x80) == 0;
                if (n < 8)
                    return ((Unsafe.ReadUnaligned<uint>(ref s) | Unsafe.ReadUnaligned<uint>(ref Unsafe.Add(ref s, n - 4))) & 0x80808080u) == 0;
                if (n < 16)
                    return ((Unsafe.ReadUnaligned<ulong>(ref s) | Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref s, n - 8))) & 0x8080808080808080UL) == 0;
                return Ascii.IsValid(MemoryMarshal.CreateReadOnlySpan(ref s, n));
            }

            internal char[]? chs;
            internal byte[] bys = Array.Empty<byte>();
            internal bool wide;

            internal bool check_length_and_getting_string()
            {
                if (u4 < u8)
                {
                    error_handler.error(this, null, OnError.OVERFLOW, OVERFLOW_ERR);
                    throw OVERFLOW_ERR;
                }

                u8_ = u8;
                u4 = 0;
                u8 = 0;
                bytes_left = 0;
                wide = false;

                return getting_string();
            }

            internal bool getting_string()
            {
                var len = (int)u8_;

                if (!wide)
                {
                    var from = (int)u4;
                    var n = Math.Min(byte_max - byte_, len - from);
                    var src = new ReadOnlySpan<byte>(buffer, byte_, n);

                    //IndexOfAnyExceptInRange is heavily vectorized in .NET
                    var at = 0 < n && 0x7F < buffer![byte_] ? 0 : src.IndexOfAnyExceptInRange((byte)0, (byte)0x7F);

                    if (at < 0)
                    {
                        if (n == len)
                        {
                            str = string.Create(len, (buf: buffer!, at: byte_), static (dst, s) => Ascii.ToUtf16(s.buf.AsSpan(s.at, dst.Length), dst, out _));
                            byte_ += len;
                            u4 = (uint)len;
                            return true;
                        }

                        if (bys.Length < len)
                            Array.Resize(ref bys, len);

                        src.CopyTo(bys.AsSpan(from));
                        byte_ += n;
                        u4 = (uint)(from + n);

                        if (from + n < len)
                            return false;

                        str = string.Create(len, bys, static (dst, b) => Ascii.ToUtf16(b.AsSpan(0, dst.Length), dst, out _));
                        return true;
                    }

                    if (chs == null)
                        chs = ArrayPool<char>.Shared.Rent(len);
                    else if (chs.Length < len)
                    {
                        ArrayPool<char>.Shared.Return(chs);
                        chs = ArrayPool<char>.Shared.Rent(len);
                    }

                    if (0 < from)
                        Ascii.ToUtf16(bys.AsSpan(0, from), chs, out _);
                    if (0 < at)
                        Ascii.ToUtf16(src[..at], chs.AsSpan(from), out _);

                    byte_ += at;
                    u4 = (uint)(from + at);
                    wide = true;
                }

                return getting_chars(len);
            }

            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool getting_chars(int target)
            {
                var buf = buffer!;
                var c = chs!;
                var pos = byte_;
                var limit = byte_max;
                var u4_ = u4;

                var val = u8;
                var shift = bytes_left;

                var bytes = limit - pos;
                if (0 < bytes)
                {
                    var cap = Math.Min((long)u4_ + bytes + 8, target);
                    if (c.Length < cap)
                        c = grow_chs((int)cap);
                }

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);
                ref var chsRef = ref MemoryMarshal.GetArrayDataReference(c);

                //=== Main loop: 8 bytes per iteration ===
                while (u4_ < target && pos <= limit - 8)
                {
                    //Gate ensures we don't overshoot target, removing inner loop checks completely
                    if (u4_ + 8 <= target)
                    {
                        var packed = Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref bufRef, pos));

                        if (shift == 0 && (packed & 0x8080808080808080UL) == 0)
                        {
                            Unsafe.Add(ref chsRef, (nint)u4_) = (char)(packed & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 1) = (char)((packed >> 8) & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 2) = (char)((packed >> 16) & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 3) = (char)((packed >> 24) & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 4) = (char)((packed >> 32) & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 5) = (char)((packed >> 40) & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 6) = (char)((packed >> 48) & 0xFF);
                            Unsafe.Add(ref chsRef, (nint)u4_ + 7) = (char)((packed >> 56) & 0xFF);
                            u4_ += 8;
                            pos += 8;
                            continue;
                        }

                        if (shift == 0 && Units.Accelerated)
                        { //units below 0x4000, ASCII among them, 8 bytes a step
                            var n = Units.ToChars(ref Unsafe.Add(ref bufRef, pos), limit - pos, ref Unsafe.Add(ref chsRef, (nint)u4_), c.Length - (int)u4_, target - (int)u4_, out var k);
                            if (0 < n)
                            {
                                pos += n;
                                u4_ += (uint)k;
                                continue;
                            }
                        }

                        if (shift == 0)
                        { //whole units of the word, each by its length, no per-byte state: while 3 bytes at least remain in the word a unit is whole in it, one the word's end cuts is read again from the next word
                            var w = packed;
                            var used = 0;
                            while (used <= 5)
                            {
                                var b0 = (uint)w & 0xFF;
                                if (b0 < 0x80)
                                {
                                    Unsafe.Add(ref chsRef, (nint)u4_++) = (char)b0;
                                    w >>= 8;
                                    used++;
                                    continue;
                                }

                                var b1 = (uint)(w >> 8) & 0xFF;
                                if (b1 < 0x80)
                                {
                                    Unsafe.Add(ref chsRef, (nint)u4_++) = (char)(b0 & 0x7F | b1 << 7);
                                    w >>= 16;
                                    used += 2;
                                    continue;
                                }

                                var b2 = (uint)(w >> 16) & 0xFF;
                                if (3 < b2)
                                    break; //past 0xFFFF or longer: the byte path below
                                Unsafe.Add(ref chsRef, (nint)u4_++) = (char)(b0 & 0x7F | (b1 & 0x7F) << 7 | b2 << 14);
                                w >>= 24;
                                used += 3;
                            }

                            if (0 < used)
                            {
                                pos += used;
                                continue;
                            }
                        }

                        var rem = packed;
                        //Linear, unrolled execution without inner bounds checks or sign extensions
                        for (int k = 0; k < 8; k++)
                        {
                            uint x = (uint)rem & 0xFF;
                            rem >>= 8;

                            if (x >= 0x80)
                            {
                                if (shift < UNIT_SHIFT_MAX)
                                {
                                    val |= (ulong)(x & 0x7F) << shift;
                                    shift += 7;
                                }
                                else
                                    shift = UNIT_BROKEN; //past three bytes: the byte that ends the unit makes U+FFFD
                            }
                            else
                            {
                                Unsafe.Add(ref chsRef, (nint)u4_++) = shift < UNIT_SHIFT_MAX || shift == UNIT_SHIFT_MAX && x <= 3 ? (char)(val | ((ulong)x << shift)) : broken_unit();
                                val = 0;
                                shift = 0;
                            }
                        }

                        pos += 8;
                    }
                    else
                    {
                        break; //Close to target, fall through to tail
                    }
                }

                //=== Tail: fewer than 8 bytes remain ===
                while (u4_ < target && pos < limit)
                {
                    uint x = Unsafe.Add(ref bufRef, pos++);
                    if (x >= 0x80)
                    {
                        if (shift < UNIT_SHIFT_MAX)
                        {
                            val |= (ulong)(x & 0x7F) << shift;
                            shift += 7;
                        }
                        else
                            shift = UNIT_BROKEN; //past three bytes: the byte that ends the unit makes U+FFFD
                    }
                    else
                    {
                        Unsafe.Add(ref chsRef, (nint)u4_++) = shift < UNIT_SHIFT_MAX || shift == UNIT_SHIFT_MAX && x <= 3 ? (char)(val | ((ulong)x << shift)) : broken_unit();
                        val = 0;
                        shift = 0;
                    }
                }

                byte_ = pos;
                u4 = u4_;

                if (u4_ < target)
                {
                    u8 = val;
                    bytes_left = shift;
                    return false;
                }

                str = new string(c.AsSpan(0, (int)u4_));
                return true;
            }

            ///<summary>
            ///The ASCII bytes of the string being received, kept in <c>bys</c>, become chars in <c>chs</c>: before a char
            ///that is not ASCII goes in.
            ///</summary>
            internal void widen()
            {
                chs = ArrayPool<char>.Shared.Rent((int)Math.Clamp(u4 + 16, 256, int.MaxValue - 8));
                Ascii.ToUtf16(bys.AsSpan(0, (int)u4), chs, out _);
                wide = true;
            }

            internal char[] grow_chs(int min)
            {
                var old = chs!;
                var c = ArrayPool<char>.Shared.Rent((int)Math.Min(Math.Max((long)old.Length << 1, min), int.MaxValue - 8));
                Array.Copy(old, c, old.Length);
                ArrayPool<char>.Shared.Return(old);
                return chs = c;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool try_get_str(uint max_chars, int get_string_case)
            {
                bit = ~get_string_case;
                u8_ = max_chars;
                u4 = 0;
                u8 = 0;
                bytes_left = 0;
                wide = false; //Start pure ASCII assumption

                getting_str_raw();

                slot!.state = (uint)get_string_case;
                mode = STR_RAW;
                return false;
            }

            internal bool getting_str_raw()
            {
                var limit = byte_max;

                if (!wide)
                {
                    var pos = byte_;
                    var src = new ReadOnlySpan<byte>(buffer, pos, limit - pos);
                    var at = src.IndexOfAnyExceptInRange((byte)0, (byte)0x7F);

                    if (at < 0)
                    {
                        var count = limit - pos;
                        if (bys.Length < u4 + count)
                            Array.Resize(ref bys, (int)Math.Clamp(bys.Length << 1, u4 + count, int.MaxValue - 8));
                        src.CopyTo(bys.AsSpan((int)u4));
                        u4 += (uint)count;
                        byte_ = limit;
                        return false;
                    }

                    //Found non-ASCII byte, switch to wide mode
                    if (bys.Length < u4 + at)
                        Array.Resize(ref bys, (int)u4 + at);
                    if (at > 0)
                        src[..at].CopyTo(bys.AsSpan((int)u4));

                    byte_ += at;
                    u4 += (uint)at;
                    wide = true;

                    chs = ArrayPool<char>.Shared.Rent((int)Math.Clamp(u4 + 16, 256, int.MaxValue - 8));
                    Ascii.ToUtf16(bys.AsSpan(0, (int)u4), chs, out _);
                }

                return getting_chars(int.MaxValue);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool try_get_utf(uint max_chars, int get_string_case)
            {
                bit = ~get_string_case;
                u8_ = max_chars;
                u4 = 0;
                u8 = 0;
                bytes_left = 0;
                wide = false; //Start pure ASCII assumption

                getting_string_utf();

                slot!.state = (uint)get_string_case;
                mode = STR_UTF8;
                return false;
            }

            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool getting_string_utf()
            {
                var limit = byte_max;

                //--- ZERO-ALLOC ASCII FAST PATH ---
                if (!wide)
                {
                    var start_pos = byte_;
                    var src = new ReadOnlySpan<byte>(buffer, start_pos, limit - start_pos);
                    var at = src.IndexOfAnyExceptInRange((byte)0, (byte)0x7F);

                    if (at < 0)
                    {
                        var count = limit - start_pos;
                        if (bys.Length < u4 + count)
                            Array.Resize(ref bys, (int)Math.Clamp(bys.Length << 1, u4 + count, int.MaxValue - 8));
                        src.CopyTo(bys.AsSpan((int)u4));
                        u4 += (uint)count;
                        byte_ = limit;
                        return false;
                    }

                    //Fallback to wide
                    if (bys.Length < u4 + at)
                        Array.Resize(ref bys, (int)u4 + at);
                    if (at > 0)
                        src[..at].CopyTo(bys.AsSpan((int)u4));

                    byte_ += at;
                    u4 += (uint)at;
                    wide = true;

                    chs = ArrayPool<char>.Shared.Rent((int)Math.Clamp(u4 + 16, 256, int.MaxValue - 8));
                    Ascii.ToUtf16(bys.AsSpan(0, (int)u4), chs, out _);
                }

                //--- EXISTING WIDE/SIMD DFA PATH ---
                var buf = buffer!;
                var c = chs!;
                var pos = byte_;
                var u4_ = (int)u4;

                var cp = (int)u8;
                var st = bytes_left;
                var need = st & 0xFF;
                var lo = st >> 8 & 0xFF;
                var hi = st >> 16 & 0xFF;

                var bytes = limit - pos;
                if (0 < bytes)
                {
                    var cap = Math.Min((long)u4_ + bytes + 8, int.MaxValue - 8);
                    if (c.Length < cap)
                        c = grow_chs((int)cap);
                }

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);
                ref var chsU = ref Unsafe.As<char, ushort>(ref MemoryMarshal.GetArrayDataReference(c));
                var charLen = c.Length;
                var skip = 0;

                while (pos < limit)
                {
                    if (need == 0 && Unsafe.Add(ref bufRef, pos) < 0x80)
                    {
                        if (0 < skip)
                            skip--;
                        else if (Vector256.IsHardwareAccelerated && 32 <= limit - pos && u4_ + 32 <= charLen)
                        {
                            var v = Vector256.LoadUnsafe(ref bufRef, (uint)pos);
                            var mask = Vector256.ExtractMostSignificantBits(v);

                            var (v_lo, v_hi) = Vector256.Widen(v);
                            v_lo.StoreUnsafe(ref chsU, (uint)u4_);
                            v_hi.StoreUnsafe(ref chsU, (uint)(u4_ + 16));

                            if (mask == 0)
                            {
                                pos += 32;
                                u4_ += 32;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(mask);
                            pos += run;
                            u4_ += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF;
                        }
                        else if (16 <= limit - pos && u4_ + 16 <= charLen)
                        {
                            var v = Vector128.LoadUnsafe(ref bufRef, (uint)pos);
                            var mask = Vector128.ExtractMostSignificantBits(v);

                            var (v_lo, v_hi) = Vector128.Widen(v);
                            v_lo.StoreUnsafe(ref chsU, (uint)u4_);
                            v_hi.StoreUnsafe(ref chsU, (uint)(u4_ + 8));

                            if (mask == 0)
                            {
                                pos += 16;
                                u4_ += 16;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(mask);
                            pos += run;
                            u4_ += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF;
                        }
                        else if (8 <= limit - pos && u4_ + 8 <= charLen)
                        {
                            var packed = Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref bufRef, pos));
                            var mask = packed & 0x8080808080808080UL;

                            Unsafe.Add(ref chsU, (nint)u4_) = (ushort)(packed & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 1) = (ushort)(packed >> 8 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 2) = (ushort)(packed >> 16 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 3) = (ushort)(packed >> 24 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 4) = (ushort)(packed >> 32 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 5) = (ushort)(packed >> 40 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 6) = (ushort)(packed >> 48 & 0xFF);
                            Unsafe.Add(ref chsU, (nint)u4_ + 7) = (ushort)(packed >> 56 & 0xFF);

                            if (mask == 0)
                            {
                                pos += 8;
                                u4_ += 8;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(mask) >> 3;
                            pos += run;
                            u4_ += run;
                        }
                    }

                    int b = Unsafe.Add(ref bufRef, pos++);

                    if (need == 0)
                    {
                        if (b < 0x80)
                        {
                            Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)b;
                            continue;
                        }

                        if (b < 0xC2 || 0xF4 < b)
                        {
                            error_handler.error(this, null, OnError.BYTES_DISTORTION, MALFORMED_UTF8_ERR);
                            Unsafe.Add(ref chsU, (nint)u4_++) = 0xFFFD;
                            continue;
                        }

                        if (b < 0xE0)
                        {
                            cp = b & 0x1F;
                            need = 1;
                            lo = 0x80;
                            hi = 0xBF;
                        }
                        else if (b < 0xF0)
                        {
                            cp = b & 0x0F;
                            need = 2;
                            lo = b == 0xE0 ? 0xA0 : 0x80;
                            hi = b == 0xED ? 0x9F : 0xBF;
                        }
                        else
                        {
                            cp = b & 0x07;
                            need = 3;
                            lo = b == 0xF0 ? 0x90 : 0x80;
                            hi = b == 0xF4 ? 0x8F : 0xBF;
                        }

                        continue;
                    }

                    if (b < lo || hi < b)
                    {
                        error_handler.error(this, null, OnError.BYTES_DISTORTION, MALFORMED_UTF8_ERR);
                        Unsafe.Add(ref chsU, (nint)u4_++) = 0xFFFD;
                        need = 0;
                        continue;
                    }

                    cp = cp << 6 | b & 0x3F;
                    lo = 0x80;
                    hi = 0xBF;
                    if (0 < --need)
                        continue;

                    if (cp < 0x1_0000)
                        Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)cp;
                    else
                    {
                        var u = cp - 0x1_0000;
                        Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)(0xD800 | u >> 10);
                        Unsafe.Add(ref chsU, (nint)u4_++) = (ushort)(0xDC00 | u & 0x3FF);
                    }
                }

                byte_ = pos;
                u4 = (uint)u4_;
                u8 = (uint)cp;
                bytes_left = need | lo << 8 | hi << 16;
                return false;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public BytesDst try_get_string(uint max_chars, bool utf, int get_string_case)
            {
                bits = max_chars;
                bit = ~get_string_case;
                return utf ? UTFStream.ONE : StringStream.ONE;
            }
#endregion

            public override string ToString()
            {
                if (slot == null)
                    return "";

                var s = slot;
                while (s.prev != null)
                    s = s.prev;
                var str = "";
                var offset = "";
                for (; s != slot; s = s.next, offset += "\t")
                    str += $"{offset}{s.dst.GetType()}\t{s.state}\n";

                str += $"{offset}{(slot.dst == null! ? "null" : slot.dst.GetType())}\t{s.state}\n";

                return str;
            }

            ///<summary>
            ///Chunked-stream <b>consumer</b> — the receive half of a streamed packet. Wire form
            ///<c>[id][len][data]…[len][data][0x0000]</c>: a 2-byte little-endian length prefix per chunk
            ///(payload ≤ 65535 bytes), a <c>0x0000</c> length marking end-of-stream. Dispatched by
            ///<see cref="Receiver.__id"/> exactly like a normal pack; the de-framed payload bytes are drained into a
            ///pluggable inner <see cref="Receiver.BytesDst"/> dst. Resumable across socket fills via the standard
            ///<c>false</c> = park / <c>true</c> = complete contract — all chunk state is per-instance, and the
            ///dst is a pure-byte consumer (reads only buffer/byte_/byte_max — never the slot).
            ///<para><b>Scenario-A semantics:</b> the dst is a flat byte consumer; the <c>0x0000</c> terminator
            ///is the sole end-authority — a codec stage never self-completes, so the dst's own return value is
            ///ignored. Chunked completion reaches the application through the receiver's normal <c>OnReceived</c> dispatch.</para>
            ///<para><b>tunnel_id</b> comes out of the id field as far as it reaches there, and off the wire for the
            ///rest: the receiver consumes <see cref="Receiver.id_bytes"/> bytes before dispatch, so on a carrier whose
            ///id field is wider than the pack id those trailing bytes already hold the discriminator, while on a
            ///carrier as narrow as the pack id none of it is captured and all of it is still on the wire. The arming
            ///states where the pack id ends, and only that number tells the two apart.</para>
            ///</summary>
            public class Chunked : BytesDst
            {
                protected BytesDst dst = null!;      //inner stage — pure-byte (cipher/decompressor/leaf) or a structured endpoint
                protected BytesDst datatype = null!; //the chained structured pack, or null for a raw stream

                int fullId;  //the FULL id as delivered to _OnReceiving: low pureIdBytes bytes = pack id, the rest is the captured front of [tunnel_id][body]
                int _rem;    //bytes left in the current chunk's payload; doubles as the little-endian length accumulator while _state == 0
                int _lenGot; //length-prefix bytes accumulated so far (0..2) — straddle-safe across fills
                int _state;  //PRIVATE state machine — never touches the network slot, so this stage composes when nested

                public int tunnel_id; //discriminator assembled by the prelude; valid from the first __put_bytes on
                int tunnelIdBytes;    //discriminator width: 0 = plain stream / one-to-one; 1..4 = many-to-one
                int pureIdBytes;      //width of the pack id inside fullId; the rest of fullId is captured wire
                int _tidGot;          //discriminator bytes assembled so far — survives a park
                int _overGot;         //bytes already taken out of fullId for the discriminator
                bool _tunnelDone;     //on_tunnel_id fired exactly once per arming

                public int __id => datatype != null ? datatype.__id : dst.__id; //raw Stream (no datatype): fall back to the endpoint id

                ///<summary>(Re)configure with a chained STRUCTURED <paramref name="datatype"/>: the de-framed body is
                ///deserialized into <paramref name="datatype"/>. The inner <paramref name="dst"/> is the pure-byte codec
                ///stage; <paramref name="datatype"/> may be <c>null</c> for a raw stream (then <see cref="__id"/> falls
                ///back to the endpoint's own id). Returns <c>this</c> for chaining.</summary>
                public Chunked Init(BytesDst dst, BytesDst datatype)
                {
                    this.datatype = datatype;
                    this.dst = dst;
                    return reset();
                }

                ///<summary>Convenience arming — the chain's own <see cref="_Adapter"/> serves as BOTH the inner byte
                ///stage and the datatype (its id identifies the stream): shorthand for <c>Init(_Adapter, _Adapter)</c>.</summary>
                public Chunked Init()
                {
                    datatype = _Adapter;
                    dst = _Adapter;
                    return reset();
                }

                Chunked reset()
                {
                    //NOTE: onStreamComplete is deliberately NOT cleared here — Receiver.OnStreamComplete(hook) plants
                    //it into this chain BEFORE the arming Init runs; it is consumed by invokeOnStreamComplete at the
                    //stream end (terminator or teardown), which always runs.
                    _rem = _lenGot = _state = 0;
                    tunnel_id = 0;
                    tunnelIdBytes = 0;
                    _tidGot = _overGot = 0;
                    _tunnelDone = false;
                    pureIdBytes = 0;
                    ofTunnel = false;
                    return this;
                }

                ///<summary>Armed through <see cref="asTunnel"/>, with a tunnel_id or without (a tunnel that is one of its kind): an
                ///ABORT ends the stream of the tunnel - and the tunnel - never the connection that carries it.</summary>
                bool ofTunnel;

                ///<summary>Arm for ONE inbound stream. <paramref name="fullId"/> is the id exactly as delivered to
                ///<c>_OnReceiving</c> — <c>src.id_bytes</c> bytes of wire, of which the low <paramref name="pureIdBytes"/>
                ///are the pack id and the rest is the captured front of <c>[tunnel_id][body]</c>. The prelude does not
                ///guess that width: on a carrier whose id field is wider than the pack id the surplus already holds the
                ///discriminator, on one as narrow as the pack id the discriminator is still on the wire, and only this
                ///number tells the two apart. <paramref name="tunnelIdBytes"/> 0 is a plain stream. Clears the chunk +
                ///private state. Returns <c>this</c> for chaining.</summary>
                public Chunked asTunnel(int fullId, int pureIdBytes, int tunnelIdBytes)
                {
                    reset();
                    ofTunnel = true;
                    this.fullId = fullId;
                    this.pureIdBytes = pureIdBytes;
                    this.tunnelIdBytes = tunnelIdBytes;
                    return this;
                }

                ///<summary>Armed as a tunnel end (<see cref="asTunnel"/> with a tunnel_id): its bytes feed a virtual connection.</summary>
                public bool isTunnel => 0 < tunnelIdBytes;

                ///<summary>
                ///This stream will not be completed — it ended as <see cref="Transmitter.Chunked.ABORT"/>, or the receiver
                ///carrying it was reset part-way. A tunnel end tells the virtual connection's receiver to drop the pack it
                ///was in the middle of; the physical connection is not involved.
                ///</summary>
                public void abandon()
                {
                    _rem = _lenGot = _state = 0;
                    if (isTunnel)
                        _Adapter.abandon();
                }

                ///<summary>Fired exactly once per armed stream, the moment <see cref="tunnel_id"/> has been shifted out of
                ///the dispatched id (tunnel endpoints only; never for a plain stream). Set it to resolve / route the inbound
                ///stream by tunnel_id (e.g. install the destination vconn into <see cref="dst"/>).</summary>
                public Action<int>? on_tunnel_id;

                ///<summary>Told that a tunnel ended: its stream ended with <see cref="Transmitter.Chunked.ABORT"/>. A tunnel is not
                ///reopened by a stream after it: a frame with the same tunnel_id is a new tunnel.</summary>
                public interface Ends
                {
                    ///<param name="whole"><c>false</c>: the source vanished in the middle of a pack, which is dropped</param>
                    void ended(int tunnel_id, bool whole);
                }

                public Ends? on_tunnel_end;

                ///<summary>The per-stream hook, planted DIRECTLY by the generated <c>Receiver.OnStreamComplete(hook)</c>
                ///override (<c>chain().onStreamComplete = hook</c>) right before this chain is armed. One-shot and
                ///nesting-safe by construction: <c>chain()</c> hands an inner stream a DIFFERENT (free) chain than the
                ///already-armed outer one. Consumed by <see cref="complete"/>.</summary>
                public Action<Receiver, bool>? onStreamComplete;

                ///<summary>The chain's terminal (leaf) Adapter — framer and leaf travel as ONE aggregate, so the
                ///stream-end default always has its target. Generated arming wires it (<c>_Adapter.Init(…)</c>);
                ///codec stages may sit between the framer and this leaf.</summary>
                public readonly BytesDst.Adapter _Adapter = new();

                ///<summary>Stream-boundary cleanup — the single call the generated <c>Chain</c> makes at BOTH ends of a
                ///stream's life: the completion branch (<paramref name="completed"/> <c>true</c>) and <c>Chain.Release</c>
                ///(<c>false</c>). Runs-and-consumes the armed hook; with no hook, a <see cref="FileStream"/> sink is
                ///closed (flushed by Dispose). Either way every per-stream reference on <see cref="_Adapter"/> is dropped.</summary>
                public void complete(Receiver src, bool completed)
                {
                    completed &= !_Adapter.failed; //a sink that failed on the way did not get the stream whole
                    if (onStreamComplete != null)
                    {
                        onStreamComplete(src, completed);
                        onStreamComplete = null;
                    }
                    else if (_Adapter.dst is FileStream)
                        try
                        {
                            _Adapter.dst.Dispose();
                        }
                        catch
                        {
                        }

                    _Adapter.dst = null;
                    _Adapter.dst_ = null;
                    _Adapter.redirect = null;
                }

                ///<summary>
                ///Framework entry. Parses <c>[len][data]</c> chunks on a PRIVATE state machine, clamping
                ///<c>byte_max</c> to each chunk boundary before draining it into <see cref="dst"/>, until the
                ///<c>0x0000</c> terminator. Returns <c>true</c> on the terminator, <c>false</c> to park when the
                ///buffer is exhausted.
                ///</summary>
                public virtual bool __put_bytes(Receiver src)
                {
                    //tunnel_id prelude; a plain stream (tunnelIdBytes == 0) never enters it. The receiver had to consume
                    //src.id_bytes bytes before it could tell which pack had arrived, so on a tunnel frame everything
                    //above the pack id inside fullId is the captured front of [tunnel_id][body]. Those bytes are spent
                    //first and the remainder of the discriminator comes off the wire — which is the whole of it on a
                    //carrier whose id field is exactly the pack id. Straddle-safe: _tidGot and _overGot survive
                    //a park, so a discriminator split across two fills resumes where it stopped.
                    if (_tidGot < tunnelIdBytes)
                    {
                        var overread = src.id_bytes - pureIdBytes;
                        if (pureIdBytes < 1 || overread < 0 || tunnelIdBytes < overread)
                            throw new InvalidOperationException($"Tunnel arming mismatch: id_bytes({src.id_bytes}) - pure pack-id width({pureIdBytes}) = {overread} captured bytes, which does not fit a tunnel_id of {tunnelIdBytes} byte(s). A pack id is at least one byte, and surplus captured bytes would be body bytes this chain cannot replay.");
                        while (_tidGot < tunnelIdBytes)
                        {
                            int v;
                            if (_overGot < overread)
                                v = (int)((uint)fullId >> ((pureIdBytes + _overGot++) * 8)) & 0xFF;
                            else if (src.byte_ < src.byte_max)
                                v = src.buffer![src.byte_++];
                            else
                                break;
                            tunnel_id |= v << (8 * _tidGot++);
                        }

                        if (_tidGot < tunnelIdBytes)
                            return false; //the discriminator is split across fills, resume here
                    }

                    for (;;)
                        switch (_state)
                        {
                            case 0: //read the 2-byte little-endian length prefix (straddle-safe, private state)

                                while (_lenGot < 2)
                                    if (src.byte_ < src.byte_max)
                                        _rem |= src.buffer![src.byte_++] << (8 * _lenGot++);
                                    else
                                        return false; //prefix split across fills → park, resume here

                                _lenGot = 0;
                                if (0 < tunnelIdBytes && !_tunnelDone)
                                {
                                    //The first chunk of a tunnel's stream: its virtual connection is found now. A stream that only
                                    //ends the tunnel finds none - a tunnel that is gone already stays gone, nothing is made to be closed.
                                    _tunnelDone = true;
                                    if (_rem == Transmitter.Chunked.ABORT)
                                    {
                                        _rem = 0;
                                        on_tunnel_end?.ended(tunnel_id, true);
                                        return true;
                                    }

                                    on_tunnel_id?.Invoke(tunnel_id);
                                }

                                if (_rem == Transmitter.Chunked.ABORT)
                                {
                                    //The stream ends as VOID (see Transmitter.Chunked.ABORT). On a tunnel that is a relay telling us
                                    //the packet's source vanished part-way: the virtual connection drops the pack it was in the middle
                                    //of, and the stream counts as finished so the physical receiver reads its next pack — the
                                    //connection, shared by every tunnel on it, goes on. Inside a pack (a streamed field) nothing
                                    //completes the pack anymore, so that is a broken pack, reported like any other.
                                    //The source of a tunnel ends with it: a relay whose source vanished, or the far end's close()
                                    //after its last packs. The virtual connection is told whether a pack was cut.
                                    var whole = _Adapter.dst_ is not Receiver r || r.idle();
                                    abandon();
                                    if (!ofTunnel)
                                        throw new InvalidDataException("The stream was aborted by its source.");
                                    if (!isTunnel)
                                        _Adapter.abandon(); //a tunnel with no tunnel_id: its pack cut is dropped all the same
                                    on_tunnel_end?.ended(tunnel_id, whole);
                                    return true;
                                }

                                if (_rem == 0)
                                {
                                    //Terminator [0]: the stream ends here. A codec inner stage (e.g. ChaCha20 → Zstd) may
                                    //still hold buffered bytes not yet drained to the downstream pack — e.g. the final
                                    //decrypted byte sitting in the cipher's scratch that the decompressor needs to finish its
                                    //frame, or decompressed plaintext not yet consumed. Drive the inner ONE more time with an
                                    //EMPTY input window so every stage flushes what it holds into its downstream before we
                                    //report completion. Without this, when delivery boundaries leave the last byte(s) buffered
                                    //exactly at the terminator, the innermost nested pack is stranded and decoded as empty.
                                    //
                                    //The flushed plaintext is dispatched to the wrapped pack through a re-entrant Write()
                                    //(the codec stage's Adapter calls dst.Write(zout)). That dispatch must run the slot.dst
                                    //dispatch loop — but a framing-level park during THIS chunk's delivery may have left mode
                                    //== STREAM_PACK, which would instead route the re-entrant Write() into unpark() and re-frame
                                    //the plaintext as a bogus chunk. The framing is finished at [0], so restore the pre-park
                                    //mode first, decoupling the framing-level streaming state from the inner pack dispatch.
                                    if (src.mode == STREAM_PACK)
                                        src.mode = src.streaming_mode;
                                    var flushMax = src.byte_max;
                                    src.byte_max = src.byte_; //empty window: no new wire bytes, only flush buffered stage output
                                    put_bytes(src);
                                    //A PREFIX-LESS string datatype (StringStream/UTFStream) cannot self-terminate — its
                                    //string ends WITH the stream. The flush above delivered anything still buffered in the
                                    //stages; the terminator makes the end authoritative HERE, so turn the chars accumulated
                                    //in chs into str, ready for get_string(). A leaf never armed (slot.state != bit — a
                                    //zero-byte stream) decodes as the empty string. A cut mid-character (mid varint / mid
                                    //UTF-8 sequence) is BYTES_DISTORTION (the UTF-8 cut substitutes U+FFFD, matching the
                                    //strict decoder's policy; the varint cut drops the partial bits). Exceeding the staged
                                    //ceiling is OVERFLOW — advisory, the chars are kept.
                                    if (datatype == StringStream.ONE || datatype == UTFStream.ONE)
                                    {
                                        if (src.slot!.state != (uint)src.bit)
                                            src.str = "";
                                        else
                                        {
                                            if (datatype == UTFStream.ONE)
                                            {
                                                if ((src.bytes_left & 0xFF) != 0)
                                                { //the terminator landed mid-sequence
                                                    error_handler.error(src, null, OnError.BYTES_DISTORTION, new InvalidDataException($"Malformed UTF-8: stream ends mid-sequence, {src.bytes_left & 0xFF} continuation byte(s) missing."));
                                                    if (!src.wide)
                                                        src.widen();
                                                    if (src.chs!.Length == src.u4)
                                                        src.grow_chs((int)src.u4 + 1);
                                                    src.chs![src.u4++] = (char)0xFFFD;
                                                }
                                            }
                                            else if (src.bytes_left != 0) //the terminator landed mid-varint-char — the partial bits are dropped
                                                error_handler.error(src, null, OnError.BYTES_DISTORTION, new InvalidDataException("Malformed string: stream ends mid-varint character."));

                                            if (src.u8_ < src.u4)
                                                error_handler.error(src, null, OnError.OVERFLOW, new ArgumentOutOfRangeException($"max_chars < received chars : {src.u8_} < {src.u4}"));

                                            src.complete_prefixless_string(); //ASCII chars are in bys, the rest in chs
                                            src.u8 = 0;
                                            src.bytes_left = 0;
                                            src.bit = ~src.bit; //release the leaf's park lock-step: slot.state == (uint)bit no longer holds
                                        }
                                    }

                                    src.byte_max = flushMax;
                                    return true;
                                }

                                _state = 1;
                                goto case 1;

                            case 1: //hand the chunk payload to dst, clamped to the chunk boundary
                            {
                                var feed = Math.Min(src.byte_max - src.byte_, _rem);
                                if (0 < feed)
                                {
                                    var savedMax = src.byte_max;
                                    var from = src.byte_;
                                    src.byte_max = from + feed;
                                    put_bytes(src); //a codec stage never self-completes → its return value is not an end signal
                                    src.byte_max = savedMax;
                                    _rem -= src.byte_ - from;
                                }

                                if (0 < _rem)
                                    return false; //chunk straddles fills, or dst parked → resume here

                                _state = 0; //chunk fully drained → read the next prefix
                                break;
                            }
                        }
                }

                ///<summary>Feeds the (chunk-clamped) window to the inner stage. Overridable seam for a framer subclass.</summary>
                public virtual bool put_bytes(Receiver src) => dst.__put_bytes(src);
            }

            ///<summary>Named alias only: a receive-side tunnel endpoint is just a <see cref="Chunked"/> armed as a tunnel
            ///via <see cref="Chunked.asTunnel(int,int,int)"/> — all behavior lives in <see cref="Chunked"/>.</summary>
            public abstract class Tunnel : Chunked
            {
            }

            ///<summary>
            ///Known-size file <b>consumer</b> — the receive half of a <c>File</c> packet. Wire form
            ///<c>[id][len][data…]</c>: a single varint-encoded total-length header up front, then
            ///exactly that many payload bytes — no per-chunk framing, no terminator (the count is the
            ///end-authority). Dispatched by <see cref="Receiver.__id"/> like a normal pack; payload bytes are drained
            ///into a pluggable pure-byte inner <see cref="Receiver.BytesDst"/> <c>dst</c> (reads only buffer/byte_/byte_max,
            ///never the slot). Resumable across socket fills via the standard false = park / true = complete contract.
            ///</summary>
            public class File : BytesDst
            {
                protected Stream dst = null!; //direct byte sink (any System.IO.Stream) — overridable

                //Application-level sink alternative to dst, armed by the AdHoc.BytesDst Init overloads: a byte consumer that
                //is not a System.IO.Stream (e.g. a virtual connection's Internal.BytesDst). Its Write() returns how many bytes
                //it ACCEPTED and may take fewer than offered, so the payload drain advances by that count and parks on 0.
                protected AdHoc.BytesDst? dst_; //non-null ⇒ payload goes here instead of dst
                protected int _id;
                protected uint _state; //resume cursor across parks
                protected long _rem;   //payload bytes left to write (countdown)

                public long maxStreamBytes = long.MaxValue; //cap on the declared payload length (the IDL [S(N)] limit); set by EVERY Init

                public int __id => _id;

                ///<summary>Convenience overload — <c>Init(dst, maxStreamBytes, int.MinValue)</c>: no dispatch id (id-less) — the stream
                ///serves an EMBEDDED FIELD data type of an outer pack (the field, not this framer, identifies it).</summary>
                public File Init(string dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                ///<summary>(Re)configure: a built-in direct-file sink at <paramref name="dst"/> (created/truncated for writing) + the
                ///<c>[S(N)]</c> cap + dispatch id — the stream serves a dedicated TOP-LEVEL transmittable pack.</summary>
                public File Init(string dst, long maxStreamBytes, int id) => Init(new FileStream(dst, FileMode.Create, FileAccess.Write, FileShare.None), maxStreamBytes, id);

                ///<summary>Convenience overload — <c>Init(dst, maxStreamBytes, int.MinValue)</c>: no dispatch id (id-less) — the stream
                ///serves an EMBEDDED FIELD data type of an outer pack.</summary>
                public File Init(Stream dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                ///<summary>PRIMARY (re)configuration: a caller-supplied byte sink (any <see cref="System.IO.Stream"/>) + the <c>[S(N)]</c>
                ///cap on the declared payload length (a longer declared length makes <see cref="__put_bytes"/> throw) + dispatch id
                ///(<see cref="int.MinValue"/> = id-less: embedded field). Returns <c>this</c> for chaining.</summary>
                public File Init(Stream dst, long maxStreamBytes, int id)
                {
                    _id = id;
                    this.maxStreamBytes = maxStreamBytes;
                    this.dst = dst;
                    dst_ = null;
                    _rem = 0;
                    _state = 0;
                    return this;
                }

                ///<summary>Convenience overload — <c>Init(dst, maxStreamBytes, int.MinValue)</c>: no dispatch id (id-less) — the stream
                ///serves an EMBEDDED FIELD data type of an outer pack.</summary>
                public File Init(AdHoc.BytesDst dst, long maxStreamBytes) => Init(dst, maxStreamBytes, int.MinValue);

                ///<summary>PRIMARY (re)configuration onto an application-level <see cref="AdHoc.BytesDst"/> sink — a byte consumer that
                ///is not a <see cref="System.IO.Stream"/> (e.g. a virtual connection's <c>Internal.BytesDst</c>) + the <c>[S(N)]</c> cap on
                ///the declared payload length (a longer declared length makes <see cref="__put_bytes"/> throw) + dispatch id
                ///(<see cref="int.MinValue"/> = id-less: embedded field).
                ///<para>Such a sink may accept fewer bytes than offered; the payload drain then parks and is re-driven until the
                ///declared length is satisfied. Returns <c>this</c> for chaining.</para></summary>
                public File Init(AdHoc.BytesDst dst, long maxStreamBytes, int id)
                {
                    _id = id;
                    this.maxStreamBytes = maxStreamBytes;
                    this.dst = null!;
                    dst_ = dst;
                    _rem = 0;
                    _state = 0;
                    return this;
                }

                ///<summary>
                ///Framework entry. Straddle-safely decodes the varint total-length header on a PRIVATE state
                ///machine, then writes exactly that many payload bytes DIRECTLY to <see cref="dst"/> (the file/stream
                ///sink). Closes the sink and returns <c>true</c> once the full payload is written.
                ///</summary>
                public virtual bool __put_bytes(Receiver src)
                {
                    int i;
                    switch (_state)
                    {
                        case 0:
                            if (!src.try_get_varint(_state = 1))
                                return false;
                            goto case 1;
                        case 1:
                            _rem = (long)src.u8;
                            if (_rem < 0 || maxStreamBytes < _rem) //a length of 2^63 and more reads negative: over any cap
                                throw BytesDst.Adapter.overflow(src, "File payload length " + (ulong)_rem + " exceeds maxStreamBytes " + maxStreamBytes);
                            if (_rem == 0)
                                break;
                            _state = 2;
                            goto case 2;
                        case 2:
                            if (0 < (i = (int)Math.Min(_rem, src.byte_max - src.byte_)))
                            {
                                if (dst_ != null)
                                    //An application-level sink may take only part of the offer; charge only what it ACCEPTED so a
                                    //0-byte accept leaves _rem intact and parks below (the declared length stays the end-authority).
                                    i = dst_.Write(src.buffer!, src.byte_, i);
                                else
                                    dst.Write(src.buffer!, src.byte_, i); //Stream.Write is all-or-throw — no partial-write loop needed

                                src.byte_ += i;
                                _rem -= i;
                            }

                            if (0 < _rem)
                                return false;
                            break;
                    }

                    close();
                    return true;
                }

                ///<summary>Close the sink and drop the reference — runs at payload completion; teardown code may call it
                ///early so an aborted reception doesn't leak the handle. Idempotent.</summary>
                public void close()
                {
                    try
                    {
                        dst_?.Close();
                    }
                    catch
                    {
                    }

                    try
                    {
                        dst?.Dispose();
                    }
                    catch
                    {
                    }

                    dst_ = null;
                    dst = null!;
                }
            }

            ///<summary>
            ///Sink that fast-forwards through (and discards) any bytes. A framer installs it in place of
            ///an inner stage that completed early, so trailing chunk/payload padding is drained cleanly
            ///instead of dead-locking the framer on <c>consumed &lt; feed</c>. Stateless singleton.
            ///</summary>
            public sealed class NullDst : BytesDst
            {
                public static readonly NullDst Instance = new();
                public int __id => 0;

                public bool __put_bytes(Receiver src)
                {
                    src.byte_ = src.byte_max;
                    return false;
                }
            }
        }

        ///<summary>
        ///The outbound state machine and mirror image of <see cref="Receiver"/>: a <see cref="BytesSrc"/> that
        ///pulls queued packs and serializes them field by field into whatever buffer the transport offers. Each
        ///<c>Read</c> call fills the buffer as far as it can; when a value would overrun the buffer the machine
        ///parks (see <see cref="mode"/>) and the next call resumes it. It emits the leading packet ID, then the
        ///body, firing <c>OnSerializing</c>/<c>OnSerialized</c> around each pack.
        ///<para>
        ///Generated protocol code subclasses this with the concrete pack sources; an optional <see cref="Framing"/>
        ///layer can wrap the output to add 0xFF framing and a trailing CRC.
        ///</para>
        ///</summary>
        public abstract class Transmitter : Base_.Transmitter, BytesSrc
        {
            ///<summary>The keys the ChaCha20 stages of this session's pack chains encrypt with: the newest one. See <see cref="Connection.Keyring"/>.</summary>
            public readonly Keyring keys = new();

            ///<summary>
            ///Internal serialization-lifecycle interface layered over <see cref="BytesSrc"/>. A queued data source that
            ///needs hooks around its own serialization — to resolve / swap the actual <see cref="BytesSrc"/> that gets
            ///written, to react once the wire write of a pack completes, or to clean up on connection close — implements
            ///this instead of plain <see cref="BytesSrc"/>.
            ///<para>
            ///Implemented by the generated per-pack <c>DataPass</c> wrapper (the sending-queue element — it resolves the
            ///<see cref="BytesSrc"/> to serialize, so a framer like <see cref="Chunked"/> is pulled by it and does NOT
            ///implement this interface itself), by <see cref="Connection.Tunnel.Relay"/>, and by
            ///<see cref="Connection.Tunnel.EndPoint"/>. The base transmit loop does not call these hooks itself; the
            ///generated transmitter's <c>_OnSerializing</c> / <c>_OnSerialized</c> dispatch (and
            ///<see cref="Connection.Tunnel.Relay"/>'s own enqueue path) invoke them.
            ///</para>
            ///</summary>
            public interface IDataPass
            {
                ///<summary>Called when this entry is dequeued for serialization. Returns the actual <see cref="BytesSrc"/>
                ///to serialize (usually <c>this</c>), or <c>null</c> to skip it.</summary>
                public BytesSrc? OnSerializing(Transmitter transmitter);

                ///<summary>Called once the wire write of <paramref name="transmitted"/> has completed.</summary>
                public void OnSerialized(Transmitter transmitter, BytesSrc transmitted);

                ///<summary>Called when the owning connection is closing; release any held resources.</summary>
                public void Close(Transmitter transmitter);
            }

            public abstract int id { get; }

            ///<summary>
            ///The owning external connection, or <c>null</c> for free-standing / test transmitters.
            ///<see cref="notify_subscribers"/> and <see cref="Wake"/> read this property to reach
            ///<see cref="Connection.External.WakeTransmit"/> on the hosting transport.
            ///</summary>
            public abstract External? ext_connection { get; }

            ///<summary>
            ///Arms the per-stream completion hook — the resource-policy channel for streamed byte fields. The
            ///implementor of <c>__bytes(scope)</c> — the only party that knows how the stream it returns must be
            ///treated — calls this on the scope right before returning; the generated override plants the hook
            ///DIRECTLY into the chain about to be armed (<c>chain().onStreamComplete = …</c> — <c>chain()</c> is
            ///idempotent until the arming, so the imminent <c>stream(…)</c> picks the very same chain; an inner
            ///stream's arming can therefore never clobber an outer stream's hook). The generated <c>Chain</c>
            ///invokes the hook INSTEAD of the default when the stream ends, consuming it.
            ///<para>Second argument: <c>true</c> — the stream completed cleanly (intrinsic source EOF); <c>false</c> —
            ///it was torn down (abort/reset) — e.g. delete the source file ONLY after a successful send.</para>
            ///<para>When no hook is armed, the stream-end default runs — a
            ///<see cref="FileStream"/> source is closed, anything else only unreferenced. To suppress even that (e.g.
            ///keep a caller-owned <see cref="FileStream"/> open), call the parameterless <see cref="OnStreamComplete()"/>.</para>
            ///<para>Overridden by the generated Transmitter (only it knows its <c>Chain</c> machinery); the base has
            ///no chain to plant into.</para>
            ///</summary>
            public virtual void OnStreamComplete(Action<Transmitter, bool>? onStreamComplete) => throw new NotSupportedException("This Transmitter has no stream-chain machinery to plant the hook into.");

            ///<summary>Convenience overload — arms <see cref="OnStreamComplete_None"/>: "do nothing at the stream end",
            ///suppressing the stream-end default for the imminent stream.</summary>
            public void OnStreamComplete() => OnStreamComplete(OnStreamComplete_None);

            ///<summary>No-op hook: arms "do nothing at the stream end", suppressing the stream-end default.</summary>
            private static readonly Action<Transmitter, bool> OnStreamComplete_None = (_, _) =>
            {};

            ///<summary>
            ///A simplified, 'one-shot' transmitter designed to serialize a single, specific packet into a byte stream.
            ///<para>
            ///It acts as a temporary, virtual connection for a single serialization task, similar to `JSON.stringify`. This is ideal for serializing
            ///a known object to a destination like a file or a byte array, or for unit testing the serialization
            ///logic of a packet without the complexity of a network connection.
            ///</para>
            ///</summary>
            public class Virtual : Transmitter
            {
                public override int id => 0;
                public override External? ext_connection => null;
                BytesSrc? src;

                public Virtual() : base(null!) {}

                ///<summary>
                ///Configures the virtual transmitter to serialize a single packet.
                ///This method must be called before invoking the Read() method.
                ///</summary>
                ///<param name="src">The packet object to be serialized.</param>
                public void SetBytesSrc(BytesSrc src) => this.src = src;

                protected override BytesSrc? _OnSerializing() => src;

                protected override void _OnSerialized(BytesSrc transmitted) => src = null;

                public override bool IsIdle() => src == null;

                public void Reset_() => reset();

                protected override void reset()
                {
                    src = null;
                    base.reset();
                }
            }

            ///<summary>
            ///The per-pack serializer contract: one implementation per message type, driven by the
            ///<see cref="Transmitter"/> after it has emitted the packet ID. Generated code implements it to push
            ///each field into the transmitter's staging registers and buffer.
            ///</summary>
            public interface BytesSrc
            {
                ///<summary>
                ///Internal method called by the `Transmitter` to serialize data for a specific message type.
                ///Implementers should write to the `Transmitter`'s buffer using its `put_` methods.
                ///</summary>
                ///<param name="dst">The `Transmitter` instance providing the byte stream and serialization context.</param>
                ///<returns>True if the message part was successfully serialized with available buffer space; false if more buffer space is needed or processing is otherwise incomplete.</returns>
                public bool __get_bytes(Transmitter dst);

                ///<summary>
                ///Gets the unique identifier for this message type or data structure.
                ///</summary>
                int __id { get; }

                ///<summary>
                ///Terminal (leaf) producer — the END of a transmit stream chain. An <see cref="Adapter"/>
                ///bridges a real .NET <see cref="System.IO.Stream"/> (any kind: file, memory, network…) into the
                ///pure-byte <see cref="BytesSrc"/> contract, so it can sit at the bottom of a composed chain.
                ///As the chain leaf it has no inner stage to forward to.
                ///<para>At the stream end — the intrinsic source EOF, or teardown (<c>Chain.Release</c>) — the
                ///generated <c>Chain</c> runs the captured <see cref="Transmitter.OnStreamComplete"/> hook, or —
                ///when none was armed — the default: a <see cref="FileStream"/> source is
                ///closed, anything else only unreferenced. Delete-after-send and other custom policies belong in
                ///the hook.</para>
                ///</summary>
                public class Adapter : BytesSrc
                {
                    //PUBLIC on purpose: codegen re-arms a statically wired endpoint by DIRECT field access (the inline
                    //equivalent of Init minus the maxStreamBytes line) so a cap set once survives per-burst re-arms.
                    public Stream? src;                         //underlying byte source (any System.IO.Stream, incl. FileStream); null while armed as a re-entrant transmitter source
                    public long maxStreamBytes = long.MaxValue; //cap on TOTAL bytes read from src (the IDL [S(N)] limit); set by EVERY Init (unlimited when the overload takes no cap)
                    public long _total;                         //bytes read from src so far — reset by Init / codegen re-arm
                    public bool farewell;                       //the burst ends its tunnel (Chunked.ending): it takes all that is queued, no share - no burst comes after it

                    public int __id => id;

                    public int id = int.MinValue; //endpoint id; reset to the int.MinValue sentinel by every id-less Init, stamped by every id-taking Init

                    //A STRUCTURED streamed datatype produces its bytes by re-entering the Transmitter itself rather than by
                    //reading a byte source. Since src is a System.IO.Stream — which a Transmitter cannot also be — that arming
                    //needs its own field and its own Init(Transmitter) overload.
                    Transmitter? _tx; //re-entrant structured-datatype source; null ⇒ src is a plain byte source

                    //PUBLIC for the same reason as src: codegen re-arms a statically wired endpoint by DIRECT field access.
                    //An application-level source that is neither a System.IO.Stream nor a Transmitter — e.g. a virtual
                    //connection's Internal.BytesSrc. Its Read() has a THREE-way result where Stream.Read has two: >0 bytes,
                    //0 = "nothing available right now but still open" (park), -1 = end of stream. Stream.Read never signals
                    //the middle case, so the two are handled by separate branches in __get_bytes.
                    public AdHoc.BytesSrc? src_; //application-level byte source; null ⇒ not armed as one
//region Init — path family (self-opened file source)

                    ///<summary>PRIMARY (re)configuration with an explicit endpoint <paramref name="id"/>. Opens the source file
                    ///read-only (shared) — the stream-end default closes it; delete-after-send
                    ///belongs in an <see cref="Transmitter.OnStreamComplete"/> hook.
                    ///<paramref name="maxStreamBytes"/> is the IDL <c>[S(N)]</c> cap on TOTAL bytes read; exceeding it makes
                    ///<see cref="__get_bytes"/> throw. Applies to THIS arming only. Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(string src, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.src = new FileStream(src, FileMode.Open, FileAccess.Read, FileShare.Read);
                        _tx = null;
                        src_ = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(src, long.MaxValue, id)</c> (no size cap).</summary>
                    public Adapter Init(string src, int id) => Init(src, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration WITHOUT an id — stamps the <see cref="int.MinValue"/> sentinel, then
                    ///delegates to the id-taking primary.</summary>
                    public Adapter Init(string src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(src, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(string src) => Init(src, long.MaxValue);
//endregion
//region Init — stream family (caller-supplied source; stream-end policy = the OnStreamComplete hook, else the stream-end default)

                    ///<summary>PRIMARY (re)configuration with a caller-supplied <see cref="System.IO.Stream"/>, read directly.
                    ///What happens to it at the stream end is decided by the <see cref="Transmitter.OnStreamComplete"/> hook the
                    ///supplier may arm, else by the stream-end default. <paramref name="maxStreamBytes"/> is the IDL
                    ///<c>[S(N)]</c> cap, set by EVERY <c>Init</c>. Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(Stream src, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        this.src = src;
                        _tx = null;
                        src_ = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(src, long.MaxValue, id)</c> (no size cap).</summary>
                    public Adapter Init(Stream src, int id) => Init(src, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration with a caller-supplied source WITHOUT an id — stamps the
                    ///<see cref="int.MinValue"/> sentinel, then delegates to the id-taking primary.</summary>
                    public Adapter Init(Stream src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(src, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(Stream src) => Init(src, long.MaxValue);
//endregion
//region Init — re-entrant transmitter source (see _tx)

                    ///<summary>Arm as a re-entrant source for a STRUCTURED streamed datatype: bytes are produced by re-entering
                    ///<paramref name="tx"/> instead of by reading a byte source. Clears <see cref="src"/> and the size cap, and
                    ///stamps the <see cref="int.MinValue"/> id sentinel — such a stream is an embedded field, never dispatched by id.</summary>
                    public Adapter Init(Transmitter tx)
                    {
                        id = int.MinValue;
                        _total = 0;
                        src = null;
                        src_ = null;
                        _tx = tx;
                        maxStreamBytes = long.MaxValue;
                        redirect = null;
                        return this;
                    }
//endregion
//region Init — application-source family (caller-supplied AdHoc.BytesSrc; never touched by the stream-end default)

                    ///<summary>PRIMARY (re)configuration with a caller-supplied <see cref="AdHoc.BytesSrc"/> source — an application-level
                    ///byte producer that is neither a <see cref="System.IO.Stream"/> nor a <see cref="Transmitter"/> (e.g. a virtual
                    ///connection's <c>Internal.BytesSrc</c>) — and an explicit endpoint <paramref name="id"/>. Adopts
                    ///<paramref name="src"/>. The stream-end default never closes such a source (it only drops the
                    ///reference); closing belongs to the supplier — via an <see cref="Transmitter.OnStreamComplete"/> hook if wanted.
                    ///<para>End of stream is the explicit <c>-1</c> from <see cref="AdHoc.BytesSrc.Read"/>; a <c>0</c> means "nothing
                    ///available yet, still open" and merely parks. <paramref name="maxStreamBytes"/> is the IDL <c>[S(N)]</c> cap on TOTAL
                    ///bytes read, set by EVERY <c>Init</c>.</para>
                    ///Returns <c>this</c> for chaining.</summary>
                    public Adapter Init(AdHoc.BytesSrc src, long maxStreamBytes, int id)
                    {
                        this.id = id;
                        _total = 0;
                        cut = false;
                        this.src = null;
                        src_ = src;
                        _tx = null;
                        this.maxStreamBytes = maxStreamBytes;
                        redirect = null;
                        return this;
                    }

                    ///<summary>id overload — <c>Init(src, long.MaxValue, id)</c>: uncapped. This is what a
                    ///generated tunnel endpoint arms its transmit Adapter with: <c>_Adapter.Init(Internal.BytesSrc, id)</c>.
                    ///<para>NOTE the second argument is an <c>int</c> id here, but a <c>long</c> selects the cap overload below — the same
                    ///id/cap split the stream family already has.</para></summary>
                    public Adapter Init(AdHoc.BytesSrc src, int id) => Init(src, long.MaxValue, id);

                    ///<summary>PRIMARY (re)configuration with a caller-supplied source WITHOUT an id — stamps the
                    ///<see cref="int.MinValue"/> sentinel, then delegates to the id-taking primary.</summary>
                    public Adapter Init(AdHoc.BytesSrc src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue);

                    ///<summary>Convenience overload — <c>Init(src, long.MaxValue)</c> (no size cap).</summary>
                    public Adapter Init(AdHoc.BytesSrc src) => Init(src, long.MaxValue);
//endregion

                    public BytesSrc? redirect;

                    ///<summary>The burst ended between two packs because it carried its share, not because its transmitter ran dry:
                    ///the tunnel goes again behind the others (<see cref="Tunnel.EndPoint.OnSerialized"/>). Cleared by whoever reads it.</summary>
                    public bool cut;

                    ///<summary>
                    ///Reads bytes straight into <c>dst.buffer</c> until the buffer is full or EOF. Returns <c>false</c> on
                    ///buffer-full — the framework's slot.src dispatch keeps driving this instance until EOF, no per-class
                    ///takeover needed. Returns <c>true</c> on EOF; cleanup then runs at the Chain level — the captured
                    ///<see cref="Transmitter.OnStreamComplete"/> hook, else the stream-end default.
                    ///</summary>
                    public virtual bool __get_bytes(Transmitter dst)
                    {
                        var buf = dst.buffer;
                        for (;;)
                        {
                            if (redirect != null)
                            {
                                if (!redirect.__get_bytes(dst))
                                    return false; //nested stream still active
                                redirect = null;  //nested chained stream completed — continue below
                            }

                            if (dst.byte_ >= dst.byte_max)
                                break;

                            if (_tx != null) //structured datatype: re-enter the transmitter
                            {
                                var position = dst.byte_;
                                if (dst.mode == STREAM_PACK)
                                    dst.mode = dst.streaming_mode;
                                var n = _tx.read(dst.buffer!);
                                dst.buffer = buf; //read() nulls buffer at exit; restore for the framer
                                if (n == int.MinValue)
                                    return true; //nested pack fully serialized
                                if (dst.byte_ == position && redirect == null)
                                    break; //no progress → park
                            }
                            else if (src_ != null) //application-level source: Read is three-way (>0 / 0 = park / -1 = EOF)
                            {
                                //The transmitter of a virtual connection is the source of a burst of its tunnel: once the burst
                                //carried a chunk it ends between two packs, and the tunnel goes behind the others on the carrier.
                                //A datatype chain reads the very transmitter that drives it (src_ == dst): that is no burst, and a
                                //stop there would leave the packs queued behind the stream unsent.
                                var t = !farewell && src_ is Transmitter tx && tx != dst && Transmitter.Chunked.MAX <= _total ? tx : null;
                                if (t != null)
                                    t.stop_between_packs = true;
                                var n = src_.Read(dst.buffer!, dst.byte_, dst.byte_max - dst.byte_);
                                if (n == 0)
                                    break; //nothing available yet but still open → park, framework re-drives

                                if (n < 0)
                                {
                                    if (t != null && !t.stop_between_packs)
                                        cut = true; //its share carried: the packs left go in the next burst
                                    return true;    //EOF, packet done — cleanup runs at the Chain level: the captured OnStreamComplete hook, else the stream-end default
                                }

                                if (maxStreamBytes < (_total += n))
                                    throw new InvalidOperationException("Stream would exceed max size of " + maxStreamBytes + " bytes.");
                                dst.byte_ += n;
                            }
                            else //plain byte source (file/stream)
                            {
                                //Stream.Read returns 0 ONLY at EOF — never as a transient "no data yet" — so a single test
                                //covers the end of the source; there is no separate short-read park to handle.
                                var n = src!.Read(dst.buffer!, dst.byte_, dst.byte_max - dst.byte_);
                                if (n == 0)
                                    return true; //EOF, packet done — cleanup runs at the Chain level: the captured OnStreamComplete hook, else the stream-end default

                                if (maxStreamBytes < (_total += n))
                                    throw new InvalidOperationException("Stream would exceed max size of " + maxStreamBytes + " bytes.");
                                dst.byte_ += n;
                            }
                        }

                        dst.buffer = buf;
                        return false; //buffer full → more may remain (park)
                    }
                }
            }

            ///<summary>
            ///Transmit-side error taxonomy: the codes reported to the <see cref="OnErrorHandler"/> when a pack
            ///cannot be sent (queue overflow, rejected/discarded packs, timeouts).
            ///</summary>
            public enum OnError
            {
                ///<summary>
                ///Transmitting packet was rejected by dataflow or business logic rules.
                ///</summary>
                REJECTED = 0,

                ///<summary>
                ///Buffer overflow occurred, typically because a declared length exceeds
                ///the buffer capacity or a predefined maximum size.
                ///</summary>
                OVERFLOW = 1,

                ///<summary>
                ///Timeout occurred during packet transmission or reception.
                ///</summary>
                TIMEOUT = 2,

                ///<summary>
                ///Generic/unspecified error during packet processing or handling.
                ///</summary>
                ERROR = 3,

                ///<summary>
                ///Unsent packets were discarded because the actor was closed or disposed.
                ///</summary>
                DISCARDED_ONCLOSE = 4,

                ///<summary>
                ///Unsent packets were discarded due to current state rules
                ///or protocol state expectations.
                ///</summary>
                DISCARDED_BYSTATE = 5,

                ///<summary>
                ///Attempted to send a packet by an actor that does not support
                ///transmitting or sending messages (no transmit/send behavior defined).
                ///</summary>
                ACTOR_NOT_TRANSMITTABLE = 6,
            }

            ///<summary>
            ///Process-wide sink for transmit-side errors (queue overflow, rejected/discarded packs, timeouts).
            ///Defaults to a handler that writes to the console; replace it to route errors elsewhere. Shared by
            ///all transmitters, so assign once at startup.
            ///</summary>
            public static OnErrorHandler error_handler = OnErrorHandler.DEFAULT;

            ///<summary>
            ///Defines an interface for handling errors that occur in a `BytesSrc` context.
            ///</summary>
            public interface OnErrorHandler
            {
                ///<summary>
                ///A default `OnErrorHandler` implementation that logs errors to the console.
                ///</summary>
                static OnErrorHandler DEFAULT = new ToConsole();

                ///<summary>
                ///A concrete `OnErrorHandler` that writes error information to the console.
                ///</summary>
                class ToConsole : OnErrorHandler
                {
                    ///<summary>
                    ///Handles a `BytesSrc` error by printing details to the console.
                    ///</summary>
                    ///<param name="src">The `AdHoc.BytesSrc` where the error occurred.</param>
                    ///<param name="arg">Additional data (e.g., the packet being processed/purged).</param>
                    ///<param name="error">The type of error .</param>
                    ///<param name="ex">An optional exception associated with the error.</param>
                    public void error(AdHoc.BytesSrc src, object? arg, OnError error, Exception? ex = null)
                    {
                        switch (error)
                        {
                            case OnError.DISCARDED_ONCLOSE:
                                //arg contains the packet that was left in the queue
                                Console.WriteLine("DISCARDED_ONCLOSE (Connection Closed). Dropped pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.DISCARDED_BYSTATE:
                                Console.WriteLine("DISCARDED (State Rule). Pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.OVERFLOW:
                                Console.WriteLine("OVERFLOW at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.REJECTED:
                                Console.WriteLine("REJECTED at " + src + (ex == null ? "" : ex + Environment.StackTrace));

                                return;
                            case OnError.TIMEOUT:
                                Console.WriteLine("TIMEOUT. Pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            case OnError.ERROR:
                                Console.WriteLine("ERROR. Pack: " + arg + " at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                            default:
                                Console.WriteLine("Error at " + src + (ex == null ? "" : ex + Environment.StackTrace));
                                return;
                        }
                    }
                }

                ///<summary>
                ///Handles a `BytesSrc` error.
                ///</summary>
                ///<param name="src">The `AdHoc.BytesSrc` where the error occurred.</param>
                ///<param name="arg"></param>
                ///<param name="error">The type of error.</param>
                ///<param name="ex">An optional exception associated with the error.</param>
                void error(AdHoc.BytesSrc src, object? arg, OnError error, Exception? ex = null);
            }

            ///<summary>
            ///Defines an interface for handling events generated by a `Transmitter`.
            ///</summary>
            public interface EventsHandler
            {
                ///<summary>
                ///Called just before a packet's serialization process begins via its `BytesSrc` handler.
                ///</summary>
                ///<param name="dst">The `Transmitter` instance that is about to send the packet.</param>
                ///<param name="src">The `BytesSrc` instance representing the packet to be serialized.</param>
                void OnSerializing(Transmitter dst, BytesSrc src) {}

                ///<summary>
                ///Called after a complete packet has been successfully serialized and (notionally) sent
                ///from the internal perspective of the `Transmitter`'s processing loop.
                ///The actual transmission to an external sink depends on the `Transmitter.Read` method being called.
                ///</summary>
                ///<param name="dst">The `Transmitter` instance that has completed sending the packet.</param>
                ///<param name="src">The `BytesSrc` in
                ///stance representing the packet that was sent.</param>
                void OnSerialized(Transmitter dst, BytesSrc src) {}
            }

            ///<summary>
            ///The current event handler for this transmitter.
            ///</summary>
            protected EventsHandler? handler;

            ///<summary>
            ///Atomically exchanges the current event handler with a new one.
            ///</summary>
            ///<param name="handler">The new event handler to set.</param>
            ///<returns>The event handler that was previously set.</returns>
            public EventsHandler exchange(EventsHandler handler) => Interlocked.Exchange(ref this.handler, handler);

            ///<summary>
            ///Initializes a new instance of the <see cref="org.unirail.AdHoc.Transmitter.Transmitter"/> class.
            ///</summary>
            ///<param name="handler">The event handler for transmitter events.</param>
            ///<param name="power_of_2_sending_queue_size">The size of the internal sending queues, expressed as a power of 2 (e.g., 5 for a size of 2^5=32). Default is 5.</param>
            public Transmitter(EventsHandler handler, int power_of_2_sending_queue_size = 5) : base(power_of_2_sending_queue_size)
            {
                this.handler = handler;
                root = new Slot(this, null);
            }
#region sending
            //do not forget to  set u8 = sending_out.value;
            protected abstract BytesSrc? _OnSerializing();
            protected abstract void _OnSerialized(BytesSrc bytes);

            public abstract bool IsIdle();

            //No lock for the sending queue: the generated connection keeps it in a RingBuffer - one CAS a put, one a take,
            //and a close from any thread empties it.
#endregion
#region value_pack transfer
            ///<summary>
            ///Sets `u8` to `src`, then calls `put_bytes(handler, next_case)` to serialize a nested message.
            ///This is used when `src` itself is the value to be serialized by `handler`.
            ///</summary>
            ///<param name="src">The `ulong` value to be effectively passed to or used by the `handler`.</param>
            ///<param name="handler">The `BytesSrc` handler for the nested message part.</param>
            ///<param name="next_case">The state to retry at if serialization by `handler` requires more buffer space.</param>
            ///<returns>True if `handler` completed serialization successfully; false if a retry is needed.</returns>
            public bool put_bytes(ulong src, BytesSrc handler, uint next_case)
            {
                u8 = src;
                return put_bytes(handler, next_case);
            }

            ///<summary>
            ///Sets `u8` to `src`, then calls `put_bytes(handler)` to serialize a nested message.
            ///This is used when `src` itself is the value to be serialized by `handler`, assuming no retry is needed.
            ///</summary>
            ///<param name="src">The `ulong` value to be effectively passed to or used by the `handler`.</param>
            ///<param name="handler">The `BytesSrc` handler for the nested message part.</param>
            public void put_bytes(ulong src, BytesSrc handler)
            {
                u8 = src;
                put_bytes(handler);
            }

            ///<summary>
            ///Invokes the `__get_bytes` method on the provided `BytesSrc` instance `src`
            ///to serialize its data using the current transmitter context.
            ///Assumes `src` is part of the current serialization slot, skipping packet ID writing.
            ///</summary>
            ///<param name="src">The `BytesSrc` instance to serialize.</param>
            public void put_bytes(BytesSrc src)
            {
                slot!.state = 1; //skip write id
                src.__get_bytes(this);
            }

            ///<summary>
            ///Serializes a nested object into the byte stream, managing the serialization stack.
            ///The method advances the slot stack and directly invokes the serializer (`__get_bytes`)
            ///for the nested <paramref name="src"/> object.
            ///</summary>
            ///<param name="src">The <see cref="BytesSrc"/> instance (typically a Pack serializer) that will provide the bytes.</param>
            ///<param name="next_case">The state for the parent slot to transition to if serialization is incomplete
            ///(e.g., buffer full) and requires a retry.</param>
            ///<returns><c>true</c> if the entire object was successfully serialized into the current buffer.
            ///Returns <c>false</c> if the buffer became full and a retry is needed.</returns>
            public bool put_bytes(BytesSrc src, uint next_case)
            {
                var O = slot!; //Store current slot to manage the serialization stack.
                //Advance to the next slot in the chain for the nested object.
                slot = O.next ?? (O.next = new Slot(this, O));

                slot.src = src;
                slot.state = 1;

                if (src.__get_bytes(this))
                {
                    slot = O;
                    return true;
                }

                O.state = next_case;
                return false;
            }

            ///<summary><c>int</c> overload of <see cref="put_bytes(BytesSrc,uint)"/> — the generated code passes an <c>int next_case</c>.</summary>
            public bool put_bytes(BytesSrc src, int next_case) => put_bytes(src, (uint)next_case);

            ///<summary>
            ///<see cref="put_bytes(BytesSrc,uint)"/> whose nested slot starts at <paramref name="enter"/>: a pack that is the leaf
            ///of the chain on one of its collection fields writes the field from its own case.
            ///</summary>
            public bool put_bytes(BytesSrc src, int enter, int next_case)
            {
                var O = slot!;
                slot = O.next ?? (O.next = new Slot(this, O));

                slot.src = src;
                slot.state = (uint)enter;

                if (src.__get_bytes(this))
                {
                    slot = O;
                    return true;
                }

                O.state = (uint)next_case;
                return false;
            }
#endregion

            ///<summary>
            ///The framing encoder of a byte stream: COBS with 0xFF as the delimiter ( <see cref="Receiver.Framing"/> ). A pack goes
            ///as 0xFF, then its bytes and its CRC-32C in blocks: up to a 0xFF of the data closer than 254 bytes a short block - the
            ///0xFF taken out, its code implies it -, else a long block up to the 0xFF, <see cref="LONG"/> bytes or the end of the
            ///bytes the buffer has. No byte waits for the ones after it.
            ///</summary>
            public class Framing : AdHoc.BytesSrc, EventsHandler
            {
                public bool isOpen() => upper_layer.isOpen(); //Check if the upper layer is open

                ///<summary>
                ///The `Transmitter` instance from which raw, unframed packet data is read.
                ///</summary>
                public Transmitter upper_layer; //Handles transmission of encoded frames

                ///<summary>
                ///Handles events for the encoding process, typically forwarding them from the original handler of the `upper_layer` before it was hooked by this framing instance.
                ///</summary>
                public EventsHandler handler; //Encoding process event handler

                ///<summary>
                ///Atomically exchanges the current event handler with a new one.
                ///</summary>
                ///<param name="handler">New event handler</param>
                ///<returns>Previous event handler</returns>
                public EventsHandler exchange(EventsHandler handler) => Interlocked.Exchange(ref this.handler, handler);

                ///<summary>
                ///Initializes a new instance of the <see cref="Framing"/> class.
                ///</summary>
                ///<param name="upper_layer">The `Transmitter` instance that will provide the raw packets to be framed.</param>
                public Framing(Transmitter upper_layer) => switch_to(upper_layer);

                ///<summary>
                ///Switches the framing layer to operate on a new `upper_layer` transmitter.
                ///This also resets the internal state of the framing encoder and hooks its event handling into the new `upper_layer`.
                ///</summary>
                ///<param name="upper_layer">New `Transmitter` instance to provide raw packets.</param>
                public void switch_to(Transmitter upper_layer)
                {
                    crc = 0;
                    if (this.upper_layer != null)
                    {
                        this.upper_layer.reset();
                        this.upper_layer.exchange(handler);
                    }

                    handler = (this.upper_layer = upper_layer).exchange(this);
                }

                int enc_position; //Current position for writing encoded bytes
                int raw_position; //Current position for reading raw input bytes

                ///<summary>
                ///The room the encoded bytes of a pack may take beyond its raw ones in a buffer, but for its long blocks: its
                ///0xFF, the head of the long block the end of the buffer ends, the code and the CRC of its last block, the word a
                ///short block is copied with.
                ///</summary>
                const int RESERVE = 1 + 3 + 1 + CRC_LEN_BYTES + 8;

                ///<summary>
                ///Where the raw bytes go in the output buffer: behind room for their encoding - <see cref="RESERVE"/>, and an
                ///eighth of the room: the heads of long blocks, a 3 in 254 at most, and a copy of the raw bytes down to their
                ///place far from them.
                ///</summary>
                ///<param name="limit">The total available size of the current output buffer segment.</param>
                ///<returns>True if room is left for raw bytes.</returns>
                bool allocate_raw_bytes_space(int limit)
                {
                    raw_position = enc_position + RESERVE + (limit - enc_position) / 8;
                    return raw_position < limit;
                }

                public void Close()
                {
                    Reset();
                    upper_layer.Close();
                }

                ///<summary>
                ///Resets the internal state of the framing encoder and the `upper_layer` transmitter.
                ///This prepares it for a new sequence of packets or a new connection.
                ///</summary>
                protected void Reset()
                {
                    upper_layer.reset();
                    crc = 0;
                }

                ///<summary>
                ///Reads raw packet data from the `upper_layer` and writes it framed into `dst`.
                ///</summary>
                ///<param name="dst">The destination buffer for the encoded, framed data.</param>
                ///<param name="dstByte">The starting offset in `dst` to write to.</param>
                ///<param name="dst_bytes">The maximum number of bytes to write to `dst`.</param>
                ///<returns>
                ///The number of bytes written to `dst`.
                ///Returns 0 if `dst` has insufficient space.
                ///Returns -1 if the `upper_layer` has no more raw packets to provide.
                ///</returns>
                public int Read(byte[] dst, int dstByte, int dst_bytes)
                {
                    enc_position = dstByte;
                    var limit = dstByte + dst_bytes;

                    while (allocate_raw_bytes_space(limit))
                    {
                        var fix = raw_position;
                        var len = upper_layer.Read(dst, raw_position, limit - raw_position);

                        if (len < 1)
                            return dstByte < enc_position ? enc_position - dstByte : len;

                        encode(dst, fix + len);
                    }

                    return dstByte < enc_position ? enc_position - dstByte : 0;
                }

                public void OnSerializing(Transmitter dst, BytesSrc src)
                {
                    handler?.OnSerializing(dst, src);
                    dst.buffer![enc_position++] = 0xFF; //write starting frame byte
                }

                ///<summary>
                ///The `upper_layer` serialized a pack: its bytes left, then its CRC in short blocks - the last one ends the
                ///pack; the bytes of the pack after its last 0xFF, fewer than 250, go in the first of them.
                ///</summary>
                public void OnSerialized(Transmitter dst, BytesSrc src)
                {
                    var b = dst.buffer!;
                    var max = dst.byte_;
                    encode(b, max, true);
                    var fix = crc; //the high byte first
                    int e = enc_position, code = e++;
                    var j = max - raw_position;
                    if (0 < j)
                    {
                        b.AsSpan(raw_position, j).CopyTo(b.AsSpan(e, j)); //e <= raw_position
                        e += j;
                    }

                    for (var i = 24; -1 < i; i -= 8)
                    {
                        var x = (byte)(fix >> i);
                        if (x == 0xFF) //ends its block: the code implies it
                        {
                            b[code] = (byte)(e - code - 1);
                            code = e++;
                        }
                        else
                            b[e++] = x;
                    }

                    b[code] = (byte)(e - code - 1);
                    enc_position = e;
                    crc = 0;

                    if (allocate_raw_bytes_space(dst.byte_max))
                        dst.byte_ = raw_position;
                    else
                        dst.byte_max = raw_position = dst.byte_; //no more space. prevent continue

                    handler?.OnSerialized(dst, src);
                }

                ///<summary>
                ///Encodes the raw bytes from <c>raw_position</c> up to <paramref name="max"/>, after the CRC took them: a short block
                ///up to a 0xFF of the data closer than 254 bytes - the vectorized IndexOf finds it -, else a long block; the bytes at
                ///the end go at once, as a long block. When <paramref name="last"/>, the bytes of the pack after its last 0xFF,
                ///fewer than 250, are left at <c>raw_position</c>: they go with the CRC.
                ///</summary>
                void encode(byte[] buf, int max, bool last = false)
                {
                    int r = raw_position, e = enc_position;
                    if (r < max)
                        crc = crc32c(crc, buf.AsSpan(r, max - r)); //before they are encoded over
                    ref var b = ref MemoryMarshal.GetArrayDataReference(buf);
                    while (r < max)
                    {
                        int j;
                        bool found;
                        ulong z;
                        if (r + 8 <= max && (z = ff_in(Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref b, r)))) != 0)
                        { //a short block: the word tells where it ends
                            j = BitOperations.TrailingZeroCount(z) >> 3;
                            found = true;
                        }
                        else
                        {
                            var scan = buf.AsSpan(r, Math.Min(max - r, LONG));
                            j = scan.IndexOf((byte)0xFF);
                            found = 0 <= j;
                            if (!found)
                            {
                                j = scan.Length;
                                if (last && r + j == max && j < 250)
                                    break;
                            }
                        }

                        int h;                //the bytes of the head of the block
                        if (found && j < 254) //a short block: up to a 0xFF of the data, the code implies it
                        {
                            buf[e] = (byte)j;
                            h = 1;
                        }
                        else //a long block: up to a 0xFF, LONG bytes or the end of the bytes here, no 0xFF implied
                        {
                            buf[e] = 254;
                            buf[e + 1] = (byte)(j % 255);
                            buf[e + 2] = (byte)(j / 255);
                            h = 3;
                        }

                        if (j <= 8 && r + 8 <= buf.Length) //a short block as a word: the gap ( RESERVE ) takes the overrun
                            Unsafe.WriteUnaligned(ref Unsafe.Add(ref b, e + h), Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref b, r)));
                        else
                            buf.AsSpan(r, j).CopyTo(buf.AsSpan(e + h, j)); //e + h <= r: the bytes behind the block are not reached
                        e += h + j;
                        r += found && h == 1 ? j + 1 : j; //a 0xFF of the data is taken out: the code implies it
                    }

                    raw_position = r;
                    enc_position = e;
                }

                uint crc; //CRC-32C of the raw bytes of the pack so far.
            }
#region Slot
            ///<summary>
            ///A journalling transport stage. It hands the transmitter's bytes on unchanged and keeps a copy of the
            ///packs the generated code brackets with <see cref="packStart"/> / <see cref="packEnd"/>, so that a peer
            ///whose socket died can have the stream continued from the position it names.
            ///<para>It is the FIRST stage of a connection's chain and reads straight from the <see cref="Transmitter"/>
            ///(<see cref="Init_"/>). What it journals is what a compressor or cipher standing outside it transforms on
            ///the way out, so a replay is transformed again on the fresh socket.</para>
            ///<para>Inside the stage a position is a byte offset in the journalled stream, counted from the start of the
            ///session. On the wire — the header of a marked pack, <c>Resume_</c>, <c>Ack_</c>, <c>Lost_</c> — a position is
            ///two fields: <c>pos</c>, the low 32 bits of the offset, and <c>time</c>, the low <see cref="TIME_BITS"/> of the
            ///unix seconds the pack is sent at. The offset is resolved back against <see cref="next_"/> by a signed 32-bit
            ///difference, so a session's positions must stay within 2 GB of each other: <see cref="capacity"/> is capped at
            ///half that. The seconds tell a position of an earlier session apart: one older than the oldest byte the journal
            ///holds is not this session's. Offsets:
            ///<see cref="base_"/> — the first byte still held;
            ///<see cref="acked_"/> — acknowledged by the peer, what lies below it is given back: files whole, the buffer in memory on every acknowledgement;
            ///<see cref="sent_"/> — handed to the transport, <see cref="resume"/> moves it;
            ///<see cref="next_"/> — produced so far, and the position the next marked pack gets.
            ///Invariant: <c>base &lt;= acked &lt;= sent &lt;= next</c>.</para>
            ///<para>Who knows where a pack ends: the receiver, and nobody else - it is the one that parses the packs. It moves
            ///its position only when a marked pack has been received whole, so the position it names - in <c>Ack_</c>, in
            ///<c>Resume_</c> - always stands on a pack boundary. By design this stage keeps bytes and positions and needs no
            ///boundary: it continues from the position it is given. The record of pack starts kept here serves the datagram
            ///transport only - see the region <c>datagram transport</c>.</para>
            ///<para>Storage: the newest bytes are held in a buffer in memory, <see cref="HOT"/> bytes at first. While the
            ///connection is open the buffer doubles whenever it fills, up to one <see cref="segment"/>: a connection whose peer
            ///keeps up with its acknowledgements never touches a file. A backlog beyond it goes to files under
            ///<see cref="dir"/>, <see cref="FILE"/> bytes each, the last one still being written. While the connection is
            ///closed and the session is kept the journal lives on the disk: at the close a buffer that has grown gives what it
            ///holds to the files and takes its first size again, and the packs queued meanwhile go to the files through it. A
            ///replay reads the files straight into the transport buffer, the tail from the buffer in memory. Files entirely
            ///below the acknowledged position are deleted on every <see cref="ack"/>; once everything is acknowledged no byte
            ///of the journal is held.
            ///<see cref="capacity"/> caps the journal; at the cap <see cref="Read"/> produces nothing until an <see cref="ack"/>
            ///frees room. The peer acknowledges when asked: <see cref="packEnd"/> tells the generated code when to send that
            ///ask, behind the data it refers to.</para>
            ///<para>Lifecycle: from creation, and after <see cref="Close"/> finds <see cref="External.resumable"/>
            ///unexpired, the stage is <see cref="awaiting"/>: marked packs are journalled only, until the position the peer
            ///names arrives through <see cref="resume"/>. A session ends when <c>Close()</c> finds the deadline
            ///expired, or when a file operation fails: the files are deleted, the positions are re-seeded and, on a
            ///failure, the socket is aborted.</para>
            ///<para>A session starts on a connection - the first one, or the next after a loss - in this order, and nothing
            ///leaves the stage out of it:</para>
            ///<list type="number">
            ///<item>Identification. Until the session is known, nobody can tell whether something of it is parked and from
            ///where it goes on. The side that made the connection knows its peer and identifies its session at once
            ///( <c>identify</c> / <c>reclaim</c> on connect ); then it sends its login - unmarked packs, the only ones that
            ///leave the stage before the two sides agreed. The side that took the connection identifies the session by the
            ///login ( or at the connect, when it knows the peer otherwise ).</item>
            ///<item>Agreement. From the identification on the side that took the connection nothing leaves its stage, marked
            ///or unmarked, but what agrees the positions: the packs of <see cref="Connection.Control"/> over a stream, the
            ///headers of the datagrams over a datagram transport. Each side names the position its decoder has got to in the
            ///peer's journal - a pack in progress counted - and each journal goes on from the position named. The side that
            ///made the connection sends nothing more either once it has heard the peer's position, until its answer is out
            ///( over datagrams the position heard is the agreement itself: its journal goes on from it at once ).</item>
            ///<item>Only then do the packs flow: the replay of the journal first, then the queue.</item>
            ///</list>
            ///<para>Why nothing in between: a parked session keeps the pack its decoder had in progress, and the decoder takes
            ///the bytes that follow as the rest of that pack. A pack sent between the identification and the agreement - even
            ///an unmarked one - would be glued into it, and the stream would be broken from there on. For the same reason the
            ///receiving side takes nothing of what comes before the position it named: the datagrams of a series that runs
            ///when it asks for a new one ( <c>Network.UDP.Peer.ask</c> ), the packs that are not of the agreement over a
            ///stream ( <see cref="Receiver.greeter"/> ). Here the rule is kept by <c>pull</c> - the side that took the
            ///connection - and by <c>agreeing</c> - over a stream.</para>
            ///<para><see cref="resume"/> and <see cref="ack"/> may be called from any thread. They post to the
            ///transport thread, which applies them at the start of its next <see cref="Read"/>, and wake it.</para>
            ///</summary>
            public class Resumable : AdHoc.BytesSrc
            {
#region clock
                ///<summary>
                ///Unix time in SECONDS, as a long: an int would overflow in 2038. 0 is 1970 and never a real
                ///reading, which leaves it free as the "not set" marker of every <c>resumable</c> field.
                ///</summary>
                public static long now() => DateTimeOffset.UtcNow.ToUnixTimeSeconds();

                ///<summary>True when <paramref name="deadline"/> is 0 or already passed.</summary>
                public static bool expired(long deadline) => deadline == 0 || deadline <= now();
#endregion
#region files of the journal
                ///<summary>
                ///Root of the files of the journal. Every process writes into its own subdirectory, named by its pid;
                ///Read on the first flush; the subdirectories of processes that are gone are left for the host to clean.
                ///</summary>
                public static string dir = Path.Combine(Path.GetTempPath(), "AdHoc", "journal");

                private static string? pid_dir;

                private static string pidDir()
                {
                    return pid_dir ??= Directory.CreateDirectory(Path.Combine(dir, Environment.ProcessId.ToString())).FullName; //idempotent: two threads create the same directory
                }

                private static bool alive(int pid)
                {
                    try
                    {
                        using var p = System.Diagnostics.Process.GetProcessById(pid);
                        return !p.HasExited;
                    }
                    catch (Exception e) when (e is ArgumentException or InvalidOperationException)
                    {
                        return false;
                    }
                }

                private static void delete (string file)
                {
                    try
                    {
                        System.IO.File.Delete(file);
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                    }
                }
#endregion

                ///<summary>
                ///Default <see cref="segment"/>: 4 MB. While the connection is open the journal lives in memory: what the peer has
                ///not reported yet is on its way or in its buffers, and the buffers of the sockets bound that. At this size the
                ///stage waits for a report: a report is a round trip away, a file is a system call and a disk.
                ///</summary>
                private const int SEGMENT = 1 << 22;

                ///<summary>
                ///The size of a file of the journal: 4 MB. Creating, opening and deleting a file costs far more than reading it
                ///or writing to it: the larger the files, the fewer of them.
                ///</summary>
                private const int FILE = 1 << 22;

                ///<summary>
                ///The buffer in memory at the start, and whenever the connection is closed: 2 KB. While the connection is open it
                ///doubles up to <see cref="segment"/> - see <see cref="flush"/> and <see cref="park"/>.
                ///</summary>
                private const int HOT = 1 << 11;

                ///<summary>
                ///The least room the transmitter makes progress in: it writes a fixed 8-byte value or a bits transaction whole or
                ///not at all, so under the cap the stage offers at least this much, or nothing.
                ///</summary>
                private const int ROOM = 16;

                ///<summary>The largest backlog held, in bytes: the files plus the buffer in memory.</summary>
                private readonly long capacity;

                ///<summary>Size of one segment, in bytes: the most the buffer in memory grows to.</summary>
                private readonly int segment;

                private Transmitter? src_; //null once the session is over

                ///<summary>The transmitter this stage journals; null once the session is over.</summary>
                public Transmitter? transmitter => src_;

                //The positions belong to the transmit runner: no other thread reads them. What the receive thread needs
                //for resume()/ack() is published once per pull — see publish().
                private long base_, acked_, sent_, next_;
                private long base_pub, acked_pub, sent_pub, next_pub, boundary_pub; //Volatile.Read/Write only

                ///<summary>The latest confirmation heard ( <see cref="ack"/> ), before the runner applies it: written by the thread that receives.</summary>
                private long heard_pub;

                //the files hold [base, hotBase()), hot holds [hotBase(), next); every file but the last is FILE bytes
                private readonly List<string> files = new();
                private FileStream? ch; //the last file, open while it is still being written
                private int written;    //bytes in the last file
                private byte[] hot = new byte[HOT];
                private int hot_off, hot_used; //a ring: what hot holds starts at hot_off, hot_used bytes, and goes round its end - a byte given back frees its place, nothing is moved
                private int pull_base;         //an offline pull serializes into the ring in a row: the place of the committed tail is pull_base + hot_used, see tail()
                private FileStream? replay_ch; //open on the file a replay is reading
                private int replay_index = -1; //its index in files

                //the marked pack in progress
                private bool open;
                private long open_start; //its stream position
                private int mark;        //where its unjournalled bytes start in the transmitter's buffer

                private bool awaiting_ = true, swallow; //transmit runner only; Close() runs while no runner is active

                private bool pulling; //inside src_.Read()

                //Who pulls the transmitter. OFFLINE (parked) — no socket: the application thread that queues a pack pulls it
                //straight into the journal, see wake()/drain(). ONLINE — the transmit runner pulls, see Read(). The switch
                //is thrown by online() from resume(connection) and back by Close() while the session is kept. `draining`
                //is the drain's eventcount: 0 idle, the increment 0→1 owns the drain; online() waits for it to reach 0.
                private volatile bool parked_ = true, closing;

                private int draining;

                //What the receive thread posts for the runner. `posted` is the only word the runner reads per pull; the
                //commands themselves are exchanged only once it is set, so a pull that has nothing to apply costs one
                //volatile read.
                private volatile bool posted, post_swallow;
                private long cmd_resume = NONE, cmd_ack = NONE;
                private long resume_at = NONE; //the position the peer named, waiting for a pack boundary
                private long replaying = NONE; //where the replay in progress started, NONE while none is
                private IOException? failure;  //set by fail(), thrown by the Read() in progress

                private const long NONE = -1;

                ///<param name="capacity">the largest backlog held, in bytes.</param>
                public Resumable(long capacity) : this(capacity, SEGMENT - (SEGMENT >> 3)) {}

                ///<param name="capacity">the largest backlog held, in bytes.</param>
                ///<param name="in_flight">how many bytes the peer has not confirmed yet the connection holds at most: at so many no pack
                ///is taken from the queue until the peer confirms. What is in flight when a socket is lost is sent again on the next one.</param>
                public Resumable(long capacity, int in_flight)
                {
                    if (1L << 31 < capacity)
                        throw new ArgumentOutOfRangeException(nameof(capacity), capacity, "The positions of a session must stay within a signed 32-bit offset of each other");
                    this.capacity = capacity;
                    this.segment = SEGMENT;
                    this.in_flight = Math.Min(in_flight, SEGMENT - (SEGMENT >> 3));
                    base_ = acked_ = sent_ = next_ = base_pub = acked_pub = sent_pub = next_pub = boundary_pub = heard_pub = Random.Shared.NextInt64(1L << 48, 1L << 61);
                }

                ///<summary>
                ///Binds the stage to the transmitter it reads from. The positions and the journal survive the call,
                ///so the generated <c>Init()</c> re-binds on every connect without losing the backlog.
                ///</summary>
                public Resumable Init_(Transmitter src_)
                {
                    this.src_ = src_;
                    src_.speed_by_src = true; //the transport takes the bytes here: its speed is measured here, not where the journal pulls
                    return this;
                }

                private void wakeRunner() => src_?.ext_connection?.WakeTransmit();

                ///<summary>
                ///A pack was queued on the transmitter: hands it to whoever pulls — the transmit runner while ONLINE, or this
                ///very thread while OFFLINE, which then journals every pack the queue holds. Called by the generated
                ///<c>sending_put0</c> on the queue's empty → non-empty edge, in place of <see cref="External.WakeTransmit"/>.
                ///</summary>
                public void wake()
                {
                    if (parked_)
                        drain();
                    else
                        wakeRunner();
                }

                ///<summary>
                ///ONLINE: the transmit runner owns the transmitter from here on. Called by the generated
                ///<c>resume(connection)</c> — on the thread the transport connects the session on, before it hands the
                ///connection a transmit buffer — after <c>ext_connection</c> has been set. Waits for an offline pull in
                ///progress to finish its pack, so the runner finds the transmitter free.
                ///</summary>
                public void online()
                {
                    parked_ = false;
                    var spin = new SpinWait();
                    while (Volatile.Read(ref draining) != 0)
                        spin.SpinOnce();
                }

                private void drain()
                {
                    if (Interlocked.Increment(ref draining) != 1)
                        return; //the drain in progress sees the count changed and pulls again
                    drain_();
                }

                ///<summary>
                ///Owns <see cref="draining"/>: runs a deferred <see cref="Close"/>, then journals the queue while OFFLINE — one
                ///pack per pull, so <see cref="online"/> never waits for more — until the count it saw is released. A pack
                ///queued meanwhile bumped the count: the release fails and the loop pulls again.
                ///</summary>
                private void drain_()
                {
                    for (;;)
                    {
                        var seen = Volatile.Read(ref draining); //what was posted before this read is served by this pass; a later post fails the release below
                        try
                        {
                            if (closing)
                            {
                                closing = false;
                                close_();
                            }

                            while (parked_ && src_ != null && journal())
                                ;
                        }
                        catch (IOException e)
                        {
                            Transmitter.error_handler.error(src_, null, OnError.ERROR, e);
                        }

                        if (Interlocked.CompareExchange(ref draining, 0, seen) == seen)
                            break;
                    }

                    if (!parked_)
                        wakeRunner(); //went ONLINE under us: what is queued is the runner's now
                }

                ///<summary>
                ///One offline pull: the transmitter serializes straight into the free tail of <see cref="hot"/>;
                ///<see cref="packEnd"/> commits the marked pack in place, unmarked bytes are left uncommitted and overwritten
                ///by the next pull. The generated <c>_OnSerializing</c> skips unmarked packs while <see cref="Transmitter.journal_only"/>.
                ///</summary>
                ///<returns><c>false</c> when the transmitter is dry or the journal is at <see cref="capacity"/>.</returns>
                private bool journal()
                {
                    var free = capacity - (next_ - acked_); //what is confirmed is the peer's: a file below it waits to be whole, it is not held for the peer
                    if (free < ROOM)
                        return false;
                    var start = tail();
                    var room = (int)Math.Min(start < hot_off ? hot_off - start : hot.Length - start, free);
                    if (open)
                        mark = start; //the pack parked mid-serialization continues here
                    src_!.journal_only = true;
                    try
                    {
                        var n = src_.Read(hot, start, room);
                        if (open && 0 < n)
                            append(hot, mark, start + n - mark); //the part of the open pack this pull produced, committed in place
                        if (failure != null)
                            throw takeFailure();
                        publish();
                        return 0 < n;
                    }
                    finally
                    {
                        src_.journal_only = false;
                    }
                }

                ///<summary>
                ///Where an offline pull serializes into <see cref="hot"/>: the place of its tail, with <see cref="ROOM"/> at least free in
                ///a row from it - up to the end of the array, or up to the start of the ring once it went round. A ring nearly full
                ///is made room in by <see cref="flush"/>; the short end of the array before a free head - a pull that stopped right
                ///there - by moving what is held, in a row then, to the front: rare.
                ///</summary>
                private int tail()
                {
                    for (;;)
                    {
                        if (hot_used == 0)
                            hot_off = 0;
                        var end = hot_off + hot_used;
                        if (end < hot.Length)
                        {
                            if (ROOM <= hot.Length - end)
                                return pull_at(end);
                            if (ROOM <= hot_off)
                            {
                                Array.Copy(hot, hot_off, hot, 0, hot_used);
                                hot_off = 0;
                                return pull_at(hot_used);
                            }
                        }
                        else if (ROOM <= hot.Length - hot_used)
                            return pull_at(end - hot.Length);

                        flush();
                    }
                }

                private int pull_at(int at)
                {
                    pull_base = at - hot_used;
                    return at;
                }

                ///<summary>The place in the ring of the byte <paramref name="i"/> places past its start.</summary>
                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                private int hot_at(int i)
                {
                    var at = hot_off + i;
                    return at < hot.Length ? at : at - hot.Length;
                }

                ///<summary>What the ring holds, in order, to the front of <paramref name="to"/> - at most two copies; the ring starts at 0 then.</summary>
                private void hot_into(byte[] to)
                {
                    var first = Math.Min(hot_used, hot.Length - hot_off);
                    Array.Copy(hot, hot_off, to, 0, first);
                    Array.Copy(hot, 0, to, first, hot_used - first);
                    hot_off = 0;
                }

                ///<summary>The position of the first byte in <see cref="hot"/>: past every file, the last one as far as it is written.</summary>
                private long hotBase() => files.Count == 0 ? base_ : base_ + (files.Count - 1) * (long)FILE + written;

                ///<summary>Stops the pull in progress right where the transmitter is: it sees no room left and returns.</summary>
                private void cut()
                {
                    var src_ = this.src_!;
                    src_.byte_max = src_.byte_;
                }

                ///<summary>
                ///Snapshots what the receive thread reads in <see cref="resume"/> and <see cref="ack"/>. Once per pull, and
                ///only the words that changed.
                ///</summary>
                private void publish()
                {
                    if (base_pub != base_)
                        Volatile.Write(ref base_pub, base_);
                    if (acked_pub != acked_)
                        Volatile.Write(ref acked_pub, acked_);
                    if (sent_pub != sent_)
                        Volatile.Write(ref sent_pub, sent_);
                    if (next_pub != next_)
                        Volatile.Write(ref next_pub, next_);
                    var b = open ? open_start : next_;
                    if (boundary_pub != b)
                        Volatile.Write(ref boundary_pub, b);
                }

                ///<summary>
                ///Marks the start of a pack to journal. Called by the generated <c>OnSerializing</c> before the pack id is written.
                ///</summary>
                public void packStart()
                {
                    if (src_ == null)
                        return;
                    if (src_.journal_only)
                        src_.byte_ = pull_base + hot_used; //an offline pull: whatever an unmarked pack left uncommitted is overwritten
                    open = true;
                    mark = src_.byte_;
                    open_start = next_;
                }

                ///<summary>
                ///Marks the end of the pack started by <see cref="packStart"/> and copies its bytes into the journal.
                ///Called by the generated <c>OnSerialized</c>.
                ///</summary>
                public void packEnd()
                {
                    if (!open)
                        return;
                    open = false;
                    var src_ = this.src_!;
                    append(src_.buffer!, mark, src_.byte_ - mark);
                    end(next_);
                    if (swallow || awaiting_ || turning || resume_at != NONE)
                        cut(); //one marked pack per pull, at its end: Read() drops it from the buffer, or switches to the journal there
                }

                //The ends of the packs journalled above the base, in order. A stream confirms in the middle of a pack, but gives a
                //pack back only once the confirmation passed its end: the journal starts at the start of a pack, so a peer that
                //has none of the journal is told a position a pack starts at ( resume ). A ring: no object per pack.
                private long[] ends = new long[16];
                private int ends_head, ends_count;

                private void end(long position)
                {
                    if (ends_count == ends.Length)
                    {
                        var grown = new long[ends.Length << 1];
                        for (var i = 0; i < ends_count; i++)
                            grown[i] = ends[(ends_head + i) & (ends.Length - 1)];
                        ends = grown;
                        ends_head = 0;
                    }
                    ends[(ends_head + ends_count++) & (ends.Length - 1)] = position;
                }

                ///<summary>Where the journal may start: the end of the last pack the confirmation passed - over datagrams, the confirmation itself.</summary>
                private long releasable()
                {
                    while (0 < ends_count && ends[ends_head] <= acked_)
                    {
                        whole_end = ends[ends_head];
                        ends_head = (ends_head + 1) & (ends.Length - 1);
                        ends_count--;
                    }
                    return datagram ? acked_ : Math.Max(whole_end, base_);
                }

                private long whole_end; //the end of the last pack the confirmation passed: the journal may start there

                private bool datagram; //a datagram transport runs this stage: the peer may take the stream up from the middle of a pack

                ///<summary>The positions, for the transport that runs this stage: acknowledged, handed out, produced.</summary>
                public long acked => acked_;

                public long sent => sent_;
                public long next => next_;

                ///<summary>How many replays began, and how many bytes they sent: a measure of what the losses cost.</summary>
                public long replays, replayed;

                ///<summary>For a log line: the positions, relative to <see cref="base_"/>, where the journal is held, and the state.</summary>
                public override string ToString() => $"replays={replays}/{replayed}B journal base={base_} acked=+{acked_ - base_} sent=+{sent_ - base_} next=+{next_ - base_} buffer={hot_used}/{hot.Length} files={files.Count}{(parked_ ? " OFFLINE" : "")}{(awaiting_ ? " awaiting" : "")}{(swallow ? " swallow" : "")}{(resume_at != NONE ? " resume_at=" + resume_at : "")}{(posted ? " posted" : "")}";
#region datagram transport
                //A datagram transport runs this stage itself. Its loop is the transmit runner and the reader of the peer's
                //reports at once, so what the peer says is applied where it is heard: nothing is posted from thread to thread.
                //The peer names bytes, not packs: how many bytes of this journal it has received. The journal is given back
                //up to that byte, and after a loss the stream goes on from that byte - in the middle of a pack, if the loss cut
                //one. Where the packs start the stage does not know and does not need to.

                private bool turning;      //a pack in the middle of serialization is being finished into the journal: see finish()
                private bool whole = true; //base stands on the start of a pack: nothing was given back in the middle of one yet

                ///<summary>
                ///The peer has received every byte of this journal below the position whose low 32 bits are <paramref name="pos"/>:
                ///they are given back. On the loop of the transport.
                ///</summary>
                public void reported(int pos)
                {
                    if (src_ == null)
                        return;
                    datagram = true;
                    var at = Math.Min(next_ + (pos - (int)next_), next_);
                    if (at <= acked_)
                        return;
                    acked_ = at;
                    if (sent_ < at)
                        sent_ = at; //the stream was turned back past what the peer holds: that is not sent again
                    whole = false;
                    release();
                    publish();
                }

                ///<summary>
                ///The peer asks the stream to go on from <paramref name="position"/> of this journal - it lost a datagram, or the
                ///connection is a new one. A guaranteed pack in the middle of serialization is finished into the journal and is not
                ///sent: what the peer has of it is in the journal, and the rest follows from there. An unguaranteed one is dropped:
                ///the peer dropped its head. On the loop of the transport.
                ///</summary>
                ///<returns><c>-1</c>: the stream goes on from <paramref name="position"/>. Otherwise the journal does not hold it - it
                ///is the position of another journal, or none at all - and the stream goes on from the position returned, the start
                ///of a pack: the peer is to be told.</returns>
                public long turn(long position)
                {
                    if (src_ == null)
                        return next_;
                    finish();
                    awaiting_ = swallow = false;
                    resume_at = NONE;
                    try
                    {
                        if (position < base_ || next_ < position)
                        {
                            closeReplay();
                            replaying = NONE;
                            if (!whole)
                            { //what is held starts in the middle of a pack the peer has no head of
                                discard();
                                base_ = next_;
                                whole = true;
                            }

                            return acked_ = sent_ = base_;
                        }

                        if (position < acked_)
                            acked_ = position;
                        closeReplay();
                        sent_ = replaying = position;
                        if (position < next_)
                            replays++;
                        else
                            replaying = NONE;
                        return -1;
                    }
                    finally
                    {
                        publish();
                    }
                }

                ///<summary>
                ///The pack in the middle of serialization ends here: a guaranteed one in the journal, where its head is - past
                ///<see cref="capacity"/> if it takes that, a pack begun is finished; an unguaranteed one nowhere.
                ///</summary>
                private void finish()
                {
                    var src_ = this.src_!;
                    if (!open)
                    {
                        if (src_.isOpen())
                            src_.Abandon();
                        return;
                    }

                    turning = true;
                    src_.journal_only = true;
                    try
                    {
                        while (open)
                        {
                            var start = tail();
                            mark = start;
                            var n = src_.Read(hot, start, start < hot_off ? hot_off - start : hot.Length - start);
                            if (open && 0 < n)
                                append(hot, mark, start + n - mark); //the part of the pack this pull produced, committed in place
                            if (failure != null)
                                throw takeFailure();
                            if (n < 1)
                                break; //the transmitter made no step: it is closed
                        }
                    }
                    finally
                    {
                        src_.journal_only = false;
                        turning = false;
                    }
                }
#endregion

                ///<summary>
                ///The journal holds bytes the peer has not confirmed: a session that lost its socket has them to send again on
                ///the next one - a dialing side dials again for them ( <see cref="Network.TCP.Redial"/> ). From any thread.
                ///</summary>
                public bool unconfirmed => Volatile.Read(ref acked_pub) < Volatile.Read(ref next_pub);

                ///<summary>
                ///What the peer has confirmed of this journal: a position, which moves while the link carries bytes - as each
                ///confirmation is heard, while the runner may wait for a send of megabytes the system has not taken yet. From any thread.
                ///</summary>
                public long confirmed => Math.Max(Volatile.Read(ref acked_pub), Volatile.Read(ref heard_pub));

                ///<summary>
                ///Bytes sent and not confirmed yet: once a step's worth is out the peer owes a confirmation, and if none comes
                ///the link carries nothing ( <see cref="Network.TCP.Redial.Stalled"/> ). From any thread.
                ///</summary>
                public long owed => Volatile.Read(ref sent_pub) - Volatile.Read(ref acked_pub);

                ///<summary>The journal holds <paramref name="position"/>: the stream can go on from it. From any thread.</summary>
                public bool holds(long position) => Volatile.Read(ref base_pub) <= position && position <= Volatile.Read(ref next_pub);

                ///<summary>How many bytes the peer has not confirmed yet the connection holds at most: in memory, under a segment.</summary>
                private readonly int in_flight;

                ///<summary>The position <paramref name="low"/> - a position as it travels, its bits under <paramref name="mask"/> - means: the nearest one to the end of the journal. From any thread.</summary>
                public long resolve(long low, long mask)
                {
                    var at = Volatile.Read(ref next_pub);
                    if (mask == -1L)
                        return low;
                    var d = (low - at) & mask;
                    if ((long)((ulong)mask >> 1) < d)
                        d -= mask + 1;
                    return at + d;
                }

                ///<summary>Nobody to wait for: the stream continues from the current position, as if the peer had named it.</summary>
                public void resume()
                {
                    Volatile.Write(ref cmd_resume, Volatile.Read(ref next_pub));
                    posted = true;
                    wakeRunner();
                }

                ///<summary>
                ///A stream: the peer names the position it wants the stream continued from - behind the last guaranteed pack it
                ///received whole. Applied by the transport thread at the next pack boundary its <see cref="Read"/> reaches - so that
                ///the stream switches to the journal between two packs, never inside one - which this call wakes. From any thread.
                ///</summary>
                ///<returns>
                ///-1 when the journal holds the position and the stream continues from it. Otherwise the position the peer has to be
                ///told: the first one still held when the position named is below the journal, the start of the pack in progress, or
                ///the next position, when it is above - a position of another journal is one or the other. Until the peer is told
                ///nothing guaranteed leaves the stage, the packs the transmitter produces are journalled only:
                ///<see cref="Control"/> says the position and calls <c>resume</c> with it.
                ///</returns>
                public long resume(long position)
                {
                    long lo = Volatile.Read(ref base_pub), hi = Volatile.Read(ref next_pub);
                    var held = lo <= position && position <= hi;
                    if (held)
                        Volatile.Write(ref cmd_resume, position);
                    else
                        post_swallow = true;
                    posted = true;
                    wakeRunner();
                    var from = held            ? position
                               : hi < position ? Volatile.Read(ref boundary_pub)
                                               : lo;
                    //what the peer confirms counts from here: a peer that asks for less than it confirmed before - the next process
                    //of a server that took the session up from a pack it had in part - confirms again what it confirmed
                    Volatile.Write(ref heard_pub, from);
                    return held ? -1 : from;
                }

                ///<summary>
                ///A stream: the peer has received every guaranteed pack below the position. Applied by the transport thread at its
                ///next <see cref="Read"/>, which this call wakes; the files entirely below the position are deleted there. A
                ///position that is not of this journal is passed by. From any thread.
                ///</summary>
                public void ack(long position)
                {
                    if (position < Volatile.Read(ref base_pub) || Volatile.Read(ref next_pub) < position)
                        return;
                    for (var cur = Volatile.Read(ref cmd_ack); cur < position; cur = Volatile.Read(ref cmd_ack))
                        if (Interlocked.CompareExchange(ref cmd_ack, position, cur) == cur)
                            break;
                    if (Volatile.Read(ref heard_pub) < position)
                        Volatile.Write(ref heard_pub, position);
                    posted = true;
                    wakeRunner();
                }

                public bool isOpen()
                {
                    var src_ = this.src_;
                    return src_ != null && src_.isOpen();
                }

                ///<summary>
                ///A parked connection (<see cref="External.parked"/> &gt;= 0) keeps the journal and every unacknowledged
                ///byte: <see cref="sent_"/> rewinds to <see cref="acked_"/> and the stage waits for the peer to name its
                ///position on reconnect, while the transmitter below is left untouched so the journal can replay what it
                ///produced. A connection that is not parked ends the session: the journal is dropped, the positions
                ///re-seeded, and the close goes on to the transmitter.
                ///</summary>
                public void Close()
                {
                    closing = true;
                    if (Interlocked.Increment(ref draining) != 1)
                        return; //the offline pull in progress closes when its pack is done
                    drain_();
                }

                ///<summary>
                ///The close itself, under <see cref="draining"/>: no runner is alive (the transport closes the codecs once
                ///every operation has reported) and no offline pull is. Either way the stage goes OFFLINE: the runner is
                ///gone, and the next <see cref="online"/> comes with the socket the session continues on. A session that is
                ///kept moves its journal to the disk - see <see cref="park"/>.
                ///</summary>
                private void close_()
                {
                    var src_ = this.src_;
                    if (src_ == null)
                        return;
                    parked_ = true;
                    awaiting_ = true;
                    swallow = false;
                    sent_ = acked_;
                    resume_at = replaying = NONE;
                    Volatile.Write(ref cmd_resume, NONE);
                    closeReplay();
                    var ext = src_.ext_connection;
                    if (ext != null && 0 <= ext.parked)
                    {
                        if (!open)
                            src_.Abandon(); //a pack of no guarantee the socket cut half-way: the peer dropped what it got of it, the rest is not for the next socket
                        park();
                        return;
                    }

                    this.src_ = null;
                    drop();
                    publish();
                    src_.Close();
                }

                ///<summary>
                ///Serves the replay backlog <c>[sent, next)</c> first. Only when it is empty does it pull fresh bytes
                ///from the transmitter, with the room limited to what is left under <see cref="capacity"/>, and journal
                ///the packs the generated code marks on the way past.
                ///</summary>
                ///<returns>
                ///Bytes written; 0 at the cap or when the transmitter made no progress; -1 when the session is over or
                ///the transmitter is dry.
                ///</returns>
                ///<exception cref="IOException">
                ///The failure that ended the session — the journal is already gone and the socket aborted by then.
                ///</exception>
                public int Read(byte[] dst, int dst_byte, int dst_bytes)
                {
                    var src = src_;
                    try
                    {
                        var n = read_(dst, dst_byte, dst_bytes);
                        return 0 < n && src != null ? src.measure(n) : n; //the replay too: what the transport takes
                    }
                    finally
                    {
                        publish();
                    }
                }

                private int read_(byte[] dst, int dst_byte, int dst_bytes)
                {
                    if (src_ == null)
                        return -1;
                    if (swallow || awaiting_)
                        sent_ = next_; //nothing is replayed until the position the peer named is applied, or the peer has been told it
                    apply();
                    if (!(swallow || awaiting_) && sent_ < next_)
                        return replay(dst, dst_byte, dst_bytes);

                    var limit = dst_byte + dst_bytes;
                    for (var pos = dst_byte;;)
                    {
                        var before = next_;
                        var n = pull(dst, pos, limit);
                        if (n < 1)
                            return pos == dst_byte ? n : pos - dst_byte;
                        pos += n;
                        sent_ = next_;
                        if ((swallow || awaiting_) && before < next_)
                            pos = mark; //the marked pack this pull produced is journalled only; it ends the buffer — see packEnd()
                        if (dst_byte < pos)
                            return pos - dst_byte;
                    } //a pull that produced nothing for the wire pulls again: the transmitter has more queued
                }

                ///<summary>
                ///One <c>src_.Read</c> into <c>[pos, limit)</c>, with the room limited to what is left under
                ///<see cref="capacity"/> and the marked bytes it produced journalled.
                ///</summary>
                ///<returns>What the transmitter returned.</returns>
                private int pull(byte[] dst, int pos, int limit)
                {
                    var room = limit - pos;
                    var hold = false;
                    //Between the identification and the agreement nothing leaves - see the order in the description of this class:
                    //  awaiting_ - the position the peer names is not applied yet;
                    //  !parked_  - the session is identified: the generated resume(connection) put the stage online;
                    //  !agreeing - over a stream Control keeps the rule below, saying the packs of the agreement;
                    //  !dialing  - the side that took the connection: the side that made it sends its login now.
                    //An unmarked pack let out here would reach a decoder that holds a pack in progress and be glued into it.
                    if (awaiting_ && !parked_ && !src_!.agreeing)
                    {
                        var ext = src_.ext_connection;
                        if (ext != null && !ext.dialing)
                            return 0; //the position the peer names wakes the transmit loop
                    }
                    if (src_!.agreeing)
                    { //a new socket: until the two sides agree nothing goes out but what Control says
                        if (Volatile.Read(ref src_.to_say) == 0)
                            return 0; //what it has to say wakes the transmit loop
                        hold = true;
                    }
                    else if (!swallow)
                    { //the announcement of a lost position must get out even at the cap
                        //At a limit no pack is taken from the queue until the peer confirms. What this side has to say of the
                        //stream it receives still goes out, between two packs: the peer waits for it as this side waits for
                        //the peer's - with both at a limit and silent, neither would ever move.
                        var free = capacity - (next_ - acked_); //what is confirmed is the peer's: a file below it waits to be whole, it is not held for the peer
                        if (free < ROOM)
                        { //the cap: a pack in the middle waits where it is
                            if (Volatile.Read(ref src_!.to_say) == 0 || src_.isOpen())
                                return 0; //an ack() wakes the transmit loop
                            hold = true;
                        }
                        else
                        {
                            if (free < room)
                                room = (int)free;
                            //The connection is open: what the peer has not reported is held in memory, a segment of it. Counted
                            //from what is acknowledged, not from the base: the base waits for a whole file to be given back.
                            //A pack in the middle is finished: the limit is met between two packs. Not while the peer has not
                            //named its position on this socket: nothing guaranteed leaves then anyway, and what does - the login
                            //that lets the peer know this side - must, or neither side would ever move.
                            hold = !awaiting_ && in_flight <= next_ - acked_;
                            if (hold && Volatile.Read(ref src_!.to_say) == 0 && !src_.isOpen())
                                return 0;
                        }
                    }

                    if (open)
                        mark = pos; //the pack parked mid-serialization continues here
                    pulling = true;
                    src_!.held = hold;
                    int n;
                    try
                    {
                        n = src_.Read(dst, pos, room);
                    }
                    finally
                    {
                        src_.held = false;
                        pulling = false;
                    }

                    if (open && 0 < n)
                        append(dst, mark, pos + n - mark); //the part of the open pack this pull produced
                    if (failure != null)
                        throw takeFailure();
                    return n;
                }

                ///<summary>
                ///Applies what <see cref="resume(long)"/> and <see cref="ack"/> posted - a stream: there another thread hears the
                ///peer. A resume waits for a pack boundary: no replay in progress and no pack mid-serialization in the transmitter; a
                ///request for the position the replay in progress started from is already being served.
                ///</summary>
                private void apply()
                {
                    if (posted)
                    {
                        posted = false; //cleared BEFORE the commands are taken: one posted after this is seen next time
                        if (post_swallow)
                        {
                            post_swallow = false;
                            swallow = true;
                            awaiting_ = false;
                        }

                        var from = Interlocked.Exchange(ref cmd_resume, NONE);
                        if (from != NONE)
                            if (from != replaying)
                                resume_at = from;
                            else
                                Connection.Control.settled(src_!); //the replay in progress serves it
                        var upto = Interlocked.Exchange(ref cmd_ack, NONE);
                        if (upto != NONE && acked_ < upto)
                        {
                            acked_ = Math.Min(upto, sent_);
                            release();
                        }
                    }

                    if (resume_at != NONE && sent_ == next_ && !src_!.isOpen())
                    {
                        sent_ = replaying = resume_at;
                        replays++;
                        if (resume_at < acked_)
                            acked_ = resume_at;
                        resume_at = NONE;
                        awaiting_ = false;
                        swallow = false;
                        AdHoc.Connection.Control.settled(src_); //the answer is out: what the session has goes on behind the bytes of the journal
                    }
                }

                ///<summary>
                ///Copies journalled bytes from <see cref="sent_"/> into <paramref name="dst"/>: from the file that holds
                ///them, or from the segment in memory.
                ///</summary>
                private int replay(byte[] dst, int dst_byte, int dst_bytes)
                {
                    long p = sent_, hot_base = hotBase();
                    var n = p < hot_base ? replayFile(dst, dst_byte, dst_bytes, p) : replayHot(dst, dst_byte, dst_bytes, p, hot_base);
                    sent_ = p + n;
                    replayed += n;
                    if (sent_ == next_)
                    {
                        replaying = NONE;
                        closeReplay();
                    }

                    return n;
                }

                private int replayHot(byte[] dst, int dst_byte, int dst_bytes, long p, long hot_base)
                {
                    int rel = (int)(p - hot_base), n = Math.Min(dst_bytes, hot_used - rel), at = hot_at(rel);
                    var first = Math.Min(n, hot.Length - at); //up to the end of the ring, the rest round it
                    Array.Copy(hot, at, dst, dst_byte, first);
                    if (first < n)
                        Array.Copy(hot, 0, dst, dst_byte + first, n - first);
                    return n;
                }

                private int replayFile(byte[] dst, int dst_byte, int dst_bytes, long p)
                {
                    int index = (int)((p - base_) / FILE), off = (int)((p - base_) % FILE);
                    var last = index == files.Count - 1;
                    var n = Math.Min(dst_bytes, (last ? written : FILE) - off);
                    try
                    {
                        FileStream src;
                        if (last && ch != null)
                            src = ch; //still being written: read it in place
                        else
                        {
                            if (replay_index != index)
                            {
                                closeReplay();
                                replay_ch = new FileStream(files[index], FileMode.Open, FileAccess.Read, FileShare.ReadWrite, 1);
                                replay_index = index;
                            }

                            src = replay_ch!;
                        }

                        for (var got = 0; got < n;)
                        {
                            var r = RandomAccess.Read(src.SafeFileHandle, dst.AsSpan(dst_byte + got, n - got), off + got);
                            if (r < 1)
                                throw new IOException("Journal file " + files[index] + " is shorter than " + FILE + " bytes");
                            got += r;
                        }
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                        fail(e as IOException ?? new IOException(e.Message, e));
                        throw takeFailure();
                    }

                    return n;
                }

                ///<summary>
                ///Copies <paramref name="count"/> bytes at <paramref name="offset"/> of <paramref name="buf"/> into the buffer
                ///in memory, making room whenever it fills - see <see cref="flush"/>. A failed write ends the session — see <see cref="fail"/>.
                ///</summary>
                private void append(byte[] buf, int offset, int count)
                {
                    if (count < 1 || failure != null)
                        return;
                    if (src_!.journal_only)
                    { //the offline pull serialized into hot itself — see journal() and packStart(): commit in place
                        hot_used += count;
                        next_ += count;
                        return;
                    }

                    try
                    {
                        while (0 < count) //at most two copies a call: where the free place of the ring runs round its end
                        {
                            if (hot_used == hot.Length)
                                flush();
                            var at = hot_at(hot_used);
                            var n = Math.Min(Math.Min(hot.Length - hot_used, hot.Length - at), count);
                            Array.Copy(buf, offset, hot, at, n);
                            offset += n;
                            hot_used += n;
                            count -= n;
                            next_ += n;
                        }
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                        fail(e as IOException ?? new IOException(e.Message, e));
                    }
                }

                ///<summary>
                ///Makes room in the ring, (nearly) full: ONLINE it doubles, up to a <see cref="segment"/>. Otherwise its head goes
                ///out to the disk: see <see cref="write"/> - OFFLINE, the connection is closed; ONLINE the runner stops at a segment
                ///and waits for a report, see <see cref="pull"/>. What was given back at the head is free where it lies: nothing
                ///is moved.
                ///</summary>
                private void flush()
                {
                    if (!parked_ && hot.Length < segment)
                    {
                        var to = new byte[Math.Min(hot.Length << 1, segment)];
                        hot_into(to);
                        hot = to;
                        return;
                    }

                    write();
                }

                ///<summary>
                ///Writes the head of the ring to the last file of the journal - a new one when there is none or the last is
                ///full: its place in the ring is free then.
                ///</summary>
                private void write()
                {
                    if (ch == null)
                    {
                        var file = Path.Combine(pidDir(), Path.GetRandomFileName() + ".seg");
                        try
                        {
                            ch = new FileStream(file, FileMode.CreateNew, FileAccess.ReadWrite, FileShare.None, 1);
                        }
                        catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                        {
                            delete (file);
                            throw;
                        }

                        files.Add(file);
                        written = 0;
                    }

                    var n = Math.Min(hot_used, FILE - written);
                    var first = Math.Min(n, hot.Length - hot_off); //up to the end of the ring, the rest round it
                    ch.Write(hot, hot_off, first);
                    if (first < n)
                        ch.Write(hot, 0, n - first);
                    written += n;
                    if (written == FILE)
                    {
                        ch.Dispose();
                        ch = null;
                    }

                    hot_off = hot_at(n);
                    hot_used -= n;
                }

                ///<summary>
                ///The connection is closed and the session is kept: the journal moves to the disk. A buffer that has grown gives
                ///what it holds to the files at once and takes its first size, <see cref="HOT"/>; what fits into that size
                ///stays in it and costs no file. Until <see cref="online"/> the buffer does not grow: the packs queued meanwhile go
                ///to the files through it. A failed write ends the session: the journal is emptied and the positions are re-seeded.
                ///</summary>
                private void park()
                {
                    if (hot.Length == HOT)
                        return;
                    try
                    {
                        if (HOT - ROOM < hot_used)
                            while (0 < hot_used)
                                write();
                    }
                    catch (Exception e) when (e is IOException or UnauthorizedAccessException)
                    {
                        drop();
                        throw e as IOException ?? new IOException(e.Message, e);
                    }

                    var first = new byte[HOT];
                    hot_into(first);
                    hot = first;
                }

                ///<summary>Lets go of everything held: the files, the file being written, the buffer in memory.</summary>
                private void discard()
                {
                    discardFiles();
                    hot_off = hot_used = 0;
                }

                private void discardFiles()
                {
                    closeReplay();
                    if (ch != null)
                    {
                        try
                        {
                            ch.Dispose();
                        }
                        catch (IOException)
                        {
                        }

                        ch = null;
                    }

                    foreach (var f in files)
                        delete (f);
                    files.Clear();
                    written = 0;
                }

                ///<summary>
                ///Gives back what lies below <see cref="acked_"/>: the files entirely below it, then — once no file is left —
                ///the acknowledged head of the buffer in memory, the whole buffer when everything is acknowledged.
                ///<see cref="base_"/> moves up to the first byte kept.
                ///</summary>
                private void release()
                {
                    var upto = releasable();
                    if (upto == next_)
                    { //everything is acknowledged: hold nothing
                        discard();
                        base_ = next_;
                        return;
                    }

                    while (0 < files.Count && (ch == null || 1 < files.Count) && base_ + FILE <= upto)
                    { //the full files below the acknowledged position; the one still being written stays
                        if (replay_index == 0)
                            closeReplay(); //an open file cannot be deleted on Windows
                        delete (files[0]);
                        files.RemoveAt(0);
                        base_ += FILE;
                        if (0 < replay_index)
                            replay_index--;
                    }

                    if (0 < files.Count)
                    {
                        var in_memory = hotBase();
                        if (upto < in_memory)
                            return;
                        discardFiles(); //everything the files hold is acknowledged: the one still being written goes too
                        base_ = in_memory;
                    }

                    if (upto <= base_)
                        return;
                    var k = (int)(upto - base_); //given back where it lies: its place in the ring is free, what stays is not moved
                    hot_off = hot_at(k);
                    hot_used -= k;
                    base_ = upto;
                }

                private void closeReplay()
                {
                    if (replay_ch == null)
                        return;
                    try
                    {
                        replay_ch.Dispose();
                    }
                    catch (IOException)
                    {
                    }

                    replay_ch = null;
                    replay_index = -1;
                }

                ///<summary>Empties the journal; the offsets go on above everything the peer may hold of this session.</summary>
                private void drop()
                {
                    discard();
                    if (HOT < hot.Length)
                        hot = new byte[HOT]; //the session is over: the buffer takes its first size
                    open = false;
                    base_ = acked_ = sent_ = next_ = whole_end = next_ + 1;
                    whole = true;
                    ends_count = 0;
                }
#region the restart of the process
                //A session outlives the process that held it: the process that ends writes what the journal is - its positions,
                //where its packs end, its files - and the process that starts takes the files over as they are. Every byte of
                //the stream the peer may still ask for is on the disk by then: the pack in the middle of serialization is
                //finished into the journal and the packs queued after it with it - what the transmitter held is in the files,
                //nothing of it is needed again ( MQTT persistent sessions: the broker writes its sessions at the stop, reads them
                //at the start ).

                ///<summary>
                ///Writes this journal of a parked session to <paramref name="to"/>: everything the transmitter holds - the pack in the
                ///middle of serialization, the packs queued after it - is journalled first, then the buffer in memory goes to the
                ///files, which stay where they are for the process that reads it back ( <see cref="load"/> ). The session is to end in
                ///this process after it: nothing more is journalled.
                ///</summary>
                ///<returns><c>false</c> - no session to write: none, or its journal failed.</returns>
                public bool save(BinaryWriter to)
                {
                    var spin = new SpinWait();
                    while (Interlocked.CompareExchange(ref draining, 1, 0) != 0)
                        spin.SpinOnce(); //the pull in progress ends its pack: the queue is this call's from here on
                    try
                    {
                        if (src_ == null || !parked_)
                            return false;
                        while (journal())
                            ;
                        if (open)
                            return false; //the cap cut the pack in the middle: its rest is not in the journal, the session cannot go on
                        while (0 < hot_used)
                            write();
                        if (ch != null)
                        {
                            ch.Flush(true);
                            ch.Dispose(); //the file stays: the next process writes on in it
                            ch = null;
                        }

                        to.Write(base_);
                        to.Write(acked_);
                        to.Write(next_);
                        to.Write(whole_end);
                        to.Write(whole);
                        to.Write(datagram);
                        to.Write(ends_count);
                        for (var i = 0; i < ends_count; i++)
                            to.Write(ends[(ends_head + i) & (ends.Length - 1)]);
                        to.Write(files.Count);
                        foreach (var f in files)
                            to.Write(f);
                        to.Write(written);
                        files.Clear(); //the files are the next process's: nothing of this one deletes them
                        hot_off = hot_used = 0;
                        src_ = null; //the session is over here: no close of it touches the journal any more
                        return true;
                    }
                    finally
                    {
                        Volatile.Write(ref draining, 0);
                    }
                }

                ///<summary>
                ///Takes up the journal <see cref="save"/> wrote in the process before: its positions, the ends of its packs, its files
                ///as they are. The stage is OFFLINE, awaiting the peer's position, as after a loss; the files written from now on go to
                ///this process's directory.
                ///</summary>
                public void load(BinaryReader from)
                {
                    discard();
                    base_ = from.ReadInt64();
                    acked_ = sent_ = from.ReadInt64();
                    next_ = from.ReadInt64();
                    whole_end = from.ReadInt64();
                    whole = from.ReadBoolean();
                    datagram = from.ReadBoolean();
                    ends_head = 0;
                    ends_count = from.ReadInt32();
                    if (ends.Length < ends_count)
                        ends = new long[(int)System.Numerics.BitOperations.RoundUpToPowerOf2((uint)ends_count)];
                    for (var i = 0; i < ends_count; i++)
                        ends[i] = from.ReadInt64();
                    for (var i = from.ReadInt32(); 0 < i; i--)
                        files.Add(from.ReadString());
                    written = from.ReadInt32();
                    if (0 < files.Count && written < FILE)
                    { //the last file is written on from where it ends
                        ch = new FileStream(files[^1], FileMode.Open, FileAccess.ReadWrite, FileShare.None, 1);
                        ch.Position = written;
                    }

                    open = false;
                    parked_ = awaiting_ = true;
                    swallow = false;
                    resume_at = replaying = NONE;
                    Volatile.Write(ref cmd_resume, NONE);
                    Volatile.Write(ref cmd_ack, NONE);
                    Volatile.Write(ref heard_pub, acked_);
                    publish();
                }
#endregion

                ///<summary>
                ///Ends the session on a failed file operation: the journal is emptied, the positions are re-seeded and
                ///the socket is aborted, so the peer reconnects and is told that its position is gone. The exception is
                ///thrown by the <see cref="Read"/> in progress.
                ///</summary>
                private void fail(IOException e)
                {
                    failure ??= e;
                    drop();
                    src_?.ext_connection?.Abort();
                }

                private IOException takeFailure()
                {
                    var e = failure!;
                    failure = null;
                    return e;
                }
            }

            ///<summary>
            ///One frame on the serialization stack — the transmit-side mirror of <see cref="Receiver.Slot"/>. Each
            ///nested pack/collection being written gets its own slot; the slots form a reused doubly-linked chain
            ///(<see cref="prev"/>/<see cref="next"/>) so the transmitter can descend and pop without per-pack
            ///allocation. A slot carries the in-progress <see cref="src"/> source, the resume <c>state</c>, and the
            ///<see cref="fields_nulls"/> null-field bitmap for its level.
            ///</summary>
            internal sealed class Slot : Base_.Transmitter.Slot
            {
                ///<summary>
                ///The packet/field source currently producing bytes at this nesting level.
                ///</summary>
                internal BytesSrc src;

                public BytesSrc src_(BytesSrc src)
                {
                    state = 1; //Start at state 1: state 0 emits the [Pack id] header, which the nested src skips
                    return this.src = src;
                }

                ///<summary>
                ///Bitmap of which optional fields at this level are present, emitted up front so the reader can skip
                ///absent ones. See <c>init_fields_nulls</c>/<c>flush_fields_nulls</c>.
                ///</summary>
                internal int fields_nulls;

                internal Slot? next;
                internal readonly Slot? prev;

                ///<summary>
                ///Initializes a new instance of the <see cref="Slot"/> class.
                ///</summary>
                ///<param name="src">The `Transmitter` associated with this slot chain.</param>
                ///<param name="prev">The previous slot in the chain, or null if this is the root slot.</param>
                public Slot(Transmitter src, Slot? prev) : base(src)
                {
                    this.prev = prev;
                    if (prev != null)
                        prev.next = this;
                }
            }

            ///<summary>Root of the slot chain — see <see cref="Receiver.root"/>.</summary>
            internal readonly Slot root;

            internal Slot? slot;
            internal Slot? streaming_slot; //completion boundary for Read
            internal uint streaming_mode;  //the pre-park mode saved on entering STREAM_PACK

            ///<summary>
            ///<c>true</c> while the <see cref="Resumable"/> stage pulls with no socket: only marked packs are wanted, the
            ///generated <c>_OnSerializing</c> skips the rest.
            ///</summary>
            public bool journal_only;

            ///<summary>
            ///A stream that guarantees packs: what <see cref="Control"/> has to say, a bit a kind. The generated
            ///<c>_OnSerializing</c> reads it before every pack and hands the record out in place of one. Volatile.Read and Interlocked only.
            ///</summary>
            public int to_say;

            ///<summary>
            ///The journal is at a limit: no pack is taken from the queue until the peer reports. What <see cref="Control"/> has
            ///to say still goes out. Set by the journal around a pull of the runner.
            ///</summary>
            public bool held;

            ///<summary>
            ///A new socket of a session that guarantees packs: until the two sides agree on where the streams go on, nothing goes
            ///out but what <see cref="Control"/> says. Set by <see cref="Control"/> when it names its position or answers the
            ///peer's, cleared by the journal when its bytes go on behind the answer.
            ///</summary>
            public volatile bool agreeing;

            ///<summary>A Confirm_ said while the two sides agree: it goes once they did ( <see cref="Control"/> ).</summary>
            internal volatile bool confirm_deferred;

            ///<summary>
            ///No new pack in this <see cref="Read"/>: it ends at the end of the pack in progress, and <c>-1</c> once there is none -
            ///cleared then. Set by the burst of a tunnel that carried its share (<see cref="BytesSrc.Adapter"/>).
            ///</summary>
            public bool stop_between_packs;

            ///<summary>
            ///Resumes the stream parked in STREAM_PACK mode and tells how it went. Negative: still parked, more bytes
            ///needed. 0: the stream ended and the pack around it goes on. Positive: the stream was the packet itself
            ///(its slot is the root), which is now complete - it is sent. Only the generated chain knows which: the answer is
            ///the slot of the stream it drives, neither the current <c>slot</c> (where the pack inside the stream
            ///stopped) nor <c>streaming_slot</c> (the innermost of nested streams, while the outer one is what ends here).
            ///</summary>
            public virtual int unpark() => 1;
#endregion

            ///<summary>
            ///Initializes the `fields_nulls` bitmask in the current slot with a starting bit.
            ///Also allocates 1 byte in the buffer for storing this bitmask later via `flush_fields_nulls`.
            ///</summary>
            ///<param name="field0_bit">The initial bit value for the nulls bitmask (e.g., representing the first field).</param>
            ///<param name="this_case">The state to retry at if buffer allocation fails.</param>
            ///<returns>True if allocation is successful and bitmask initialized; false if a retry is needed.</returns>
            public bool init_fields_nulls(int field0_bit, uint this_case)
            {
                if (!Allocate(1, this_case))
                    return false;
                slot!.fields_nulls = field0_bit;
                return true;
            }

            ///<summary>
            ///Sets a specific bit in the `fields_nulls` bitmask of the current slot.
            ///This is used to mark a field as non-null (by convention, a set bit means non-null).
            ///</summary>
            ///<param name="field">The bit corresponding to the field to mark (e.g., a power of 2).</param>
            public void set_fields_nulls(int field) => slot!.fields_nulls |= field;

            ///<summary>
            ///Writes the `fields_nulls` bitmask from the current slot as a single byte into the buffer.
            ///Assumes space was previously allocated by `init_fields_nulls`.
            ///</summary>
            public void flush_fields_nulls() => put((byte)slot!.fields_nulls);

            ///<summary>
            ///Checks if a specific field is marked as null based on the `fields_nulls` bitmask in the current slot.
            ///</summary>
            ///<param name="field">The bit representing the field to check (e.g., a power of 2).</param>
            ///<returns>True if the field's corresponding bit is NOT set in `fields_nulls` (meaning it is null, by convention where 0 means null); false otherwise.</returns>
            public bool is_null(int field) => (slot!.fields_nulls & field) == 0;

            public bool isOpen() => slot?.src != null; //a packet is being serialized right now

            ///<summary>
            ///Ends the session: leaves nothing of the connection that just died behind — neither the string staged
            ///for a stream, nor the generator's registers, which on this side alias the application's pack data.
            ///Runs unconditionally, like <see cref="Receiver.Close"/>.
            ///</summary>
            public virtual void Close()
            {
                drop();
                clear(); //Generator-emitted registers
                for (var s = root; s != null; s = s.next)
                    s.clear();
            }

            ///<summary>
            ///Drops the pack in flight, and only it: the queue behind it stays, and so does the session. For a connection
            ///that outlives its link — a virtual one, whose tunnel packet died with the physical link. No-op between packs.
            ///<para>
            ///Why drop rather than continue or replay: the peer has already thrown away the part it received (its
            ///<see cref="Receiver.Abandon"/> runs when its link dies, or when the relay ends the packet with
            ///<see cref="Chunked.ABORT"/>), so it expects a pack id next. Continuing would hand it the tail of this pack as
            ///if it were the start of a new one. Replaying is impossible: serialization reads the application's live
            ///objects and is not rewindable, and keeping a copy of every pack until the far end has it is what the journal
            ///does for guaranteed packs — a tunnel carries none. So the pack is lost, as a datagram would be.
            ///</para>
            ///<para>Overridden by the generated transmitter to also release the queue entry the pack came from
            ///(<c>sending_out</c>), which only it knows.</para>
            ///</summary>
            public virtual void Abandon()
            {
                if (isOpen())
                    drop();
            }

            ///<summary>What <see cref="Close"/> and <see cref="Abandon"/> share: forget the pack in flight and every
            ///per-pack register.</summary>
            void drop()
            {
                reset();

                if (bytesCopy != null)
                {
                    bytesCopy.fail(this);
                    bytesCopy = null;
                }

                mode = OK;
                u4 = 0;
                bytes_left = 0;
                buffer = null;
                str = null;  //A string abandoned mid-stream, up to STR_LEN_MAX chars
                strs = null; //Drop a string-fragment supplier abandoned mid-transfer

                streaming_slot = null;
                streaming_mode = OK;
            }

            ///<summary>
            ///Rewinds the packet in flight and releases the borrowed buffer. Error and session path.
            ///<para>Overridable: a generated streaming transmitter overrides it to release its active chain first,
            ///then calls <c>base.reset()</c>.</para>
            ///</summary>
            protected virtual void reset()
            {
                if (slot == null)
                    return;
                if (bytesCopy != null)
                {
                    bytesCopy.fail(this);
                    bytesCopy = null;
                }

                for (var s = slot; s != null; s = s.next)
                    s.src = null;
                slot = null;
                buffer = null;
                mode = OK;
            }

            ///<summary>
            ///Defines an interface for intercepting raw bytes from the stream as they are generated by the <see cref="Transmitter"/>.
            ///<para>
            ///This is primarily used for logging outgoing traffic, calculating checksums on the fly, or mirroring the output stream.
            ///</para>
            ///</summary>
            public interface BytesCopy : Broadcastable
            {
                ///<summary>
                ///Called when the <see cref="Transmitter.Read"/> method is about to return because the destination buffer is full,
                ///but the packet is not yet fully serialized.
                ///This provides a chunk of raw bytes that have been generated so far.
                ///</summary>
                ///<param name="t">The transmitter instance.</param>
                ///<param name="offset">The offset in the provided destination buffer where this chunk starts.</param>
                ///<param name="count">The number of bytes in this chunk.</param>
                void pass(Transmitter t, int offset, int count);

                ///<summary>
                ///Called when the packet has fully serialized.
                ///This provides the final chunk of raw bytes for the packet.
                ///After this call, the <see cref="Transmitter.bytesCopy"/> is automatically cleared (set to null).
                ///</summary>
                ///<param name="t">The transmitter instance.</param>
                ///<param name="offset">The offset in the provided destination buffer where this chunk starts.</param>
                ///<param name="count">The number of bytes in this chunk.</param>
                void done(Transmitter t, int offset, int count);

                ///<summary>
                ///Called if the transmitter is reset (due to error or connection close) before the packet completes serialization.
                ///Implementations should discard any partially captured data.
                ///After this call, the <see cref="Transmitter.bytesCopy"/> is automatically cleared.
                ///</summary>
                ///<param name="t">The transmitter instance.</param>
                void fail(Transmitter t);
            }

            ///<summary>
            ///The active read hook. Set this property to capture raw bytes for the *current* packet being serialized.
            ///<para>
            ///<b>Lifecycle:</b><br/>
            ///1. Assign this field inside <see cref="EventsHandler.OnSerializing"/>.<br/>
            ///2. The hook receives data via <see cref="BytesCopy.pass"/> (partial) or <see cref="BytesCopy.done"/> (final).<br/>
            ///3. Upon <see cref="BytesCopy.done"/> or <see cref="BytesCopy.fail"/>, this field is automatically reset to <c>null</c>.
            ///</para>
            ///<para>
            ///<b>Note on Packet IDs:</b><br/>
            ///Unlike the Receiver, if you set this hook within <see cref="EventsHandler.OnSerializing"/>, it <b>will</b>
            ///capture the Packet ID bytes, because the Transmitter generates the ID immediately <i>after</i> the event is fired.
            ///</para>
            ///</summary>
            public BytesCopy? bytesCopy;

            ///<summary>
            ///Main outbound entry point: serialize queued packs into <paramref name="dst"/> until it is full or the
            ///send queue drains. Dequeues the next pack when starting fresh, emits its ID then body, resumes any
            ///value parked by an earlier call (per <see cref="mode"/>), and fires <c>OnSerializing</c>/<c>OnSerialized</c>
            ///as packs begin and finish. A pack whose serialization overruns <paramref name="dst"/> simply parks and
            ///continues on the next call. This is the core of the <see cref="BytesSrc"/> implementation for <see cref="Transmitter"/>.
            ///</summary>
            ///<param name="dst">The destination byte array where serialized data will be written.</param>
            ///<param name="dst_byte">The starting offset in `dst`.</param>
            ///<param name="dst_bytes">The maximum number of bytes to write into `dst`.</param>
            ///<returns>
            ///The number of bytes written to `dst`.
            ///Returns 0 if `dst` has insufficient space to write even a part of the next packet segment.
            ///Returns -1 if there are no more packets in the sending queue to process.
            ///Returns int.MinValue if a streaming source completes serialization.
            ///</returns>
            public int Read(byte[] dst, int dst_byte, int dst_bytes)
            {
                var bytesCopyOffset = dst_byte;
                var dry = false; //the queue is empty, not held
                for (buffer = dst, byte_max = (byte_ = dst_byte) + dst_bytes; byte_ < byte_max;)
                {
                    if (slot?.src == null)
                    {
                        //A value pack carries its payload in u8 — the party that queues it stages the value
                        //there (the generated DataPass.OnSerializing does), so there is nothing to arm here.
                        if (stop_between_packs)
                        { //the burst that reads this transmitter carried its share: it ends between two packs
                            if (byte_ == dst_byte)
                                stop_between_packs = false;
                            goto exit;
                        }

                        var src = held && (Volatile.Read(ref to_say) == 0 || journal_only) ? null : _OnSerializing(); //Get next BytesSrc from sending queue

                        if (src == null)
                        {
                            dry = !held || Volatile.Read(ref to_say) != 0 && !journal_only;
                            goto exit; //Send queue drained. Not an error and not the end of the session, so
                        }
                        //nothing is torn down here: reset() is where the generated override
                        //releases the stream chain, and that chain has to survive between
                        //drains (it is released in Close(), or when it is evicted).

                        if (slot == null)
                            slot = root;

                        stream_byte = 0; //Byte cursor of the raw-copy sources (BytesCopy.InMemory)
                        slot.src = src;
                        slot.state = 0; //write id request
                        bytesCopyOffset = byte_;
                        handler?.OnSerializing(this, src);
                        if (slot == null)
                            return -1; //sending event handler has reset this
                    }
                    else
                        switch (mode) //the packet transmission was interrupted, recall where we stopped
                        {
                            case STREAM_PACK:
                            {
                                mode = streaming_mode;
                                var done = unpark();
                                if (done < 0)
                                    goto exit;
                                if (0 < done)
                                    goto dispatched;
                                break;
                            }
                            case STR:
                                if (slot.state == (uint)bit)
                                    break;

                                if (!varint())
                                    goto exit;

                                if (u4 == uint.MaxValue)
                                    u4 = 0;

                                if (!put_chars(str!, slot.state, u4)) //the rest the fast way: a long string spans many buffers
                                    goto exit;

                                str = null;
                                break;
                            case STR_UTF8:
                                //Chain-string leaf park (see UTFStream) → SKIP, the leaf completes it.
                                if (slot.state == (uint)bit)
                                    break;

                                //No length prefix on this wire — a park always stages char-phase state
                                //(split-sequence bytes in u8_ / bytes_left), which putting_utf resumes itself.
                                if (!putting_utf())
                                    goto exit;
                                break; //putting_utf cleared str
                            case VAL4:
                                if (byte_max - byte_ < bytes_left)
                                    goto exit;
                                put_val(u4, bytes_left);
                                break;
                            case VAL8:
                                if (byte_max - byte_ < bytes_left)
                                    goto exit;
                                put_val(u8, bytes_left);
                                break;
                            case VAL16:
                                if (byte_max - byte_ < 16)
                                    goto exit;
                                put(new UInt128(u16, u8));
                                break;
                            case BITS_BYTES:
                                if (byte_max - byte_ < bits_transaction_bytes_)
                                    goto exit;     //space for one full transaction
                                bits_byte = byte_; //preserve space for bits info
                                byte_++;
                                put_val(u8, bytes_left);
                                break;
                            case BITS_VAL16:
                                if (byte_max - byte_ < bits_transaction_bytes_)
                                    goto exit;     //space for one full transaction
                                bits_byte = byte_; //preserve space for bits info
                                byte_++;
                                put(new UInt128(u16, u8));
                                break;
                            case VARINT:
                                if (varint())
                                    break;
                                goto exit;
                            case BITS:
                                if (byte_max - byte_ < bits_transaction_bytes_)
                                    goto exit;     //space for one full transaction
                                bits_byte = byte_; //preserve space for bits info
                                byte_++;
                                break;
                        }

                    mode = OK; //Restore mode to OK after resuming transmission

                    //Get bytes from byte source and put into buffer
                    for (;;)
                        if (slot!.src!.__get_bytes(this))
                        {
                            if (slot == streaming_slot)
                                return int.MinValue; //streamed body complete → hand control back to the re-entrant caller (Adapter); the framer's [0] finishes the stream
                            if (slot.prev == null)
                                break;        //top-level packet complete → finish
                            slot = slot.prev; //pop one level
                        }
                        else
                            goto exit;

                dispatched:
                    if (bytesCopy != null)
                    {
                        bytesCopy.done(this, bytesCopyOffset, byte_ - bytesCopyOffset);
                        bytesCopy = null;
                    }

                    _OnSerialized(slot.src);
                    handler?.OnSerialized(this, slot.src);

                    if (slot == null)
                        return -1;   //sent event handler has reset this
                    slot.src = null; //sing of the request next packet
                }

            exit:
                bytesCopy?.pass(this, bytesCopyOffset, byte_ - bytesCopyOffset);
                buffer = null;
                //Nothing written is NOT end-of-stream while a pack is parked mid-serialization (e.g. the next value does not
                //fit the space left): that is 0 = "no progress this call, more to come", exactly as the Java and TS runtimes
                //report it. A caller that distinguishes the two — BytesSrc.Adapter over a tunnel endpoint's transmitter —
                //would otherwise end the chunked tunnel packet mid-pack and strand the rest until an unrelated send.
                var ret = dst_byte < byte_    ? gave(byte_ - dst_byte)
                          : slot?.src != null ? 0
                                              : -1; //no more packets left
                if (dry)
                    speed_dry = true; //the next bytes start a new measure
                return ret;
            }

            ///<summary>
            ///The speed this transmitter gives bytes at, bytes a second: the bytes it gave since the last measure, over the time
            ///since then - measured once 10 ms at least went by. A wait for the transport or the peer is counted, the time the
            ///queue is empty is not. Not averaged: the speed now. Any transport: the bytes are those it takes. 0 - none measured
            ///yet. From any thread.
            ///</summary>
            public long speed => Volatile.Read(ref speed_);

            long speed_, speed_bytes, speed_at; //the speed; the bytes given and the clock ( Stopwatch ) since it was measured last
            bool speed_dry = true;              //the queue was empty: the next bytes start the measure
            bool speed_by_src;                  //a journal is the source the transport reads: it measures ( Resumable.Read )

            private int gave(int ret) => speed_by_src ? ret : measure(ret);

            private int measure(int ret)
            { //bytes the transport took: one clock reading
                var now = System.Diagnostics.Stopwatch.GetTimestamp();
                if (speed_dry)
                { //the bytes of the first read after a pause are given at once: the measure starts behind them
                    speed_dry = false;
                    speed_at = now;
                    speed_bytes = 0;
                    return ret;
                }
                speed_bytes += ret;
                var t = now - speed_at;
                if (System.Diagnostics.Stopwatch.Frequency / 100 <= t)
                { //what went since the last measure, over the time it took - waits of the transport and of the peer too
                    Volatile.Write(ref speed_, (long)(speed_bytes * (double)System.Diagnostics.Stopwatch.Frequency / t));
                    speed_at = now;
                    speed_bytes = 0;
                }
                return ret;
            }

            ///<summary>Re-entrant entry (used by a streaming <see cref="BytesSrc.Adapter"/>): drive Read over the current window; returns <see cref="int.MinValue"/> when the streamed body completes.</summary>
            public int read(byte[] buffer) => Read(buffer, byte_, byte_max - byte_);

            ///<summary>
            ///Checks if a specified number of bytes can be allocated in the current output buffer.
            ///If not, sets the transmitter to retry mode at `this_case`.
            ///</summary>
            ///<param name="bytes">The number of bytes required in the buffer.</param>
            ///<param name="this_case">The state to set for retry if allocation fails due to insufficient space.</param>
            ///<returns>True if `bytes` are available in the remaining buffer; false if not and retry mode is set.</returns>
            public bool Allocate(uint bytes, uint this_case)
            {
                slot!.state = this_case;
                if (bytes <= remaining)
                    return true;
                mode = RETRY;
                return false;
            }

            ///<summary>
            ///Puts a boolean value into the buffer, encoded as a single bit (1 for true, 0 for false),
            ///using the bitwise serialization mechanism.
            ///<para>
            ///Uses <see cref="Unsafe.As{TFrom,TTo}(ref TFrom)"/> to reinterpret the <c>bool</c>'s
            ///single-byte storage directly as a byte, skipping the JIT's defensive <c>cmp; setne; movzx</c>
            ///normalization. Safe because managed C# code always stores <c>bool</c> as exactly 0 or 1.
            ///Benchmarked at ~2x faster than <c>src ? 1 : 0</c> in inlined hot loops on .NET 10 RyuJIT.
            ///</para>
            ///</summary>
            ///<param name="src">The boolean value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(bool src) => put_bits(Unsafe.As<bool, byte>(ref src), 1);

            ///<summary>
            ///Puts a nullable boolean value into the buffer, encoded as two bits:
            ///00 for null, 10 for false, 11 for true.
            ///Uses the bitwise serialization mechanism.
            ///</summary>
            ///<param name="src">The nullable boolean value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(bool? src) => put_bits(src.HasValue ? src.Value ? 3 : //11 binary
                                                                      2
                                                                : //10 binary
                                                       0,
                                                   2); //00 binary
#region bits
            int bits_byte = -1;
            uint bits_transaction_bytes_;

            ///<summary>
            ///Initializes a bitwise transaction, ensuring `transaction_bytes` are available.
            ///This version is typically called to *continue* a bitwise operation after a retry.
            ///</summary>
            ///<param name="transaction_bytes">Minimum number of bytes that should be available in the buffer for this transaction segment.</param>
            ///<param name="this_case">The state to retry at if `transaction_bytes` are not available.</param>
            ///<returns>True if sufficient bytes are available; false if a retry is needed (mode set to BITS).</returns>
            public bool init_bits_(uint transaction_bytes, uint this_case)
            {
                if ((bits_transaction_bytes_ = transaction_bytes) <= byte_max - byte_)
                    return true;
                slot!.state = this_case;
                byte_ = bits_byte; //trim byte at bits_byte index
                mode = BITS;
                return false;
            }

            ///<summary>
            ///Initializes a bitwise transaction. Allocates one byte in the buffer to start accumulating bits
            ///and ensures at least `transaction_bytes` are available for the whole operation.
            ///Resets `bits` accumulator and `bit` pointer.
            ///</summary>
            ///<param name="transaction_bytes">Minimum number of bytes that should be available in the buffer for this transaction. This includes the initial byte allocated here.</param>
            ///<param name="this_case">The state to retry at if `transaction_bytes` are not available.</param>
            ///<returns>True if sufficient bytes are available and bitwise context is initialized; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool init_bits(uint transaction_bytes, uint this_case)
            {
                if (byte_max - byte_ < (bits_transaction_bytes_ = transaction_bytes))
                {
                    slot!.state = this_case;
                    mode = RETRY;
                    return false;
                }

                bits = 0;
                bit = 0;
                bits_byte = byte_++; //Allocate space for the first byte of bits
                return true;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_bits(bool src) => put_bits(src ? 1 : 0, 1);

            ///<summary>
            ///Puts a specified number of bits from `src` into the bit accumulator (`bits`).
            ///If the accumulator fills a byte, that byte is written to `buffer[bits_byte]`,
            ///`bits_byte` is advanced, and the accumulator is updated.
            ///</summary>
            ///<param name="src">The integer containing the bits to put (in its lower `len_bits`).</param>
            ///<param name="len_bits">The number of bits from `src` to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_bits(int src, int len_bits)
            {
                bits |= (uint)src << bit;
                if ((bit += len_bits) < 9)
                    return; //yes 9! not 8!  to avoid allocating the next byte after the current one is full. it might be redundant
                buffer![bits_byte] = (byte)bits;
                bits >>= 8;
                bit -= 8;
                bits_byte = byte_;
                if (byte_ < byte_max)
                    byte_++;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_bits(bool src, uint continue_at_case) => put_bits(src ? 1 : 0, 1, continue_at_case);

            ///<summary>
            ///Puts a specified number of bits from `src` into the bit accumulator, with retry capability.
            ///If writing a filled byte requires more buffer space than `bits_transaction_bytes_` allows from current `byte_`,
            ///it sets up a retry.
            ///</summary>
            ///<param name="src">The integer containing the bits to put.</param>
            ///<param name="len_bits">The number of bits from `src` to put.</param>
            ///<param name="continue_at_case">The state to retry at if buffer space runs out.</param>
            ///<returns>True if bits were put successfully (or partially, with more buffer available); false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put_bits(int src, int len_bits, uint continue_at_case)
            {
                bits |= (uint)src << bit;
                if ((bit += len_bits) < 9)
                    return true; //yes 9! not 8!  to avoid allocating the next byte after the current one is full. it might be redundant
                buffer![bits_byte] = (byte)bits;
                bits >>= 8;
                bit -= 8;
                if (byte_max - byte_ < bits_transaction_bytes_)
                {
                    slot!.state = continue_at_case;
                    return false;
                }

                bits_byte = byte_++;
                return true;
            }

            ///<summary>
            ///Finalizes the current bitwise transaction. If any bits are remaining in the `bits` accumulator
            ///(i.e., `0 ᐸ bit`), they are written to `buffer[bits_byte]`. If no bits were written to the
            ///current `bits_byte` (i.e. `bit == 0`), `byte_` is trimmed back to `bits_byte`, effectively
            ///de-allocating the unused byte.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void end_bits()
            {
                if (0 < bit)
                    buffer![bits_byte] = (byte)bits;
                else
                    byte_ = bits_byte; //trim byte at bits_byte index. allocated, but not used
            }

            ///<summary>
            ///Puts a nulls bitmask using `put_bits`. If `put_bits` requires a retry,
            ///this method sets the mode to `BITS` for continuation.
            ///</summary>
            ///<param name="nulls">The nulls bitmask value.</param>
            ///<param name="nulls_bits">The number of bits in the `nulls` bitmask.</param>
            ///<param name="continue_at_case">The state to retry at if putting bits fails.</param>
            ///<returns>True if the nulls bitmask was put successfully; false if a retry is needed.</returns>
            public bool put_nulls(int nulls, int nulls_bits, uint continue_at_case)
            {
                if (put_bits(nulls, nulls_bits, continue_at_case))
                    return true;

                mode = BITS;
                return false;
            }

            ///<summary>
            ///Sets up a retry for a bitwise operation that was interrupted.
            ///Resets `byte_` to `bits_byte` (start of current bit-holding byte) and sets mode to `BITS`
            ///and state to `continue_at_case`.
            ///</summary>
            ///<param name="continue_at_case">The state to resume the bitwise operation at.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void continue_bits_at(uint continue_at_case)
            {
                slot!.state = continue_at_case;
                byte_ = bits_byte;
                mode = BITS;
            }

            ///<summary>
            ///Items of a bit array straight from its list: while the bit stream stands on a byte boundary, whole chunks -
            ///as many groups of 8 items (<c>bitsPerItem</c> bytes each) as one ulong takes - go to the buffer in one read of
            ///the list and one write. The pending bit byte is written first; a fresh one is reserved after. The items before
            ///the next boundary and the tail go one by one, as before.
            ///</summary>
            ///<returns>The items sent: a multiple of 8, and 0 when the stream is not on a byte boundary.</returns>
            public int put_bits<T>(org.unirail.collections.BitsList<T>.R src, int item, int items)
                where T : struct
            {
                if ((bit & 7) != 0)
                    return 0;
                if (BitConverter.IsLittleEndian) //the list's words are LSB first: its bytes are the wire's - all whole groups in one copy
                {
                    int bl = src.bitsPerItem, pl = bits_flush(), gl = Math.Min(items >> 3, (byte_max - pl) / bl);
                    if (gl != 0)
                        src.Bytes(item, gl << 3).CopyTo(buffer.AsSpan(pl));
                    bits_reserve(pl + gl * bl);
                    return gl << 3;
                }

                int b = src.bitsPerItem, K = 8 / b, pos = bits_flush(), got = 0;
                for (int g; 0 < (g = Math.Min(Math.Min(K, items - got >> 3), (byte_max - pos) / b)); got += g << 3, pos += g * b)
                    store(buffer!, pos, src.Raw(item + got, g << 3), g * b, byte_max);
                bits_reserve(pos);
                return got;
            }

            ///<summary><see cref="put_bits{T}(org.unirail.collections.BitsList{T}.R, int, int)"/> of one-bit items, every whole byte
            ///the buffer has room for at once.</summary>
            public int put_bits(org.unirail.collections.BitList.R src, int item, int items)
            {
                if ((bit & 7) != 0)
                    return 0;
                var pos = bits_flush();
                var g = Math.Max(0, Math.Min(items >> 3, byte_max - pos));
                src.GetBytes(item, buffer.AsSpan(pos, g));
                bits_reserve(pos + g);
                return g << 3;
            }

            ///<summary>
            ///Nullable items straight from their list, whole groups of 8: a byte of their nulls (1 - null) and their values right
            ///after it, room checked once a group. The stream stands on a byte boundary; a fresh bit byte is reserved after.
            ///The items before the next boundary, the tail and what the buffer cut go one by one, as before.
            ///</summary>
            ///<returns>The items sent, a multiple of 8; 0 when the stream is not on a byte boundary or no group fits.</returns>
            public int put_nulls<T>(org.unirail.collections.NullablePrimitiveList<T>.R src, int item, int items)
                where T : struct
            {
                if (!BitConverter.IsLittleEndian || items < 8 || (bit & 7) != 0)
                    return 0;
                var pos = bit == 0 ? bits_byte : byte_;
                if (byte_max - pos < 1 + (Unsafe.SizeOf<T>() << 3))
                    return 0;
                if (bit != 0)
                    buffer![bits_byte] = (byte)bits;
                var groups = src.GroupsTo(buffer!, ref pos, byte_max, item, items >> 3);
                bits_reserve(pos);
                return groups << 3;
            }

            int bits8_at; //where the chunk `bits8` made room for goes

            ///<summary>
            ///Room for a chunk of a bit array an abstract pack hands item by item: while the bit stream stands on a byte
            ///boundary, up to <paramref name="items"/> items of <paramref name="bits_per_item"/> bits - as many as one ulong
            ///and the buffer take, whole bytes. The codec packs them into a ulong and writes it at once with <see cref="bits8_put"/>.
            ///</summary>
            ///<returns>The items the chunk takes, 0 when the stream is not on a byte boundary or no chunk fits.</returns>
            public int bits8(int items, int bits_per_item)
            {
                if ((bit & 7) != 0)
                    return 0;
                var pos = bits_flush();
                var n = (int)Math.Min(Math.Min(items, 64 / bits_per_item), ((long)(byte_max - pos) << 3) / bits_per_item); //a window past 256 MB: its bits do not fit an int
                n -= n % (8 >> System.Numerics.BitOperations.TrailingZeroCount(bits_per_item));                            //whole bytes
                if (n <= 0)
                {
                    bits_reserve(pos);
                    return 0;
                }

                bits8_at = pos;
                return n;
            }

            ///<summary>Writes the chunk <see cref="bits8"/> made room for: <paramref name="n"/> items of <paramref name="bits_per_item"/> bits, item 0 in the lowest.</summary>
            public void bits8_put(ulong items, int n, int bits_per_item)
            {
                var bytes = n * bits_per_item >> 3;
                store(buffer!, bits8_at, items, bytes, byte_max);
                bits_reserve(bits8_at + bytes);
            }

            //the bit stream on a byte boundary: the pending full byte written to its place. returns where the next byte goes
            int bits_flush()
            {
                if (bit == 0)
                    return bits_byte; //the reserved byte holds nothing yet: it is the next
                buffer![bits_byte] = (byte)bits;
                return byte_;
            }

            //a fresh bit byte reserved at `pos`, as `put_bits` does after a full byte
            void bits_reserve(int pos)
            {
                bits = 0;
                bit = 0;
                bits_byte = pos;
                byte_ = pos < byte_max ? pos + 1 : pos;
            }
#endregion

            public bool put_bits_bytes(int info, int info_bits, double value, int value_bytes, uint continue_at_case) => put_bits_bytes(info, info_bits, Unsafe.As<double, ulong>(ref value), value_bytes, continue_at_case);
            public bool put_bits_bytes(int info, int info_bits, float value, int value_bytes, uint continue_at_case) => put_bits_bytes(info, info_bits, Unsafe.As<float, uint>(ref value), value_bytes, continue_at_case);

            ///<summary>
            ///Puts a sequence of `info_bits` followed by `value_bytes` representing `value`.
            ///This is a common pattern for length-prefixed or type-prefixed fields.
            ///If `put_bits` for `info` requires retry, sets mode to `BITS_BYTES` and stores `value` and `value_bytes`
            ///in `u8` and `bytes_left` respectively for continuation.
            ///</summary>
            ///<param name="info">The integer containing the information bits (e.g., length or type).</param>
            ///<param name="info_bits">The number of bits to take from `info`.</param>
            ///<param name="value">The `ulong` value to write after the info bits.</param>
            ///<param name="value_bytes">The number of bytes to use for serializing `value`.</param>
            ///<param name="continue_at_case">The state to retry at if operation fails.</param>
            ///<returns>True if both info bits and value bytes were put successfully; false if a retry is needed.</returns>
            public bool put_bits_bytes(int info, int info_bits, ulong value, int value_bytes, uint continue_at_case)
            {
                if (put_bits(info, info_bits, continue_at_case))
                {
                    put_val(value, value_bytes);
                    return true;
                }

                u8 = value;
                bytes_left = value_bytes;
                mode = BITS_BYTES;
                return false;
            }

            public bool put_bits_bytes(int info, int info_bits, Int128 value, int value_bytes, uint continue_at_case) => put_bits_bytes(info, info_bits, unchecked((UInt128)value), value_bytes, continue_at_case);
            public bool put_bits_bytes(int info, int info_bits, Guid value, int value_bytes, uint continue_at_case) => put_bits_bytes(info, info_bits, uuid(value), value_bytes, continue_at_case);

            ///<summary>
            ///Puts `info_bits` of `info` followed by the 16 bytes of `value`: little-endian, the low 8 bytes first.
            ///If `put_bits` for `info` requires retry, keeps `value` in `u8` / `u16` and sets mode to `BITS_VAL16`.
            ///</summary>
            ///<param name="info">The integer containing the information bits (e.g., null flags).</param>
            ///<param name="info_bits">The number of bits to take from `info`.</param>
            ///<param name="value">The 128-bit value to write after the info bits.</param>
            ///<param name="value_bytes">Always 16.</param>
            ///<param name="continue_at_case">The state to retry at if operation fails.</param>
            ///<returns>True if both info bits and value bytes were put successfully; false if a retry is needed.</returns>
            public bool put_bits_bytes(int info, int info_bits, UInt128 value, int value_bytes, uint continue_at_case)
            {
                if (put_bits(info, info_bits, continue_at_case))
                {
                    put(value);
                    return true;
                }

                u8 = unchecked((ulong)value);
                u16 = unchecked((ulong)(value >> 64));
                mode = BITS_VAL16;
                return false;
            }
#region varint
            ///<summary>
            ///Minimum number of bytes (1..<paramref name="min"/>) needed to represent
            ///<paramref name="src"/>, capped at the caller-supplied <paramref name="min"/>.
            ///Computed in two instructions on x64 (<c>lzcnt + shift</c>) plus a single CMOV for
            ///the cap. Replaces the chained-ternary <c>bytes1..bytes5</c> family. Returns 1 for
            ///<c>src == 0</c> (since <c>BitOperations.Log2(0) == 0</c> in .NET).
            ///<para>The <paramref name="min"/> parameter is the second argument to
            ///<see cref="Math.Min(int, int)"/> — it acts as an <em>upper bound</em> on the
            ///return value. Each varint type's info-field width determines the cap (2/3/4/7/8
            ///for VarInt21/32/42/73/83 respectively).</para>
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            static int byte_count(ulong src, int min) => Math.Min((BitOperations.Log2(src) >> 3) + 1, min);

            ///<summary>VarInt21: 1 length-bit (0=1B, 1=2B) then 1-2 payload bytes.</summary>
            public bool put_varint21(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 2);
                return put_bits_bytes(bytes - 1, 1, src, bytes, continue_at_case);
            }

            ///<summary>VarInt21 with nulls_bits prefix.</summary>
            public bool put_varint21(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 2);
                return put_bits_bytes(bytes - 1 << nulls_bits | nulls, nulls_bits + 1, src, bytes, continue_at_case);
            }

            ///<summary>VarInt32: 2 length-bits (1..3 = byte count) then 1-3 payload bytes.</summary>
            public bool put_varint32(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 3);
                return put_bits_bytes(bytes, 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt32 with nulls_bits prefix.</summary>
            public bool put_varint32(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 3);
                return put_bits_bytes(bytes << nulls_bits | nulls, nulls_bits + 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt42: 2 length-bits (0..3 = byte count - 1) then 1-4 payload bytes.</summary>
            public bool put_varint42(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 4);
                return put_bits_bytes(bytes - 1, 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt42 with nulls_bits prefix.</summary>
            public bool put_varint42(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 4);
                return put_bits_bytes(bytes - 1 << nulls_bits | nulls, nulls_bits + 2, src, bytes, continue_at_case);
            }

            ///<summary>VarInt73: 3 length-bits (1..7 = byte count) then 1-7 payload bytes.</summary>
            public bool put_varint73(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 7);
                return put_bits_bytes(bytes, 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt73 with nulls_bits prefix.</summary>
            public bool put_varint73(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 7);
                return put_bits_bytes(bytes << nulls_bits | nulls, nulls_bits + 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt83: 3 length-bits (0..7 = byte count - 1) then 1-8 payload bytes.</summary>
            public bool put_varint83(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes - 1, 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt83 with nulls_bits prefix.</summary>
            public bool put_varint83(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes - 1 << nulls_bits | nulls, nulls_bits + 3, src, bytes, continue_at_case);
            }

            ///<summary>VarInt84: 4 length-bits (1..8 = byte count) then 1-8 payload bytes.</summary>
            public bool put_varint84(ulong src, uint continue_at_case)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes, 4, src, bytes, continue_at_case);
            }

            ///<summary>VarInt84 with nulls_bits prefix.</summary>
            public bool put_varint84(ulong src, uint continue_at_case, int nulls, int nulls_bits)
            {
                var bytes = byte_count(src, 8);
                return put_bits_bytes(bytes << nulls_bits | nulls, nulls_bits + 4, src, bytes, continue_at_case);
            }

            ///<summary>
            ///Puts a standard varint-encoded `ulong` value into the buffer.
            ///If not enough buffer space, sets mode to `VARINT` and state to `next_case` for retry,
            ///storing `src` in `u8_` for continuation.
            ///</summary>
            ///<param name="src">The ulong value to varint-encode and put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the varint was put successfully; false if a retry is needed.</returns>
            public bool put_varint(ulong src, uint next_case)
            {
                if (varint(src))
                    return true;

                slot!.state = next_case;
                mode = VARINT;
                return false;
            }

            ///<summary>
            ///Puts the varint-encoded value currently stored in `u8_` into the buffer.
            ///This is used for retrying a `put_varint` operation.
            ///</summary>
            ///<returns>True if the varint was put successfully; false if more buffer space is needed.</returns>
            internal bool varint() => varint(u8_);

            ///<summary>
            ///Writes a `ulong` value into the buffer using standard varint encoding.
            ///Each byte written has its MSB set if more bytes follow; the last byte has MSB clear.
            ///Only 7 bits per byte are used for data.
            ///<para>
            ///Hot path stages 1&ndash;9 bytes into a single <see cref="ulong"/> register and emits them
            ///with one <see cref="Unsafe.WriteUnaligned{T}(ref byte, T)"/> when the buffer has &gt;= 9 bytes
            ///of headroom (varint of a 56-bit value fits in 8 bytes; the 9th byte is the &lt;=8-bit terminator).
            ///The 10-byte case (top bit set on a full ulong) falls through to the slow per-byte loop.
            ///</para>
            ///</summary>
            ///<param name="src">The `ulong` value to encode and write.</param>
            ///<returns>True if the entire varint value was written to the buffer; false if the buffer ran out of space, in which case `u8_` stores the remaining part of `src` to be encoded.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool varint(ulong src)
            {
                var buf = buffer!;
                var pos = byte_;
                var max = byte_max;
                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);

                //Fast path: src fits in 1..8 varint bytes (i.e. value < 2^56) AND we have >= 8 bytes
                //headroom in the buffer for an 8-byte unaligned store. Stage all bytes into one ulong,
                //emit them in a single store, then advance byte_ by exactly the varint byte count.
                //Bytes written past the actual varint length are scratch (they'll be overwritten before
                //any transmit, since the transmitter only reads up to byte_).
                if (src < (1UL << 56) && max - pos >= 8)
                {
                    //Lay out continuation-bit bytes into staged: each 7-bit group with MSB set,
                    //except the terminator. Loop is fully unrolled below; the compiler will collapse
                    //the per-iteration branch since the upper bound is a small constant range.
                    ulong staged = 0;
                    var shift = 0;
                    while (src >= 0x80)
                    {
                        staged |= ((src & 0x7FUL) | 0x80UL) << shift;
                        src >>= 7;
                        shift += 8;
                    }

                    staged |= src << shift; //terminator (MSB clear)
                    Unsafe.WriteUnaligned(ref Unsafe.Add(ref bufRef, pos), staged);
                    byte_ = pos + (shift >> 3) + 1;
                    return true;
                }

                //Slow path: per-byte with bounds.
                while (pos < max)
                {
                    if (src < 0x80)
                    {
                        Unsafe.Add(ref bufRef, pos) = (byte)src;
                        byte_ = pos + 1;
                        return true;
                    }

                    Unsafe.Add(ref bufRef, pos++) = (byte)(0x80 | src);
                    src >>= 7;
                }

                byte_ = pos;
                u8_ = src;
                return false;
            }

            ///<summary>
            ///Encodes a signed long value using ZigZag encoding.
            ///This maps signed integers to unsigned integers so that numbers with a small absolute value
            ///(i.e., close to zero, positive or negative) have a small varint encoded value.
            ///</summary>
            ///<param name="src">The signed long value to encode.</param>
            ///<param name="right">The number of bits to right-shift `src` in the XOR operation (typically 63 for Int64).</param>
            ///<returns>The ZigZag-encoded unsigned long value.</returns>
            public static ulong zig_zag(long src, int right) => (ulong)(src << 1 ^ src >> right);
#endregion

            ///<summary>
            ///Puts a `ulong` value `src` into the buffer using a fixed number of `bytes`.
            ///If not enough buffer space, sets up a retry.
            ///</summary>
            ///<param name="src">The `ulong` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 8).</param>
            ///<param name="next_field_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put_val(ulong src, int bytes, uint next_field_case)
            {
                if (remaining < bytes)
                {
                    put(src, bytes, next_field_case);
                    return false;
                }

                put_val(src, bytes);
                return true;
            }

            ///<summary>
            ///Puts a `ulong` value `src` into the buffer using a fixed number of `bytes`,
            ///respecting endianness. Advances buffer position.
            ///Assumes sufficient space is available.
            ///</summary>
            ///<param name="src">The `ulong` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 8).</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_val(ulong src, int bytes)
            {
                put_val(src, bytes, buffer, byte_);
                byte_ += bytes;
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            static void put_val(ulong src, int srcBytes, byte[] dst, int dstOffset)
            {
                switch (srcBytes)
                {
                    case 8:
                        Endianness.OK.UInt64(src, dst, dstOffset);
                        break;
                    case 7:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        Endianness.OK.UInt16((ushort)(src >> 32), dst, dstOffset + 4);
                        dst[dstOffset + 6] = (byte)(src >> 48);
                        break;
                    case 6:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        Endianness.OK.UInt16((ushort)(src >> 32), dst, dstOffset + 4);
                        break;
                    case 5:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        dst[dstOffset + 4] = (byte)(src >> 32);
                        break;
                    case 4:
                        Endianness.OK.UInt32((uint)src, dst, dstOffset);
                        break;
                    case 3:
                        Endianness.OK.UInt16((ushort)src, dst, dstOffset);
                        dst[dstOffset + 2] = (byte)(src >> 16);
                        break;
                    case 2:
                        Endianness.OK.UInt16((ushort)src, dst, dstOffset);
                        break;
                    case 1:
                        dst[dstOffset] = (byte)src;
                        break;
                    default:
                        throw new ArgumentOutOfRangeException(nameof(srcBytes),
                                                              $"Invalid byte count: {srcBytes}. Must be between 1 and 8.");
                }
            }

            ///<summary>
            ///Puts a `uint` value `src` into the buffer using a fixed number of `bytes`.
            ///If not enough buffer space, sets up a retry.
            ///</summary>
            ///<param name="src">The `uint` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 4).</param>
            ///<param name="next_field_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put_val(uint src, int bytes, uint next_field_case)
            {
                if (remaining < bytes)
                {
                    put(src, bytes, next_field_case);
                    return false;
                }

                put_val(src, bytes);
                return true;
            }

            ///<summary>
            ///Puts a `uint` value `src` into the buffer using a fixed number of `bytes`,
            ///respecting endianness. Advances buffer position.
            ///Assumes sufficient space is available.
            ///</summary>
            ///<param name="src">The `uint` value to put.</param>
            ///<param name="bytes">The number of bytes to use for `src` (1 to 4).</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put_val(uint src, int bytes)
            {
                byte_ += bytes;
                switch (bytes)
                {
                    case 4:
                        Endianness.OK.UInt32(src, buffer!, byte_ - 4);
                        return;
                    case 3:
                        Endianness.OK.UInt16((ushort)src, buffer!, byte_ - 3);
                        buffer![byte_ - 1] = (byte)(src >> 16);
                        return;
                    case 2:
                        Endianness.OK.UInt16((ushort)src, buffer!, byte_ - 2);
                        return;
                    case 1:
                        buffer![byte_ - 1] = (byte)src;
                        return;
                }
            }

            ///<summary>
            ///Puts a string into the buffer using varint encoding for its length and for each character.
            ///If not enough buffer space, sets mode to `STR` and state to `next_case` for retry,
            ///storing `src` in the `str` field for continuation.
            ///</summary>
            ///<param name="src">The string to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            ///<summary>
            ///Writes <paramref name="src"/> to the buffer as a length-prefixed varint sequence.
            ///Hot path: 8 ASCII chars per iteration packed into a single <see cref="ulong"/> and emitted via
            ///<see cref="Unsafe.WriteUnaligned{T}(ref byte, T)"/>. Detects ASCII via the OR-mask
            ///<c>(c0|c1|...|c7) &amp; ~0x7F == 0</c>; on hit, writes 8 bytes in one store.
            ///<para>
            ///Falls back to per-char <see cref="varint(ulong)"/> for &lt; 8-char tails, any non-ASCII char,
            ///or when fewer than 8 buffer bytes remain. The slow path uses the same <c>varint()</c> the
            ///<c>case STR:</c> resume dispatcher uses, so partial-buffer interruptions store remaining
            ///bits in <c>u8_</c> and resume transparently on the next call.
            ///</para>
            ///<para>
            ///Length sentinel: <c>u4 = uint.MaxValue</c> at entry signals "length-phase". On length-varint
            ///partial, <c>u4</c> stays at <c>uint.MaxValue</c> and the resume path knows to finish the
            ///length first via <c>varint()</c>.
            ///</para>
            ///</summary>
            ///<param name="src">The string to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            ///<summary>
            ///A length the description does not allow: the string, the array, the items of a Map or a Set, a dimension
            ///above its limit. Thrown while the pack is serialized - an error of the code that filled the pack, never cut.
            ///</summary>
            [MethodImpl(MethodImplOptions.NoInlining)]
            [System.Diagnostics.CodeAnalysis.DoesNotReturn]
            public static void overflow(string what, long len, long max) => throw new ArgumentOutOfRangeException(what, len, $"{what}: {len}, above the limit of the description {max}");

            ///<summary>
            ///<see cref="put(string, uint)"/> of a string the description limits to <paramref name="max"/> chars:
            ///a longer one throws (<see cref="overflow"/>).
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool put(string src, uint max, uint next_case)
            {
                check_length(src, max);
                return put(src, next_case);
            }

            ///<summary>
            ///A string above <paramref name="max"/> chars, the limit of the description, throws (<see cref="overflow"/>).
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void check_length(string src, uint max)
            {
                if (max < (uint)src.Length)
                    overflow("a string", src.Length, max);
            }

            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            public bool put(string src, uint next_case)
            {
                bit = ~(int)next_case; //string-leaf park discriminator seed: for a PLAIN field park slot.state == next_case
                //while bit == ~next_case — never equal; only a chain leaf's flip makes slot.state == (uint)bit

                //=== A short ASCII string with room: its length byte, then its chars narrowed into bytes ===
                var len = src.Length;
                var pos = byte_;
                if (len < 0x80 && len < byte_max - pos && Ascii.FromUtf16(src, new Span<byte>(buffer, pos + 1, len), out _) == OperationStatus.Done)
                {
                    buffer![pos] = (byte)len;
                    byte_ = pos + 1 + len;
                    u4 = (uint)len;
                    return true;
                }

                //=== Length phase ===
                u4 = uint.MaxValue; //length-phase sentinel for the case STR resume
                if (!varint((ulong)src.Length))
                {
                    slot!.state = next_case;
                    str = src;
                    mode = STR;
                    return false;
                }

                return put_chars(src, next_case);
            }

            ///<summary>
            ///Writes <paramref name="src"/> to the buffer as varint-encoded characters with NO length prefix —
            ///the wire <see cref="Receiver.try_get_str"/> reads. Works exactly like <see cref="put(string, uint)"/>
            ///minus the varint character-count prefix. Without a count the receiver cannot know where the string
            ///ends, so this wire only works where an enclosing framer bounds it (the string ends WITH the stream,
            ///at the framer's terminator): the canonical user is the <see cref="StringStream"/> chain leaf; a
            ///plain field should use <see cref="put(string, uint)"/>.
            ///</summary>
            ///<param name="src">The string to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public bool put_str(string src, uint next_case)
            {
                bit = ~(int)next_case; //string-leaf park discriminator seed — see put(string, uint)
                return put_chars(src, next_case);
            }

            ///<summary>
            ///Emits <paramref name="src"/>'s characters as varints from index 0 — the shared char-phase body of
            ///<see cref="put(string, uint)"/> (after its length prefix) and <see cref="put_str"/>. Every entry
            ///starts at char 0: a park is resumed by the <c>case STR:</c> dispatcher / the
            ///<see cref="StringStream"/> leaf (varint() + char loop), never by re-entering here.
            ///</summary>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool put_chars(string src, uint next_case, uint from = 0)
            {
                var buf = buffer!;
                var pos = byte_;
                var limit = byte_max;
                var len = src.Length;
                uint u4_ = from;

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);

                //=== Fast path: the ASCII chars up to the first other one, narrowed into bytes as far as the room goes ( vectorized ) ===
                if ((int)u4_ < len && pos < limit)
                {
                    Ascii.FromUtf16(src.AsSpan((int)u4_), new Span<byte>(buf, pos, limit - pos), out var w);
                    u4_ += (uint)w;
                    pos += w;
                }

                //=== Vector path: chars below 0x4000 ( ASCII among them ), 8 a step; one char from 0x4000 on goes the slow way ===
                if (Units.Accelerated)
                {
                    ref var srcRef = ref MemoryMarshal.GetReference(src.AsSpan());
                    while ((int)u4_ + 8 <= len && pos + 16 <= limit)
                    {
                        var n = Units.ToVarints(ref Unsafe.Add(ref srcRef, (int)u4_), len - (int)u4_, ref Unsafe.Add(ref bufRef, pos), limit - pos, out var written);
                        u4_ += (uint)n;
                        pos += written;
                        if ((int)u4_ + 8 > len || pos + 16 > limit)
                            break;
                        var c = (uint)src[(int)u4_]; //from 0x4000 on: three bytes, all of them fit here
                        Unsafe.Add(ref bufRef, pos) = (byte)(c | 0x80);
                        Unsafe.Add(ref bufRef, pos + 1) = (byte)(c >> 7 | 0x80);
                        Unsafe.Add(ref bufRef, pos + 2) = (byte)(c >> 14);
                        pos += 3;
                        u4_++;
                    }
                }

                //Sync byte_/u4 so varint() (which advances byte_ internally) sees the right cursor.
                byte_ = pos;
                u4 = u4_;

                //=== Slow path: per-char varint, resume-compatible ===
                //varint() either fully writes the char or stores remaining bits in u8_ and returns
                //false. The resume path (transmitter case STR) calls varint() to finish, then loops.
                while (u4 < len)
                    if (!varint(src[(int)u4++]))
                    {
                        slot!.state = next_case;
                        str = src;
                        mode = STR;
                        return false;
                    }

                return true;
            }

            ///<summary>
            ///Writes <paramref name="src"/> to the buffer as raw <b>UTF-8</b> bytes with NO length prefix —
            ///the wire format <see cref="Receiver.try_get_utf"/> reads.
            ///If not enough buffer space, sets mode to <c>STR_UTF8</c> and state to <paramref name="next_case"/>
            ///for retry, storing <paramref name="src"/> in the <c>str</c> field for continuation.
            ///<para>
            ///Without a count the receiver cannot know where the string ends, so this wire only works where an
            ///enclosing framer bounds it (the string ends WITH the stream, at the framer's terminator): the
            ///canonical user is the <see cref="UTFStream"/> chain leaf.
            ///</para>
            ///<para>
            ///CONTRACT — the caller supplies well-formed UTF-16: NO unpaired surrogates (they have no UTF-8
            ///encoding). The encoder does NOT validate — feeding a malformed string is a caller bug with
            ///unspecified wire effects (a mid-transmission failure, or a silently different value on the peer).
            ///A caller unsure of its data must validate or sanitize it FIRST, with the standard library:
            ///<c>Encoding.UTF8.GetByteCount(src)</c> throws under
            ///<c>new UTF8Encoding(false, throwOnInvalidBytes: true)</c>, or sanitize explicitly with
            ///<c>Encoding.UTF8.GetString(Encoding.UTF8.GetBytes(src))</c> (an unpaired surrogate becomes U+FFFD)
            ///— and be explicit about the substitution.
            ///</para>
            ///</summary>
            ///<param name="src">The string to put — well-formed UTF-16, per the CONTRACT above.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the string was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            public bool put_utf(string src, uint next_case)
            {
                bit = ~(int)next_case; //string-leaf park discriminator seed — see put(string, uint)

                //No length prefix on this wire — straight to the char phase.
                u4 = 0;
                bytes_left = 0; //no split sequence pending
                str = src;

                if (putting_utf())
                {
                    u8_ = 0;
                    return true; //putting_utf already cleared str
                }

                slot!.state = next_case;
                mode = STR_UTF8;
                return false;
            }

            ///<summary>
            ///Encodes <c>str</c>'s characters as UTF-8 from index <c>u4</c> on, until the source is exhausted or
            ///the buffer is full.
            ///<para>
            ///Register roles while in this phase: <c>u4</c> = next char to encode;
            ///<c>bytes_left</c> = count of bytes of a sequence split by the previous fill, packed little-endian in
            ///<c>u8_</c> and drained before anything else — so the tail bytes of every buffer are used, matching
            ///<c>put(string)</c>'s partial-varint behavior. A surrogate met in the loop is assumed a PAIR lead —
            ///<see cref="put_utf"/>'s CONTRACT puts UTF-16 well-formedness on the caller.
            ///</para>
            ///<para>
            ///Bulk path: on ASCII, UTF-8 is the identity, so the encoder reuses the varint codec's SIMD ASCII
            ///shape — 16 chars per <see cref="Vector256"/> narrow-store, 8 per <see cref="Vector128"/>,
            ///with the same short-run backoff. Non-ASCII falls to a scalar path that builds the 2..4-byte
            ///sequence ONCE in registers and only decides where it goes: straight out when it fits whole,
            ///split-staged otherwise.
            ///</para>
            ///</summary>
            ///<returns>True if the string was encoded completely (<c>str</c> is cleared); false if the buffer
            ///filled up and the resume state was committed to <c>u4</c> / <c>u8_</c> / <c>bytes_left</c>.</returns>
            [MethodImpl(MethodImplOptions.AggressiveOptimization)]
            internal bool putting_utf()
            {
                var buf = buffer!;
                var src = str!;
                var pos = byte_;
                var limit = byte_max;
                var i = (int)u4;
                var len = src.Length;

                ref var bufRef = ref MemoryMarshal.GetArrayDataReference(buf);

                //Drain a sequence split by the previous fill.
                if (0 < bytes_left)
                {
                    var p = u8_;
                    var n = bytes_left;
                    do
                    {
                        if (pos == limit) //still unfinished, but bytes went out
                        {
                            byte_ = pos;
                            u4 = (uint)i;
                            u8_ = p;
                            bytes_left = n;
                            return false;
                        }

                        Unsafe.Add(ref bufRef, pos++) = (byte)p;
                        p >>= 8;
                    } while (0 < --n);

                    bytes_left = 0;
                }

                ref var srcRef = ref MemoryMarshal.GetReference(src.AsSpan());
                ref var srcU = ref Unsafe.As<char, ushort>(ref srcRef); //vector ops are not defined over `char`

                var skip = 0;

                while (i < len && pos < limit)
                {
                    //An ASCII run cannot start on a non-ASCII character, so one compare gates the whole bulk block.
                    if (Unsafe.Add(ref srcRef, i) < 0x80)
                    {
                        if (0 < skip)
                            skip--;
                        else if (Vector256.IsHardwareAccelerated && 16 <= len - i && 16 <= limit - pos)
                        {
                            var v = Vector256.LoadUnsafe(ref srcU, (uint)i);

                            //16 bytes of room are guaranteed, so this store is in bounds even when only the
                            //leading `run` of them are meaningful - the rest is overwritten next round.
                            Vector256.Narrow(v, v).GetLower().StoreUnsafe(ref bufRef, (uint)pos);

                            if ((v & VARINT_NON_ASCII_256) == Vector256<ushort>.Zero) //cheap any-test, the common case
                            {
                                i += 16;
                                pos += 16;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(Vector256.GreaterThan(v, VARINT_ASCII_MAX_256).ExtractMostSignificantBits());
                            i += run; //>= 1: element 0 was ASCII
                            pos += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF; //runs this short cost more in vector work than they save
                        }
                        else if (8 <= len - i && 8 <= limit - pos)
                        {
                            var v = Vector128.LoadUnsafe(ref srcU, (uint)i);

                            Unsafe.WriteUnaligned(ref Unsafe.Add(ref bufRef, pos), Vector128.Narrow(v, v).AsUInt64().GetElement(0));

                            if ((v & VARINT_NON_ASCII_128) == Vector128<ushort>.Zero)
                            {
                                i += 8;
                                pos += 8;
                                continue;
                            }

                            var run = BitOperations.TrailingZeroCount(Vector128.GreaterThan(v, VARINT_ASCII_MAX_128).ExtractMostSignificantBits());
                            i += run;
                            pos += run;
                            if (run < 8)
                                skip = VARINT_BACKOFF;
                        }
                    }

                    int c0 = Unsafe.Add(ref srcRef, i); //the interrupting, or room-limited, character
                    if (c0 < 0x80)
                    {
                        Unsafe.Add(ref bufRef, pos++) = (byte)c0; //loop head guarantees pos < limit
                        i++;
                        continue;
                    }

                    //ONE place computes the sequence; the branch below only decides where to put it.
                    int b0, b1, b2 = 0, b3 = 0, n;
                    if (c0 < 0x800)
                    {
                        b0 = 0xC0 | c0 >> 6;
                        b1 = 0x80 | c0 & 0x3F;
                        n = 2;
                        i++;
                    }
                    else if ((c0 & 0xF800) == 0xD800) //a validated surrogate PAIR — two chars, one code point
                    {
                        var point = 0x1_0000 + ((c0 - 0xD800) << 10) + (Unsafe.Add(ref srcRef, i + 1) - 0xDC00);
                        b0 = 0xF0 | point >> 18;
                        b1 = 0x80 | point >> 12 & 0x3F;
                        b2 = 0x80 | point >> 6 & 0x3F;
                        b3 = 0x80 | point & 0x3F;
                        n = 4;
                        i += 2;
                    }
                    else
                    {
                        b0 = 0xE0 | c0 >> 12;
                        b1 = 0x80 | c0 >> 6 & 0x3F;
                        b2 = 0x80 | c0 & 0x3F;
                        n = 3;
                        i++;
                    }

                    if (n <= limit - pos) //fits whole — straight out, the staging is never touched
                    {
                        Unsafe.Add(ref bufRef, pos++) = (byte)b0;
                        Unsafe.Add(ref bufRef, pos++) = (byte)b1;
                        if (2 < n)
                            Unsafe.Add(ref bufRef, pos++) = (byte)b2;
                        if (3 < n)
                            Unsafe.Add(ref bufRef, pos++) = (byte)b3;
                        continue;
                    }

                    //Does not fit whole: emit what fits, pack the rest for the next fill.
                    var pend = (ulong)(uint)(b0 | b1 << 8 | b2 << 16 | b3 << 24);
                    var left = n;
                    while (pos < limit)
                    {
                        Unsafe.Add(ref bufRef, pos++) = (byte)pend;
                        pend >>= 8;
                        left--;
                    }

                    byte_ = pos;
                    u4 = (uint)i;
                    u8_ = pend;
                    bytes_left = left;
                    return false;
                }

                byte_ = pos;
                u4 = (uint)i;
                if (i < len)
                    return false; //buffer full on a char boundary — nothing staged (bytes_left == 0)

                //=== Success ===
                str = null;
                return true;
            }

            ///<summary>
            ///OPTIONAL string-fragment supplier for a chain-string transmission — the streaming answer to
            ///"my content is produced in pieces". A generator that yields text in fragments (a document
            ///renderer, a report builder) would otherwise have to concatenate them into one big <c>string</c>
            ///just to send it; instead, set this field (alongside staging the FIRST fragment as <see cref="str"/>)
            ///and <see cref="StringStream"/>/<see cref="UTFStream"/> will pull fragment after fragment from it
            ///once the current one is fully emitted — until it returns <c>null</c>, which ends the transfer. The
            ///fragments concatenate ON THE WIRE: the prefix-less stream carries just their characters back to
            ///back, so the receiver assembles them into ONE string, indistinguishable from sending the
            ///pre-concatenated whole (bit-identical wire).
            ///<para>
            ///Fragments may be empty. For the <see cref="UTFStream"/> wire, <see cref="put_utf"/>'s CONTRACT
            ///applies to EACH fragment: well-formed UTF-16 — in particular, a surrogate pair must not be split
            ///across two fragments.
            ///</para>
            ///<para>
            ///Consulted ONLY by the chain leaves; plain <c>put*(string, …)</c> fields ignore it. Cleared when
            ///the supplier is drained and by <see cref="reset"/>.
            ///</para>
            ///</summary>
            public Func<string?>? strs;

            ///<summary>
            ///Stages <paramref name="src"/> for a transform-chain transmission and hands back the matching
            ///stateless string LEAF, ready to be embedded with <c>datatype(chain_id, leaf, next_case)</c>.
            ///The string rides the <see cref="str"/> register — otherwise idle for the whole span of a string
            ///transfer — which is what lets the leaf itself stay a shared, stateless singleton. To stream content
            ///produced in pieces without concatenating it first, ALSO set <see cref="strs"/> — the leaf will pull
            ///and send the following fragments after <paramref name="src"/> completes.
            ///</summary>
            ///<param name="src">The string the chain will carry.</param>
            ///<param name="utf">Leaf codec: <c>true</c> — UTF-8 (<see cref="put_utf"/> wire, the
            ///directional-string case), <c>false</c> — varint (<see cref="put(string, uint)"/> wire, the plain
            ///<c>[Zstd] string</c> case).</param>
            ///<param name="next_case">The field's retry case — the SAME value the pack passes to
            ///<c>datatype(chain_id, leaf, next_case)</c>. Seeded as <c>bit = ~next_case</c>: unique to this field
            ///within the pack's switch, so the leaf's park state can never collide with any other
            ///<c>slot.state</c> in flight, and every string transfer re-seeds <c>bit</c> so it is never stale.</param>
            ///<returns>The shared leaf singleton to pass into the chain.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public BytesSrc put(string src, bool utf, uint next_case)
            {
                str = src;
                bit = ~(int)next_case; //discriminator seed: slot.state == (uint)bit only after the leaf's FIRST park flips it
                return utf ? UTFStream.ONE : StringStream.ONE;
            }

            ///<summary>
            ///Sets up a retry operation for putting a `uint` value.
            ///Stores `src`, `bytes`, and `next_case` in `u4`, `bytes_left`, and `slot.state` respectively.
            ///Sets mode to `VAL4`.
            ///</summary>
            ///<param name="src">The `uint` value that needs to be written.</param>
            ///<param name="bytes">The number of bytes `src` should occupy (1 to 4).</param>
            ///<param name="next_case">The state to resume at when more buffer space is available.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            void put(uint src, int bytes, uint next_case)
            {
                slot!.state = next_case;
                bytes_left = bytes;
                u4 = src;
                mode = VAL4;
            }

            ///<summary>
            ///Sets up a retry operation for putting a `ulong` value.
            ///Stores `src`, `bytes`, and `next_case` in `u8`, `bytes_left`, and `slot.state` respectively.
            ///Sets mode to `VAL8`.
            ///</summary>
            ///<param name="src">The `ulong` value that needs to be written.</param>
            ///<param name="bytes">The number of bytes `src` should occupy (1 to 8).</param>
            ///<param name="next_case">The state to resume at when more buffer space is available.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            void put(ulong src, int bytes, uint next_case)
            {
                slot!.state = next_case;
                bytes_left = bytes;
                u8 = src;
                mode = VAL8;
            }

            ///<summary>
            ///Sets the transmitter's current processing mode to `RETRY` and records `the_case` as the state
            ///to resume from when more buffer space is available (or operation can be retried).
            ///</summary>
            ///<param name="the_case">The specific state or step in the serialization logic to resume at.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void retry_at(uint the_case)
            {
                slot!.state = the_case;
                mode = RETRY;
            }

            ///<summary>
            ///Calculates the minimum number of bytes required to represent an integer value.
            ///0 requires 0 bytes (by some conventions, not universally).
            ///1-255 requires 1 byte.
            ///256-65535 requires 2 bytes.
            ///65536-16777215 requires 3 bytes.
            ///Larger values up to Int32.MaxValue require 4 bytes.
            ///</summary>
            ///<param name="value">The integer value.</param>
            ///<returns>The number of bytes required (0-4).</returns>
            public int bytes4value(int value) => value < 0xFFFF     ? value < 0xFF ? value == 0 ? 0 : 1 : 2
                                                 : value < 0xFFFFFF ? 3
                                                                    : 4;

            ///<summary>
            ///Puts a boolean value into the buffer as a single byte (1 for true, 0 for false).
            ///If not enough buffer space, sets up a retry.
            ///</summary>
            ///<param name="src">The boolean value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(bool src, uint next_case) => put(Unsafe.As<bool, byte>(ref src), next_case);

            ///<summary>
            ///Puts a signed byte value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The signed byte value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(sbyte src) => buffer![byte_++] = (byte)src;

            ///<summary>
            ///Puts a nullable signed byte value into the buffer. Assumes the value is not null and sufficient space is available.
            ///</summary>
            ///<param name="src">The nullable signed byte value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(sbyte? src) => buffer![byte_++] = (byte)src!.Value;

            ///<summary>
            ///Puts a signed byte value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The signed byte value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(sbyte src, uint next_case) => put((byte)src, next_case);

            ///<summary>
            ///Puts a nullable signed byte value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable signed byte value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(sbyte? src, uint next_case) => put((byte)src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned byte value into the buffer. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The unsigned byte value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(byte src) => buffer![byte_++] = src;

            ///<summary>
            ///Puts a nullable unsigned byte value into the buffer. Assumes the value is not null and sufficient space is available.
            ///</summary>
            ///<param name="src">The nullable unsigned byte value to put. Must have a value.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(byte? src) => buffer![byte_++] = src!.Value;

            ///<summary>
            ///Puts a nullable unsigned byte value into the buffer. Assumes value is not null. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The nullable unsigned byte value to put. Must have a value.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(byte? src, uint next_case) => put(src!.Value, next_case);

            ///<summary>
            ///Puts an unsigned byte value into the buffer. If not enough space, sets up a retry.
            ///</summary>
            ///<param name="src">The unsigned byte value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the byte was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(byte src, uint next_case)
            {
                if (byte_ < byte_max)
                {
                    put(src);
                    return true;
                }

                put(src, 1, next_case);
                return false;
            }

            ///<summary>
            ///Closes the window of a one-byte array <see cref="AdHoc.window"/> opened, and sets the retry when it held fewer
            ///bytes than asked: the buffer is full.
            ///</summary>
            public int window_done(int asked, uint retry_case)
            {
                var n = window_close();
                if (n < asked)
                    retry_at(retry_case);
                return n;
            }

            ///<summary>
            ///Writes a sequence of bytes from a source array into the internal output buffer.
            ///If the data exceeds available space, it performs a partial write and sets a retry state.
            ///</summary>
            ///<param name="src">The source byte array to read from.</param>
            ///<param name="src_byte">The starting index (offset) in the source array.</param>
            ///<param name="src_bytes">The number of bytes to attempt to write.</param>
            ///<param name="retry_case">The state identifier to transition to if the buffer becomes full.</param>
            ///<returns>The number of bytes actually written to the buffer.</returns>
            public int put(ReadOnlySpan<byte> src, int src_byte, int src_bytes, uint retry_case)
            {
                if (remaining < src_bytes)
                {
                    src_bytes = remaining;
                    retry_at(retry_case);
                }

                src.Slice(src_byte, src_bytes).CopyTo(buffer!.AsSpan(byte_));
                byte_ += src_bytes;
                return src_bytes;
            }

            ///<inheritdoc cref="put(ReadOnlySpan{byte}, int, int, uint)"/>
            public int put(byte[] src, int src_byte, int src_bytes, uint retry_case)
            {
                if (remaining < src_bytes)
                {
                    src_bytes = remaining;
                    retry_at(retry_case);
                }

                Array.Copy(src, src_byte, buffer, byte_, src_bytes);
                byte_ += src_bytes;
                return src_bytes;
            }

