            ///<summary>
            ///Puts a UInt128 value into the buffer: 16 bytes, little-endian. If not enough space, keeps it in `u8` / `u16`
            ///and sets up a retry.
            ///</summary>
            ///<param name="src">The UInt128 value to put.</param>
            ///<param name="next_case">The state to retry at if writing fails.</param>
            ///<returns>True if the value was put successfully; false if a retry is needed.</returns>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(UInt128 src, uint next_case)
            {
                if (remaining < 16)
                {
                    slot!.state = next_case;
                    u8 = unchecked((ulong)src);
                    u16 = unchecked((ulong)(src >> 64));
                    mode = VAL16;
                    return false;
                }

                put(src);
                return true;
            }

            ///<summary>
            ///Puts an Int128 value into the buffer: 16 bytes, little-endian, two's complement. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The Int128 value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(Int128 src) => put(unchecked((UInt128)src));

            ///<summary>Puts a UUID as its UInt128 ( <see cref="AdHoc.uuid(Guid)"/> ). If not enough space, sets up a retry.</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public bool put(Guid src, uint next_case) => put(uuid(src), next_case);

            ///<summary>Puts a UUID as its UInt128 ( <see cref="AdHoc.uuid(Guid)"/> ). Assumes sufficient space.</summary>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(Guid src) => put(uuid(src));

            ///<summary>
            ///Puts a UInt128 value into the buffer: 16 bytes, little-endian, the low 8 bytes first. Assumes sufficient space.
            ///</summary>
            ///<param name="src">The UInt128 value to put.</param>
            [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
            public void put(UInt128 src)
            {
                Endianness.OK.UInt64(unchecked((ulong)src), buffer, byte_);
                Endianness.OK.UInt64(unchecked((ulong)(src >> 64)), buffer, byte_ + 8);
                byte_ += 16;
            }

            public override string ToString()
            {
                if (slot == null)
                    return "";
                var s = slot;
                while (s.prev != null)
                    s = s.prev;
                var str = "";
                var offset = "";
                for (; s != slot; s = s.next, offset += "\t")
                    str += $"{offset}{s.src?.GetType()}\t{s.state}\n";

                str += $"{offset}{slot.src?.GetType()}\t{s.state}\n";

                return str;
            }

            ///<summary>
            ///Infrastructure base class for one-to-many message broadcasting (publisher → multiple subscribers pattern) -
            ///without a lock.
            ///<para>
            ///This is an internal infrastructure component. It is **not** meant to be used directly
            ///by application code. Concrete implementations are typically generated by source generators
            ///as part of the connection/messaging infrastructure.
            ///</para>
            ///<para>
            ///The subscribers are an array replaced whole on every change - copy on write, published with a CAS. A broadcast
            ///reads it once and walks it without a lock: broadcasts from any number of threads run side by side, and a
            ///subscription that changes meanwhile is seen by the next broadcast. A change copies the array - O(subscribers) -
            ///which is the right trade where broadcasts are many and subscriptions change seldom. Nothing is allocated on the
            ///path of a broadcast.
            ///</para>
            ///</summary>
            ///<typeparam name="DST">Type of subscriber/destination. Must be a concrete subtype
            ///of <see cref="Transmitter"/>. Usually represents a connection or client proxy.</typeparam>
            public abstract class Broadcaster<DST>
                where DST : Transmitter
            {
                ///<summary>
                ///The subscribers, unique by reference: never changed in place - a change publishes a new array.
                ///</summary>
                DST[] _subscribers = [];

                ///<summary>The subscribers at this moment - a snapshot, not to be changed.</summary>
                public DST[] Subscribers => Volatile.Read(ref _subscribers);

                ///<summary>How many subscribers there are at this moment.</summary>
                public int Count => Volatile.Read(ref _subscribers).Length;

                public bool IsEmpty => Volatile.Read(ref _subscribers).Length == 0;

                ///<summary>Drops every subscriber.</summary>
                public void Reset() => Volatile.Write(ref _subscribers, []);

                ///<summary>
                ///Implements the logic to enqueue the captured data into the transmission queue of one subscriber.
                ///<para>
                ///Called with no lock held. It may subscribe and unsubscribe, this broadcaster included - the walk in progress
                ///goes on over the array it started with. It should be fast and not block: it runs once per subscriber.
                ///</para>
                ///</summary>
                protected abstract bool Broadcasting(Broadcastable src, DST dst);

                ///<summary>Whether the roles of the subscriber allow the pack: no - it is not its, and it stays subscribed.</summary>
                protected virtual bool allowed(Broadcastable src, DST dst) => true;

                ///<summary>
                ///Broadcasts the pack the receiver has captured and gives the reference of the capture back: the pack
                ///returns to its pool once the last subscriber has sent it - at once, when there is none.
                ///</summary>
                public void Broadcast(Receiver bytes_src)
                {
                    Broadcastable? src = bytes_src.bytesCopy;
                    if (src == null)
                        return;
                    bytes_src.bytesCopy = null;
                    try
                    {
                        Broadcast(src);
                    }
                    finally
                    {
                        src.Release();
                    }
                }

                public void PrepareBroadcastIfAnySubscriber(Receiver bytes_src, int pack_id)
                {
                    if (0 < Count)
                        Receiver.BytesCopy.InMemory.Acquire(pack_id, bytes_src);
                }

                ///<summary>
                ///Broadcasts the captured packet to all subscribers of this moment. No lock: the array read at the start is
                ///walked, whatever changes meanwhile. A subscriber whose <see cref="Broadcasting"/> throws, or that refused and whose
                ///connection is closed, is unsubscribed after the walk - a closed one would refuse every broadcast from now on; one
                ///whose queue is full stays - a transient full queue is not grounds for dropping it.
                ///Allocates nothing, but for the list of the broken ones when there are any.
                ///<para>
                ///The references: the caller holds one of its own for the time of the call. Every subscriber gets one with
                ///the pack and gives it back once the pack is out, or discarded. They are taken in one atomic step for all
                ///the subscribers, before the first of them can send the pack and give its reference back; those of the
                ///subscribers that did not take the pack are given back in one step after the walk. So a broadcast costs
                ///one atomic step, whatever the number of subscribers, and a second one only when a subscriber refused.
                ///</para>
                ///</summary>
                ///<param name="src">The raw byte source captured by a <see cref="Receiver"/>.</param>
                public void Broadcast(Broadcastable? src)
                {
                    if (src == null)
                        return;
                    var all = Volatile.Read(ref _subscribers);
                    if (all.Length == 0)
                        return;
                    DST[]? broken = null;
                    int nb = 0, back = 0, i = 0;
                    src.Acquire(all.Length);
                    try
                    {
                        for (; i < all.Length; i++)
                            try //a problem with a subscriber should not influence to others
                            {
                                if (!allowed(src, all[i]) || !Broadcasting(src, all[i]))
                                {
                                    back++; //not queued: a full queue stays, a closed connection leaves after the walk
                                    if (!(all[i].ext_connection?.IsOpen ?? false))
                                        (broken ??= new DST[all.Length])[nb++] = all[i];
                                }
                            }
                            catch (Exception)
                            {
                                back++;
                                (broken ??= new DST[all.Length])[nb++] = all[i]; //unsubscribe the problematic, after the walk
                            }
                    }
                    finally
                    {
                        if (0 < (back += all.Length - i)) //a walk cut short: those not reached
                            src.Release(back);
                    }

                    for (i = 0; i < nb; i++)
                        Unsubscribe(broken![i]);
                }

                ///<summary>
                ///Adds a subscriber; any thread, no lock.
                ///</summary>
                ///<param name="dst">The subscriber to add.</param>
                ///<returns><c>false</c>: it was subscribed already.</returns>
                public bool Subscribe(DST dst)
                {
                    for (;;)
                    {
                        var was = Volatile.Read(ref _subscribers);
                        foreach (var s in was)
                            if (ReferenceEquals(s, dst))
                                return false;
                        var now = new DST[was.Length + 1];
                        Array.Copy(was, now, was.Length);
                        now[was.Length] = dst;
                        if (ReferenceEquals(Interlocked.CompareExchange(ref _subscribers, now, was), was))
                            return true;
                    }
                }

                ///<summary>
                ///Removes a subscriber; any thread, no lock. Nothing is made when it is not subscribed.
                ///</summary>
                ///<param name="dst">The subscriber to remove.</param>
                ///<returns><c>false</c>: it was not subscribed.</returns>
                public bool Unsubscribe(DST dst)
                {
                    for (;;)
                    {
                        var was = Volatile.Read(ref _subscribers);
                        var at = -1;
                        for (var i = 0; i < was.Length; i++)
                            if (ReferenceEquals(was[i], dst))
                            {
                                at = i;
                                break;
                            }

                        if (at < 0)
                            return false;
                        DST[] now = was.Length == 1 ? [] : new DST[was.Length - 1];
                        Array.Copy(was, 0, now, 0, at);
                        Array.Copy(was, at + 1, now, at, was.Length - at - 1);
                        if (ReferenceEquals(Interlocked.CompareExchange(ref _subscribers, now, was), was))
                            return true;
                    }
                }

                ///<summary>
                ///Removes every subscriber <paramref name="which"/> accepts; any thread, no lock. <paramref name="which"/> may
                ///be asked again for a subscriber, when another change came in between.
                ///</summary>
                ///<returns>How many were removed.</returns>
                public int RemoveWhere(Predicate<DST> which)
                {
                    for (;;)
                    {
                        var was = Volatile.Read(ref _subscribers);
                        var keep = new DST[was.Length];
                        var n = 0;
                        foreach (var s in was)
                            if (!which(s))
                                keep[n++] = s;
                        if (n == was.Length)
                            return 0;
                        if (n == 0)
                            keep = [];
                        else
                            Array.Resize(ref keep, n);
                        if (ReferenceEquals(Interlocked.CompareExchange(ref _subscribers, keep, was), was))
                            return was.Length - n;
                    }
                }
            }

            ///<summary>
            ///Defines a reference-counted resource optimized for zero-allocation broadcasting.
            ///</summary>
            public interface Broadcastable : BytesSrc
            {
                ///<summary>
                ///Increments the reference counter to signal active use.
                ///</summary>
                ///<returns>The updated reference count after the increment.</returns>
                int Acquire();

                ///<summary>
                ///Takes <paramref name="n"/> references at once - those of all the subscribers of a broadcast. An
                ///implementation makes it one atomic step.
                ///</summary>
                ///<returns>The updated reference count.</returns>
                int Acquire(int n)
                {
                    var count = State();
                    while (0 < n--)
                        count = Acquire();
                    return count;
                }

                ///<summary>
                ///Gives <paramref name="n"/> references back at once, as <see cref="Release()"/> does one.
                ///</summary>
                ///<returns>The updated reference count, or -1 if more is given back than is held.</returns>
                int Release(int n)
                {
                    var count = State();
                    while (0 < n-- && -1 < count)
                        count = Release();
                    return count;
                }

                ///<summary>
                ///Returns the current instantaneous reference count.
                ///</summary>
                ///<remarks>
                ///In multi-threaded environments, this value is an "at-the-moment" snapshot
                ///and may change immediately after the call returns.
                ///</remarks>
                ///<returns>The current reference count.</returns>
                int State();

                ///<summary>
                ///Decrements the reference counter. If the counter reaches zero, the object is recycled.
                ///</summary>
                ///<returns>
                ///The updated reference count, or -1 if called on an already-released resource.
                ///</returns>
                int Release();
            }

            ///<summary>
            ///Chunked-stream <b>producer</b> — the transmit half of a streamed packet. Emits
            ///<c>[id][len][data]…[len][data][0x0000]</c>: the stream's id, then 2-byte little-endian
            ///length-prefixed chunks (payload ≤ <see cref="MAX"/> bytes each) pulled from a pluggable inner
            ///<see cref="Transmitter.BytesSrc"/> src, closed by a <c>0x0000</c> terminator. The serializer owns the
            ///framing: it reserves the prefix, fills the chunk, then back-patches the real length; the
            ///terminator is written once the src signals end (<c>__get_bytes</c> returns <c>true</c>).
            ///Resumable across transmit-buffer fills via the standard <c>true</c>/<c>false</c> contract;
            ///all chunk state is per-instance; src is a pure-byte producer (writes only buffer/byte_/byte_max — never the slot).
            ///</summary>
            public class Chunked : BytesSrc
            {
                ///<summary>
                ///The largest chunk payload. A chunk length is two bytes, and two of its values are not lengths:
                ///<c>0x0000</c> ends the stream and <see cref="ABORT"/> ends it as void. So a chunk carries at most
                ///<c>0xFFFE</c> bytes, and every producer of chunks (this class, <see cref="Tunnel.Relay"/>) honours it.
                ///</summary>
                public const int MAX = 0xFFFE;

                ///<summary>
                ///Chunk length that ends the stream as VOID: whatever the receiver got of it after its last complete pack
                ///is to be discarded, and nothing more of it will come. A relay writes it when the source of the packet it
                ///is forwarding disappears mid-way (a closed Observer tab during an upload, a dropped link): the receiving
                ///end resets only the virtual connection this stream belonged to, and the physical connection — shared
                ///by every tunnel on it — keeps running. The same shape as HTTP/2 RST_STREAM or QUIC RESET_STREAM: a
                ///chunked stream has no other way to stop part-way, and closing the connection is what we avoid.
                ///</summary>
                public const int ABORT = 0xFFFF;

                protected BytesSrc src = null!;      //inner stage — pure-byte (cipher/compressor/leaf) or a structured endpoint
                protected BytesSrc datatype = null!; //the chained structured pack, or null for a raw stream

                int idBytes = 1; //leading id width on the wire (bytes); 0 ⇒ id-less (a field stream / the enqueuing DataPass wrote it)
                int _state;      //PRIVATE chunk state machine (0 = chunk, 1 = terminator); the [id][tunnel_id] prelude rides dst.slot.state

                //--- tunnel_id prelude (asTunnel only) ----------------------------------------------------------
                //A tunnel endpoint emits a fixed-width little-endian tunnel_id field right after the pack id (the
                //many-to-one routing discriminator) and before the chunked body. Wire: [id][tunnel_id][chunks][0].
                public int tunnelId; //discriminator emitted on the wire (set via asTunnel); the RECEIVE side spells it tunnel_id
                int tunnelIdBytes;   //tunnel_id width on the wire: 0 = plain stream / one-to-one (nothing emitted); 1..4 = many-to-one. Zeroed once emitted

                public int __id => datatype != null ? datatype.__id : src.__id; //raw Stream (no datatype): fall back to the endpoint id

                ///<summary>(Re)configure with a chained STRUCTURED <paramref name="datatype"/>: the chunk body carries the
                ///serialized <paramref name="datatype"/> pack. Arms as an id-less stream (<c>idBytes == 0</c> — see
                ///<see cref="asStream"/>); the inner <paramref name="src"/> is the pure-byte codec stage, and it also supplies
                ///<see cref="__id"/> for a raw stream (<paramref name="datatype"/> <c>null</c>). Returns <c>this</c> for chaining.</summary>
                public Chunked Init(BytesSrc src, BytesSrc datatype)
                {
                    this.datatype = datatype;
                    this.src = src;
                    return asTunnel(0, 0, 0);
                }

                ///<summary>Convenience arming — the chain's own <see cref="_Adapter"/> serves as BOTH the inner byte
                ///stage and the datatype (its id identifies the stream): shorthand for <c>Init(_Adapter, _Adapter)</c>.</summary>
                public Chunked Init()
                {
                    datatype = _Adapter;
                    src = _Adapter;
                    return asTunnel(0, 0, 0);
                }

                ///<summary>Arm as a plain stream with an <paramref name="idBytes"/>-wide leading id (0 ⇒ id-less field stream).
                ///The id itself is <see cref="__id"/> (delegated to the chained datatype when present). Clears the private
                ///state. Returns <c>this</c> for chaining.</summary>
                public Chunked asStream(int idBytes) => asTunnel(idBytes, 0, 0);

                ///<summary>Arm as a tunnel endpoint: after the <paramref name="idBytes"/>-wide pack id, emits a
                ///<paramref name="tunnelIdBytes"/>-wide (0..4, little-endian) <paramref name="tunnelId"/> field before the
                ///chunk body (<c>tunnelIdBytes == 0</c> ⇒ plain stream — identical to <see cref="asStream"/>). Clears the
                ///private state. Returns <c>this</c> for chaining.</summary>
                public Chunked asTunnel(int idBytes, int tunnelId, int tunnelIdBytes)
                {
                    //NOTE: onStreamComplete is deliberately NOT cleared here — Transmitter.OnStreamComplete(hook)
                    //plants it into this chain BEFORE the arming Init runs; it is consumed by invokeOnStreamComplete
                    //at the stream end (source EOF or teardown), which always runs.
                    this.idBytes = idBytes;
                    _state = 0;
                    this.tunnelId = tunnelId;
                    this.tunnelIdBytes = tunnelIdBytes;
                    end = 0;
                    return this;
                }

                ///<summary>The per-stream hook, planted DIRECTLY by the generated <c>Transmitter.OnStreamComplete(hook)</c>
                ///override (<c>chain().onStreamComplete = hook</c>) right before this chain is armed. One-shot and
                ///nesting-safe by construction: <c>chain()</c> hands an inner stream a DIFFERENT (free) chain than the
                ///already-armed outer one. Consumed by <see cref="complete"/>.</summary>
                public Action<Transmitter, bool>? onStreamComplete;

                ///<summary>The chain's terminal (leaf) Adapter — framer and leaf travel as ONE aggregate, so the
                ///stream-end default always has its target. Generated arming wires it (<c>_Adapter.Init(…)</c>);
                ///codec stages may sit between the framer and this leaf.</summary>
                public readonly BytesSrc.Adapter _Adapter = new();

                ///<summary>Stream-boundary cleanup — the single call the generated <c>Chain</c> makes at BOTH ends of a
                ///stream's life: the completion branch (<paramref name="completed"/> <c>true</c>) and <c>Chain.Release</c>
                ///(<c>false</c>). Runs-and-consumes the armed hook; with no hook, a <see cref="FileStream"/> source is
                ///closed. Either way every per-stream reference on <see cref="_Adapter"/> is dropped.</summary>
                public void complete(Transmitter dst, bool completed)
                {
                    if (onStreamComplete != null)
                    {
                        onStreamComplete(dst, completed);
                        onStreamComplete = null;
                    }
                    else if (_Adapter.src is FileStream)
                        try
                        {
                            _Adapter.src.Dispose();
                        }
                        catch
                        {
                        }

                    _Adapter.src = null;
                    _Adapter.src_ = null;
                    _Adapter.redirect = null;
                }

                ///<summary>
                ///Framework entry. Emits <c>[id][tunnel_id]</c> through the transmitter's own retry machinery
                ///(<c>put_val(…, dst.slot.state = 1)</c> — parks in <c>mode</c> and resumes at the slot state), then
                ///length-prefixed chunks from <see cref="src"/> (each ≤ 65535 bytes, the prefix reserved up front and
                ///back-patched after the fill) on the PRIVATE <c>_state</c> machine, then a <c>0x0000</c> terminator
                ///once the src signals end. Returns <c>true</c> once the whole stream is written, <c>false</c> to park —
                ///including after every non-final chunk, so one drive emits at most one chunk.
                ///</summary>
                public virtual bool __get_bytes(Transmitter dst)
                {
                    switch (dst.slot!.state)
                    {
                        case 0:
                            //idBytes == 0 writes nothing and returns true (put_val(uint, 0) is a no-op), but the eagerly
                            //evaluated argument still advances the slot state past the id.
                            if (!dst.put_val((uint)__id, idBytes, dst.slot.state = 1))
                                return false;
                            goto case 1;
                        case 1:
                        {
                            if (tunnelIdBytes == 0)
                                break;
                            var bytes = tunnelIdBytes;
                            tunnelIdBytes = 0; //emitted once per arming
                            if (!dst.put_val((uint)tunnelId, bytes, 1))
                                return false;
                            break;
                        }
                    }

                    for (;;)
                        switch (_state)
                        {
                            case 0: //one length-prefixed chunk of pure bytes pulled from src
                            {
                                if (dst.remaining < 3)
                                    return false; //room for the 2-byte prefix + ≥1 payload byte

                                var lenPos = dst.byte_;
                                dst.byte_ = lenPos + 2; //reserve the length prefix
                                var byte_max = dst.byte_max;
                                var cap = lenPos + 2 + MAX; //clamp this chunk to ≤ MAX payload bytes (0xFFFF is ABORT)
                                if (cap < dst.byte_max)
                                    dst.byte_max = cap;
                                var done = get_bytes(dst);
                                dst.byte_max = byte_max;

                                var n = dst.byte_ - (lenPos + 2);
                                if (n == 0)
                                {
                                    dst.byte_ = lenPos; //nothing produced → rewind the empty reservation

                                    //`done` must be tested BEFORE treating n == 0 as a park: done-with-nothing-produced is
                                    //reachable — it is exactly the case where the PREVIOUS chunk consumed the source's last
                                    //byte, so this call hits EOF before producing anything. Parking here would re-drive an
                                    //already-completed (closed) source forever; the terminator ends the stream correctly.
                                    if (!done)
                                        return false; //src alive but produced nothing now → park
                                    _state = 1;
                                    break;
                                }

                                Endianness.OK.UInt16((ushort)n, dst.buffer!, lenPos); //back-patch the real length
                                if (!done)
                                    return false;
                                _state = 1;
                                break;
                            }
                            case 1: //2-byte zero terminator → end of stream
                                if (dst.remaining < 2)
                                    return false;
                                Endianness.OK.UInt16(end, dst.buffer!, dst.byte_);
                                dst.byte_ += 2;
                                return true;
                        }
                }

                ///<summary><c>true</c>: the stream ends with <see cref="ABORT"/> in place of the terminator - a tunnel's last burst,
                ///what tells the peer's end that the tunnel is over. Everything before it arrives whole.</summary>
                public Chunked ending(bool ends)
                {
                    end = ends ? (ushort)ABORT : (ushort)0;
                    _Adapter.farewell = ends; //the last burst carries every pack queued before Close(): no burst follows it
                    return this;
                }

                ushort end; //what the stream ends with: 0, or ABORT

                ///<summary>Pulls the next chunk payload from the inner stage. Overridable seam for a framer subclass.</summary>
                public virtual bool get_bytes(Transmitter dst) => src.__get_bytes(dst);
            }

            ///<summary>Named alias only: a transmit-side tunnel endpoint is just a <see cref="Chunked"/> armed as a tunnel
            ///via <see cref="Chunked.asTunnel(int,int,int)"/> — all behavior lives in <see cref="Chunked"/>.</summary>
            public abstract class Tunnel : Chunked
            {
            }

            ///<summary>
            ///Known-size file <b>producer</b> — the transmit half of a <c>File</c> packet. Emits
            ///<c>[id][len][data…]</c>: the file's id, a single varint-encoded total-length header
            ///(supplied up front via <see cref="Init"/>), then exactly that many payload bytes pulled from a
            ///pluggable pure-byte inner <see cref="Transmitter.BytesSrc"/> <c>src</c> — no chunk framing, no terminator.
            ///Resumable across transmit-buffer fills via the standard true/false contract; all state is
            ///per-instance, src writes only buffer/byte_/byte_max (never the slot).
            ///</summary>
            public class File : BytesSrc
            {
                protected Stream src = null!; //direct byte source (any System.IO.Stream) — overridable

                //Application-level source alternative to src, armed by the AdHoc.BytesSrc Init overloads: a byte producer that
                //is not a System.IO.Stream (e.g. a virtual connection's Internal.BytesSrc). Its Read() is three-way: >0 bytes,
                //0 = "nothing available yet, still open" (park), -1 = end of stream.
                protected AdHoc.BytesSrc? src_; //non-null ⇒ payload is pulled from here instead of src
                protected int _id, _idBytes = 1;
                protected uint _state; //resume cursor across parks
                protected long _rem, maxStreamBytes = long.MaxValue;

                public int __id => _id;

                ///<summary>Convenience overload — <c>Init(src, maxStreamBytes, int.MinValue, 0)</c>: no dispatch id written (id-less) —
                ///the stream serves an EMBEDDED FIELD data type of an outer pack (the field, not this framer, identifies it).</summary>
                public File Init(string src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue, 0);

                ///<summary>(Re)configure: a built-in direct-file source opened from <paramref name="src"/> for reading + the <c>[S(N)]</c>
                ///cap + dispatch id + id width — the stream serves a dedicated TOP-LEVEL transmittable pack. Payload length taken from the file.</summary>
                public File Init(string src, long maxStreamBytes, int id, int idBytes) => Init(new FileStream(src, FileMode.Open, FileAccess.Read, FileShare.Read), maxStreamBytes, id, idBytes);

                ///<summary>Convenience overload — <c>Init(src, maxStreamBytes, int.MinValue, 0)</c>: no dispatch id written (id-less) —
                ///embedded field. Payload length taken from the SEEKABLE <paramref name="src"/>.</summary>
                public File Init(Stream src, long maxStreamBytes) => Init(src, maxStreamBytes, int.MinValue, 0);

                ///<summary>(Re)configure from a SEEKABLE source: the payload length is taken from <c>src.Length</c>.
                ///A non-seekable stream has no declarable size, so it reaches the primary overload as <c>-1</c> and
                ///throws — pass the size explicitly instead.</summary>
                public File Init(Stream src, long maxStreamBytes, int id, int idBytes) => Init(src, maxStreamBytes, id, idBytes, src.CanSeek? src.Length: -1);

                ///<summary>PRIMARY (re)configuration: a caller-supplied byte source (any <see cref="System.IO.Stream"/>)
                ///+ the <c>[S(N)]</c> cap + dispatch id (<see cref="int.MinValue"/> = id-less: embedded
                ///field) + id width + the total payload length declared up front. A negative <paramref name="size"/> (unknown) throws, as
                ///does a <paramref name="size"/> above <paramref name="maxStreamBytes"/>. Returns <c>this</c> for chaining.</summary>
                public File Init(Stream src, long maxStreamBytes, int id, int idBytes, long size)
                {
                    _id = id;
                    _idBytes = idBytes;
                    this.src = src;
                    src_ = null;
                    if (size < 0)
                        throw new InvalidOperationException("File size unknown: " + size);
                    if (maxStreamBytes < size)
                        throw new InvalidOperationException("File size " + size + " exceeds max " + maxStreamBytes);
                    this.maxStreamBytes = maxStreamBytes;
                    _rem = size;
                    _state = 0;
                    return this;
                }

                ///<summary>Convenience overload — <c>Init(src, maxStreamBytes, int.MinValue, 0, size)</c>: no dispatch id written
                ///(id-less) — embedded field.</summary>
                public File Init(AdHoc.BytesSrc src, long maxStreamBytes, long size) => Init(src, maxStreamBytes, int.MinValue, 0, size);

                ///<summary>PRIMARY (re)configuration from an application-level <see cref="AdHoc.BytesSrc"/> source — a byte producer that
                ///is not a <see cref="System.IO.Stream"/> (e.g. a virtual connection's <c>Internal.BytesSrc</c>) + the <c>[S(N)]</c> cap +
                ///dispatch id (<see cref="int.MinValue"/> = id-less: embedded field) + id width + the total payload length declared up front.
                ///A negative <paramref name="size"/> (unknown) throws, as does a <paramref name="size"/> above
                ///<paramref name="maxStreamBytes"/>.
                ///<para>Such a source has no declarable length of its own — there is no <c>Length</c> to fall back on, which is why
                ///<paramref name="size"/> has no defaulting overload here. Returns <c>this</c> for chaining.</para></summary>
                public File Init(AdHoc.BytesSrc src, long maxStreamBytes, int id, int idBytes, long size)
                {
                    _id = id;
                    _idBytes = idBytes;
                    this.src = null!;
                    src_ = src;
                    if (size < 0)
                        throw new InvalidOperationException("File size unknown: " + size);
                    if (maxStreamBytes < size)
                        throw new InvalidOperationException("File size " + size + " exceeds max " + maxStreamBytes);
                    this.maxStreamBytes = maxStreamBytes;
                    _rem = size;
                    _state = 0;
                    return this;
                }

                ///<summary>
                ///Framework entry. Writes the dispatch id and the varint total-length header through the transmitter's own
                ///retry machinery, then produces exactly <c>_rem</c> payload bytes read DIRECTLY from <see cref="src"/>
                ///(clamped to the remaining count). Closes the source and returns <c>true</c> once the full payload is
                ///written, <c>false</c> to park when the transmit buffer fills.
                ///</summary>
                public virtual bool __get_bytes(Transmitter dst)
                {
                    for (;;)
                        switch (_state)
                        {
                            case 0:
                                if (dst.slot!.state == 0 && _idBytes > 0 && !dst.put_val((uint)_id, _idBytes, _state = dst.slot.state = 1))
                                    return false;
                                goto case 1;
                            case 1:
                                if (!dst.put_varint((ulong)_rem, _state = 2))
                                    return false;
                                goto case 2;
                            case 2:
                                for (int n; 0 < _rem;)
                                {
                                    var room = dst.byte_max - dst.byte_;
                                    if (room == 0)
                                        return false;
                                    if (_rem < room)
                                        room = (int)_rem; //clamp the read to the declared remainder
                                    if (src_ != null)
                                    {
                                        n = src_.Read(dst.buffer!, dst.byte_, room);
                                        //The declared length is the end-authority, so a source that reports EOF (-1) while payload
                                        //is still outstanding can never satisfy it. Parking would stall the pack forever, so fail loudly.
                                        if (n < 0)
                                            throw new InvalidOperationException("File source signalled end of stream with " + _rem + " payload bytes still undelivered.");
                                    }
                                    else
                                    {
                                        n = src.Read(dst.buffer!, dst.byte_, room);
                                        //Stream.Read returns 0 only at the end of the stream: with payload still owed it never makes it up
                                        if (n == 0)
                                            throw new InvalidOperationException("File source ended with " + _rem + " payload bytes still undelivered.");
                                    }

                                    if (n <= 0)
                                        return false; //nothing produced this turn → park
                                    dst.byte_ += n;
                                    _rem -= n;
                                }

                                close();
                                return true;
                        }
                }

                ///<summary>Close the source and drop the reference — runs at payload completion; teardown code may call it
                ///early so an aborted send doesn't leak the handle. Idempotent.</summary>
                public void close()
                {
                    try
                    {
                        src_?.Close();
                    }
                    catch
                    {
                    }

                    try
                    {
                        src?.Dispose();
                    }
                    catch
                    {
                    }

                    src_ = null;
                    src = null!;
                }
            }
        }

        ///<summary>VirtuallyConnects tunnel machinery: the zero-copy <see cref="Tunnel.Relay"/> (the schema-blind
        ///PATH-host forwarder) and the <see cref="Tunnel.EndPoint"/> bridge bases (tunnel endpoints).</summary>
        public interface Tunnel
        {
            ///<summary>
            ///Chunked-stream relay: forwards one inbound tunnel packet <c>[id][tunnel_id][len][data]…[0]</c> to the
            ///outbound connection that serves its tunnel_id, without parsing the packs inside and without holding the
            ///whole packet.
            ///<para>
            ///<b>Receive side.</b> It installs as the inbound packet's inner <see cref="Receiver.BytesDst"/> and turns every
            ///buffer the transport delivers into a <i>region</i> handed to the transmit side through a one-place slot. A
            ///region that holds the packet's end is copied; one that does not is taken over whole when the transport
            ///allows it (<see cref="Connection.External.swapReceive"/>, raw TCP): the relay becomes the transport's
            ///top-level sink and later buffers arrive at <see cref="Write"/>. A transport that decodes frames inside its
            ///buffer (a WebSocket) cannot hand it over, and then every region is copied.
            ///</para>
            ///<para>
            ///<b>Own framing.</b> The source's chunk headers and terminator are NOT passed through. The scan notes where they
            ///sit in a region ("holes"; the bytes are not moved), and the transmit side writes each region as a chunk of its
            ///own, <c>[len][payload]</c>, stepping over the holes. The reason is failure, not taste: a region ends wherever a
            ///socket read ended — usually inside a source chunk. With the source's framing passed through, an outbound stream
            ///whose source vanishes stops inside a chunk, and the peer parses whatever comes next on its connection as the
            ///rest of that chunk; the only way back to a consistent stream is to close that connection, which on a shared
            ///link (Monitoring → Server) drops every tunnel on it. With its own framing the relay is on a chunk boundary after
            ///every region, so it ends such a packet with <see cref="Transmitter.Chunked.ABORT"/> and the peer resets that one
            ///virtual connection (HTTP/2 RST_STREAM, QUIC RESET_STREAM: the same answer to the same problem). The cost is two
            ///bytes per region; the payload is still copied exactly once, in <see cref="__get_bytes"/>.
            ///</para>
            ///<para>
            ///<b>tunnel_id routing.</b> Many-to-one links carry a fixed-width little-endian <see cref="tunnel_id"/> right
            ///after the pack id; <see cref="__put_bytes"/> reads it (from the bytes the receiver already took with the id
            ///when its id field is wider than the pack id, else from the wire), and <see cref="OutboundSrc.outbound"/>
            ///resolves and enqueues the target. The outbound prefix <c>[id][tunnel_id]</c> is written afresh.
            ///</para>
            ///<para>
            ///<b>Failures.</b> No target, or the target refused the enqueue: the packet is consumed and dropped whole — a
            ///packet ends only between packs (a burst closes when its virtual connection has nothing in flight), so the
            ///peer merely misses whole packs. The target dies holding our pack (<see cref="Close(Transmitter)"/>): the
            ///receive drops the rest of that packet. The source dies mid-packet (<see cref="InboundLost"/>): the transmit
            ///finishes the region it holds and writes ABORT; if nothing of the packet reached the wire yet, it vanishes.
            ///</para>
            ///</summary>
            public class Relay : BytesDst, BytesSrc, Receiver.BytesDst, Transmitter.IDataPass, Transmitter.BytesSrc
            {
                public interface OutboundSrc
                {
                    ///<summary>
                    ///Resolves the outbound connection for <paramref name="tunnel_id"/>: enqueues <paramref name="dst"/> on the
                    ///returned connection's transmitter (the generated <c>sending_put</c>) and may rewrite <c>dst.tunnel_id</c>
                    ///before that. Returns <c>null</c> when there is no live target or the enqueue was refused — the relay
                    ///then drops the current packet.
                    ///</summary>
                    External? outbound(Relay dst, int tunnel_id);
                }

                //--- Transmitter.IDataPass lifecycle ---------------------------------------------------
                public Transmitter.BytesSrc? OnSerializing(Transmitter transmitter) => this;

                public void OnSerialized(Transmitter transmitter, Transmitter.BytesSrc transmitted)
                {
                    //Outbound pack fully serialized → this single instance is free to forward the next
                    //packet. Clear the per-pack transmit state and release the enqueue gate, then wake the inbound
                    //receive so a packet that was parked on the gate (see __put_bytes) can proceed.
                    _prefixDone = false;
                    _enqueued = false;
                    Inbound?.WakeReceive();
                }

                ///<summary>
                ///The OUTBOUND connection is being torn down while this pack is queued or in flight on it. Runs on that
                ///teardown, after its transmit has stopped but concurrently with the INBOUND receive, so it touches only
                ///transmit-local state: the receive owns the parse state and learns of the loss from
                ///<see cref="_outboundLost"/> — it then drops the rest of the current packet and empties the slot.
                ///The flag is raised BEFORE the gate is released, so a receive that passes the gate always sees it.
                ///</summary>
                public void Close(Transmitter transmitter)
                {
                    _txBuf = _txDrained = null;
                    _txLen = _txPayload = _txChunkLeft = 0;
                    _txState = TX_BETWEEN;
                    _prefixDone = false;
                    _outboundLost = true;
                    _enqueued = false;
                    Inbound?.WakeReceive(); //it may be parked on the gate or on the full slot
                }

                ///<summary>
                ///The INBOUND connection died (called from its teardown once no receive runs any more — the receiver's
                ///reset for a packet dispatched by id, the transport for a promoted one). The partly received packet is
                ///abandoned: the parse state is cleared, so a resumed session starts clean at a packet id. If its
                ///outbound pack is queued or in flight it can never be completed, so <see cref="_lostSeq"/> tells the
                ///transmit to end it (see <see cref="__get_bytes"/>).
                ///</summary>
                public void InboundLost()
                {
                    var mid = _outboundResolved || _rxStaged; //the packet's end has not been published yet
                    _scanState = _prefixGot = _chunkLen = _payloadLeft = 0;
                    _tidGot = _overGot = _overread = 0;
                    _outboundResolved = _rxStaged = _drop = false;
                    _rxBuf = _rxSwapBuf = null; //may be the dead transport's buffer, which it returns to its pool
                    if (_enqueued)
                    {
                        if (!mid)
                            return; //the whole packet is published: the transmit finishes it normally
                        //Tagged with the packet's number, not a plain flag: if the outbound dies concurrently the tag goes
                        //stale on its own, instead of ending whatever pack is routed next.
                        _lostSeq = _seq;
                        unfeed(tunnel_id); //the ABORT that ends the packet ends its tunnel too
                        Outbound?.WakeTransmit();
                    }
                    else
                    {
                        _outboundLost = false;
                        discardSlot();
                    }
                }

                //--- the tunnels this relay fed: what Gone() tells the far ends of ---------------------------------
                int[] _tids = new int[2];
                int _fed;          //how many of _tids are used
                int _lastTid = -1; //the tunnel of the last packet routed: the check a packet costs

                void fed(int tid)
                {
                    _lastTid = tid;
                    for (var i = 0; i < _fed; i++)
                        if (_tids[i] == tid)
                            return;
                    if (_fed == _tids.Length)
                        Array.Resize(ref _tids, _fed * 2);
                    _tids[_fed++] = tid;
                }

                void unfeed(int tid)
                {
                    for (var i = 0; i < _fed; i++)
                        if (_tids[i] == tid)
                        {
                            _tids[i] = _tids[--_fed];
                            break;
                        }

                    _lastTid = -1;
                }

                ///<summary>
                ///The inbound connection is gone for good (its <c>OnClose</c>): the far end of every tunnel it fed is told -
                ///a frame <c>[id][tunnel_id][ABORT]</c> of each, queued on the outbound <see cref="OutboundSrc.outbound"/>
                ///names, after what this relay queued there before. The far end closes that tunnel's virtual connection
                ///(<see cref="Receiver.Chunked.Ends"/>). Called once no receive runs on the inbound any more.
                ///</summary>
                public void Gone()
                {
                    for (var i = 0; i < _fed; i++)
                        _outboundSrc.outbound(new Farewell(_outId, _idBytes, _tids[i], _tidBytes), _tids[i]);
                    _fed = 0;
                    _lastTid = -1;
                }

                ///<summary>The frame that ends a tunnel whose source is gone: <c>[id][tunnel_id][ABORT]</c>. A Relay only so that
                ///<see cref="OutboundSrc.outbound"/> routes it as it routes the packets; nothing of the Relay's machinery runs.</summary>
                sealed class Farewell : Relay, Transmitter.IDataPass, Transmitter.BytesSrc
                {
                    readonly int id, idBytes, tidBytes;

                    public Farewell(int id, int idBytes, int tid, int tidBytes)
                    {
                        this.id = id;
                        this.idBytes = idBytes;
                        this.tidBytes = tidBytes;
                        tunnel_id = tid; //outbound() may rewrite it, as it does a packet's
                    }

                    Transmitter.BytesSrc? Transmitter.IDataPass.OnSerializing(Transmitter transmitter) => this;
                    void Transmitter.IDataPass.OnSerialized(Transmitter transmitter, Transmitter.BytesSrc transmitted) {}
                    void Transmitter.IDataPass.Close(Transmitter transmitter) {}
                    int Transmitter.BytesSrc.__id => id;

                    bool Transmitter.BytesSrc.__get_bytes(Transmitter dst)
                    {
                        if (dst.byte_max - dst.byte_ < idBytes + tidBytes + 2)
                            return false;
                        dst.put_val((ulong)(uint)id, idBytes);
                        if (tidBytes > 0)
                            dst.put_val((ulong)(uint)tunnel_id, tidBytes);
                        Endianness.OK.UInt16((ushort)Transmitter.Chunked.ABORT, dst.buffer!, dst.byte_);
                        dst.byte_ += 2;
                        return true;
                    }
                }

                ///<summary>Empties the shared slot: its region was meant for an outbound that will never take it. Only
                ///the receive side or a teardown calls it, when no live transmit can hold the lock for more than a moment.</summary>
                void discardSlot()
                {
                    var spin = new SpinWait();
                    while (Interlocked.CompareExchange(ref _lock, 1, 0) != 0)
                        spin.SpinOnce();
                    _sBuf = null;
                    Volatile.Write(ref _lock, 0);
                }

                const int PREFIX_BYTES = 2; //chunk length prefix width (little-endian).
                //MUST equal the protocol's chunk_length_store_bytes; kept as a local const
                //to stay usable in the hot scan loop — update both together if the width changes.

                External Inbound = null!;         //inbound (source) connection — NEVER null once Init() runs (set there, never cleared); Wake calls in the hot paths need no null check
                External Outbound = null!;        //outbound (target) connection — resolved per packet by outbound(). Non-null in the publish/take/__get_bytes hot paths (they run only AFTER outbound() resolved it to a live target), so those Wake calls need no null check. null while a packet is dropped (see _drop) and before the first packet — Close()/teardown guard accordingly
                OutboundSrc _outboundSrc = null!; //router callback: tunnel_id → outbound External (and it enqueues us)
                int _outId;                       //the full id arg the inbound receiver parsed (low _idBytes = pure pack id, high bits = over-read [tunnel_id][body-lead])
                int _idBytes;                     //PURE pack-id width (bytes), set once in Init
                int _overread;                    //over-read bytes sitting in _outId past the pure id (= src.id_bytes - _idBytes)
                int _overGot;                     //over-read bytes consumed so far for the current packet (0.._overread)

                //--- tunnel_id: parsed from the inbound right after the pack id, re-emitted on the outbound ---------
                int _tidBytes;                       //tunnel_id width on the wire: 0 = one-to-one (no tunnel_id); 1..4 = many-to-one (little-endian)
                int _tidGot;                         //tunnel_id bytes read so far for the current packet (0.._tidBytes)
                bool _outboundResolved;              //outbound() already called for the current packet (tunnel_id fully read)
                volatile bool _enqueued;             //an outbound pack for this instance is queued / in flight → hold the next inbound packet
                bool _prefixDone;                    //[id][tunnel_id] prefix already written for the current outbound pack
                bool _drop;                          //no live target for the current packet → its body is consumed and forwarded nowhere
                readonly byte[] _lead = new byte[1]; //one over-read body byte, fed to scan() while dropping
                volatile bool _outboundLost;         //Close(Transmitter): the outbound died holding our pack → the receive drops the rest of that packet
                volatile int _seq;                   //number of the packet currently routed, bumped by every resolve
                volatile int _lostSeq = -1;          //InboundLost(): _seq of a packet whose inbound died mid-way → the transmit ends its pack

                //=== Lock-free work, try-lock handoff in EXACTLY TWO places ============================
                volatile int _lock; //0 = free, 1 = held

                //A region travels with the positions of the source's framing bytes inside it ("holes": [start, length]
                //pairs relative to the region start, ascending, adjacent ones merged) and its payload size. The hole
                //arrays are swapped between staging, slot and transmit instead of copied; they grow only when a region
                //holds more source chunk boundaries than ever before.

                //--- shared (touched ONLY inside publish()/take(), under _lock) ---
                byte[]? _sBuf;
                int _sOff, _sLen, _sPayload, _sHoleCount;
                bool _sLast, _sAbort;
                int[] _sHoles = new int[8];
                int _sTid;     //the body slot (+ tunnel_id snapshot)
                byte[]? _free; //a free buffer handed back by the transmit

                //--- receive-local (staging; no lock) ---
                byte[]? _rxWork;
                bool _rxStaged;
                byte[]? _rxBuf;
                int _rxOff, _rxLen;
                bool _rxLast;
                bool _rxAbort; //the source itself ended the packet with ABORT: forwarded as such
                int[] _rxHoles = new int[8];
                int _rxHoleCount, _rxHoleBytes;
                int _rxSwap;

                byte[]? _rxSwapBuf;

                //Bytes of the offered window the staged region takes, counted from where it was staged — a count, not a
                //position. A region that failed to publish is offered again from where the receiver stopped, which is
                //where it was staged; but a region made only of bytes over-read into the pack id takes nothing from the
                //window, the receiver reports that window consumed, and the retry arrives with a different one. A stored
                //position would then skip bytes of the new window unscanned and desynchronize the chunk parse.
                int _rxTake;
                int _rxRet;
                //_rxSwap: 0 = no swap (copied), 1 = swapReceive(this,_rxSwapBuf) promote, 2/3 = swapReceive(null,_rxSwapBuf) EOS

                //--- transmit-local (touched only by __get_bytes; no lock) ---
                const int TX_BETWEEN = 0, TX_PREFIX = 1, TX_REGION = 2, TX_END = 3;
                int _txState; //TX_BETWEEN: no region in hand; TX_PREFIX: [id][tunnel_id] due; TX_REGION: a region in hand; TX_END: the terminator due
                byte[]? _txBuf;
                int _txOff, _txLen; //the region in hand: _txBuf[_txOff .. _txOff+_txLen), holes included
                int _txRel;         //next region byte to look at, relative to _txOff
                int _txPayload;     //payload bytes of the region not yet written
                int _txChunkLeft;   //payload bytes still owed to the chunk header already written
                int[] _txHoles = new int[8];
                int _txHoleCount, _txHoleAt;
                int _txEnd; //TX_END writes this: 0 (end) or ABORT
                bool _txLast, _txAbort;
                int _txTid, _txOutId, _txIdBytes, _txTidBytes;
                byte[]? _txDrained; //buffer just drained, handed back to _free at the NEXT take()

                //chunk scan state (persists across buffers)
                int _scanState;   //0 = reading prefix, 1 = in payload
                int _prefixGot;   //prefix bytes accumulated (0..PREFIX_BYTES)
                int _chunkLen;    //current chunk length being decoded
                int _payloadLeft; //payload bytes remaining in the current chunk

                volatile bool _aborted;

                public int __id => _outId; //outbound id

                //parsed tunnel_id; outbound() may rewrite it to reroute.
                public int tunnel_id = 0;

                public Relay Init(int id, int id_bytes, int tunnel_id_bytes, External inbound, OutboundSrc outbound_src)
                {
                    _outId = id;
                    _idBytes = id_bytes;
                    _tidBytes = tunnel_id_bytes;
                    Inbound = inbound;
                    _outboundSrc = outbound_src;
                    return this;
                }

                ///<summary>
                ///Scans <c>b[pos..end)</c> for the end of the chunked body, resuming across calls. Returns the index just past
                ///the terminator if found, else -1. Pure pointer walk, no copy. With <paramref name="regionStart"/> ≥ 0 every
                ///framing byte met (length prefixes, the terminator) is noted as a hole relative to it; -1 notes nothing.
                ///A source that ends its stream with ABORT ends it here too, and the region is marked to forward that.
                ///</summary>
                int scan(byte[] b, int pos, int end, int regionStart)
                {
                    while (pos < end)
                        if (_scanState == 0) //prefix
                        {
                            var from = pos;
                            while (_prefixGot < PREFIX_BYTES && pos < end)
                                _chunkLen |= b[pos++] << (8 * _prefixGot++);
                            if (0 <= regionStart)
                                hole(from - regionStart, pos - from);
                            if (_prefixGot < PREFIX_BYTES)
                                return -1; //prefix straddles the buffer boundary
                            if (_chunkLen == 0 || _chunkLen == Transmitter.Chunked.ABORT)
                            {
                                _rxAbort = _chunkLen != 0;
                                if (_rxAbort)
                                    unfeed(tunnel_id); //the source ended its tunnel itself: Gone() has nothing to tell of it
                                _chunkLen = 0;
                                _prefixGot = 0;
                                _tidGot = 0;
                                _outboundResolved = false;
                                return pos; //EOS: index just after the terminator
                            }

                            _payloadLeft = _chunkLen;
                            _chunkLen = 0;
                            _prefixGot = 0;
                            _scanState = 1;
                        }
                        else //payload
                        {
                            var take = Math.Min(_payloadLeft, end - pos);
                            pos += take;
                            _payloadLeft -= take;
                            if (_payloadLeft == 0)
                                _scanState = 0;
                            else
                                return -1; //payload continues in the next buffer
                        }

                    return -1;
                }

                ///<summary>Notes <paramref name="length"/> framing bytes at <paramref name="at"/> (relative to the region start)
                ///in the region being staged.</summary>
                void hole(int at, int length)
                {
                    if (length == 0)
                        return;
                    _rxHoleBytes += length;
                    var n = _rxHoleCount;
                    if (0 < n && _rxHoles[n * 2 - 2] + _rxHoles[n * 2 - 1] == at) //right after the previous hole: one hole
                    {
                        _rxHoles[n * 2 - 1] += length;
                        return;
                    }

                    if (_rxHoles.Length == n * 2)
                        Array.Resize(ref _rxHoles, n * 4);
                    _rxHoles[n * 2] = at;
                    _rxHoles[n * 2 + 1] = length;
                    _rxHoleCount = n + 1;
                }

                ///<summary>Starts staging a region: no holes, no ABORT seen yet.</summary>
                void stage()
                {
                    _rxHoleCount = _rxHoleBytes = 0;
                    _rxAbort = false;
                }

                ///<summary>
                ///No live target for the current packet (<see cref="OutboundSrc.outbound"/> returned null): consume its chunked
                ///body up to the terminating <c>[0]</c> and forward nothing. A dropped packet is never promoted, so all of its
                ///body keeps arriving here through <see cref="__put_bytes"/>.
                ///</summary>
                bool drop(Receiver src, byte[] b, int pos, int end)
                {
                    while (_overGot < _overread) //body bytes over-read into the id come first
                    {
                        _lead[0] = (byte)((uint)_outId >> ((_idBytes + _overGot++) * 8));
                        if (0 <= scan(_lead, 0, 1, -1))
                            return dropped(src, pos);
                    }

                    var eos = scan(b, pos, end, -1);
                    if (eos < 0)
                    {
                        src.byte_ = end; //the whole buffer is body → consumed, continue with the next one
                        return false;
                    }

                    return dropped(src, eos);
                }

                bool dropped(Receiver src, int pos)
                {
                    _drop = false;
                    src.byte_ = pos;
                    src.slot.dst = null; //tunneling relay: never actor traffic → skip OnReceived
                    return true;
                }

                //--- Receive side ---------------------------------------------------------------------

                ///<summary>First-entry: the deserializer dispatches the first body bytes here. Decides
                ///copy (single-buffer) vs promote-to-swap (multi-buffer).</summary>
                public bool __put_bytes(Receiver src)
                {
                    if (_aborted)
                    {
                        src.byte_ = src.byte_max; //torn down → discard the rest of the body
                        return true;
                    }

                    var b = src.buffer!;
                    //Enqueue gate: hold the NEW packet while the previous outbound pack is queued/in flight.
                    if (!_rxStaged && !_outboundResolved && _enqueued)
                        return false;

                    //Read AFTER the gate: Close(Transmitter) raises it before releasing the gate, so a packet that got
                    //through can never be the lost one mistaken for a fresh start.
                    if (_outboundLost)
                    {
                        _outboundLost = false;
                        discardSlot(); //the dead transmit will never take it
                        if (_rxStaged) //a region already scanned but not published: account for it as its publish would have
                        {
                            _rxStaged = false;
                            _rxBuf = _rxSwapBuf = null;
                            if (_rxLast)
                                return dropped(src, src.byte_ + _rxTake); //it was the packet's end
                            src.byte_ += _rxTake;
                            _drop = true;
                        }
                        else if (_outboundResolved) //the lost packet is still arriving
                            _drop = true;
                    }

                    if (!_rxStaged)
                    {
                        var pos = src.byte_;
                        var end = src.byte_max;
                        //Phase 0 — parse tunnel_id (over-read region of _outId first, then the buffer; straddle-safe).
                        if (!_outboundResolved)
                        {
                            if (_tidGot == 0)
                            {
                                tunnel_id = 0;
                                _overGot = 0;
                                _overread = src.id_bytes - _idBytes;
                            }

                            while (_tidGot < _tidBytes)
                            {
                                int v;
                                if (_overGot < _overread)
                                    v = (int)(((uint)_outId >> ((_idBytes + _overGot++) * 8)) & 0xFF);
                                else if (pos < end)
                                    v = b[pos++];
                                else
                                    break;
                                tunnel_id |= v << (8 * _tidGot++);
                            }

                            src.byte_ = pos;
                            if (_tidGot < _tidBytes)
                                return false; //tunnel_id straddles → resume on the next input
                            //tunnel_id complete → route. The callback may rewrite tunnel_id; it either enqueues us (sending_put) on
                            //the connection it returns, or returns null when there is no live target — then this packet is dropped.
                            _outboundResolved = true;
                            _seq = (_seq + 1) & int.MaxValue; //a new packet: a _lostSeq still around belongs to an older one; never -1
                            _enqueued = true;                 //before outbound()/sending_put → visible to the transmit dequeue
                            Outbound = _outboundSrc.outbound(this, tunnel_id)!;
                            if (Outbound == null)
                            {
                                _enqueued = false; //nothing was queued → no OnSerialized will ever release the gate
                                _drop = true;      //consume this packet's body up to its [0], forward nothing
                            }
                            else if (tunnel_id != _lastTid || _fed == 0)
                                fed(tunnel_id); //a packet of the tunnel before it: one compare
                        }

                        if (_drop)
                            return drop(src, b, pos, end);

                        stage();
                        //Over-read body bytes (front of the chunked body pulled into _outId) are isolated into _rxWork and
                        //prepended to the available inbound bytes, then scanned/staged from _rxWork.
                        var leadBody = _overread - _overGot;
                        if (leadBody > 0)
                        {
                            _rxWork ??= ArrayPool<byte>.Shared.Rent(Math.Max(b.Length, 256));
                            for (var k = 0; k < leadBody; k++)
                                _rxWork[k] = (byte)((uint)_outId >> ((_idBytes + _overGot + k) * 8));
                            _overGot += leadBody;

                            var copyB = Math.Min(end - pos, _rxWork.Length - leadBody); //inbound bytes appended after the lead
                            Array.Copy(b, pos, _rxWork, leadBody, copyB);
                            var total = leadBody + copyB;

                            var eos = scan(_rxWork, 0, total, 0); //scan [lead | inbound] in the scratch
                            _rxBuf = _rxWork;
                            _rxOff = 0;
                            _rxSwap = 0;
                            _rxSwapBuf = null;
                            if (eos < 0) //no EOS yet → forward [lead | inbound] as one non-final region
                            {
                                _rxLen = total;
                                _rxLast = false;
                                _rxTake = copyB;
                            }
                            else //EOS within [lead | inbound]
                            {
                                _rxLen = eos;
                                _rxLast = true;
                                var fromB = eos - leadBody; //inbound bytes consumed up to EOS (lead bytes never came from b)
                                if (fromB < 0)
                                    fromB = 0;
                                _rxTake = fromB;
                            }

                            _rxStaged = true;
                        }
                        else
                        {
                            if (pos == end)
                                return false; //body begins in the next buffer

                            //Produce a region into the _rx staging fields. _rxWork = free work buffer (scratch / swap-in).
                            _rxWork ??= ArrayPool<byte>.Shared.Rent(b.Length);
                            var eos = scan(b, pos, end, pos);
                            if (eos < 0 && Inbound.canSwapReceive) //no EOS → large packet → PROMOTE: hand b to the slot, swap _rxWork in as receive buffer
                            {
                                _rxBuf = b;
                                _rxOff = pos;
                                _rxLen = end - pos;
                                _rxLast = false;
                                _rxSwap = 1;
                                _rxSwapBuf = _rxWork;
                                _rxTake = end - pos;
                            }
                            else //copy the region into _rxWork (scratch); the deserializer keeps b. Its end, or b cannot be taken over.
                            {
                                var bodyLen = eos < 0 ? end - pos : eos - pos;
                                if (_rxWork.Length < bodyLen) //too small → return the old scratch first (solely owned here: pre-publish, not shared/swapped)
                                {
                                    ArrayPool<byte>.Shared.Return(_rxWork);
                                    _rxWork = ArrayPool<byte>.Shared.Rent(Math.Max(b.Length, bodyLen));
                                }

                                Array.Copy(b, pos, _rxWork, 0, bodyLen);
                                _rxBuf = _rxWork;
                                _rxOff = 0;
                                _rxLen = bodyLen;
                                _rxLast = 0 <= eos;
                                _rxSwap = 0;
                                _rxSwapBuf = null;
                                _rxTake = bodyLen;
                            }

                            _rxStaged = true;
                        }
                    }

                    //Publish (receive lock site #1). Locked OR slot full ⇒ park + re-drive the transmit (wake-on-defer).
                    if (!publish())
                    {
                        Outbound?.WakeTransmit();
                        return false;
                    }

                    //Published → finalize once: consume FIRST, then rotate the receive buffer, then wake the transmit.
                    _rxStaged = false;
                    src.byte_ += _rxTake;
                    finalizeSwap();
                    var done = _rxSwap != 0 || _rxLast;
                    if (done)
                        src.slot.dst = null; //tunneling relay: never actor traffic → skip OnReceived
                    Outbound?.WakeTransmit();
                    return done; //false ⇒ non-final region forwarded → keep this relay as the slot dst
                }

                ///<summary>Steady-state (after promotion): every inbound buffer arrives here.</summary>
                public int Write(byte[] src, int src_byte, int src_bytes)
                {
                    if (_aborted)
                        return src_bytes;
                    var end = src_byte + src_bytes;
                    if (_outboundLost) //only an unfinished packet is served here, so the lost one is still arriving
                    {
                        _outboundLost = false;
                        discardSlot(); //the dead transmit will never take it
                        _drop = true;
                        if (_rxStaged) //a region already scanned but not published: account for it as its finalize would have
                        {
                            _rxStaged = false;
                            _rxBuf = _rxSwapBuf = null;
                            if (!_rxLast)
                                return _rxRet; //all of it was body: consumed, src stays the receive buffer
                            _drop = false;
                            Inbound.swapReceive(null, src); //it held the end: restore id-dispatched receiving, src (with any trailing) stays
                            return _rxRet;
                        }
                    }

                    if (_drop)
                    {
                        var at = scan(src, src_byte, end, -1);
                        if (at < 0)
                            return src_bytes; //all body → consumed, keep dropping
                        _drop = false;
                        Inbound.swapReceive(null, src); //packet over: restore id-dispatched receiving, src (with any trailing) stays
                        return at - src_byte;
                    }

                    if (!_rxStaged)
                    {
                        stage();
                        _rxWork ??= ArrayPool<byte>.Shared.Rent(src.Length);
                        var eos = scan(src, src_byte, end, src_byte);
                        if (eos < 0) //no EOS → hand the whole region to the slot, swap _rxWork in, keep relaying
                        {
                            _rxBuf = src;
                            _rxOff = src_byte;
                            _rxLen = src_bytes;
                            _rxLast = false;
                            _rxSwap = 1;
                            _rxSwapBuf = _rxWork;
                            _rxRet = src_bytes;
                        }
                        else if (eos == end) //clean EOS at buffer end (no trailing): hold src, restore deserializer into _rxWork
                        {
                            _rxBuf = src;
                            _rxOff = src_byte;
                            _rxLen = eos - src_byte;
                            _rxLast = true;
                            _rxSwap = 2;
                            _rxSwapBuf = _rxWork;
                            _rxRet = src_bytes;
                        }
                        else //EOS mid-buffer: copy body into _rxWork (scratch); src (with the trailing) stays the receive buffer
                        {
                            var bodyLen = eos - src_byte;
                            if (_rxWork.Length < bodyLen) //too small → return the old scratch first (solely owned here: pre-publish, not shared/swapped)
                            {
                                ArrayPool<byte>.Shared.Return(_rxWork);
                                _rxWork = ArrayPool<byte>.Shared.Rent(Math.Max(src.Length, bodyLen));
                            }

                            Array.Copy(src, src_byte, _rxWork, 0, bodyLen);
                            _rxBuf = _rxWork;
                            _rxOff = 0;
                            _rxLen = bodyLen;
                            _rxLast = true;
                            _rxSwap = 3;
                            _rxSwapBuf = src;
                            _rxRet = eos - src_byte; //consume up to eos; transport stashes the trailing
                        }

                        _rxStaged = true;
                    }

                    //Publish (receive lock site #1). Locked OR slot full ⇒ park (return 0) + re-drive the transmit.
                    if (!publish())
                    {
                        Outbound?.WakeTransmit();
                        return 0;
                    }

                    _rxStaged = false;
                    finalizeSwap();
                    Outbound?.WakeTransmit();
                    return _rxRet;
                }

                //RECEIVE lock site #1: publish the staged _rx region into the shared slot and grab a free buffer for next work.
                bool publish()
                {
                    if (Interlocked.CompareExchange(ref _lock, 1, 0) != 0)
                        return false; //lost CAS → defer (no spin)
                    if (_sBuf != null)
                    {
                        Volatile.Write(ref _lock, 0);
                        return false;
                    } //slot full → release & defer

                    _sBuf = _rxBuf;
                    _sOff = _rxOff;
                    _sLen = _rxLen;
                    _sPayload = _rxLen - _rxHoleBytes;
                    (_sHoles, _rxHoles) = (_rxHoles, _sHoles); //the slot was empty: its array is free for the next staging
                    _sHoleCount = _rxHoleCount;
                    _sLast = _rxLast;
                    _sAbort = _rxAbort;
                    _sTid = tunnel_id;
                    var nextWork = _free;
                    _free = null;
                    Volatile.Write(ref _lock, 0);
                    _rxWork = nextWork; //may be null → allocated on the next produce
                    return true;
                }

                //TRANSMIT lock site #2: take the slot region into _tx and hand the previously-drained buffer back to _free.
                bool take()
                {
                    if (Interlocked.CompareExchange(ref _lock, 1, 0) != 0)
                        return false; //lost CAS → defer (no spin)
                    if (_sBuf == null)
                    {
                        Volatile.Write(ref _lock, 0);
                        return false;
                    } //slot empty → release & defer

                    _txBuf = _sBuf;
                    _txOff = _sOff;
                    _txLen = _sLen;
                    _txPayload = _sPayload;
                    (_txHoles, _sHoles) = (_sHoles, _txHoles); //the previous region is done: its array goes back to the slot
                    _txHoleCount = _sHoleCount;
                    _txLast = _sLast;
                    _txAbort = _sAbort;
                    _txTid = _sTid;
                    _txOutId = _outId;
                    _txIdBytes = _idBytes;
                    _txTidBytes = _tidBytes;
                    _sBuf = null;
                    _free = _txDrained;
                    _txDrained = null; //return the previously-drained buffer for the receive to reuse
                    Volatile.Write(ref _lock, 0);
                    _txRel = 0;
                    _txHoleAt = 0;
                    _txChunkLeft = 0;
                    return true;
                }

                //Receive-side finalize after a successful publish(): rotate the receive buffer per the staged plan.
                void finalizeSwap()
                {
                    if (_rxSwap == 1)
                        Inbound.swapReceive(this, _rxSwapBuf!);
                    else if (_rxSwap == 2)
                        Inbound.swapReceive(null, _rxSwapBuf!);
                    else if (_rxSwap == 3)
                        Inbound.swapReceive(null, _rxSwapBuf!);
                }

                //--- Transmit side --------------------------------------------------------------------

                ///<summary>
                ///Drives this instance as its own outbound <see cref="Transmitter.IDataPass"/>: the <c>[id][tunnel_id]</c>
                ///prefix once, then every region as one chunk of its own (split only past <see cref="Transmitter.Chunked.MAX"/>),
                ///then <c>[0]</c> — or <see cref="Transmitter.Chunked.ABORT"/> when the source vanished. Returns <c>false</c> to
                ///park (buffer full, or no region yet) and <c>true</c> once the terminator is written.
                ///</summary>
                public bool __get_bytes(Transmitter dst)
                {
                    if (_aborted)
                        return true; //torn down → retire this outbound pack so the transmitter resumes its own queue
                    var outBuf = dst.buffer!;
                    for (;;)
                        switch (_txState)
                        {
                            case TX_BETWEEN:
                                //No region in hand, so no chunk open: the one place a vanished source is acted upon. A chunk once
                                //begun is always finished first — its bytes are all in memory — so the peer is never left inside one.
                                if (_lostSeq == _seq)
                                {
                                    _lostSeq = -1;
                                    discardSlot(); //a region published for the lost packet: the packet ends here
                                    if (!_prefixDone)
                                        return retire(dst); //nothing of it reached the wire: it simply vanishes
                                    _txEnd = Transmitter.Chunked.ABORT;
                                    _txState = TX_END;
                                    continue;
                                }

                                if (!take()) //locked (receive holds it) OR slot empty ⇒ park
                                {
                                    Inbound?.WakeReceive(); //re-drive the receive: if it lost the CAS to us it must retry publish()
                                    return false;
                                }

                                Inbound?.WakeReceive(); //took a region: slot emptied + a buffer handed back → the receive can produce
                                _txState = _prefixDone ? TX_REGION : TX_PREFIX;
                                continue;

                            case TX_PREFIX: //emit [pure id][tunnel_id] once, from the take()-snapshotted route
                                if (dst.byte_max - dst.byte_ < _txIdBytes + _txTidBytes)
                                    return false; //flush, resume with room (the taken region waits in _txBuf)
                                dst.put_val((ulong)(uint)_txOutId, _txIdBytes);
                                if (_txTidBytes > 0)
                                    dst.put_val((ulong)(uint)_txTid, _txTidBytes);
                                _prefixDone = true;
                                _txState = TX_REGION;
                                continue;

                            case TX_REGION:
                                if (_txChunkLeft == 0)
                                {
                                    if (_txPayload == 0) //the region is written (a region of framing only writes nothing — an empty chunk would read as the end)
                                    {
                                        _txDrained = _txBuf; //hand this buffer back to the receive at the NEXT take()
                                        _txBuf = null;
                                        if (_txLast)
                                        {
                                            _txEnd = _txAbort ? Transmitter.Chunked.ABORT : 0;
                                            _txState = TX_END;
                                        }
                                        else
                                            _txState = TX_BETWEEN;

                                        continue;
                                    }

                                    if (dst.byte_max - dst.byte_ < PREFIX_BYTES + 1)
                                        return false; //room for our chunk header and at least one byte of it
                                    _txChunkLeft = Math.Min(_txPayload, Transmitter.Chunked.MAX);
                                    dst.put_val((ulong)_txChunkLeft, PREFIX_BYTES);
                                }

                                while (0 < _txChunkLeft) //copy payload, stepping over the source's framing
                                {
                                    if (dst.byte_max <= dst.byte_)
                                        return false; //outbound buffer full → flush, resume on next turn
                                    while (_txHoleAt < _txHoleCount && _txHoles[_txHoleAt * 2] == _txRel)
                                        _txRel += _txHoles[_txHoleAt++ * 2 + 1];
                                    var stop = _txHoleAt < _txHoleCount ? _txHoles[_txHoleAt * 2] : _txLen;
                                    var n = Math.Min(Math.Min(stop - _txRel, _txChunkLeft), dst.byte_max - dst.byte_);
                                    Array.Copy(_txBuf!, _txOff + _txRel, outBuf, dst.byte_, n);
                                    dst.byte_ += n;
                                    _txRel += n;
                                    _txChunkLeft -= n;
                                    _txPayload -= n;
                                }

                                continue;

                            default: //TX_END: [0] ends the packet, ABORT ends it as void
                                if (dst.byte_max - dst.byte_ < PREFIX_BYTES)
                                    return false;
                                dst.put_val((ulong)_txEnd, PREFIX_BYTES);
                                return retire(dst);
                        }
                }

                ///<summary>Retires this outbound pack: the transmitter then runs <see cref="OnSerialized"/>, which opens the gate.</summary>
                bool retire(Transmitter dst)
                {
                    _txState = TX_BETWEEN;
                    dst.slot!.src = null; //tunneling relay: never actor traffic → skip the transmitter's pack-level handling
                    return true;
                }

                ///<summary>Unused in the copy relay (the body is copied through <see cref="__get_bytes"/> into the outbound
                ///transmitter's own buffer). Retained only to satisfy <see cref="Transmitter.BytesSrc"/>.</summary>
                public int Read(byte[] dst, int dst_byte, int dst_bytes) => _aborted ? -1 : 0;

                //--- Lifecycle (channel interfaces) ---------------------------------------------------

                public bool isOpen() => !_aborted;

                public void Close()
                {
                    _aborted = true;
                    Outbound?.WakeTransmit(); //resolved lazily by outbound(); may be null before the first packet
                    Inbound?.WakeReceive();
                }
            }

            ///<summary>
            ///Tunnel-endpoint bridge base: the virtual <see cref="Connection.External"/> a virtual connection (vconn) is
            ///built on (<see cref="Internal"/> == vconn), enqueued on the physical transmitter as its own
            ///<see cref="Transmitter.IDataPass"/>. A concrete subclass supplies <see cref="WakeTransmit"/> (enqueue a
            ///fresh outbound burst once per burst) and <see cref="OnSerializing"/> (resolve the
            ///<see cref="Transmitter.BytesSrc"/> that gets serialized — normally a tunnel-armed
            ///<see cref="Transmitter.Chunked"/> over this endpoint's outbound bytes). <see cref="inUse"/> is the
            ///single-enqueue gate, cleared by <see cref="OnSerialized"/> / <see cref="Close(Transmitter)"/>.
            ///</summary>
            public abstract class EndPoint : External, Transmitter.IDataPass
            {
                public int tunnel_id;          //this endpoint's tunnel_id — also what Id and the framing prefix use
                protected Internal? _internal; //underscore-prefixed: `internal` is a C# keyword. Exposed as the Internal property below
                protected int receiveTimeout = int.MaxValue;
                protected int transmitTimeout = int.MaxValue;
                protected int inUse; //1 - an outbound pack is queued / in flight for this endpoint: taken by Interlocked.Exchange, two wakes at once queue one burst

                ///<summary>A wake came: the burst armed after it ( <see cref="farewell"/> ) takes what is queued, the one out
                ///before it asks for the next ( <see cref="OnSerialized"/> ). The generated WakeTransmit writes it before it
                ///takes the gate, the burst that ends opens the gate before it looks at it: a pack queued as the burst ended
                ///is never left without one ( Rust <c>wanted</c> ).</summary>
                protected volatile bool wanted;

                //The External surface below is nothing but properties over the protected backing fields above, so a
                //subclass may read and write exactly the same state directly.
                //A tunnel endpoint owns no slot in a host registry.
                public int index() => 0;

                //On a virtual link the tunnel id is the identity of the far end, and the framing prefix reads
                //the same field.
                public int id
                {
                    get => tunnel_id;
                    set => tunnel_id = value;
                }

                //Negative while the tunnel closes; a negative one set keeps its magnitude and closes the tunnel, what is queued first.
                public int ReceiveTimeout
                {
                    get => closing ? -receiveTimeout : receiveTimeout;
                    set {
                        receiveTimeout = value < 0 ? (value == int.MinValue? int.MaxValue: -value) : value;
                        if (value < 0)
                            Close();
                    }
                }

                public int TransmitTimeout
                {
                    get => closing ? -transmitTimeout : transmitTimeout;
                    set {
                        transmitTimeout = value < 0 ? (value == int.MinValue? int.MaxValue: -value) : value;
                        if (value < 0)
                            Close();
                    }
                }

                ///<summary><see cref="Close()"/> was called: the next burst ends the tunnel - the packs queued by then, and
                ///<see cref="Transmitter.Chunked.ABORT"/> in place of the terminator. The peer's end closes on it.</summary>
                protected volatile bool closing;

                ///<summary>The burst being serialized is the one that ends the tunnel: see <see cref="farewell"/>.</summary>
                protected bool farewell_;

                ///<summary>Called by the generated <c>OnSerializing</c> as it arms a burst: whether the burst ends the tunnel.</summary>
                protected bool farewell()
                {
                    wanted = false; //the burst armed now takes what the wakes before it asked for
                    return farewell_ = closing;
                }

                ///<summary>1 - the virtual connection was told the tunnel ended ( <see cref="closed"/> ).</summary>
                int ended;

                public bool IsOpen => !closing;

                ///<summary>Ends the tunnel: what is queued goes first, then the peer is told and this end closes - its
                ///<c>OnExternalEvent(THIS_CLOSE_GRACEFUL)</c> and <c>OnClose()</c> come when the last burst is serialized.
                ///From any thread.</summary>
                public void Close()
                {
                    if (closing)
                        return;
                    closing = true;
                    WakeTransmit();
                }

                ///<summary>A tunnel has nothing to cut short: the same as <see cref="Close()"/>.</summary>
                public void Abort() => Close();

                public Internal Internal
                {
                    get => _internal!;
                    set => _internal = value;
                }

                ///<summary>Enqueue this endpoint on the physical transmitter (once) so its turn pulls
                ///<see cref="OnSerializing"/>. Application/transport-specific.</summary>
                public abstract void WakeTransmit();

                ///<summary>Called when this endpoint is dequeued for serialization: return the
                ///<see cref="Transmitter.BytesSrc"/> to serialize (normally a tunnel-armed
                ///<see cref="Transmitter.Chunked"/>), or <c>null</c> to skip this turn.</summary>
                public abstract Transmitter.BytesSrc? OnSerializing(Transmitter transmitter);

                public virtual void OnSerialized(Transmitter transmitter, Transmitter.BytesSrc transmitted)
                {
                    Interlocked.Exchange(ref inUse, 0); //a full fence: the gate opens before the wish is looked at
                    var cut = transmitted is Transmitter.Chunked c && c._Adapter.cut;
                    if (cut)
                        ((Transmitter.Chunked)transmitted)._Adapter.cut = false;
                    if (farewell_)
                    {
                        farewell_ = false;
                        closed(Network.TCP.ExternalConnection.Event.THIS_CLOSE_GRACEFUL);
                    }
                    else if (closing || cut || wanted)
                        WakeTransmit(); //Close() came while a burst was in flight, or the burst carried its share, or a pack came while it was out: the next one, behind the other tunnels
                }

                ///<summary>The tunnel started: <paramref name="remote"/> - its first frame came from the far end, else this side
                ///opened it. The virtual connection hears the connect event as on a socket - <c>REMOTE_CONNECT</c> /
                ///<c>THIS_CONNECT</c>, then <c>OnOpen()</c>: between two hosts of one type it takes by it the half of the instance
                ///ids that is its own, the side that opened the tunnel is the left one. The mirror of <see cref="closed"/>.</summary>
                public void connected(bool remote)
                {
                    if (_internal == null)
                        return;
                    _internal.OnExternalEvent(this, remote ? Network.TCP.ExternalConnection.Event.REMOTE_CONNECT : Network.TCP.ExternalConnection.Event.THIS_CONNECT);
                    _internal.OnOpen();
                }

                ///<summary>The tunnel ended - this side's <see cref="Close()"/> was serialized, or the peer's end arrived
                ///(<see cref="Receiver.Chunked.Ends"/>). The generated endpoint tells the virtual connection and lets its carrier
                ///forget it.</summary>
                protected internal virtual void closed(Network.TCP.ExternalConnection.Event e)
                {
                    closing = true; //no burst after this one: IsOpen is false
                    if (_internal == null || Interlocked.Exchange(ref ended, 1) != 0)
                        return; //once: the far end's end and the last burst of this one may both come

                    _internal.OnExternalEvent(this, e);
                    _internal.OnClose();
                }

                ///<summary>
                ///The physical link died while this endpoint's burst was queued or in flight on it. What the burst had
                ///already framed is gone with the link, and the peer abandons the virtual connection's partial pack (its
                ///receiver resets with the link). The pack still in flight on <see cref="Internal"/>'s transmitter is
                ///therefore dropped too — see <see cref="Transmitter.Abandon"/> — so the next burst starts at a pack
                ///boundary. A burst ends only between packs, so a burst that was merely queued finds nothing to drop.
                ///Dropped BEFORE the gate opens: a wake that slips in afterwards may start a burst at once.
                ///</summary>
                public virtual void Close(Transmitter transmitter)
                {
                    (_internal?.BytesSrc as Transmitter)?.Abandon();
                    Volatile.Write(ref inUse, 0);
                }

                public EndPoint Init(int tunnel_id)
                {
                    this.tunnel_id = tunnel_id; //single source of truth — also what Id and the framing prefix use
                    return this;
                }
            }
        }
    }

    ///<summary>
    ///Transform-chain LEAF for a <c>string</c> field in the <c>AdHoc.varint</c> text codec — the PREFIX-LESS
    ///<c>[varint characters…]</c> wire that <see cref="Connection.Transmitter.put_str"/> and
    ///<see cref="Connection.Receiver.try_get_str"/> produce: no character count, the string simply ends WITH
    ///the enclosing stream (the chain's framer sees the terminator and finalizes the reception in its
    ///<c>[0]</c>-terminator branch). Emitted/consumed INSIDE a chain: <c>leaf → stages → chunked root</c>.
    ///Embed it with the machinery every chain leaf uses — <c>datatype(chain_id, leaf, next_case)</c> — exactly
    ///as a pack-typed leaf embeds itself.
    ///<para>
    ///Truly STATELESS — <see cref="ONE"/> serves every connection and every field concurrently, because every piece
    ///of working state already lives in the machine driving it. A park inside <c>put_str</c>/<c>try_get_str</c> is
    ///completed BY THIS LEAF (the parked-resume branch inlines the <c>case STR</c>/<c>case STR_RAW</c> body),
    ///because inside a chain the delivery can reach the leaf directly, bypassing the mode dispatcher — whose
    ///<c>case STR</c>/<c>case STR_RAW</c>/<c>case STR_UTF8</c>
    ///therefore SKIP a leaf park (<c>slot.state == (uint)bit</c>) so the same bytes are never processed twice.
    ///The per-use inputs ride machine registers that are otherwise
    ///idle for the whole span of a string transfer:
    ///<list type="bullet">
    ///<item>TRANSMIT — the source string is staged in <see cref="str"/> by <see cref="Connection.Transmitter.put(string,bool,uint)"/>;
    ///content produced in pieces streams fragment-by-fragment via <see cref="Connection.Transmitter.strs"/>
    ///(the fragments concatenate on the wire into ONE string — bit-identical to sending the pre-concatenated whole).</item>
    ///<item>RECEIVE — the character ceiling (<c>[D(+N)]</c>) is staged in <see cref="bits"/> by
    ///<see cref="Connection.Receiver.try_get_string(uint,bool,int)"/>; the decoded string is left in <see cref="str"/>, where the
    ///field's code collects it with <see cref="Connection.Receiver.get_string"/> after the chain completes.</item>
    ///</list>
    ///</para>
    ///<para>
    ///<b>Park discriminator.</b> The field's own retry case rides <see cref="bit"/> as its COMPLEMENT
    ///(<c>bit == ~get_string_case</c>): seeded by the stagers and re-seeded by EVERY string primitive at entry —
    ///plain fields included — so it is never stale. A plain field's park therefore always leaves
    ///<c>slot.state == case</c> with <c>bit == ~case</c> (never equal); only this leaf's FIRST park flips the pair
    ///into lock-step (the primitive's park stamps <c>slot.state = case</c>; the leaf then just flips
    ///<c>bit = ~bit</c>), making <c>slot.state == (uint)bit</c> hold exactly
    ///while a chain-leaf string park is in flight — a collision-free test, since a case value is unique within its
    ///pack's switch and a chain REUSES the slot it was armed on (the leaf cannot assume a zeroed state).
    ///</para>
    ///<para>
    ///These leaves may stay SINGLETONS for one reason: a string leaf is only ever a chain leaf, identified by the
    ///FIELD that armed it, so it never has to answer <c>__id</c> with a real value. A leaf that can be a TOP-LEVEL
    ///pack does have to, and no shared instance can — such a leaf must be a per-arming instance. A byte-stream leaf
    ///also needs no park discriminator at all: it parks without setting <see cref="mode"/>, so it never reaches
    ///those dispatcher arms.
    ///</para>
    ///</summary>
    public sealed class StringStream : Connection.Receiver.BytesDst, Connection.Transmitter.BytesSrc
    {
        ///<summary>The shared instance — the class carries no state, so one is all there ever is.</summary>
        public static readonly StringStream ONE = new();

        StringStream() {}

        ///<summary>Id-less: a chain leaf is identified by the FIELD that armed the chain, never dispatched by id.</summary>
        public int __id => int.MinValue;

        public bool __put_bytes(Connection.Receiver src)
        {
            if (src.slot!.state == (uint)src.bit)
                //parked resume — in a chain the delivery can reach this leaf directly, bypassing the receiver's
                //mode dispatcher (whose case STR_RAW SKIPS this park — see there). getting_str_raw goes on with
                //the ASCII kept in bys or the split-char state from u8 / bytes_left and, with no count, never
                //self-completes: the string ends WITH the stream, finalized by the framer's [0]-terminator branch
                //(see Chunked).
                return src.getting_str_raw();

            //First entry — no park yet (bit == ~case, seeded by the try_get_string(max_chars, utf, case) stager).
            src.try_get_str(src.bits, ~src.bit); //always parks: a prefix-less string ends only with the stream
            src.bit = ~src.bit;                  //park → flip: try_get_str's park already stamped slot.state = case, so from here on slot.state == (uint)bit
            return false;
        }

        public bool __get_bytes(Connection.Transmitter dst)
        {
            if (dst.slot!.state != (uint)dst.bit) //first entry — no park yet (bit == ~case, seeded by the put(src, utf, case) stager)
            {
                if (!dst.put_str(dst.str!, (uint)~dst.bit))
                {
                    dst.bit = ~dst.bit; //park → flip: put_str's park already stamped slot.state = case, so from here on slot.state == (uint)bit
                    return false;
                }
            }
            else
            { //Parked resume — the case STR body runs HERE (the transmitter's mode dispatcher SKIPS this park).
                //No length phase on this wire: the pending varint is always a (partial) character.
                if (!dst.varint())
                    return false;

                if (!dst.put_chars(dst.str!, dst.slot.state, dst.u4)) //the rest the fast way: a long string spans many buffers
                    return false;
            }

            //The current fragment is out. Streaming content produced in pieces? Pull fragment after fragment
            //from the supplier — they concatenate ON THE WIRE (no prefix, no separator: just more characters
            //of the SAME string). A park inside put_str stamps slot.state = the passed case and the flip locks
            //slot.state == (uint)bit again, so the resume lands in the parked branch above and, once the
            //fragment completes, falls back into this pull loop.
            if (dst.strs != null)
            {
                for (string? s; (s = dst.strs()) != null;)
                    if (!dst.put_str(s, (uint)~dst.bit))
                    {
                        dst.bit = ~dst.bit; //park → flip — same lock-step as above
                        return false;
                    }

                dst.strs = null; //drained — the wire string ends with this fragment
            }

            dst.str = null; //release the staged source
            return true;
        }
    }

    ///<summary>
    ///The <see cref="StringStream"/> leaf over <b>UTF-8</b>: the PREFIX-LESS <c>[UTF-8 bytes]</c> wire —
    ///exactly what <see cref="Connection.Transmitter.put_utf"/> and <see cref="Connection.Receiver.try_get_utf"/>
    ///produce: no character count, the string simply ends WITH the enclosing stream (the chain's framer sees
    ///the terminator and finalizes the reception in its <c>[0]</c>-terminator branch). Emitted/consumed INSIDE
    ///a chain (the <c>[Zstd] ToStream&lt;E, string&gt;</c> case: the UTF-8 leaf is compressed under the chunked
    ///root on the streamed path). Same stateless singleton contract and the same register staging as
    ///<see cref="StringStream"/> — see there for the mechanics.
    ///<para>
    ///The codec's contract carries over unchanged: the TRANSMIT side does not validate — well-formed UTF-16
    ///(no unpaired surrogates) is the caller's obligation, see <c>put_utf</c>'s CONTRACT; malformed UTF-8 on
    ///the receive side is reported through <c>error_handler</c> as <c>OnError.BYTES_DISTORTION</c> with U+FFFD
    ///substituted — decoding stays deterministic and always terminates at the stream's end.
    ///</para>
    ///</summary>
    public sealed class UTFStream : Connection.Receiver.BytesDst, Connection.Transmitter.BytesSrc
    {
        ///<summary>The shared instance — the class carries no state, so one is all there ever is.</summary>
        public static readonly UTFStream ONE = new();

        UTFStream() {}

        ///<summary>Id-less: a chain leaf is identified by the FIELD that armed the chain, never dispatched by id.</summary>
        public int __id => int.MinValue;

        public bool __put_bytes(Connection.Receiver src)
        {
            if (src.slot!.state == (uint)src.bit)
                //parked resume — in a chain the delivery can reach this leaf directly, bypassing the receiver's
                //mode dispatcher (whose case STR_UTF8 SKIPS this park — see there). getting_string_utf resumes
                //its own mid-sequence state from u8 / bytes_left and never self-completes: the string ends WITH
                //the stream, finalized by the framer's [0]-terminator branch (see Chunked).
                return src.getting_string_utf();

            //First entry — no park yet (bit == ~case, seeded by the try_get_string(max_chars, utf, case) stager).
            src.try_get_utf(src.bits, ~src.bit); //always parks: a prefix-less string ends only with the stream
            src.bit = ~src.bit;                  //park → flip: try_get_utf's park already stamped slot.state = case, so from here on slot.state == (uint)bit
            return false;
        }

        public bool __get_bytes(Connection.Transmitter dst)
        {
            if (dst.slot!.state != (uint)dst.bit) //first entry — no park yet (bit == ~case, seeded by the put(src, utf, case) stager)
            {
                if (!dst.put_utf(dst.str!, (uint)~dst.bit))
                {
                    dst.bit = ~dst.bit; //park → flip: put_utf's park already stamped slot.state = case, so from here on slot.state == (uint)bit
                    return false;
                }
            }
            else
            { //Parked resume — the case STR_UTF8 body runs HERE (the transmitter's mode dispatcher SKIPS this park).
                //No length phase on this wire — a park always stages char-phase state (split-sequence bytes in
                //u8_ / bytes_left), which putting_utf resumes itself.
                if (!dst.putting_utf())
                    return false;
            }

            //The current fragment is out. Streaming content produced in pieces? Pull fragment after fragment
            //from the supplier — they concatenate ON THE WIRE (no prefix, no separator: just more UTF-8 bytes
            //of the SAME string). put_utf's CONTRACT applies to EACH fragment: well-formed UTF-16, a surrogate
            //pair never split across fragments. Park/flip keeps slot.state == (uint)bit, so the resume lands in
            //the parked branch above and, once the fragment completes, falls back into this pull loop.
            if (dst.strs != null)
            {
                for (string? s; (s = dst.strs()) != null;)
                    if (!dst.put_utf(s, (uint)~dst.bit))
                    {
                        dst.bit = ~dst.bit; //park → flip — same lock-step as above
                        return false;
                    }

                dst.strs = null; //drained — the wire string ends with this fragment
            }

            dst.str = null; //release the staged source (put_utf already cleared it — kept for symmetry)
            return true;
        }
    }

    ///<summary>
    ///The "mode" sentinels of the receive/transmit state machine. A primitive read or write is attempted
    ///directly against <see cref="buffer"/>; if the buffer runs out mid-value, the slot's state records the
    ///resume point and <see cref="mode"/> is set to one of these to record WHAT kind of value is half-assembled.
    ///On the next buffer fill the dispatcher picks the partial value back up. <see cref="OK"/> means "nothing
    ///pending — proceed to the next field"; <see cref="RETRY"/> is the generic "need more bytes, resume at the
    ///saved state". The values form a contiguous block from <see cref="OK"/> so the whole set stays clear of any
    ///real field index.
    ///</summary>
    internal const uint OK = int.MaxValue, //Idle / done: nothing mid-assembly; advance to the next field. Also the success return of a write.
        STR = OK - 100,                    //Mid-string: assembling a string (varint char count, then the characters).
        STR_UTF8 = STR - 1,                //Mid-string over UTF-8: assembling a string (varint char count, then the characters as raw UTF-8 bytes).
        RETRY = STR + 1,                   //Generic "need more bytes": resume the half-finished step at the slot's saved state.
        VAL4 = RETRY + 1,                  //Mid fixed 4-byte value: raw 32-bit payload (e.g. float / fixed int) gathered into u4.
        VAL8 = VAL4 + 1,                   //Mid fixed 8-byte value: raw 64-bit payload (e.g. double / fixed long) gathered into u8.
        INT1 = VAL8 + 1,                   //Mid 1-byte integer: one wire byte to be sign-extended into u8.
        INT2 = INT1 + 1,                   //Mid 2-byte integer: two wire bytes to be sign-extended into u8.
        INT4 = INT2 + 1,                   //Mid 4-byte integer: four wire bytes to be sign-extended into u8.
        LEN0 = INT4 + 1,                   //Mid collection length stored in 0 bytes (length fixed/implicit; no bytes read).
        LEN1 = LEN0 + 1,                   //Mid collection length stored in 1 byte.
        LEN2 = LEN1 + 1,                   //Mid collection length stored in 2 bytes.
        BITS = LEN2 + 1,                   //Mid bit-field: gathering packed bits into the `bits` accumulator.
        BITS_BYTES = BITS + 1,             //Mid bit-field followed by byte-aligned data (bits first, then bytes).
        VARINT = BITS_BYTES + 1,           //Mid Base_-128 varint: gathering a variable-length integer one continuation byte at a time.
        STREAM_PACK = VARINT + 1,          //Parked at a streamed-datatype boundary: the next drive routes into unpark() to re-frame the chained pack (see streaming_mode).
        STR_RAW = STREAM_PACK + 1,         //Mid PREFIX-LESS string: varint characters with no declared count — the string ends WITH the enclosing stream, finalized by the framer's [0]-terminator branch (see Receiver.Chunked).
        VAL16 = STR_RAW + 1,               //Mid fixed 16-byte value (Int128 / UInt128): the low 64 bits gathered into u8, the high 64 into u16.
        BITS_VAL16 = VAL16 + 1;            //Mid bit-field followed by a 16-byte value (Int128 / UInt128): the low 64 bits in u8, the high 64 in u16.

    ///<summary>
    ///Number of valid bits currently held in the <see cref="bits"/> accumulator (the bit cursor for packed
    ///bit-field reads/writes); ranges from 0 to 7.
    ///</summary>
    protected int bit;

    ///<summary>
    ///The string currently being assembled from the stream (receive) or fed to the stream (transmit).
    ///</summary>
    public string? str;

    ///<summary>
    ///Bit accumulator: packed bit-fields are shifted in/out here, <see cref="bit"/> bits at a time, before they
    ///spill to or from whole bytes in <see cref="buffer"/>.
    ///</summary>
    public uint bits;

    ///<summary>
    ///The single reusable working buffer through which all bytes flow. Its size, not the pack size, bounds
    ///resident memory; it is borrowed for the duration of a Read/Write call and released on return.
    ///</summary>
    public byte[]? buffer;

    ///<summary>
    ///Read/write cursor: index of the next byte to process in <see cref="buffer"/>.
    ///</summary>
    public int byte_;

    ///<summary>
    ///Exclusive upper bound for access into <see cref="buffer"/> — bytes <c>[<see cref="byte_"/>..<see cref="byte_max"/>)</c>
    ///are available this turn. See <see cref="remaining"/>.
    ///</summary>
    public int byte_max;

    ///<summary>
    ///The size of the window an abstract pack is handed for a one-byte array (see <see cref="window"/>). One at a time -
    ///the pack returns before the codec goes on - so one register is enough.
    ///</summary>
    protected int window_bytes;

    ///<summary>
    ///Opens a window of the buffer for up to <paramref name="bytes"/> bytes of a one-byte array - as many as the buffer
    ///holds (to receive) or takes (to send) now, from the cursor. An abstract pack reads or writes the span the way that
    ///suits it; the codec closes the window with <c>window_done</c>, which moves the cursor past it.
    ///</summary>
    public Span<byte> window(int bytes) => buffer!.AsSpan(byte_, window_bytes = Math.Min(bytes, remaining));

    ///<summary>Closes the window <see cref="window"/> opened: the cursor past it.</summary>
    ///<returns>the bytes the window held - the codec moves its index by them.</returns>
    protected int window_close()
    {
        byte_ += window_bytes;
        return window_bytes;
    }

    //`bytes` (1..8) little-endian bytes at `pos` as a ulong: one read while 8 bytes are in the array - the bytes past
    //`bytes` are masked off
    internal static ulong load(byte[] buf, int pos, int bytes)
    {
        if (pos + 8 <= buf.Length)
        {
            var v = System.Buffers.Binary.BinaryPrimitives.ReadUInt64LittleEndian(buf.AsSpan(pos));
            return bytes == 8 ? v : v & (1UL << (bytes << 3)) - 1;
        }

        var u = 0UL;
        for (var i = 0; i < bytes; i++)
            u |= (ulong)buf[pos + i] << (i << 3);
        return u;
    }

    //the `bytes` (1..8) lowest bytes of `v` little-endian at `pos`: one write while 8 bytes fit before `max` - the bytes
    //past `bytes` are behind the position the caller moves to, the stream overwrites them; nothing is written past `max`
    internal static void store(byte[] buf, int pos, ulong v, int bytes, int max)
    {
        if (pos + 8 <= max)
            System.Buffers.Binary.BinaryPrimitives.WriteUInt64LittleEndian(buf.AsSpan(pos), v);
        else
            for (var i = 0; i < bytes; i++, v >>= 8)
                buf[pos + i] = (byte)v;
    }

    ///<summary>The code of one bit item - already masked - as the item's type: what <c>get_bits&lt;T&gt;</c> gives for it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T bits_as<T>(ulong code)
    {
        var u = (uint)code;
        return Unsafe.As<uint, T>(ref u);
    }

    ///<summary>
    ///The state-machine sentinel describing what value, if any, is mid-assembly when the buffer drained.
    ///See the <see cref="OK"/>/<see cref="RETRY"/>/<see cref="VARINT"/>/… constants above.
    ///</summary>
    public uint mode;

    ///<summary>
    ///32-bit staging register: holds the value of a 4-byte read/write (and the running varint result) while it
    ///is assembled from or emitted to the buffer.
    ///</summary>
    internal uint u4;

    ///<summary>
    ///64-bit staging register: holds the value of an 8-byte read/write, the sign-extended INTn result, and
    ///varint accumulation.
    ///</summary>
    public ulong u8;

    ///<summary>
    ///Secondary 64-bit staging register, used when one operation needs two values in flight at once (e.g. a
    ///length/flag alongside the main value, or string-decode bookkeeping).
    ///</summary>
    public ulong u8_;

    ///<summary>
    ///High 64 bits of a 16-byte value (Int128 / UInt128) cut by the buffer end; the low 64 bits are in <see cref="u8"/>.
    ///</summary>
    public ulong u16;

    ///<summary>
    ///Running byte offset within the current pack/stream payload (used by streaming and copy hooks).
    ///</summary>
    public ulong stream_byte;

    ///<summary>
    ///Gets the value currently stored in the `u8` buffer, reinterpreted as type `T`.
    ///This is an unsafe cast and assumes `T` is compatible with an 8-byte representation.
    ///</summary>
    ///<typeparam name="T">The type to reinterpret the `u8` buffer as.</typeparam>
    ///<returns>The value from `u8` cast to type `T`.</returns>
    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    public T get8<T>() => Unsafe.As<ulong, T>(ref u8);

    ///<summary>Bytes still to transfer to finish the current multi-byte value (counts down as the buffer is consumed).</summary>
    int bytes_left;

    ///<summary>Total width in bytes of the current multi-byte value; with <see cref="bytes_left"/> it gives the byte offset already filled, so a resumed read shifts each byte into the right position.</summary>
    int bytes_max;

    ///<summary>
    ///Gets the number of bytes remaining in the `buffer` from the current `byte_` position to `byte_max`.
    ///</summary>
    public int remaining => byte_max - byte_;

    ///<summary>
    ///A UUID as the 128-bit number whose big-endian bytes are its RFC 9562 bytes: the high 64 bits are RFC bytes 0-7.
    ///On the wire it goes as that UInt128: 16 bytes little-endian, so wire byte 0 is RFC byte 15.
    ///<c>Guid.ToByteArray()</c> swaps the first three fields - not used.
    ///</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static UInt128 uuid(Guid src)
    {
        Span<byte> rfc = stackalloc byte[16];
        src.TryWriteBytes(rfc, true, out _);
        return BinaryPrimitives.ReadUInt128BigEndian(rfc);
    }

    ///<summary>The UUID whose RFC 9562 bytes are the big-endian bytes of <paramref name="src"/>, see <see cref="uuid(Guid)"/>.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static Guid uuid(UInt128 src)
    {
        Span<byte> rfc = stackalloc byte[16];
        BinaryPrimitives.WriteUInt128BigEndian(rfc, src);
        return new Guid(rfc, true);
    }

    ///<summary>
    ///The text of the fixed-point decimals of the generated <c>[Decimal(p, s)]</c> types and their bridge to <see cref="decimal"/>.
    ///A value is an integer of units 10^-scale within ±(10^p - 1): a <c>long</c> up to 18 digits, an <see cref="Int128"/> above.
    ///The text has exactly <c>scale</c> digits after the point, and no point at scale 0. Parsing is exact: an optional sign, digits,
    ///an optional point and digits; a nonzero digit past the scale, or a magnitude over <c>max</c>, is an error. No floating point;
    ///nothing is allocated but the <see cref="string"/> of <c>ToString</c> and an exception.
    ///</summary>
    public static class Decimal
    {
        ///<summary>The longest text: a sign, "0", the point and 38 digits.</summary>
        public const int MAX_CHARS = 41;

        //10^0 .. 10^19
        static readonly ulong[] POW10 = {
            1UL, 10UL, 100UL, 1_000UL, 10_000UL, 100_000UL, 1_000_000UL, 10_000_000UL, 100_000_000UL,
            1_000_000_000UL, 10_000_000_000UL, 100_000_000_000UL, 1_000_000_000_000UL, 10_000_000_000_000UL,
            100_000_000_000_000UL, 1_000_000_000_000_000UL, 10_000_000_000_000_000UL, 100_000_000_000_000_000UL,
            1_000_000_000_000_000_000UL, 10_000_000_000_000_000_000UL
        };

        //10^0 .. 10^38
        static readonly UInt128[] POW10_128 = pow10_128();

        static UInt128[] pow10_128()
        {
            var t = new UInt128[39];
            t[0] = 1;
            for (var i = 1; i < t.Length; i++)
                t[i] = t[i - 1] * 10;
            return t;
        }

        //the decimal digits of m right-aligned at the end of buf; returns their count
        static int digits(ulong m, Span<char> buf)
        {
            var i = buf.Length;
            do
            {
                var q = m / 10;
                buf[--i] = (char)('0' + (int)(m - q * 10));
                m = q;
            } while (m != 0);

            return buf.Length - i;
        }

        static int digits(UInt128 m, Span<char> buf)
        {
            var i = buf.Length;
            while (ulong.MaxValue < m) //19 digits at a time by one 128-bit division
            {
                var (q, r) = UInt128.DivRem(m, POW10[19]);
                var lo = (ulong)r;
                for (var k = 0; k < 19; k++)
                {
                    var t = lo / 10;
                    buf[--i] = (char)('0' + (int)(lo - t * 10));
                    lo = t;
                }

                m = q;
            }

            return buf.Length - i + digits((ulong)m, buf[..i]);
        }

        //the digits d of the magnitude laid out with the sign and the point
        static bool layout(ReadOnlySpan<char> d, bool neg, int scale, Span<char> dst, out int written)
        {
            int n = d.Length,
                f = n < scale ? n : scale, //the fraction digits d has
                whole = n - f,             //the integer digits d has; 0 - a single "0"
                len = (neg ? 1 : 0) + (whole == 0 ? 1 : whole) + (scale == 0 ? 0 : 1 + scale);
            written = 0;
            if (dst.Length < len)
                return false;
            var o = 0;
            if (neg)
                dst[o++] = '-';
            if (whole == 0)
                dst[o++] = '0';
            else
            {
                d[..whole].CopyTo(dst[o..]);
                o += whole;
            }

            if (scale != 0)
            {
                dst[o++] = '.';
                dst.Slice(o, scale - f).Fill('0');
                o += scale - f;
                d[whole..].CopyTo(dst[o..]);
                o += f;
            }

            written = o;
            return true;
        }

        ///<summary>Writes the text of <paramref name="units"/> at <paramref name="scale"/> into <paramref name="dst"/>; false, and nothing written, when it does not fit.</summary>
        public static bool TryFormat(long units, int scale, Span<char> dst, out int written)
        {
            Span<char> d = stackalloc char[20];
            var neg = units < 0;
            var n = digits(neg ? unchecked(0UL - (ulong)units) : (ulong)units, d);
            return layout(d[^n..], neg, scale, dst, out written);
        }

        ///<inheritdoc cref="TryFormat(long, int, Span{char}, out int)"/>
        public static bool TryFormat(Int128 units, int scale, Span<char> dst, out int written)
        {
            Span<char> d = stackalloc char[40];
            var neg = Int128.IsNegative(units);
            var n = digits(neg ? unchecked(UInt128.Zero - (UInt128)units) : (UInt128)units, d);
            return layout(d[^n..], neg, scale, dst, out written);
        }

        ///<summary>The text of <paramref name="units"/> at <paramref name="scale"/>: the string is the only object made.</summary>
        public static string ToString(long units, int scale)
        {
            Span<char> t = stackalloc char[MAX_CHARS];
            TryFormat(units, scale, t, out var n);
            return new string(t[..n]);
        }

        ///<inheritdoc cref="ToString(long, int)"/>
        public static string ToString(Int128 units, int scale)
        {
            Span<char> t = stackalloc char[MAX_CHARS];
            TryFormat(units, scale, t, out var n);
            return new string(t[..n]);
        }

        //0 - parsed, 1 - not a decimal, 2 - a nonzero digit past the scale, 3 - over max
        static int parse(ReadOnlySpan<char> s, int scale, ulong max, out long units)
        {
            units = 0;
            int k = 0, frac = -1; //frac: the digits taken after the point; -1 before it
            bool neg = false, any = false, past = false;
            if (0 < s.Length && (s[0] == '-' || s[0] == '+'))
                neg = s[k++] == '-';
            ulong m = 0, lim = max / 10, last = max % 10;
            for (; k < s.Length; k++)
            {
                var c = s[k];
                if (c == '.' && frac < 0)
                {
                    frac = 0;
                    continue;
                }

                var d = (uint)(c - '0');
                if (9 < d)
                    return 1;
                any = true;
                if (scale <= frac)
                {
                    past |= d != 0;
                    continue;
                }

                if (lim < m || m == lim && last < d)
                    return 3;
                m = m * 10 + d;
                if (0 <= frac)
                    frac++;
            }

            if (!any)
                return 1;
            if (past)
                return 2;
            var p = POW10[scale - (frac < 0 ? 0 : frac)];
            if (max / p < m)
                return 3;
            m *= p;
            units = neg ? -(long)m : (long)m;
            return 0;
        }

        static int parse(ReadOnlySpan<char> s, int scale, UInt128 max, out Int128 units)
        {
            units = 0;
            int k = 0, frac = -1;
            bool neg = false, any = false, past = false;
            if (0 < s.Length && (s[0] == '-' || s[0] == '+'))
                neg = s[k++] == '-';
            UInt128 m = 0, lim = max / 10;
            var last = (uint)(max % 10);
            for (; k < s.Length; k++)
            {
                var c = s[k];
                if (c == '.' && frac < 0)
                {
                    frac = 0;
                    continue;
                }

                var d = (uint)(c - '0');
                if (9 < d)
                    return 1;
                any = true;
                if (scale <= frac)
                {
                    past |= d != 0;
                    continue;
                }

                if (lim < m || m == lim && last < d)
                    return 3;
                m = m * 10 + d;
                if (0 <= frac)
                    frac++;
            }

            if (!any)
                return 1;
            if (past)
                return 2;
            var p = POW10_128[scale - (frac < 0 ? 0 : frac)];
            if (max / p < m)
                return 3;
            m *= p;
            units = neg ? -(Int128)m : (Int128)m;
            return 0;
        }

        static Exception error(int e, ReadOnlySpan<char> s) => e switch {
            1 => new FormatException($"Not a decimal: `{s}`"),
            2 => new FormatException($"A nonzero digit past the scale: `{s}`"),
            _ => new OverflowException($"Out of the range of the precision: `{s}`")
        };

        ///<summary>
        ///The units of the text <paramref name="s"/> at <paramref name="scale"/> within ±<paramref name="max"/>, read without copying it.
        ///Digits past the scale must be zeros.
        ///</summary>
        public static bool TryParse(ReadOnlySpan<char> s, int scale, long max, out long units) => parse(s, scale, (ulong)max, out units) == 0;

        ///<inheritdoc cref="TryParse(ReadOnlySpan{char}, int, long, out long)"/>
        public static bool TryParse(ReadOnlySpan<char> s, int scale, Int128 max, out Int128 units) => parse(s, scale, (UInt128)max, out units) == 0;

        ///<inheritdoc cref="TryParse(ReadOnlySpan{char}, int, long, out long)"/>
        ///<exception cref="FormatException">not a decimal, or a nonzero digit past the scale</exception>
        ///<exception cref="OverflowException">a magnitude over <paramref name="max"/></exception>
        public static long Parse(ReadOnlySpan<char> s, int scale, long max)
        {
            var e = parse(s, scale, (ulong)max, out var units);
            return e == 0 ? units : throw error(e, s);
        }

        ///<inheritdoc cref="Parse(ReadOnlySpan{char}, int, long)"/>
        public static Int128 Parse(ReadOnlySpan<char> s, int scale, Int128 max)
        {
            var e = parse(s, scale, (UInt128)max, out var units);
            return e == 0 ? units : throw error(e, s);
        }

        ///<summary>The exact <see cref="decimal"/> of <paramref name="units"/> at <paramref name="scale"/> ( 0..28 ).</summary>
        public static decimal ToDecimal(long units, int scale)
        {
            var m = units < 0 ? unchecked(0UL - (ulong)units) : (ulong)units;
            return new decimal(unchecked((int)(uint)m), (int)(uint)(m >> 32), 0, units < 0, (byte)scale);
        }

        ///<summary>The exact <see cref="decimal"/> of <paramref name="units"/> at <paramref name="scale"/> ( 0..28 ), the magnitude below 2^96.</summary>
        public static decimal ToDecimal(Int128 units, int scale)
        {
            var neg = Int128.IsNegative(units);
            var m = neg ? unchecked(UInt128.Zero - (UInt128)units) : (UInt128)units;
            return new decimal(unchecked((int)(uint)m), unchecked((int)(uint)(m >> 32)), unchecked((int)(uint)(m >> 64)), neg, (byte)scale);
        }

        //the magnitude of d in units 10^-scale: 0 - exact, 2 - a nonzero digit past the scale, 3 - over max
        static int units_of(decimal d, int scale, UInt128 max, out UInt128 m, out bool neg)
        {
            Span<int> b = stackalloc int[4];
            decimal.GetBits(d, b);
            m = (UInt128)(uint)b[2] << 64 | ((ulong)(uint)b[1] << 32 | (uint)b[0]);
            neg = b[3] < 0;
            var e = b[3] >> 16 & 0xFF;
            if (scale < e)
            {
                var (q, r) = UInt128.DivRem(m, POW10_128[e - scale]);
                if (r != 0)
                    return 2;
                m = q;
            }
            else if (e < scale)
            {
                var p = POW10_128[scale - e];
                if (max / p < m)
                    return 3;
                m *= p;
            }

            return m <= max ? 0 : 3;
        }

        ///<summary>The units at <paramref name="scale"/> of <paramref name="d"/>, exactly.</summary>
        ///<exception cref="ArgumentException">a nonzero digit past the scale</exception>
        ///<exception cref="OverflowException">a magnitude over <paramref name="max"/></exception>
        public static long FromDecimal(decimal d, int scale, long max)
        {
            var e = units_of(d, scale, (ulong)max, out var m, out var neg);
            if (e != 0)
                throw e == 2 ? new ArgumentException($"A nonzero digit past the scale {scale}: {d}") : new OverflowException($"Out of ±{max} units: {d}");
            return neg ? -(long)(ulong)m : (long)(ulong)m;
        }

        ///<inheritdoc cref="FromDecimal(decimal, int, long)"/>
        public static Int128 FromDecimal(decimal d, int scale, Int128 max)
        {
            var e = units_of(d, scale, (UInt128)max, out var m, out var neg);
            if (e != 0)
                throw e == 2 ? new ArgumentException($"A nonzero digit past the scale {scale}: {d}") : new OverflowException($"Out of ±{max} units: {d}");
            return neg ? -(Int128)m : (Int128)m;
        }

        //──────────────────────────────── arithmetic ────────────────────────────────
        //Units within ±max; an operand in its own scale. Products and quotients are exact on 256 bits and then rounded by an
        //explicit RoundingMode. Out of ±max - OverflowException; rounding needed under UNNECESSARY - ArithmeticException.

        static OverflowException overflow() => new("Out of the range of the decimal");

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static UInt128 abs(Int128 x) => Int128.IsNegative(x) ? unchecked(UInt128.Zero - (UInt128)x) : (UInt128)x;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static Int128 signed(UInt128 q, bool neg, Int128 max) => (UInt128)max < q ? throw overflow() : neg ? -(Int128)q
                                                                                                           : (Int128)q;

        //the 256-bit product of two magnitudes
        static void mul(UInt128 a, UInt128 b, out UInt128 hi, out UInt128 lo)
        {
            unchecked
            {
                ulong a0 = (ulong)a, a1 = (ulong)(a >> 64), b0 = (ulong)b, b1 = (ulong)(b >> 64);
                var p00 = (UInt128)a0 * b0;
                var p01 = (UInt128)a0 * b1;
                var p10 = (UInt128)a1 * b0;
                var mid = (p00 >> 64) + (ulong)p01 + (ulong)p10;
                lo = mid << 64 | (ulong)p00;
                hi = (UInt128)a1 * b1 + (p01 >> 64) + (p10 >> 64) + (mid >> 64);
            }
        }

        //(hi, lo) · m; false - past 256 bits
        static bool mul(UInt128 hi, UInt128 lo, UInt128 m, out UInt128 h, out UInt128 l)
        {
            mul(lo, m, out var c, out l);
            mul(hi, m, out var hh, out var hl);
            h = unchecked(c + hl);
            return hh == 0 && c <= h;
        }

        //(hi, lo) / d; false - the quotient is past 128 bits
        static bool div(UInt128 hi, UInt128 lo, UInt128 d, out UInt128 q, out UInt128 r)
        {
            unchecked
            {
                if (hi == 0)
                {
                    (q, r) = UInt128.DivRem(lo, d);
                    return true;
                }

                q = r = 0;
                if (d <= hi)
                    return false;
                if (d <= ulong.MaxValue) //two 128-by-64 steps: hi < d < 2^64
                {
                    var (q1, r1) = UInt128.DivRem(hi << 64 | (lo >> 64), d);
                    var (q0, r0) = UInt128.DivRem(r1 << 64 | (ulong)lo, d);
                    q = q1 << 64 | q0;
                    r = r0;
                    return true;
                }

                var rem = hi; //< d
                for (var i = 127; -1 < i; i--)
                {
                    var top = rem >> 127;
                    rem = rem << 1 | (lo >> i & 1);
                    q <<= 1;
                    if (top != 0 || d <= rem)
                    {
                        rem -= d;
                        q |= 1;
                    }
                }

                r = rem;
                return true;
            }
        }

        //q, or q + 1 when the dropped part, compared to a half ( half: -1, 0, 1 ), rounds it up
        static UInt128 round(UInt128 q, int half, bool inexact, bool neg, RoundingMode mode)
        {
            if (!inexact)
                return q;
            var up = mode switch {
                RoundingMode.UP => true,
                RoundingMode.DOWN => false,
                RoundingMode.CEILING => !neg,
                RoundingMode.FLOOR => neg,
                RoundingMode.HALF_UP => 0 <= half,
                RoundingMode.HALF_DOWN => 0 < half,
                RoundingMode.HALF_EVEN => 0 < half || half == 0 && (q & 1) != 0,
                _ => throw new ArithmeticException("Rounding necessary")
            };
            return up ? q + 1 : q;
        }

        //(hi, lo) / ( den · 10^k ) rounded, 0 <= k <= 38; false - the quotient is past 128 bits
        static bool div_round(UInt128 hi, UInt128 lo, UInt128 den, int k, bool neg, RoundingMode mode, out UInt128 q)
        {
            if (!div(hi, lo, den, out var q1, out var r1))
            {
                q = 0;
                return false;
            }

            if (k == 0)
            {
                q = round(q1, r1.CompareTo(den - r1), r1 != 0, neg, mode);
                return true;
            }

            //the second divisor 10^k is even: the remainder r2·den + r1 is a half exactly when r2 is a half of 10^k and r1 is 0
            var d = POW10_128[k];
            var (q2, r2) = UInt128.DivRem(q1, d);
            var c = r2.CompareTo(d - r2);
            if (c == 0 && r1 != 0)
                c = 1;
            q = round(q2, c, r2 != 0 || r1 != 0, neg, mode);
            return true;
        }

        ///<summary>round( <paramref name="x"/> · <paramref name="y"/> · 10^<paramref name="e"/> ) within ±<paramref name="max"/>: the product of units of scales sx and sy in scale sr is e = sr - sx - sy.</summary>
        public static Int128 Multiply(Int128 x, Int128 y, int e, RoundingMode mode, Int128 max)
        {
            var neg = Int128.IsNegative(x) != Int128.IsNegative(y);
            mul(abs(x), abs(y), out var hi, out var lo);
            UInt128 q;
            if (e < 0)
            {
                if (e < -76)
                    q = round(0, -1, hi != 0 || lo != 0, neg, mode); //the product is below 10^76: less than a half
                else if (!(e < -38 ? div_round(hi, lo, POW10_128[38], -e - 38, neg, mode, out q) : div_round(hi, lo, POW10_128[-e], 0, neg, mode, out q)))
                    throw overflow();
            }
            else
            {
                if (0 < e && (hi != 0 || lo != 0) && (38 < e || !mul(hi, lo, POW10_128[e], out hi, out lo)))
                    throw overflow();
                if (hi != 0)
                    throw overflow();
                q = lo;
            }

            return signed(q, neg, max);
        }

        ///<inheritdoc cref="Multiply(Int128, Int128, int, RoundingMode, Int128)"/>
        public static long Multiply(long x, long y, int e, RoundingMode mode, long max) => (long)Multiply((Int128)x, y, e, mode, max);

        ///<summary>round( <paramref name="x"/> · 10^<paramref name="n"/> / <paramref name="y"/> ) within ±<paramref name="max"/>: the quotient of units of scales sx and sy in scale sr is n = sr - sx + sy.</summary>
        public static Int128 Divide(Int128 x, Int128 y, int n, RoundingMode mode, Int128 max)
        {
            if (y == 0)
                throw new DivideByZeroException();
            var neg = Int128.IsNegative(x) != Int128.IsNegative(y);
            UInt128 ax = abs(x), ay = abs(y), hi = 0, lo = ax, q;
            if (n < 0)
            {
                if (n < -38)
                    q = round(0, -1, ax != 0, neg, mode); //the divisor is past 10^39 > 2·|x|: less than a half
                else if (!div_round(0, ax, ay, -n, neg, mode, out q))
                    throw overflow();
            }
            else
            {
                for (; 0 < n; n -= 38)
                    if (!mul(hi, lo, POW10_128[n < 38 ? n : 38], out hi, out lo))
                        throw overflow();
                if (!div_round(hi, lo, ay, 0, neg, mode, out q))
                    throw overflow();
            }

            return signed(q, neg, max);
        }

        ///<inheritdoc cref="Divide(Int128, Int128, int, RoundingMode, Int128)"/>
        public static long Divide(long x, long y, int n, RoundingMode mode, long max) => (long)Divide((Int128)x, y, n, mode, max);

        ///<summary><paramref name="a"/> + <paramref name="b"/> within ±<paramref name="max"/>.</summary>
        public static long Add(long a, long b, long max)
        {
            var r = unchecked(a + b);
            return ((a ^ r) & (b ^ r)) < 0 || r < -max || max < r ? throw overflow() : r;
        }

        ///<inheritdoc cref="Add(long, long, long)"/>
        public static Int128 Add(Int128 a, Int128 b, Int128 max)
        {
            var r = unchecked(a + b);
            return Int128.IsNegative((a ^ r) & (b ^ r)) || r < -max || max < r ? throw overflow() : r;
        }

        ///<summary><paramref name="a"/> - <paramref name="b"/> within ±<paramref name="max"/>.</summary>
        public static long Subtract(long a, long b, long max)
        {
            var r = unchecked(a - b);
            return ((a ^ b) & (a ^ r)) < 0 || r < -max || max < r ? throw overflow() : r;
        }

        ///<inheritdoc cref="Subtract(long, long, long)"/>
        public static Int128 Subtract(Int128 a, Int128 b, Int128 max)
        {
            var r = unchecked(a - b);
            return Int128.IsNegative((a ^ b) & (a ^ r)) || r < -max || max < r ? throw overflow() : r;
        }

        ///<summary>The units of scale <paramref name="from"/> in scale <paramref name="to"/>, within ±<paramref name="max"/>.</summary>
        public static long Rescale(long units, int from, int to, RoundingMode mode, long max) => Multiply(units, 1, to - from, mode, max);

        ///<inheritdoc cref="Rescale(long, int, int, RoundingMode, long)"/>
        public static Int128 Rescale(Int128 units, int from, int to, RoundingMode mode, Int128 max) => Multiply(units, 1, to - from, mode, max);

        ///<summary>The integer of <paramref name="units"/> at <paramref name="scale"/>.</summary>
        public static long ToLong(Int128 units, int scale, RoundingMode mode) => (long)Multiply(units, 1, -scale, mode, long.MaxValue);

        ///<summary>The units at <paramref name="scale"/> of the integer <paramref name="v"/>, within ±<paramref name="max"/>.</summary>
        public static long FromLong(long v, int scale, long max) => Multiply(v, 1, scale, RoundingMode.UNNECESSARY, max);

        ///<inheritdoc cref="FromLong(long, int, long)"/>
        public static Int128 FromLong(long v, int scale, Int128 max) => Multiply(v, 1, scale, RoundingMode.UNNECESSARY, max);

        ///<summary>An approximate <see cref="double"/> of the units: for showing only.</summary>
        public static double ToDouble(long units, int scale) => units / Math.Pow(10, scale);

        ///<inheritdoc cref="ToDouble(long, int)"/>
        public static double ToDouble(Int128 units, int scale) => (double)units / Math.Pow(10, scale);

        ///<summary>The units at <paramref name="scale"/> of the exact value of <paramref name="v"/>, rounded by <paramref name="mode"/>, within ±<paramref name="max"/>.</summary>
        public static Int128 FromDouble(double v, int scale, RoundingMode mode, Int128 max)
        {
            if (!double.IsFinite(v))
                throw overflow();
            var bits = BitConverter.DoubleToInt64Bits(v);
            var neg = bits < 0;
            var exp = (int)(bits >> 52 & 0x7FF);
            var m = (ulong)bits & 0xF_FFFF_FFFF_FFFFUL;
            if (exp == 0)
                exp = 1;
            else
                m |= 1UL << 52;
            if (m == 0)
                return 0;
            var e = exp - 1075;                               //v = m · 2^e
            mul(m, POW10_128[scale], out var hi, out var lo); //below 2^180
            UInt128 q;
            unchecked
            {
                if (0 <= e)
                {
                    if (hi != 0 || 127 < e || 0 < e && lo >> (128 - e) != 0)
                        throw overflow();
                    q = lo << e;
                }
                else
                {
                    var k = -e;
                    bool half, sticky;
                    if (255 < k) //the half bit is above the number
                    {
                        q = 0;
                        half = false;
                        sticky = true;
                    }
                    else
                    {
                        var j = k - 1; //the half bit
                        if (k < 128)
                        {
                            if (hi >> k != 0)
                                throw overflow();
                            q = lo >> k | hi << (128 - k);
                        }
                        else
                            q = hi >> (k - 128);

                        half = ((j < 128 ? lo >> j : hi >> (j - 128)) & 1) != 0;
                        sticky = j < 128 ? j != 0 && (lo & UInt128.MaxValue >> (128 - j)) != 0 : lo != 0 || j != 128 && (hi & UInt128.MaxValue >> (256 - j)) != 0;
                    }

                    q = round(q, half ? sticky ? 1 : 0 : -1, half || sticky, neg, mode);
                }
            }

            return signed(q, neg, max);
        }

        ///<inheritdoc cref="FromDouble(double, int, RoundingMode, Int128)"/>
        public static long FromDouble(double v, int scale, RoundingMode mode, long max) => (long)FromDouble(v, scale, mode, (Int128)max);
    }

    ///<summary>The rounding of a dropped part: the modes and their order those of <c>java.math.RoundingMode</c>, the same in every AdHoc language.</summary>
    public enum RoundingMode
    {
        ///<summary>Away from zero.</summary>
        UP,
        ///<summary>Towards zero.</summary>
        DOWN,
        ///<summary>Towards positive infinity.</summary>
        CEILING,
        ///<summary>Towards negative infinity.</summary>
        FLOOR,
        ///<summary>To the nearest, a half away from zero.</summary>
        HALF_UP,
        ///<summary>To the nearest, a half towards zero.</summary>
        HALF_DOWN,
        ///<summary>To the nearest, a half to the even neighbour.</summary>
        HALF_EVEN,
        ///<summary>No rounding: an inexact result is an <see cref="ArithmeticException"/>.</summary>
        UNNECESSARY
    }

    ///<summary>
    ///The bytes of a one-byte array field, for the block copy the generated code does instead of a byte-by-byte loop
    ///(<see cref="Connection.Transmitter.put(ReadOnlySpan{byte}, int, int, uint)"/>,
    ///<see cref="Connection.Receiver.get_bytes(Span{byte}, int, int, uint)"/>). One name for every holder of one-byte
    ///items - <c>byte</c>, <c>sbyte</c>, a one-byte enum, in an array or a list - so the generated code does not depend
    ///on which one the field has.
    ///</summary>
    ///<summary>
    ///Copies whole elements of <paramref name="width"/> bytes between the wire (little-endian) and a holder's memory. On a
    ///little-endian host - every host .NET runs on in practice - the two are the same bytes: one memcpy. Elsewhere each
    ///element is reversed on the way.
    ///</summary>
    public static void copy_le(ReadOnlySpan<byte> src, Span<byte> dst, int width)
    {
        if (BitConverter.IsLittleEndian || width == 1)
        {
            src.CopyTo(dst);
            return;
        }

        for (var i = 0; i < src.Length; i += width)
            for (var j = 0; j < width; j++)
                dst[i + j] = src[i + width - 1 - j];
    }

    public static Span<byte> bytes<T>(T[] src)
        where T : unmanaged => MemoryMarshal.AsBytes(src.AsSpan());

    ///<inheritdoc cref="bytes{T}(T[])"/>
    public static Span<byte> bytes<T>(List<T> src)
        where T : unmanaged => MemoryMarshal.AsBytes(CollectionsMarshal.AsSpan(src));

    ///<summary>
    ///A list being received: grown to <paramref name="count"/> items first, so the block lands in place. The list is
    ///created for exactly that many, so it does not reallocate; on a resumed call the count is already there.
    ///</summary>
    public static Span<byte> bytes<T>(List<T> src, int count)
        where T : unmanaged
    {
        CollectionsMarshal.SetCount(src, count);
        return MemoryMarshal.AsBytes(CollectionsMarshal.AsSpan(src));
    }

    ///<summary>
    ///Resizes an array to a new length. If the array is expanded, new elements are filled with `fill_value`.
    ///If the array is shrunk, elements are truncated. If lengths are equal, the original array is returned.
    ///</summary>
    ///<typeparam name="T">The type of elements in the array.</typeparam>
    ///<param name="src">The source array to resize.</param>
    ///<param name="new_length">The desired new length of the array.</param>
    ///<param name="fill_value">The value to use for newly added elements if the array is expanded.</param>
    ///<returns>The resized array. This may be the original array instance if `new_length` matches the original length, or a new array instance if `Array.Resize` reallocates.</returns>
    public static T[] Resize<T>(T[] src, int new_length, T fill_value)
    {
        var len = src.Length;
        if (len == new_length)
            return src;

        Array.Resize(ref src, new_length);
        if (len < new_length)
            Array.Fill(src, fill_value, len, new_length - len);
        return src;
    }

    ///<summary>
    ///Resizes a `List<T>` to a new length. If the list is expanded, new elements are added with `fillValue`.
    ///If the list is shrunk, elements are removed from the end.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="list">The list to resize.</param>
    ///<param name="newLength">The desired new length of the list.</param>
    ///<param name="fillValue">The value to use for newly added elements if the list is expanded.</param>
    ///<returns>The original list instance, resized.</returns>
    public static List<T> Resize<T>(List<T> list, int newLength, T fillValue)
    {
        if (list.Count < newLength)
            while (list.Count < newLength)
                list.Add(fillValue);
        else
            list.RemoveRange(newLength, list.Count - newLength);

        return list;
    }

    ///<summary>
    ///Resizes the specified `IList<T>` to the new length.
    ///If `newLength` is greater than the current count, the list is expanded and new elements are filled with `fillValue`.
    ///If `newLength` is less than the current count, the list is truncated.
    ///This method handles `T[]` and `List<T>` efficiently, and provides a generic fallback for other `IList<T>` implementations.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="list">The list to resize.</param>
    ///<param name="newLength">The desired length of the list.</param>
    ///<param name="fillValue">The value to use for filling the list if it is expanded.</param>
    ///<returns>The resized list. This may be a new instance if `list` was an array and resizing occurred, or the original instance for other `IList<T>` types.</returns>
    public static IList<T> Resize<T>(IList<T> list, int newLength, T fillValue)
    {
        switch (list)
        {
            case T[] array:
                return Resize(array, newLength, fillValue);

            case List<T> list_:
                return Resize(list_, newLength, fillValue);

            default:
                //If the list is neither an array nor a List<T>, handle the resizing manually
                if (list.Count < newLength)
                    while (list.Count < newLength)
                        list.Add(fillValue);
                else
                    while (list.Count > newLength)
                        list.RemoveAt(list.Count - 1);

                return list;
        }
    }

    ///<summary>
    ///Converts an `IList<T>` to a `List<T>`, taking at most `max` elements from the source.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="src">The source `IList<T>`.</param>
    ///<param name="max">The maximum number of elements to include in the new list.</param>
    ///<returns>A new `List<T>` containing elements from `src`, truncated or copied entirely based on `max`.</returns>
    public static List<T> toList<T>(IList<T> src, int max)
    {
        var ret = new List<T>(max);

        if (max < src.Count)
            for (var i = 0; i < max; i++)
                ret.Add(src[i]);
        else
            ret.AddRange(src);

        return ret;
    }

    ///<summary>
    ///Creates a new array of a specified size. If `fill` is not the default value for type `T`,
    ///the array is filled with `fill`. Otherwise, it's returned with default-initialized elements
    ///(which is the standard behavior for `new T[size]`).
    ///</summary>
    ///<typeparam name="T">The type of elements in the array.</typeparam>
    ///<param name="fill">The value to fill the array with if it's not the default for `T`.</param>
    ///<param name="size">The size of the array to create.</param>
    ///<returns>A new array of the specified size, potentially filled with `fill`.</returns>
    public static T[] sizeArray<T>(T fill, int size)
    {
        var ret = new T[size];
        //Only fill the array if fill is not the default value for the type (e.g., 0 for integers, null for reference types)
        if (EqualityComparer<T>.Default.Equals(fill, default))
            return ret;

        //Fill the array with the specified fill value
        Array.Fill(ret, fill);
        return ret;
    }

    ///<summary>
    ///Creates a new `List<T>` of a specified size, filling it with the given `fill` value.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    ///<param name="fill">The value to fill the list with.</param>
    ///<param name="size">The desired number of elements in the list.</param>
    ///<returns>A new `List<T>` of size `size`, with all elements initialized to `fill`.</returns>
    public static List<T> sizeList<T>(T fill, int size)
    {
        var ret = new List<T>(size);

        while (-1 < --size)
            ret.Add(fill);
        return ret;
    }
#region CRC
    ///<summary>
    ///Length of the CRC checksum of a framed pack in bytes: CRC-32C.
    ///</summary>
    const int CRC_LEN_BYTES = 4;

    ///<summary>The bytes of a long block of the framing at most: its length goes as two bytes 0..254, the low one first.</summary>
    const int LONG = 254 + 254 * 255;

    ///<summary>The high bit of each byte 0xFF of <paramref name="w"/>: exact at the lowest such byte, the ones above it may be off.</summary>
    static ulong ff_in(ulong w)
    {
        var v = ~w;
        return v - 0x0101010101010101UL & ~v & 0x8080808080808080UL;
    }

    ///<summary>
    ///The CRC-32C ( Castagnoli ) of <paramref name="crc"/> followed by <paramref name="src"/>: 0 to start, the result goes on
    ///with the next bytes - as the Java lib's <c>CRC32C</c> and the Rust lib's <c>crc32c</c>. The processor's crc32 instruction
    ///( SSE4.2, ARM ) where it has it, eight bytes a step. One crc32 waits for the one before it: three runs side by side over
    ///neighbouring blocks of <see cref="CRC_BLOCK"/> bytes keep the processor busy, the first one's CRC is then carried over the
    ///other two ( <see cref="crc32c_zeros"/> ). "123456789" gives 0xE3069283.
    ///</summary>
    internal static uint crc32c(uint crc, ReadOnlySpan<byte> src)
    {
        var c = ~crc;
        ref var b = ref MemoryMarshal.GetReference(src);
        int i = 0, n = src.Length;
        for (; i + 3 * CRC_BLOCK <= n; i += 3 * CRC_BLOCK)
        {
            uint c1 = 0, c2 = 0;
            for (var j = i; j < i + CRC_BLOCK; j += 8)
            {
                c = BitOperations.Crc32C(c, Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref b, j)));
                c1 = BitOperations.Crc32C(c1, Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref b, j + CRC_BLOCK)));
                c2 = BitOperations.Crc32C(c2, Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref b, j + 2 * CRC_BLOCK)));
            }

            c = crc32c_zeros(crc32c_zeros(c) ^ c1) ^ c2;
        }

        for (; i + 8 <= n; i += 8)
            c = BitOperations.Crc32C(c, Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref b, i)));
        for (; i < n; i++)
            c = BitOperations.Crc32C(c, Unsafe.Add(ref b, i));
        return ~c;
    }

    ///<summary>The bytes of a block of each of the three runs of <see cref="crc32c"/>.</summary>
    const int CRC_BLOCK = 256;

    ///<summary>
    ///The crc32 state <paramref name="c"/> carried over <see cref="CRC_BLOCK"/> zero bytes - linear in <paramref name="c"/>: a
    ///lookup for each of its bytes in <see cref="crc32c_zero_tables"/>.
    ///</summary>
    static uint crc32c_zeros(uint c)
    {
        ref var t = ref MemoryMarshal.GetArrayDataReference(crc32c_zero_tables);
        return Unsafe.Add(ref t, (int)(c & 0xFF)) ^ Unsafe.Add(ref t, 256 + (int)(c >> 8 & 0xFF)) ^ Unsafe.Add(ref t, 512 + (int)(c >> 16 & 0xFF)) ^ Unsafe.Add(ref t, 768 + (int)(c >> 24));
    }

    ///<summary>Byte k of a crc32 state, value v, carried over <see cref="CRC_BLOCK"/> zero bytes: at <c>256 * k + v</c>.</summary>
    static readonly uint[] crc32c_zero_tables = zero_tables();

    static uint[] zero_tables()
    {
        var t = new uint[4 * 256];
        for (var k = 0; k < 4; k++)
            for (var v = 0; v < 256; v++)
            {
                var c = (uint)v << 8 * k;
                for (var j = 0; j < CRC_BLOCK; j += 8)
                    c = BitOperations.Crc32C(c, 0UL);
                t[256 * k + v] = c;
            }

        return t;
    }
#endregion

    ///<summary>
    ///Implements equality comparison and hash code generation for `IList<T>` instances
    ///based on their element-wise content and sequence.
    ///</summary>
    ///<typeparam name="T">The type of elements in the list.</typeparam>
    public class ArrayEqualHash<T> : IEqualityComparer<IList<T>>
    {
        public bool Equals(IList<T>? x, IList<T>? y) => x == null || y == null ? x == y : x.Count == y.Count && x.SequenceEqual(y);

        public int GetHashCode(IList<T> list) => list.Aggregate(17, (current, item) => HashCode.Combine(current, item));
    }

    static readonly ConcurrentDictionary<object, object> pool = new();

    ///<summary>
    ///Gets a singleton instance of `ArrayEqualHash<T>` for the specified type `T`.
    ///This comparer can be used for `IList<T>` instances where equality depends on element sequence and values.
    ///</summary>
    ///<typeparam name="T">The type of elements in the lists to be compared.</typeparam>
    ///<returns>An `IEqualityComparer<IList<T>>` instance.</returns>
    public static IEqualityComparer<IList<T>> getArrayEqualHash<T>()
    {
        var t = typeof(T);
        if (pool.TryGetValue(t, out var value))
            return (IEqualityComparer<IList<T>>)value;
        var ret = new ArrayEqualHash<T>();
        pool[t] = ret;
        return ret;
    }

    ///<summary>
    ///The varints of a string's UTF-16 units below 0x4000 - one byte below 0x80, two above - and the chars back, 8 a step:
    ///a char becomes both its bytes in its 16-bit lane, and one byte shuffle keeps the ones the varints have (SSSE3
    ///<c>pshufb</c>, NEON <c>tbl</c>), by a table of the 256 masks of which of the 8 take two. Latin, Cyrillic, Greek, Hebrew,
    ///Arabic, the Indic scripts, ASCII among them, go so; a unit from 0x4000 on (CJK, a surrogate) is left to the scalar code
    ///of the caller, as everything is where no shuffle is (<see cref="Accelerated"/>).
    ///</summary>
    internal static class Units
    {
        //[m * 16 ..]: the bytes of 8 lanes the varints of 8 chars keep - the low one of each, the high one too where bit k of m
        //says char k takes two; 0x80 past them - a zero byte
        static readonly byte[] TO_VARINTS = table(true);

        //[m * 16 ..]: the lanes that end a varint, bit k of m - a char each, in order; 0x80 past them
        static readonly byte[] TO_CHARS = table(false);

        static byte[] table(bool varints)
        {
            var t = new byte[256 * 16];
            for (var m = 0; m < 256; m++)
            {
                int o = m * 16, n = 0;
                for (var k = 0; k < 8; k++)
                    if (varints)
                    {
                        t[o + n++] = (byte)(2 * k);
                        if ((m >> k & 1) != 0)
                            t[o + n++] = (byte)(2 * k + 1);
                    }
                    else if ((m >> k & 1) != 0)
                    {
                        t[o + n++] = (byte)(2 * k);
                        t[o + n++] = (byte)(2 * k + 1);
                    }

                while (n < 16)
                    t[o + n++] = 0x80;
            }

            return t;
        }

        public static bool Accelerated
        {
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            get => BitConverter.IsLittleEndian && (System.Runtime.Intrinsics.X86.Ssse3.IsSupported || System.Runtime.Intrinsics.Arm.AdvSimd.Arm64.IsSupported);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static Vector128<byte> shuffle(Vector128<byte> v, Vector128<byte> at) => System.Runtime.Intrinsics.X86.Ssse3.IsSupported ? System.Runtime.Intrinsics.X86.Ssse3.Shuffle(v, at) : System.Runtime.Intrinsics.Arm.AdvSimd.Arm64.VectorTableLookup(v, at);

        ///<summary>
        ///The chars from <paramref name="src"/> on, at most <paramref name="chars"/> of them, as their varints from
        ///<paramref name="dst"/> on, while a whole step has 16 bytes of the <paramref name="room"/> - the bytes past the varints
        ///in them are scratch. Stops before a char from 0x4000 on. Returns the chars done, <paramref name="written"/> - the bytes.
        ///</summary>
        [MethodImpl(MethodImplOptions.AggressiveOptimization)]
        public static int ToVarints(ref char src, int chars, ref byte dst, int room, out int written)
        {
            int i = 0, o = 0;
            ref var tab = ref MemoryMarshal.GetArrayDataReference(TO_VARINTS);
            ref var s = ref Unsafe.As<char, ushort>(ref src);
            while (i + 8 <= chars && o + 16 <= room)
            {
                var c = Vector128.LoadUnsafe(ref s, (nuint)i);
                var two = Vector128.GreaterThan(c, Vector128.Create((ushort)0x7F));
                //1yyyyyyy 0xxxxxxx: the low 7 bits, more follow; the high 7
                var w = Vector128.ConditionalSelect(two, c & Vector128.Create((ushort)0x7F) | Vector128.Create((ushort)0x80) | c << 1 & Vector128.Create((ushort)0x7F00), c);
                var m = Vector128.ExtractMostSignificantBits(two);
                shuffle(w.AsByte(), Vector128.LoadUnsafe(ref tab, (nuint)(m << 4))).StoreUnsafe(ref dst, (nuint)o);
                var big = Vector128.ExtractMostSignificantBits(Vector128.GreaterThan(c, Vector128.Create((ushort)0x3FFF)));
                if (big != 0)
                {
                    var k = BitOperations.TrailingZeroCount(big);
                    i += k;
                    o += k + BitOperations.PopCount(m & ((1u << k) - 1));
                    break;
                }

                i += 8;
                o += 8 + BitOperations.PopCount(m);
            }

            written = o;
            return i;
        }

        ///<summary>
        ///The varints of units below 0x4000 from <paramref name="src"/> on, at most <paramref name="max"/> of them, as chars from
        ///<paramref name="dst"/> on, 8 bytes a step while 8 chars of the <paramref name="room"/> are there - the ones past the
        ///units in them are scratch. Stops before a varint of 3 bytes; one the end of a step cuts goes into the next.
        ///Returns the bytes done, <paramref name="chars"/> - the chars.
        ///</summary>
        [MethodImpl(MethodImplOptions.AggressiveOptimization)]
        public static int ToChars(ref byte src, int bytes, ref char dst, int room, int max, out int chars)
        {
            int i = 0, o = 0;
            ref var tab = ref MemoryMarshal.GetArrayDataReference(TO_CHARS);
            ref var d = ref Unsafe.As<char, byte>(ref dst);
            while (i + 8 <= bytes && o + 8 <= room && o + 8 <= max)
            {
                var p = Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref src, i));
                var high = p & 0x8080808080808080UL;
                var bad = high & high >> 8; //two first bytes in a row: a varint of 3 bytes
                var n = bad != 0 ? BitOperations.TrailingZeroCount(bad) >> 3 : high >> 63 != 0 ? 7
                                                                                               : //its second byte in the next step
                                                                               8;
                if (n == 0)
                    break;
                var b = Vector128.WidenLower(Vector128.CreateScalar(p).AsByte());
                var q = Vector128.WidenLower(Vector128.CreateScalar(p << 8).AsByte()); //the byte before each
                var pair = Vector128.GreaterThan(q, Vector128.Create((ushort)0x7F));
                var val = Vector128.ConditionalSelect(pair, q & Vector128.Create((ushort)0x7F) | b << 7, b);
                //the bytes that end a varint, their top bits gathered into one byte: bit k - byte k
                var m = (uint)((~p & 0x8080808080808080UL) * 0x0002040810204081UL >> 56) & (1u << n) - 1;
                shuffle(val.AsByte(), Vector128.LoadUnsafe(ref tab, (nuint)(m << 4))).StoreUnsafe(ref d, (nuint)(o << 1));
                o += BitOperations.PopCount(m);
                i += n;
                if (bad != 0)
                    break;
            }

            chars = o;
            return i;
        }
    }

    ///<summary>
    ///Endianness-aware integer codec. Read/Write methods on the nested <see cref="OK"/> static class
    ///select the host endianness at JIT-time via <see cref="BitConverter.IsLittleEndian"/> (a recognized
    ///JIT-folded constant). Verified equivalent to the prior interface-based dispatch via
    ///DisassemblyDiagnoser (35-byte loop, identical instructions on .NET 10 RyuJIT AVX2).
    ///<para>
    ///<b>Compile-time hosts.</b> Define one of the following symbols to make the endianness a
    ///<i>C# compile-time constant</i> (the inactive branch is dropped from IL entirely, no JIT-fold required):
    ///<list type="bullet">
    ///<item><c>ADHOC_LE_HOST</c> &mdash; force little-endian. Safe on x86/x64/ARM-LE.</item>
    ///<item><c>ADHOC_BE_HOST</c> &mdash; force big-endian.</item>
    ///</list>
    ///With neither defined, the codec stays portable and the JIT does the folding at runtime.
    ///</para>
    ///</summary>
    internal static class Endianness
    {
#if ADHOC_BE_HOST && ADHOC_LE_HOST
#error "Define at most one of ADHOC_LE_HOST / ADHOC_BE_HOST."
#endif

#if ADHOC_BE_HOST
        //BE host: const false → C# compiler folds `LE_HOST ? a : b` to `b` at compile time.
        private const bool LE_HOST = false;
#elif ADHOC_LE_HOST
        //LE host: const true → C# compiler folds `LE_HOST ? a : b` to `a` at compile time.
        private const bool LE_HOST = true;
#else
        //Portable: BitConverter.IsLittleEndian is a JIT-time constant; the `?:` collapses in native code.
        private static readonly bool LE_HOST = BitConverter.IsLittleEndian;
#endif

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static ref byte RefAt(byte[] src, int index) => ref Unsafe.AddByteOffset(ref MemoryMarshal.GetArrayDataReference(src), (nint)(uint)index);

        public static class OK
        {
            //---- byte[] READ ----
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static short Int16(byte[] src, int index)
            {
                var v = Unsafe.ReadUnaligned<short>(ref RefAt(src, index));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static ushort UInt16(byte[] src, int index)
            {
                var v = Unsafe.ReadUnaligned<ushort>(ref RefAt(src, index));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static int Int32(byte[] src, int index)
            {
                var v = Unsafe.ReadUnaligned<int>(ref RefAt(src, index));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static uint UInt32(byte[] src, int index)
            {
                var v = Unsafe.ReadUnaligned<uint>(ref RefAt(src, index));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static long Int64(byte[] src, int index)
            {
                var v = Unsafe.ReadUnaligned<long>(ref RefAt(src, index));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static ulong UInt64(byte[] src, int index)
            {
                var v = Unsafe.ReadUnaligned<ulong>(ref RefAt(src, index));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            //---- ReadOnlySpan<byte> READ ----
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static short Int16(ReadOnlySpan<byte> src)
            {
                var v = Unsafe.ReadUnaligned<short>(ref MemoryMarshal.GetReference(src));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static ushort UInt16(ReadOnlySpan<byte> src)
            {
                var v = Unsafe.ReadUnaligned<ushort>(ref MemoryMarshal.GetReference(src));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static int Int32(ReadOnlySpan<byte> src)
            {
                var v = Unsafe.ReadUnaligned<int>(ref MemoryMarshal.GetReference(src));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static uint UInt32(ReadOnlySpan<byte> src)
            {
                var v = Unsafe.ReadUnaligned<uint>(ref MemoryMarshal.GetReference(src));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static long Int64(ReadOnlySpan<byte> src)
            {
                var v = Unsafe.ReadUnaligned<long>(ref MemoryMarshal.GetReference(src));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static ulong UInt64(ReadOnlySpan<byte> src)
            {
                var v = Unsafe.ReadUnaligned<ulong>(ref MemoryMarshal.GetReference(src));
                return LE_HOST ? v : BinaryPrimitives.ReverseEndianness(v);
            }

            //---- byte[] WRITE ----
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void Int16(short src, byte[] dst, int index) => Unsafe.WriteUnaligned(ref RefAt(dst, index), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void UInt16(ushort src, byte[] dst, int index) => Unsafe.WriteUnaligned(ref RefAt(dst, index), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void Int32(int src, byte[] dst, int index) => Unsafe.WriteUnaligned(ref RefAt(dst, index), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void UInt32(uint src, byte[] dst, int index) => Unsafe.WriteUnaligned(ref RefAt(dst, index), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void Int64(long src, byte[] dst, int index) => Unsafe.WriteUnaligned(ref RefAt(dst, index), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void UInt64(ulong src, byte[] dst, int index) => Unsafe.WriteUnaligned(ref RefAt(dst, index), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            //---- Span<byte> WRITE ----
            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void Int16(short src, Span<byte> dst) => Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(dst), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void UInt16(ushort src, Span<byte> dst) => Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(dst), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void Int32(int src, Span<byte> dst) => Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(dst), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void UInt32(uint src, Span<byte> dst) => Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(dst), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void Int64(long src, Span<byte> dst) => Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(dst), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));

            [MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static void UInt64(ulong src, Span<byte> dst) => Unsafe.WriteUnaligned(ref MemoryMarshal.GetReference(dst), LE_HOST ? src : BinaryPrimitives.ReverseEndianness(src));
        }
    }

    ///<summary>
    ///Represents a boolean value that can also be null. Internally stored as a byte:
    ///0 for false, 1 for true, and 2 (see `NULL` constant) for null.
    ///</summary>
    public struct NullableBool : IEquatable<NullableBool>
    {
        ///<summary>
        ///Initializes a new instance of the <see cref="NullableBool"/> struct to the null state.
        ///</summary>
        public NullableBool() {}

        ///<summary>
        ///Initializes a new instance of the <see cref="NullableBool"/> struct with a specified boolean value.
        ///</summary>
        ///<param name="value">The boolean value.</param>
        public NullableBool(bool value) => Value = value;

        ///<summary>
        ///Initializes a new instance of the <see cref="NullableBool"/> struct with a raw byte value
        ///representing its state (0 for false, 1 for true, 2 for null).
        ///</summary>
        ///<param name="value">The byte value (0, 1, or 2).</param>
        public NullableBool(byte value) => this.value = value;

        ///<summary>
        ///The internal byte representation of the NullableBool state.
        ///0 = false, 1 = true, 2 (NULL) = null.
        ///</summary>
        public byte value = NULL;

        ///<summary>
        ///Gets or sets the boolean value of this <see cref="NullableBool"/>.
        ///Throws an exception if getting the value when it is null.
        ///Setting a value makes `hasValue` true.
        ///</summary>
        public bool Value
        {
            get => value == 1;
            set => this.value = Unsafe.As<bool, byte>(ref value);
        }

        ///<summary>
        ///Indicates whether the NullableBool has a value (not null).
        ///</summary>
        public bool hasValue => value != NULL;

        ///<summary>
        ///Sets the NullableBool to null state.
        ///</summary>
        public void to_null() => value = NULL;

        public static bool operator ==(NullableBool? a, NullableBool? b) => a.HasValue == b.HasValue && (!a.HasValue || a!.Value.value == b!.Value.value);
        public static bool operator !=(NullableBool? a, NullableBool? b) => a.HasValue != b.HasValue || a.HasValue && a!.Value.value != b!.Value.value;

        public static bool operator ==(NullableBool a, NullableBool b) => a.value == b.value;
        public static bool operator !=(NullableBool a, NullableBool b) => a.value != b.value;

        public static bool operator ==(NullableBool a, bool b) => a.value != NULL && a.value == Unsafe.As<bool, byte>(ref b);

        public static bool operator !=(NullableBool a, bool b) => a.value == NULL || a.value != Unsafe.As<bool, byte>(ref b);

        public static bool operator ==(bool a, NullableBool b) => b.value != NULL && b.value == Unsafe.As<bool, byte>(ref a);

        public static bool operator !=(bool a, NullableBool b) => b.value == NULL || b.value != Unsafe.As<bool, byte>(ref a);

        public override bool Equals(object? other) => other is NullableBool p && p.value == value;
        public bool Equals(NullableBool other) => value == other.value;
        public override int GetHashCode() => value.GetHashCode();

        public static explicit operator bool(NullableBool a) => a.Value;
        public static implicit operator NullableBool(bool a) => new NullableBool(a);

        public static implicit operator NullableBool(bool? a) => a == null ? NULL : a.Value;

        public static explicit operator byte(NullableBool a) => a.value;
        public static implicit operator NullableBool(byte a) => new NullableBool(a);

        ///<summary>
        ///Constant value representing a null state for the `NullableBool` struct.
        ///</summary>
        public const byte NULL = 2;
    }

    //Decoding table for base64
    static readonly byte[] char2byte = new byte[256];

    ///<summary>
    ///Static constructor for the `AdHoc` class. Initializes the base64 decoding table.
    ///This table allows quick lookup of the numerical value of each base64 character.
    ///</summary>
    static AdHoc()
    {
        for (int i = 'A'; i <= 'Z'; i++)
            char2byte[i] = (byte)(i - 'A');
        for (int i = 'a'; i <= 'z'; i++)
            char2byte[i] = (byte)(i - 'a' + 26);
        for (int i = '0'; i <= '9'; i++)
            char2byte[i] = (byte)(i - '0' + 52);
        char2byte['+'] = 62;
        char2byte['/'] = 63;
    }

    ///<summary>
    ///Decodes a base64 encoded byte array in-place, modifying the original array.
    ///</summary>
    ///<param name="bytes">The byte array containing the base64 encoded data.</param>
    ///<param name="src_index">The index in `bytes` where the base64 encoded data starts.</param>
    ///<param name="dst_index">The index in `bytes` where the decoded data will be written.</param>
    ///<param name="len">The number of base64 characters to decode.</param>
    ///<returns>The number of bytes written to the decoded data.</returns>
    public static int base64decode(byte[] bytes, int src_index, int dst_index, int len)
    {
        var max = src_index + len;

        while (src_index < max && bytes[max - 1] == '=')
            max--;

        var new_len = max - src_index;
        for (var i = new_len >> 2; 0 < i; i--) //Process full 4-character blocks
        {
            var b = char2byte[bytes[src_index++]] << 18 |
                    char2byte[bytes[src_index++]] << 12 |
                    char2byte[bytes[src_index++]] << 6 |
                    char2byte[bytes[src_index++]];

            bytes[dst_index++] = (byte)(b >> 16);
            bytes[dst_index++] = (byte)(b >> 8);
            bytes[dst_index++] = (byte)b;
        }

        switch (new_len & 3)
        {
            case 3:
                //If there are 3 characters remaining, decode them into 2 bytes
                var b = char2byte[bytes[src_index++]] << 12 |
                        char2byte[bytes[src_index++]] << 6 |
                        char2byte[bytes[src_index]];
                bytes[dst_index++] = (byte)(b >> 10); //Extract first byte
                bytes[dst_index++] = (byte)(b >> 2);  //Extract second byte
                break;
            case 2:
                //If there are 2 characters remaining, decode them into 1 byte
                bytes[dst_index++] = (byte)((char2byte[bytes[src_index++]] << 6 | char2byte[bytes[src_index]]) >> 4);
                break;
        }

        return dst_index;
    }

    ///<summary>
    ///Retrieves a set of TXT records from DNS for a given key, returning the values as a byte array.
    ///</summary>
    ///<param name="key">The DNS key to query.</param>
    ///<returns>An array of `Memory<byte>` representing the TXT record values associated with the key, or null if the lookup fails.</returns>
    //Using DNS as readonly key-value storage https://datatracker.ietf.org/doc/html/rfc1035
    public static Memory<byte>[] value(string key)
    {
        byte[] Create_DNS_TXT_Record_Request(string domain)
        {
            var id = (ushort) new Random().Next(65536); //Generate a random query ID

            var request = new byte[12 + domain.Length + 2 + 4]; //Initialize the request packet

            //Set DNS header fields
            request[0] = (byte)(id >> 8);
            request[1] = (byte)(id);
            request[2] = 0x01; //QR=0, OPCODE=0, AA=0, TC=0, RD=1
            request[5] = 0x01; //QDCOUNT=1

            //Add the domain name to the question section
            var index = 12;
            var p = index++;

            foreach (var ch in domain)
                if (ch == '.')
                {
                    request[p] = (byte)(index - p - 1);
                    p = index++;
                }
                else
                    request[index++] = (byte)ch;

            request[p] = (byte)(index - p - 1); //Set the length for the last label

            index += 2;              //Terminate domain name, set question type (TXT) and class (IN)
            request[index++] = 0x10; //QTYPE = TXT
            request[++index] = 0x01; //QCLASS = IN

            return request;
        }

        //The index right behind the domain name at index: labels up to the zero octet, or ending with a two-octet
        //compression pointer (RFC 1035 4.1.4). Past the end of the response - the name runs past it.
        static int Skip_Name(byte[] response, int index)
        {
            while (index < response.Length)
                if (response[index] == 0)
                    return index + 1;
                else if (0xC0 <= response[index])
                    return index + 2;
                else
                    index += response[index] + 1;
            return index;
        }

        static Memory<byte>[] Parse_DNS_TXT_Record_Response(byte[] response)
        {
            if (response.Length < 12)
                return [];
            var questionCount = response[4] << 8 | response[5]; //Extract question and answer counts from the header
            var answerCount = response[6] << 8 | response[7];

            var index = 12;

            for (var i = 0; i < questionCount; i++) //Skip the question section: QNAME, QTYPE, QCLASS
                index = Skip_Name(response, index) + 4;

            var dst_index = 0;
            var dst_index_ = 0;
            var records = new Memory<byte>[answerCount];
            var got = 0;                                                                                                 //answers the response holds whole
            for (var i = 0; i < answerCount && (index = Skip_Name(response, index)) + 10 <= response.Length; i++, got++) //Parse each answer, its NAME skipped
            {
                //TYPE            two octets containing one of the RR TYPE codes.
                var TYPE = (ushort)(response[index] << 8 | response[index + 1]);
                //CLASS           two octets containing one of the RR CLASS codes.
                //
                //TTL             a 32 bit signed integer that specifies the time interval
                //                that the resource record may be cached before the source
                //                of the information should again be consulted.  Zero
                //                values are interpreted to mean that the RR can only be
                //                used for the transaction in progress, and should not be
                //                cached.  For example, SOA records are always distributed
                //                with a zero TTL to prohibit caching.  Zero values can
                //                also be used for extremely volatile data.
                index += 8;                                                          //Skip all above
                var RDLENGTH = (ushort)(response[index] << 8 | response[index + 1]); //an unsigned 16 bit integer that specifies the length in  octets of the RDATA field.
                index += 2;
                //TXT-DATA        One or more <character-string>s. where <character-string> is a single length octet followed by that number of characters
                //!!! attention records in reply may follow in arbitrary order

                var max = Math.Min(index + RDLENGTH, response.Length);
                if (TYPE == 16) //TXT record
                    while (index < max)
                    {
                        var len = Math.Min(response[index++], max - index);
                        Array.Copy(response, index, response, dst_index, len);
                        dst_index += len;
                        index += len;
                    }
                else
                    index = max; //another type (a CNAME before the TXT...): its RDATA is skipped, the next answer read where it starts

                records[i] = new Memory<byte>(response, dst_index_, dst_index - dst_index_);
                dst_index_ = dst_index;
            }

            return got == answerCount ? records : records[..got];
        }

        var ep = new IPEndPoint(IPAddress.Any, 0);

        using (var udpClient = new UdpClient())
        {
            udpClient.Client.ReceiveTimeout = 5000; //a server that does not answer is not waited for for ever: the next one is asked
            foreach (var os_dns in NetworkInterface.GetAllNetworkInterfaces()
                         .Where(n => n.OperationalStatus == OperationalStatus.Up)
                         .SelectMany(n => n.GetIPProperties().DnsAddresses)
                         .ToArray())
                try
                {
                    var request = Create_DNS_TXT_Record_Request(key);

                    udpClient.Send(request, request.Length, os_dns.ToString(), 53);

                    var response = udpClient.Receive(ref ep);

                    return Parse_DNS_TXT_Record_Response(response);
                }
                catch (Exception e)
                {
                }
        }

        return null;
    }
#region varint text codec
    ///<summary>Elements with any bit above 6 set are non-ASCII - used as a single cheap any-test over a vector.</summary>
    static readonly Vector128<ushort> VARINT_NON_ASCII_128 = Vector128.Create((ushort)0xFF80);

    static readonly Vector256<ushort> VARINT_NON_ASCII_256 = Vector256.Create((ushort)0xFF80);

    ///<summary>Compared with <c>GreaterThan</c> to build a per-element non-ASCII mask.</summary>
    static readonly Vector128<ushort> VARINT_ASCII_MAX_128 = Vector128.Create((ushort)0x7F);

    static readonly Vector256<ushort> VARINT_ASCII_MAX_256 = Vector256.Create((ushort)0x7F);

    ///<summary>High bit of every byte of a <c>ulong</c> - the varint continuation flag, eight at a time.</summary>
    const ulong VARINT_CONTINUATION = 0x8080_8080_8080_8080UL;

    ///<summary>
    ///After an ASCII run shorter than 8 elements, the bulk path is skipped for this many elements. One
    ///vector load then costs more than the run it would find saves, so text dense in multi-byte characters
    ///settles into the plain per-element loop instead of probing ahead of every character.
    ///</summary>
    const int VARINT_BACKOFF = 24;

    ///<summary>Staging size used by the <c>scratch</c>-less <see cref="varint(ReadOnlySpan{byte}, int, StringBuilder)"/>.</summary>
    public const int VARINT_SCRATCH = 256;

    ///<summary>
    ///Calculates the number of bytes required to varint encode a span of characters.
    ///Varint encoding uses variable numbers of bytes to represent integers, optimizing for small numbers.
    ///Each character may require 1, 2, or 3 bytes.
    ///<para>
    ///The count is EXACT, not an estimate: the per-character width counted here is the width
    ///<see cref="varint(ReadOnlySpan{char}, Span{byte})"/> writes, so a buffer of this size fills precisely.
    ///</para>
    ///<para>
    ///SIMD: every character is classified by two vector compares, and the two result masks are folded by
    ///popcount. Counting through the masks rather than through vector accumulators means there is no element
    ///width to overflow and so no periodic-flush interval to size correctly.
    ///</para>
    ///</summary>
    ///<param name="src">The ReadOnlySpan of characters to encode.</param>
    ///<returns>The exact number of bytes needed to varint-encode the characters in `src`.</returns>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static int varint_bytes(ReadOnlySpan<char> src)
    {
        var len = src.Length;
        if (len == 0)
            return 0;

        ref var srcRef = ref MemoryMarshal.GetReference(src);
        ref var srcU = ref Unsafe.As<char, ushort>(ref srcRef); //vector ops are not defined over `char`
        int i = 0, extra = 0;

        if (Vector256.IsHardwareAccelerated && 16 <= len)
        {
            var c80 = Vector256.Create((ushort)0x80);
            var c4k = Vector256.Create((ushort)0x4_000);
            for (var lim = len - 16; i <= lim; i += 16)
            {
                var v = Vector256.LoadUnsafe(ref srcU, (uint)i);
                extra += BitOperations.PopCount(Vector256.GreaterThanOrEqual(v, c80).ExtractMostSignificantBits()) + BitOperations.PopCount(Vector256.GreaterThanOrEqual(v, c4k).ExtractMostSignificantBits());
            }
        }
        else if (Vector128.IsHardwareAccelerated && 8 <= len)
        {
            var c80 = Vector128.Create((ushort)0x80);
            var c4k = Vector128.Create((ushort)0x4_000);
            for (var lim = len - 8; i <= lim; i += 8)
            {
                var v = Vector128.LoadUnsafe(ref srcU, (uint)i);
                extra += BitOperations.PopCount(Vector128.GreaterThanOrEqual(v, c80).ExtractMostSignificantBits()) + BitOperations.PopCount(Vector128.GreaterThanOrEqual(v, c4k).ExtractMostSignificantBits());
            }
        }

        for (; i < len; i++) //tail
        {
            ushort ch = Unsafe.Add(ref srcRef, i);
            if (0x80 <= ch)
            {
                extra++;
                if (0x4_000 <= ch)
                    extra++;
            }
        }

        return len + extra; //one byte per character, plus the continuations counted above
    }

    ///<summary>
    ///Counts the number of characters represented by a varint-encoded byte span.
    /// Varint encoding represents each character via 1 to 3 bytes.
    ///</summary>
    ///<para>
    ///SIMD: a character ends on the one byte per sequence whose high bit is CLEAR, so the count is the number
    ///of such bytes. It is cheaper to gather the high bits of a whole vector at once and popcount them, then
    ///subtract that continuation count from the bytes consumed, than to test each byte on its own.
    ///</para>
    ///<param name="src">The span of bytes in varint encoding.</param>
    ///<returns>The number of characters encoded by the `src` bytes.</returns>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static int varint_chars(ReadOnlySpan<byte> src)
    {
        var len = src.Length;
        if (len == 0)
            return 0;

        ref var srcRef = ref MemoryMarshal.GetReference(src);
        int i = 0, cont = 0;

        if (Vector256.IsHardwareAccelerated && 32 <= len)
            for (var lim = len - 32; i <= lim; i += 32)
                cont += BitOperations.PopCount(Vector256.ExtractMostSignificantBits(Vector256.LoadUnsafe(ref srcRef, (uint)i)));
        else if (Vector128.IsHardwareAccelerated && 16 <= len)
            for (var lim = len - 16; i <= lim; i += 16)
                cont += BitOperations.PopCount(Vector128.ExtractMostSignificantBits(Vector128.LoadUnsafe(ref srcRef, (uint)i)));

        var chars = i - cont; //bytes consumed by the vector loop, less the continuation bytes among them

        for (; i < len; i++) //tail
            if (Unsafe.Add(ref srcRef, i) < 0x80)
                chars++;
        return chars;
    }

    ///<summary>
    ///Encodes a portion of a string into a byte array using varint encoding.
    ///Each character is represented by one, two, or three bytes.
    ///This function is used in the `Transmitter`'s implementation.
    ///</summary>
    ///<param name="src">The source string to encode.</param>
    ///<param name="dst">The destination byte array.</param>
    ///<returns>
    ///A 64-bit unsigned integer. This combines two pieces of information:
    ///- High 32 bits: The index in the source string (`src`) of the next character *not* yet processed.  If all characters
    ///were encoded, this will equal `src.Length`.
    ///- Low 32 bits: The number of bytes written to the `dst` byte array.
    ///</returns>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static ulong varint(ReadOnlySpan<char> src, Span<byte> dst)
    {
        int src_from = 0, dst_from = 0, src_max = src.Length, dst_max = dst.Length;
        if (src_max == 0 || dst_max == 0)
            return 0;

        ref var srcRef = ref MemoryMarshal.GetReference(src);
        ref var srcU = ref Unsafe.As<char, ushort>(ref srcRef); //vector ops are not defined over `char`
        ref var dstRef = ref MemoryMarshal.GetReference(dst);

        var skip = 0; //characters to handle one-at-a-time before attempting the bulk path again

        while (src_from < src_max)
        {
            //An ASCII run cannot start on a non-ASCII character, so one compare gates the whole bulk
            //block. The backoff counter lives INSIDE that guard: dense non-ASCII must not pay for it.
            if (Unsafe.Add(ref srcRef, src_from) < 0x80)
            {
                if (0 < skip)
                    skip--;
                else if (Vector256.IsHardwareAccelerated && 16 <= src_max - src_from && 16 <= dst_max - dst_from)
                {
                    var v = Vector256.LoadUnsafe(ref srcU, (uint)src_from);

                    //16 bytes of room are guaranteed, so this store is in bounds even when only the
                    //leading `run` of them are meaningful - the rest is overwritten next round.
                    Vector256.Narrow(v, v).GetLower().StoreUnsafe(ref dstRef, (uint)dst_from);

                    if ((v & VARINT_NON_ASCII_256) == Vector256<ushort>.Zero) //cheap any-test, the common case
                    {
                        src_from += 16;
                        dst_from += 16;
                        continue;
                    }

                    //Interrupted. The mask locates the first non-ASCII element, so the probe is not
                    //wasted: the run before it is committed and the interrupting character is encoded
                    //by the tail below, in this same iteration.
                    var run = BitOperations.TrailingZeroCount(Vector256.GreaterThan(v, VARINT_ASCII_MAX_256).ExtractMostSignificantBits());
                    src_from += run; //>= 1: element 0 was ASCII
                    dst_from += run;
                    if (run < 8)
                        skip = VARINT_BACKOFF; //runs this short cost more in vector work than they save
                }
                else if (8 <= src_max - src_from && 8 <= dst_max - dst_from)
                {
                    var v = Vector128.LoadUnsafe(ref srcU, (uint)src_from);

                    Unsafe.WriteUnaligned(ref Unsafe.Add(ref dstRef, dst_from), Vector128.Narrow(v, v).AsUInt64().GetElement(0));

                    if ((v & VARINT_NON_ASCII_128) == Vector128<ushort>.Zero)
                    {
                        src_from += 8;
                        dst_from += 8;
                        continue;
                    }

                    var run = BitOperations.TrailingZeroCount(Vector128.GreaterThan(v, VARINT_ASCII_MAX_128).ExtractMostSignificantBits());
                    src_from += run;
                    dst_from += run;
                    if (run < 8)
                        skip = VARINT_BACKOFF;
                }
            }

            int ch = Unsafe.Add(ref srcRef, src_from); //the interrupting, or room-limited, character
            if (ch < 0x80)                             //Most frequent case: ASCII (0-127). 1 byte.
            {
                if (dst_from == dst_max)
                    break;

                Unsafe.Add(ref dstRef, dst_from++) = (byte)ch;
            }
            else if (ch < 0x4_000) //2 bytes.
            {
                if (dst_max - dst_from < 2)
                    break;

                Unsafe.Add(ref dstRef, dst_from++) = (byte)(0x80 | ch);
                Unsafe.Add(ref dstRef, dst_from++) = (byte)(ch >> 7);
            }
            else //3 bytes.
            {
                if (dst_max - dst_from < 3)
                    break;

                Unsafe.Add(ref dstRef, dst_from++) = (byte)(0x80 | ch);
                Unsafe.Add(ref dstRef, dst_from++) = (byte)(0x80 | ch >> 7);
                Unsafe.Add(ref dstRef, dst_from++) = (byte)(ch >> 14);
            }

            src_from++;
        }

        //High 32 bits = next character index to process; low 32 bits = bytes written.
        return (ulong)(uint)src_from << 32 | (uint)dst_from;
    }

    ///<summary>
    ///Decodes a sequence of varint-encoded bytes into a string, appending the result to the provided StringBuilder.
    ///This is the complimentary of the `varint(ReadOnlySpan<char> src, Span<byte> dst)` method.
    ///This function is used in the `Receiver`'s implementation.
    ///</summary>
    ///<param name="src">The input byte array containing varint-encoded data.</param>
    ///<param name="ret">An integer, used to carry over state from a previous call to this function
    ///(for multi-byte characters that were only partially decoded in a previous call).
    ///- Low 16 bits: Contains the partial character being decoded (if incomplete).
    ///- High 8 bits: The number of bits processed for the current partial character (from previous call).
    ///</param>
    ///<param name="dst">The StringBuilder to which the decoded characters are appended.</param>
    ///<returns>
    ///An integer, to be used as `ret` in a subsequent call if decoding isn't finished.
    ///- Low 16 bits: If a character is only partially decoded (e.g. 2 bytes), these bits contain
    ///the partially decoded character.
    ///- High 8 bits: Number of bits processed for a partial character.
    ///</returns>
    ///<summary>Convenience overload - stages through a <c>stackalloc</c> buffer. Prefer the <c>scratch</c>
    ///overload when calling repeatedly: this one is zeroed on entry, which dominates for tiny <paramref name="src"/>.</summary>
    [SkipLocalsInit]
    public static int varint(ReadOnlySpan<byte> src, int ret, StringBuilder dst)
    {
        Span<char> scratch = stackalloc char[VARINT_SCRATCH];
        return varint(src, ret, dst, scratch);
    }

    ///<summary>
    ///Decodes a sequence of varint-encoded bytes into a string, appending the result to the provided StringBuilder.
    ///This is the complimentary of the `varint(ReadOnlySpan&lt;char&gt; src, Span&lt;byte&gt; dst)` method.
    ///This function is used in the `Receiver`'s implementation.
    ///<para>
    ///<paramref name="scratch"/> stages decoded characters so they reach <paramref name="dst"/> in batches
    ///instead of one <c>Append(char)</c> each. Its length is ADAPTED TO, not trusted: a stride needing more
    ///room than it has is skipped, and below 8 nothing is batched. No length is unsafe.
    ///</para>
    ///</summary>
    ///<param name="src">The input byte array containing varint-encoded data.</param>
    ///<param name="ret">Resume state from a previous call - see the returns section.</param>
    ///<param name="dst">The StringBuilder to which the decoded characters are appended.</param>
    ///<param name="scratch">Caller-owned staging buffer. Reuse one across calls; any length works.</param>
    ///<returns>
    ///An integer, to be used as `ret` in a subsequent call if decoding isn't finished.
    ///- Low 16 bits: If a character is only partially decoded (e.g. 2 bytes), these bits contain
    ///the partially decoded character.
    ///- High 8 bits: Number of bits processed for a partial character.
    ///</returns>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static int varint(ReadOnlySpan<byte> src, int ret, StringBuilder dst, Span<char> scratch)
    {
        int src_from = 0, src_to = src.Length;
        var ch = ret & 0xFFFF;    //Low 16 bits: partial character value (resume state)
        var s = ret >> 16 & 0xFF; //High 8 bits: bits already processed (resume state)

        if (src_to == 0)
            return ret;

        ref var srcRef = ref MemoryMarshal.GetReference(src);
        var cap = scratch.Length;

        if (cap < 8) //too small to batch anything - append directly
        {
            while (src_from < src_to)
            {
                int b = Unsafe.Add(ref srcRef, src_from++);
                if (b < 0x80)
                {
                    dst.Append(end_unit(ch, b, s));
                    s = 0;
                    ch = 0;
                }
                else if (s < UNIT_SHIFT_MAX)
                {
                    ch |= (b & 0x7F) << s;
                    s += 7;
                }
                else
                { //a fourth byte: no shift past 14, the state keeps its fields
                    ch = 0;
                    s = UNIT_BROKEN;
                }
            }

            return s << 16 | ch;
        }

        ref var bufU = ref Unsafe.As<char, ushort>(ref MemoryMarshal.GetReference(scratch));
        int bi = 0, skip = 0;

        while (src_from < src_to)
        {
            //A run cannot start mid-character (s != 0) nor on a continuation byte, so one compare gates
            //the whole bulk block. The backoff counter lives INSIDE that guard: dense multi-byte text
            //must not pay for it.
            if (s == 0 && Unsafe.Add(ref srcRef, src_from) < 0x80)
            {
                if (0 < skip)
                    skip--;
                else if (Vector256.IsHardwareAccelerated && 32 <= cap && 32 <= src_to - src_from)
                {
                    if (cap - 32 < bi)
                    {
                        dst.Append(scratch[..bi]);
                        bi = 0;
                    }

                    var v = Vector256.LoadUnsafe(ref srcRef, (uint)src_from);
                    var mask = Vector256.ExtractMostSignificantBits(v); //one bit per continuation byte

                    //Room for 32 is guaranteed by the flush above, so widening the whole vector is in
                    //bounds even when only the leading `run` characters are meaningful.
                    var (lo, hi) = Vector256.Widen(v);
                    lo.StoreUnsafe(ref bufU, (uint)bi);
                    hi.StoreUnsafe(ref bufU, (uint)(bi + 16));

                    if (mask == 0)
                    {
                        src_from += 32;
                        bi += 32;
                        continue;
                    }

                    //Interrupted. The mask locates the first continuation byte, so the probe is not
                    //wasted: the run before it is committed and the multi-byte character is decoded by
                    //the tail below.
                    var run = BitOperations.TrailingZeroCount(mask);
                    src_from += run; //>= 1: byte 0 was ASCII
                    bi += run;
                    if (run < 8)
                        skip = VARINT_BACKOFF;
                }
                else if (16 <= cap && 16 <= src_to - src_from)
                {
                    if (cap - 16 < bi)
                    {
                        dst.Append(scratch[..bi]);
                        bi = 0;
                    }

                    var v = Vector128.LoadUnsafe(ref srcRef, (uint)src_from);
                    var mask = Vector128.ExtractMostSignificantBits(v);

                    var (lo, hi) = Vector128.Widen(v);
                    lo.StoreUnsafe(ref bufU, (uint)bi);
                    hi.StoreUnsafe(ref bufU, (uint)(bi + 8));

                    if (mask == 0)
                    {
                        src_from += 16;
                        bi += 16;
                        continue;
                    }

                    var run = BitOperations.TrailingZeroCount(mask);
                    src_from += run;
                    bi += run;
                    if (run < 8)
                        skip = VARINT_BACKOFF;
                }
                else if (8 <= src_to - src_from) //no vectors, or fewer than 16 bytes left
                {
                    if (cap - 8 < bi)
                    {
                        dst.Append(scratch[..bi]);
                        bi = 0;
                    }

                    var packed = Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref srcRef, src_from));
                    Unsafe.Add(ref bufU, bi) = (ushort)(packed & 0xFF);
                    Unsafe.Add(ref bufU, bi + 1) = (ushort)((packed >> 8) & 0xFF);
                    Unsafe.Add(ref bufU, bi + 2) = (ushort)((packed >> 16) & 0xFF);
                    Unsafe.Add(ref bufU, bi + 3) = (ushort)((packed >> 24) & 0xFF);
                    Unsafe.Add(ref bufU, bi + 4) = (ushort)((packed >> 32) & 0xFF);
                    Unsafe.Add(ref bufU, bi + 5) = (ushort)((packed >> 40) & 0xFF);
                    Unsafe.Add(ref bufU, bi + 6) = (ushort)((packed >> 48) & 0xFF);
                    Unsafe.Add(ref bufU, bi + 7) = (ushort)((packed >> 56) & 0xFF);

                    var flagged = packed & VARINT_CONTINUATION;
                    if (flagged == 0)
                    {
                        src_from += 8;
                        bi += 8;
                        continue;
                    }

                    var run = BitOperations.TrailingZeroCount(flagged) >> 3; //bit index -> byte index
                    src_from += run;
                    bi += run;
                    if (run < 8)
                        skip = VARINT_BACKOFF;
                }
            }

            if (bi == cap)
            {
                dst.Append(scratch);
                bi = 0;
            }

            int b2 = Unsafe.Add(ref srcRef, src_from++);
            if (b2 < 0x80)
            {
                Unsafe.Add(ref bufU, bi++) = (ushort)end_unit(ch, b2, s);
                s = 0;
                ch = 0;
            }
            else if (s < UNIT_SHIFT_MAX)
            {
                ch |= (b2 & 0x7F) << s;
                s += 7;
            }
            else
            { //a fourth byte: no shift past 14, the state keeps its fields
                ch = 0;
                s = UNIT_BROKEN;
            }
        }

        if (0 < bi)
            dst.Append(scratch[..bi]);

        //Return current state (partial char + shift) for potential continuation.
        return s << 16 | ch;
    }

    ///<summary>The shift a varint UTF-16 unit gets to: three bytes at most, the last of them with 2 bits.</summary>
    const int UNIT_SHIFT_MAX = 14;

    ///<summary>The shift of a unit that went past three bytes: its bits are dropped, the byte that ends it makes U+FFFD.</summary>
    const int UNIT_BROKEN = 21;

    ///<summary>
    ///The char a varint ends with the byte <paramref name="b"/> (below 0x80) at <paramref name="s"/>, <paramref name="ch"/> the bits
    ///before it. A unit of more than three bytes, or above U+FFFF, is U+FFFD: this codec has no receiver to tell it to - the
    ///receiver tells it ( <c>Receiver.broken_unit</c> ).
    ///</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    static char end_unit(int ch, int b, int s) => s < UNIT_SHIFT_MAX || s == UNIT_SHIFT_MAX && b <= 3 ? (char)(b << s | ch) : '�';
#endregion

    ///<summary>
    ///Creates a Boyer-Moore pattern table to optimize case-sensitive string searches.
    ///This table is used by the `boyer_moore_ASCII_Case_sensitive` and `boyer_moore_ASCII_Case_insensitive` methods.
    ///</summary>
    ///<param name="src">The search pattern string.</param>
    ///<returns>An array of uints representing the pattern table.</returns>
    public static uint[] boyer_moore_pattern(string src)
    {
        var ret = new uint[src.Length];
        for (var i = src.Length; -1 < --i;)
            if (ret[i] == 0)
                for (int ii = i, ch = src[i], p = i << 8 | ch & 0xFF; -1 < ii; ii--) //the low byte only: the whole char would run into the index
                    if (src[ii] == ch)
                        ret[ii] = (uint)p;
        return ret;
    }

    ///<summary>
    ///Performs a Boyer-Moore search for a case-sensitive match of a pattern in the whole byte array.
    ///</summary>
    public static int boyer_moore_ASCII_Case_sensitive(byte[] bytes, uint[] pattern) => boyer_moore_ASCII_Case_sensitive(bytes, bytes.Length, pattern);

    ///<summary>
    ///Performs a Boyer-Moore search for a case-sensitive match of a pattern in <c>bytes[0..length)</c>.
    ///</summary>
    ///<param name="bytes">The byte array to search within.</param>
    ///<param name="length">How many bytes of <paramref name="bytes"/> hold data — a pooled buffer holds stale bytes past it.</param>
    ///<param name="pattern">The Boyer-Moore pattern table generated for the search pattern.</param>
    ///<returns>The index of the FIRST byte of the first match, or -1 if not found.</returns>
    //Case-sensitive
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static int boyer_moore_ASCII_Case_sensitive(byte[] bytes, int length, uint[] pattern)
    {
        ref var bRef = ref MemoryMarshal.GetArrayDataReference(bytes);
        ref var pRef = ref MemoryMarshal.GetArrayDataReference(pattern);

        //i is the candidate START: the comparison below reads bytes[i + j] for every pattern index j.
        for (int len = pattern.Length, i = 0, max = Math.Min(length, bytes.Length) - len + 1; i < max;)
        {
            for (var j = len; -1 < --j;)
            {
                var p = Unsafe.Add(ref pRef, j);

                if ((byte)p == Unsafe.Add(ref bRef, i + j))
                    continue; //Compare characters

                //Use the last occurrence to determine how far to skip
                var last = p >>> 8; //Extract last occurrence position
                i += (int)Math.Max(1, j - last);
                goto next;
            }

            return i; //the match starts here
        next:;
        }

        return -1; //Pattern not found
    }

    ///<summary>
    ///Performs a Boyer-Moore search for a case-insensitive match of a pattern in the whole byte array.
    ///</summary>
    public static int boyer_moore_ASCII_Case_insensitive(byte[] bytes, uint[] pattern) => boyer_moore_ASCII_Case_insensitive(bytes, bytes.Length, pattern);

    ///<summary>
    ///Performs a Boyer-Moore search for a case-insensitive match of a pattern in <c>bytes[0..length)</c>.
    ///</summary>
    ///<param name="bytes">The byte array to search within.</param>
    ///<param name="length">How many bytes of <paramref name="bytes"/> hold data — a pooled buffer holds stale bytes past it.</param>
    ///<param name="pattern">The Boyer-Moore pattern table generated for the search pattern.</param>
    ///<returns>The index of the FIRST byte of the first match, or -1 if not found.</returns>
    //Case-insensitive
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static int boyer_moore_ASCII_Case_insensitive(byte[] bytes, int length, uint[] pattern)
    {
        ref var bRef = ref MemoryMarshal.GetArrayDataReference(bytes);
        ref var pRef = ref MemoryMarshal.GetArrayDataReference(pattern);

        //i is the candidate START: the comparison below reads bytes[i + j] for every pattern index j.
        for (int len = pattern.Length, i = 0, max = Math.Min(length, bytes.Length) - len + 1; i < max;)
        {
            for (var j = len; -1 < --j;)
            {
                var p = Unsafe.Add(ref pRef, j);
                var c = (byte)p; //the pattern character; the bits above it hold its last occurrence, not part of it

                switch (c - Unsafe.Add(ref bRef, i + j))
                {
                    case 0:
                        continue;
                    case 32: //pattern lower case, text upper case
                        if ('a' <= c && c <= 'z')
                            continue;
                        break;
                    case -32: //pattern upper case, text lower case
                        if ('A' <= c && c <= 'Z')
                            continue;
                        break;
                }

                //Use the last occurrence to determine how far to skip
                var last = p >>> 8; //Extract last occurrence position
                i += (int)Math.Max(1, j - last);
                goto next;
            }

            return i; //the match starts here
        next:;
        }

        return -1; //Pattern not found
    }

    ///<summary>
    ///Packs a specified number of bits from a long value into a byte array at a given bit offset.
    ///<para>
    ///Hot middle loop emits up to 8 bytes per iteration via <see cref="Unsafe.WriteUnaligned{T}(ref byte, T)"/>
    ///when at least 8 source bits remain; per-byte tail handles the &lt;= 7 leftover.
    ///</para>
    ///</summary>
    ///<param name="src">The source long value containing the bits to pack.</param>
    ///<param name="dst">The destination byte array where bits will be packed.</param>
    ///<param name="dstBit">The starting bit position in the destination array.</param>
    ///<param name="dstBits">The number of bits to pack from the source.</param>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static void Pack(ulong src, byte[] dst, int dstBit, int dstBits)
    {
        var i = dstBit >> 3;
        ref var dstRef = ref MemoryMarshal.GetArrayDataReference(dst);
        dstBit &= 7;

        var done = Math.Min(dstBits, 8 - dstBit);
        var mask = ~0UL >> 64 - done;

        ref var head = ref Unsafe.Add(ref dstRef, i);
        head = (byte)(head & ~(mask << dstBit) | (src & mask) << dstBit);
        src >>= done;
        dstBits -= done;
        i++;

        //Bulk: 8 bytes per store while >= 64 source bits remain.
        while (dstBits >= 64)
        {
            Unsafe.WriteUnaligned(ref Unsafe.Add(ref dstRef, i), src);
            //Cannot shift by 64 (undefined for ulong). Loop ends here when full ulong consumed.
            src = 0;
            dstBits -= 64;
            i += 8;
        }

        //Tail: per-byte for remaining 8..63 bits.
        for (; 7 < dstBits; dstBits -= 8, src >>= 8, i++)
            Unsafe.Add(ref dstRef, i) = (byte)src;

        if (dstBits == 0)
            return;

        mask = ~0UL >> 64 - dstBits;
        ref var tail = ref Unsafe.Add(ref dstRef, i);
        tail = (byte)(tail & ~mask | src & mask);
    }

    ///<summary>
    ///Unpacks a specified number of bits from a byte array starting at a given bit offset into a long value.
    ///<para>
    ///Hot middle loop reads up to 8 bytes per iteration via <see cref="Unsafe.ReadUnaligned{T}(ref byte)"/>
    ///when at least 8 destination bits remain; per-byte tail handles the &lt;= 7 leftover.
    ///</para>
    ///</summary>
    ///<param name="src">The source byte array containing the bits to unpack.</param>
    ///<param name="srcBit">The starting bit position in the source array.</param>
    ///<param name="srcBits">The number of bits to unpack.</param>
    ///<returns>The unpacked bits as a long value.</returns>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static ulong Unpack(byte[] src, int srcBit, int srcBits)
    {
        var i = srcBit >> 3;
        ref var srcRef = ref MemoryMarshal.GetArrayDataReference(src);
        srcBit &= 7;

        var done = Math.Min(srcBits, 8 - srcBit);
        var result = (ulong)(Unsafe.Add(ref srcRef, i) >> srcBit) & (1UL << done) - 1;

        srcBits -= done;
        i++;

        //Bulk: 8 bytes per load while >= 64 result bits remain.
        if (srcBits >= 64)
        {
            result |= Unsafe.ReadUnaligned<ulong>(ref Unsafe.Add(ref srcRef, i)) << done;
            //After reading 64 bits, srcBits drops below 64 and we cap at 64 effective bits in result.
            //Original loop would have rotated `done` past 63 (undefined-shift territory), so we stop here.
            return result;
        }

        //Tail: per-byte while >= 8 source bits remain.
        for (; 7 < srcBits; done += 8, srcBits -= 8, i++)
            result |= (ulong)Unsafe.Add(ref srcRef, i) << done;

        return srcBits == 0 ? result : result | (Unsafe.Add(ref srcRef, i) & (1UL << srcBits) - 1) << done;
    }

    public static DateTime DateTime(string dateTime, string format) => System.DateTime.ParseExact(dateTime, format, CultureInfo.InvariantCulture, DateTimeStyles.AdjustToUniversal);

    ///<summary>
    ///A lightweight, reentrant spinlock using CAS + SpinWait.
    ///Uses ManagedThreadId for ownership tracking.
    ///Much faster than Monitor in very short, high-contention critical sections.
    ///NOT suitable when hold times are long or unpredictable.
    ///</summary>
    public struct FastReentrantSpinLock
    {
        int owner = 0;
        int locks = 0;
        public FastReentrantSpinLock() {}

        ///<summary>
        ///Acquires the lock, blocking until it is held by the calling thread. Re-acquisition by the current owner
        ///just bumps the reentrancy count and returns immediately; contenders spin via <see cref="SpinWait"/>.
        ///</summary>
        public void Acquire()
        {
            var th = Environment.CurrentManagedThreadId;

            if (Volatile.Read(ref owner) == th)
            {
                locks++;
                return;
            }

            for (var sw = new SpinWait(); Interlocked.CompareExchange(ref owner, th, 0) != 0;)
                sw.SpinOnce();
            locks = 1;
        }

        ///<summary>
        ///Releases one level of the lock held by the calling thread. Unwinds one reentrancy level; the lock is
        ///actually freed (owner cleared) only when the outermost <see cref="Release"/> matches the first <see cref="Acquire"/>.
        ///</summary>
        public void Release()
        {
            if (Volatile.Read(ref owner) != Environment.CurrentManagedThreadId)
                return; //not the owner — nothing to release
            if (0 < --locks)
                return; //still held by an outer Acquire
            Volatile.Write(ref owner, 0);
        }
    }

    public static StringBuilder ToString(byte[] src) { return ToString(src, 0, src.Length, new StringBuilder(src.Length * 5)); }
    private static readonly char[] HEX_CHARS = "0123456789ABCDEF".ToCharArray();

    public static StringBuilder ToString(byte[] src, int start, int end, StringBuilder dst)
    {
        for (var i = start; i < end; i += 16)
        {
            var leading = true;
            for (var shift = 28; shift >= 0; shift -= 4)
            {
                var nibble = (i >> shift) & 0xF;
                if (leading && nibble == 0 && shift > 0)
                    dst.Append(' ');
                else
                {
                    leading = false;
                    dst.Append(HEX_CHARS[nibble]);
                }
            }

            dst.Append(": ");

            for (var j = 0; j < 16; j++)
            {
                if (i + j < end)
                {
                    var value = src[i + j] & 0xFF;
                    dst.Append(HEX_CHARS[(value >> 4) & 0xF]);
                    dst.Append(HEX_CHARS[value & 0xF]);
                    dst.Append(' ');
                }
                else
                    dst.Append("   ");
            }

            dst.Append(": ");
            var s = Math.Min(i + 16, end).ToString();
            for (var i1 = s.Length; i1 < 8; i1++)
                dst.Append(' ');
            dst.Append(s);
            dst.Append('\n');
        }

        return dst;
    }
}